QATAR_FLAG_URL = ("https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Flag_of_Qatar_%283-2%29.svg/"
                  "3840px-Flag_of_Qatar_%283-2%29.svg.png?utm_source=commons.wikimedia.org"
                  "&utm_campaign=index&utm_content=thumbnail")
FLAG_URL_OVERRIDES = {"QA": QATAR_FLAG_URL, "QAR": QATAR_FLAG_URL}   # country / currency code -> exact image URL

def _fetch_flag_override(code, path):
    """Downloads the override flag, shrinks it (the source is 3840 px wide) and caches it. True on success."""
    raw = _http_get(FLAG_URL_OVERRIDES[code], headers={"User-Agent": "NCZ-Games-Launcher/1.0 (flag icons)"}, timeout=20)
    img = QImage.fromData(raw)
    if img.isNull():
        return False
    if img.width() > 480:
        img = img.scaledToWidth(480, Qt.TransformationMode.SmoothTransformation)
    img = img.convertToFormat(QImage.Format.Format_ARGB32)
    # recolor the maroon to #70113d: every pixel is a mix of white and the flag's own maroon (edges are
    # antialiased), so work out how much maroon it holds and re-mix with the new colour
    rc = img.pixel(int(img.width() * 0.8), img.height() // 2)
    tgt = (0x70, 0x11, 0x3d)
    span = [max(255 - ((rc >> 16) & 255), 1), max(255 - ((rc >> 8) & 255), 1), max(255 - (rc & 255), 1)]
    for y in range(img.height()):
        for x in range(img.width()):
            c = img.pixel(x, y)
            a = (c >> 24) & 255
            r, g, b = (c >> 16) & 255, (c >> 8) & 255, c & 255
            t = min(1.0, max(0.0, ((255 - r) / span[0] + (255 - g) / span[1] + (255 - b) / span[2]) / 3.0))
            nr = int(round(255 + (tgt[0] - 255) * t))
            ng = int(round(255 + (tgt[1] - 255) * t))
            nb = int(round(255 + (tgt[2] - 255) * t))
            img.setPixel(x, y, (a << 24) | (nr << 16) | (ng << 8) | nb)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return img.save(path, "PNG")

def _country_flag_path(code):
    suffix = "_custom2" if code in FLAG_URL_OVERRIDES else ""
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "flags", f"country_{code}{suffix}.png")

def get_country_flag_file(code):
    """Flag image for a country code, downloaded once and cached. '' if unavailable (call off the GUI thread)."""
    code = (code or "").upper()
    if code not in COUNTRIES:
        return ""
    path = _country_flag_path(code)
    if os.path.exists(path) and os.path.getsize(path) > 100:
        return path
    if code in FLAG_URL_OVERRIDES:
        try:
            if _fetch_flag_override(code, path):
                return path
        except Exception:
            _log_exc("get_country_flag_file")
        return ""
    try:
        raw = _http_get(f"https://flagcdn.com/w160/{code.lower()}.png",
                        headers={"User-Agent": "NCZ-Games-Launcher/1.0 (flag icons)"}, timeout=8)
        if not QImage.fromData(raw).isNull():
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "wb") as f:
                f.write(raw)
            return path
    except Exception:    # expected: offline or the server did not answer
        pass
    return ""

# ── country auto-detected from the IP address when the account has none (never overrides your own choice)
_country_auto_state = {"uid": None, "next": 0.0}

def _country_manual_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "country_manual.json")

def country_is_manual(uid):
    try:
        with open(_country_manual_path(), encoding="utf-8") as f:
            return uid in json.load(f)
    except Exception:
        return False

def mark_country_manual(uid):
    """The user picked a country (or 'Not shown') themselves, so it is never auto-set for this account again."""
    try:
        with open(_country_manual_path(), encoding="utf-8") as f:
            uids = json.load(f)
        uids = uids if isinstance(uids, list) else []
    except Exception:
        uids = []
    if uid not in uids:
        uids.append(uid)
        try:
            os.makedirs(os.path.dirname(_country_manual_path()), exist_ok=True)
            with open(_country_manual_path(), "w", encoding="utf-8") as f:
                json.dump(uids, f)
        except OSError:    # expected: file may not exist yet or be unreadable
            pass

def detect_country_by_ip():
    """Two-letter country code from the public IP address ('' if it can't be found)."""
    for url, as_json in (("https://api.country.is/", True), ("https://ipapi.co/country/", False)):
        try:
            raw = _http_get(url, timeout=6).decode("utf-8", errors="replace").strip()
            code = json.loads(raw).get("country") if as_json else raw
            code = str(code or "").strip().upper()
            if code in COUNTRIES:
                return code
        except Exception:
            continue
    return ""

def cloud_autoset_country():
    """If the account has no country and the user never chose one, sets it from the IP. At most every 30 minutes."""
    acct = load_account()
    if not acct or not cloud_configured():
        return
    uid, now, st = acct["uid"], time.time(), _country_auto_state
    if st["uid"] == uid and now < st["next"]:
        return
    st.update(uid=uid, next=now + 1800)
    if country_is_manual(uid):
        return
    cloud_pull_profile()                     # the country may already be saved from another device
    if load_profile_country():
        return
    code = detect_country_by_ip()
    if code:
        cloud_save_profile(country=code)

def load_profile_country():
    """The logged-in account's country code ('' if none), from the local profile cache."""
    acct = load_account()
    if not acct:
        return ""
    try:
        with open(get_profile_cache_path(), encoding='utf-8') as f:
            data = json.load(f)
        if isinstance(data, dict) and data.get("uid") == acct["uid"]:
            code = str(data.get("country") or "").upper()
            return code if code in COUNTRIES else ""
    except Exception:    # expected: file may not exist yet or be unreadable
        pass
    return ""

def prepare_avatar_png(path):
    """Centre-crops the image to a square and shrinks it to a small PNG for the cloud."""
    img = QImage(path)
    if img.isNull():
        raise CloudError("Couldn't read that image.", "BAD_IMAGE")
    side = min(img.width(), img.height())
    img = img.copy((img.width() - side) // 2, (img.height() - side) // 2, side, side)
    img = img.scaled(AVATAR_SIZE, AVATAR_SIZE, Qt.AspectRatioMode.IgnoreAspectRatio,
                     Qt.TransformationMode.SmoothTransformation)
    buf = QBuffer()
    buf.open(QIODevice.OpenModeFlag.WriteOnly)
    img.save(buf, "PNG")
    return bytes(buf.data())

def _decode_photo(photo):
    if not isinstance(photo, str) or not photo or len(photo) > MAX_PHOTO_CHARS:
        return None
    try:
        raw = base64.b64decode(photo, validate=True)
    except Exception:
        return None
    return raw if QImage().loadFromData(raw) else None

def load_profile_cache():
    """Returns (username, avatar_path or None) for the logged-in account, from the local cache."""
    acct = load_account()
    if not acct:
        return "", None
    try:
        with open(get_profile_cache_path(), encoding='utf-8') as f:
            data = json.load(f)
        if isinstance(data, dict) and data.get("uid") == acct["uid"]:
            avatar = get_avatar_cache_path()
            has_photo = bool(data.get("has_photo")) and os.path.exists(avatar)
            return str(data.get("username") or ""), (avatar if has_photo else None)
    except Exception:    # expected: file may not exist yet or be unreadable
        pass
    return "", None

def save_profile_cache(uid, username, png_bytes, country=""):
    folder = os.path.dirname(get_profile_cache_path())
    os.makedirs(folder, exist_ok=True)
    avatar = get_avatar_cache_path()
    if png_bytes:
        tmp = avatar + ".tmp"
        with open(tmp, 'wb') as f:
            f.write(png_bytes)
        os.replace(tmp, avatar)
    else:
        try:
            os.remove(avatar)
        except OSError:    # expected: cleanup that may already be done
            pass
    with open(get_profile_cache_path(), 'w', encoding='utf-8') as f:
        json.dump({"uid": uid, "username": username or "", "has_photo": bool(png_bytes),
                   "country": country or ""}, f)

def _profile_url(uid, token):
    base = FIREBASE_DB_URL.strip().rstrip("/")
    return (f"{base}/users/{urllib.parse.quote(uid, safe='')}/profile.json"
            f"?auth={urllib.parse.quote(token, safe='')}")

def cloud_pull_profile():
    """Downloads the profile from the cloud and refreshes the local cache."""
    token, uid = get_id_token()
    data = _http_json(_profile_url(uid, token))
    data = data if isinstance(data, dict) else {}
    username = data.get("username") if isinstance(data.get("username"), str) else ""
    png = _decode_photo(data.get("photo"))
    country = str(data.get("country") or "").upper()
    save_profile_cache(uid, username, png, country if country in COUNTRIES else "")
    return username

def cloud_save_profile(username=None, png=None, remove_photo=False, country=None):
    payload = {"updated": {".sv": "timestamp"}}
    if username is not None:
        payload["username"] = username
    if png is not None:
        payload["photo"] = base64.b64encode(png).decode("ascii")
    elif remove_photo:
        payload["photo"] = None
    if country is not None:                     # "" removes the country
        country = str(country).upper()
        payload["country"] = country if country in COUNTRIES else None
    token, uid = get_id_token()
    _http_json(_profile_url(uid, token), "PATCH", payload)
    if country is not None:
        try:        # friends see it right away instead of at the next presence update
            _http_json(_fdb(f"public/{uid}", token), "PATCH", {"country": payload["country"]})
        except CloudError:    # expected: offline or timed out
            pass
    return cloud_pull_profile()

def describe_save(text):
    try:
        night = json.loads(text).get("night")
        if isinstance(night, (int, float)) and not isinstance(night, bool):
            return f"Night {int(night) if float(night).is_integer() else night}"
    except Exception:    # expected: file may not exist yet or be unreadable
        pass
    return ""

def format_cloud_time(ms):
    try:
        return time.strftime("%Y-%m-%d %H:%M", time.localtime(float(ms) / 1000.0))
    except Exception:
        return "an unknown time"

# ── desktop shortcut ──
# `python main.py` never caches the compiled file it runs, so all 50k lines were compiled on every start (~5 s, ~20 MiB).
# Importing it instead lets Python keep __pycache__/main.cpython-*.pyc. This stub does what `python main.py` did
# (same sys.argv, the script's folder first on sys.path, no '' / cwd entry) and needs no extra file, so the self-updater still only swaps main.py.
# No quotes, $ or % in it: it goes into .lnk / .desktop / Run-key command lines as one argument.
_NCZ_IMPORT_STUB = ("import sys,os,importlib;p=os.path.abspath(sys.argv.pop(1));sys.argv[0]=p;"
                    "sys.path[:]=[os.path.dirname(p)]+[x for x in sys.path if x];"
                    "importlib.import_module(os.path.splitext(os.path.basename(p))[0]).main()")

def _launcher_script_args(script=None):
    """Interpreter arguments that run main.py (from source) with its compiled code cached: ['-c', stub, main.py]."""
    return ["-c", _NCZ_IMPORT_STUB, script or os.path.abspath(__file__)]

def get_launch_command():
    """(target, args, working_dir) that starts this launcher the way it is currently being run."""
    appimage = os.environ.get("APPIMAGE")
    if appimage:
        return appimage, [], os.path.dirname(os.path.abspath(appimage))
    if getattr(sys, "frozen", False):
        return sys.executable, [], os.path.dirname(os.path.abspath(sys.executable))
    script = os.path.abspath(__file__)
    exe = sys.executable
    if sys.platform.startswith("win"):
        pythonw = os.path.join(os.path.dirname(exe), "pythonw.exe")
        if os.path.exists(pythonw):
            exe = pythonw  # no console window
    return exe, _launcher_script_args(script), os.path.dirname(script)

def _shortcut_icon_name(src, ext):
    """One file per theme icon, so Windows/the desktop can't keep showing a cached icon of another theme."""
    stem = re.sub(r"[^A-Za-z0-9_-]", "", os.path.splitext(os.path.basename(src))[0]) or "icon"
    try:
        import hashlib    # lazy: saves memory/startup until used
        with open(src, "rb") as _f:
            tag = "-" + hashlib.md5(_f.read()).hexdigest()[:8]      # changes whenever the icon's pixels change
    except Exception:
        tag = ""
    return ("launcher" if ext == ".ico" else "launcher-icon") + ("" if stem == "icon" else "-" + stem) + tag + ext

def _shortcut_marker():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "shortcut_icon.txt")

def prepare_shortcut_icon(src=None):
    """Copies/converts the current theme's icon (or `src`) to a stable location the shortcut can point at. None if unavailable."""
    src = src or asset_path("icon.png")
    if not src or not os.path.exists(src):
        return None
    folder = os.path.dirname(get_launcher_settings_path())
    os.makedirs(folder, exist_ok=True)
    try:
        if sys.platform.startswith("win"):
            dest = os.path.join(folder, _shortcut_icon_name(src, ".ico"))
            img = QImage(src)
            if img.isNull():
                return None
            size = 256
            scaled = img.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatio,
                                Qt.TransformationMode.SmoothTransformation)
            canvas = QImage(size, size, QImage.Format.Format_ARGB32)
            canvas.fill(Qt.GlobalColor.transparent)
            painter = QPainter(canvas)
            painter.drawImage((size - scaled.width()) // 2, (size - scaled.height()) // 2, scaled)
            painter.end()
            return dest if canvas.save(dest, "ICO") else None
        dest = os.path.join(folder, _shortcut_icon_name(src, ".png"))
        shutil.copyfile(src, dest)
        return dest
    except Exception:
        return None

def _ps_quote(text):
    return "'" + str(text).replace("'", "''") + "'"

def _create_windows_shortcut(target, args, workdir, icon):
    script = (
        "$desktop=[Environment]::GetFolderPath('Desktop');"
        "$lnk=Join-Path $desktop 'NCZ Games Launcher.lnk';"
        "$s=(New-Object -ComObject WScript.Shell).CreateShortcut($lnk);"
        f"$s.TargetPath={_ps_quote(target)};"
        f"$s.Arguments={_ps_quote(subprocess.list2cmdline(args))};"
        f"$s.WorkingDirectory={_ps_quote(workdir)};"
        + (f"$s.IconLocation={_ps_quote(icon)};" if icon else "")
        + "$s.Description='NCZ Games Launcher';"
        "$s.Save();Write-Output $lnk"
    )
    try:
        result = subprocess.run(
            ["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", script],
            capture_output=True, text=True, timeout=30, creationflags=0x08000000)
    except Exception as e:
        raise RuntimeError(f"Couldn't run PowerShell: {e}")
    if result.returncode != 0:
        detail = (result.stderr or result.stdout or "").strip().splitlines()
        raise RuntimeError(detail[0] if detail else "PowerShell couldn't create the shortcut.")
    return result.stdout.strip().splitlines()[-1] if result.stdout.strip() else "your Desktop"

def _linux_desktop_dir():
    try:
        out = subprocess.run(["xdg-user-dir", "DESKTOP"], capture_output=True, text=True,
                             timeout=5, env=system_env()).stdout.strip()
        if out and os.path.isdir(out):
            return out
    except Exception:
        _log_exc("_linux_desktop_dir")
    fallback = os.path.expanduser("~/Desktop")
    return fallback if os.path.isdir(fallback) else None

def _create_linux_shortcut(target, args, workdir, icon):
    desktop = _linux_desktop_dir()
    if not desktop:
        raise RuntimeError("Couldn't find your Desktop folder.")

    def quote(arg):
        return '"' + str(arg).replace("%", "%%") + '"'

    lines = [
        "[Desktop Entry]",
        "Type=Application",
        "Version=1.0",
        "Name=NCZ Games Launcher",
        "Comment=Install and launch NCZ games",
        "Exec=" + " ".join(quote(a) for a in [target] + list(args)),
        f"Path={workdir}",
    ]
    if icon:
        lines.append(f"Icon={icon}")
    lines += ["Terminal=false", "Categories=Game;", ""]
    path = os.path.join(desktop, "NCZ Games Launcher.desktop")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    os.chmod(path, 0o755)
    if shutil.which("gio"):  # lets GNOME launch it without the "Allow Launching" step
        try:
            subprocess.run(["gio", "set", path, "metadata::trusted", "true"],
                           capture_output=True, timeout=5, env=system_env())
        except Exception:
            _log_exc("_create_linux_shortcut")
    return path

def create_desktop_shortcut(icon_src=None):
    """Creates (or refreshes) a desktop shortcut and returns its path. Raises RuntimeError with a readable message.
    icon_src: icon file to use instead of the running theme's (used when switching themes)."""
    target, args, workdir = get_launch_command()
    demo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "demo.py")     # the sign-in / installer script next to main.py
    if not os.environ.get("APPIMAGE") and not getattr(sys, "frozen", False) and os.path.isfile(demo):
        args, workdir = [demo], os.path.dirname(demo)      # the shortcut opens demo.py (it starts main.py once signed in)
    icon = prepare_shortcut_icon(icon_src)
    if sys.platform.startswith("win"):
        result = _create_windows_shortcut(target, args, workdir, icon)
    elif sys.platform.startswith("linux"):
        result = _create_linux_shortcut(target, args, workdir, icon)
    else:
        raise RuntimeError("Desktop shortcuts aren't supported on this platform yet.")
    try:                                     # remember which icon the shortcut has, so a theme change can refresh it
        with open(_shortcut_marker(), "w", encoding="utf-8") as f:
            f.write(os.path.basename(icon or ""))
    except Exception:
        _log_exc("create_desktop_shortcut")
    return result

