def build_palette(t):
    palette = QPalette()
    text = QColor(t["text"])
    disabled = QColor(t["disabled_text"])
    palette.setColor(QPalette.ColorRole.Window, QColor(t["bg"]))
    palette.setColor(QPalette.ColorRole.WindowText, text)
    palette.setColor(QPalette.ColorRole.Base, QColor(t["input"]))
    palette.setColor(QPalette.ColorRole.AlternateBase, QColor(t["panel"]))
    palette.setColor(QPalette.ColorRole.ToolTipBase, QColor(t["panel"]))
    palette.setColor(QPalette.ColorRole.ToolTipText, text)
    palette.setColor(QPalette.ColorRole.Text, text)
    palette.setColor(QPalette.ColorRole.Button, QColor(t["button"]))
    palette.setColor(QPalette.ColorRole.ButtonText, text)
    palette.setColor(QPalette.ColorRole.BrightText, QColor(255, 80, 80))
    palette.setColor(QPalette.ColorRole.Link, QColor(t["accent"]))
    palette.setColor(QPalette.ColorRole.Highlight, QColor(t["accent"]))
    palette.setColor(QPalette.ColorRole.HighlightedText, QColor(_on_accent()))
    palette.setColor(QPalette.ColorRole.PlaceholderText, QColor(t["subtext"]))
    palette.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Text, disabled)
    palette.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.ButtonText, disabled)
    palette.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.WindowText, disabled)
    return palette

_app_font_family = {"name": None}

def load_app_font():
    """Registers assets/ubuntu.ttf with Qt and returns its family name (None if it can't be loaded)."""
    if _app_font_family["name"]:
        return _app_font_family["name"]
    # ubuntu.ttf first (it decides the family name), then any other weights next to it
    # (ubuntu-bold.ttf, ubuntu-medium.ttf, ...) so bold text uses the real bold, not a smeared fake one.
    paths = [asset_path("ubuntu.ttf")]
    try:
        for f in sorted(os.listdir(ASSETS_DIR)):
            if f.lower().startswith("ubuntu") and f.lower().endswith((".ttf", ".otf")) and f.lower() != "ubuntu.ttf":
                paths.append(os.path.join(ASSETS_DIR, f))
    except OSError:    # expected: file may not exist yet or be unreadable
        pass
    for path in paths:
        if os.path.isfile(path):
            font_id = QFontDatabase.addApplicationFont(path)
            if font_id != -1 and not _app_font_family["name"]:
                families = QFontDatabase.applicationFontFamilies(font_id)
                if families:
                    _app_font_family["name"] = families[0]
    return _app_font_family["name"]

def build_app_font():
    font = QFont()
    family = load_app_font()
    if family:
        font.setFamily(family)
    else:
        font.setFamilies(["Segoe UI", "Noto Sans", "Helvetica Neue", "Arial"])
    font.setPointSize(10)
    font.setHintingPreference(QFont.HintingPreference.PreferNoHinting)  # no pixel-snapping, so thin strokes aren't "eaten"
    font.setStyleStrategy(QFont.StyleStrategy.PreferAntialias)
    return font

def system_prefers_dark():
    app = QApplication.instance()
    try:
        return app.styleHints().colorScheme() == Qt.ColorScheme.Dark
    except Exception:
        window_color = app.palette().color(QPalette.ColorRole.Window)
        return window_color.lightness() < 128

# kept: used at import time before the later definition at line 29691
def set_accent(color):
    """Recolors the launcher's accent (buttons, highlights, links) in both themes."""
    c = QColor(color)
    if not c.isValid():
        c = QColor("#a666ff")
    base, hover, press = c.name(), c.lighter(120).name(), c.darker(125).name()
    for t in THEMES.values():
        t.update(accent=base, accent_hover=hover, accent_press=press, red=base, red_hover=hover, red_press=press,
                 accent_fill=f"rgba({c.red()},{c.green()},{c.blue()},0.18)")
    try:                                     # in-game toasts follow the accent too
        import overlay as _overlay_mod    # lazy: saves memory/startup until used
        _overlay_mod.set_accent(base)
    except Exception:    # expected: optional module may be missing
        pass

def _hue_shift_icon(src, hue, sat_scale, size=256):
    """The icon with every coloured pixel (the N and the glow) moved to `hue`; the white outline, stars and black sky stay.
    sat_scale compensates for the target colour being more or less saturated than the original lavender."""
    img = QImage(src)
    if img.isNull():
        return None
    if max(img.width(), img.height()) > size:
        img = img.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
    img = img.convertToFormat(QImage.Format.Format_ARGB32)
    for y in range(img.height()):
        for x in range(img.width()):
            c = img.pixelColor(x, y)
            if c.alpha() and not (c.saturationF() < 0.22 and c.valueF() > 0.82):      # skip white
                c.setHsvF(hue, min(1.0, c.saturationF() * sat_scale), c.valueF(), c.alphaF())
                img.setPixelColor(x, y, c)
    return img

# kept: used at import time before the later definition at line 29696
def apply_accent_to_icon(color):
    """Recolors assets/icon.png to match the accent: the icon's background becomes exactly the chosen colour and
    the other shades move with it. The original is kept once as assets/icon_default.png and every recolor starts
    from it, so Reset restores the exact original. Returns True if icon.png changed."""
    try:
        icon = accent_icon_path()
        orig = os.path.join(ASSETS_DIR, "icon-cl.png")           # Classic's own icon is the base for recolouring
        if not os.path.exists(orig):
            orig = os.path.join(ASSETS_DIR, "icon_default.png")  # the untouched original (older versions kept it here)
        if not os.path.exists(orig):
            orig = os.path.join(ASSETS_DIR, "icon.png")
            if not os.path.exists(orig):
                return False
        os.makedirs(os.path.dirname(icon), exist_ok=True)
        if QColor(color).name() == "#a666ff":
            try:
                os.remove(icon)                      # back to the bundled purple icon
            except FileNotFoundError:    # expected: file or process may already be gone
                pass
            return True
        target = QColor(color)
        out = _hue_shift_icon(orig, max(0.0, target.hueF()), target.saturationF() / 0.6)    # N + glow follow the accent
        return bool(out is not None and out.save(icon, "PNG"))
    except Exception:
        return False

_crisp_filter = {"obj": None}

def _install_crisp_text(app):
    """Style-sheet font rules (bold buttons, sized labels...) make Qt drop the app font's 'no hinting + antialias'
    settings, which is what makes small bold text look blocky. This puts them back on every widget once it is polished."""
    if _crisp_filter["obj"] is not None:
        return
    from PyQt6.QtCore import QEvent    # lazy: saves memory/startup until used

    class _CrispText(QObject):
        def eventFilter(self, obj, ev):
            try:
                if ev.type() in (QEvent.Type.Polish, QEvent.Type.Show) and obj.isWidgetType():
                    f = obj.font()
                    if (f.hintingPreference() != QFont.HintingPreference.PreferNoHinting
                            or not (f.styleStrategy() & QFont.StyleStrategy.PreferAntialias)):
                        f.setHintingPreference(QFont.HintingPreference.PreferNoHinting)
                        f.setStyleStrategy(QFont.StyleStrategy.PreferAntialias)
                        obj.setFont(f)
            except Exception:
                _log_exc("eventFilter")
            return False

    _crisp_filter["obj"] = _CrispText(app)
    app.installEventFilter(_crisp_filter["obj"])

# kept: used at import time before the later definition at line 29702
def apply_dark_mode(mode):
    app = QApplication.instance()
    if app is None:
        return
    app.setStyle("Fusion")
    use_dark = mode == "on" or (mode == "system" and system_prefers_dark())
    theme = THEMES["dark" if use_dark else "light"]
    try:                                     # in-game toasts follow light / dark mode
        import overlay as _overlay_mod    # lazy: saves memory/startup until used
        _overlay_mod.set_light(not use_dark)
    except Exception:    # expected: optional module may be missing
        pass
    app.setPalette(build_palette(theme))
    app.setFont(build_app_font())
    _install_crisp_text(app)
    family = load_app_font()
    force_font = f'* {{ font-family: "{family}"; }}\n' if family else ""
    app.setStyleSheet(force_font + STYLE_TEMPLATE.substitute(theme))
    _theme_state["nav_text"] = theme["nav_text"]
    _theme_state["nav_active"] = theme["nav_active"]
    for listener in list(_theme_listeners):
        try:
            listener()
        except Exception:
            _log_exc("apply_dark_mode")

class JsonEditorDialog(QDialog):
    def __init__(self, file_path, title="Edit Save File", parent=None):
        super().__init__(parent)
        self.setWindowTitle(title)
        self.setFixedSize(380, 460)
        self.setModal(True)
        self.file_path = file_path
        self.trailing_null = False

        layout = QVBoxLayout(self)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(10)

        self.data = {}
        if os.path.exists(file_path):
            try:
                self.data, self.trailing_null = load_game_json(file_path)
            except Exception:
                self.data = {}
                self.trailing_null = False

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        content_widget = QWidget()
        form_layout = QFormLayout(content_widget)
        form_layout.setSpacing(12)

        self.inputs = {}
        if isinstance(self.data, dict) and self.data:
            for key, val in self.data.items():
                key_str = str(key)
                formatted_key = key_str.replace('_', ' ')
                if formatted_key:
                    formatted_key = formatted_key[0].upper() + formatted_key[1:]

                line_edit = QLineEdit(str(val))
                form_layout.addRow(QLabel(formatted_key), line_edit)
                self.inputs[key] = (line_edit, type(val))
        else:
            no_data_label = QLabel("No editable keys found in JSON file.")
            no_data_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            form_layout.addRow(no_data_label)

        scroll.setWidget(content_widget)
        layout.addWidget(scroll)

        btn_save = QPushButton("Save and Exit")
        btn_save.setObjectName("Primary")
        btn_save.setFixedHeight(38)
        btn_save.clicked.connect(self.save_and_exit)
        layout.addWidget(btn_save)

    def save_and_exit(self):
        if not self.inputs:
            self.accept()
            return

        new_data = {}
        for key, (line_edit, orig_type) in self.inputs.items():
            text_val = line_edit.text().strip()
            if orig_type is bool:
                val = text_val.lower() in ('true', '1', 'yes')
            elif orig_type is int:
                try:
                    val = int(text_val)
                except ValueError:
                    val = text_val
            elif orig_type is float:
                try:
                    val = float(text_val)
                except ValueError:
                    val = text_val
            else:
                val = text_val
            new_data[key] = val

        try:
            os.makedirs(os.path.dirname(self.file_path), exist_ok=True)
            structured = unflatten_dict(new_data)
            payload = json.dumps(structured, indent=4).encode('utf-8')
            if self.trailing_null:
                payload += b'\x00'
            with open(self.file_path, 'wb') as f:
                f.write(payload)
        except Exception:
            _log_exc("save_and_exit")

        self.accept()

