    def _refresh_archive_tool_status(self):
        saved = load_launcher_settings().get("archive_tool", "")
        self._archive_probe = getattr(self, "_archive_probe", 0) + 1      # a newer refresh makes older results stale
        if not saved:
            # find_tool checks every PATH / install folder (~0.6 s): off the GUI thread, it used to run at startup
            self.archive_tool_status.setText("Detecting 7-Zip / WinRAR...")
            probe = self._archive_probe
            def done(found, probe=probe):
                if probe != self._archive_probe:
                    return
                try:
                    self.archive_tool_status.setText(f"Auto-detected: {found}" if found else
                                                     "No 7-Zip or WinRAR found automatically. Pick the .exe above.")
                except RuntimeError:
                    pass        # Settings page already gone
            worker = TaskWorker(lambda: find_tool(*_SEVENZIP_NAMES, *_UNRAR_NAMES, "WinRAR", "Rar"))
            worker.done.connect(done)
            worker.failed.connect(lambda _e: done(None))
            self._archive_workers = [w for w in getattr(self, "_archive_workers", []) if w.isRunning()] + [worker]
            worker.start()
        elif os.path.isfile(os.path.expandvars(os.path.expanduser(saved))):
            self.archive_tool_status.setText(f"Using: {saved}")
        else:
            self.archive_tool_status.setText("That file doesn't exist. Pick the .exe again.")

    def _save_archive_tool(self, path):
        settings = load_launcher_settings()
        settings["archive_tool"] = (path or "").strip().strip('"')
        save_launcher_settings(settings)
        _TOOL_CACHE.clear()
        self.archive_tool_edit.setText(settings["archive_tool"])
        self._refresh_archive_tool_status()

    def _on_archive_tool_edited(self):
        if self.archive_tool_edit.text().strip().strip('"') != load_launcher_settings().get("archive_tool", ""):
            self._save_archive_tool(self.archive_tool_edit.text())

    def _on_browse_archive_tool(self):
        start = os.environ.get("ProgramFiles", os.path.expanduser("~")) if sys.platform.startswith("win") \
            else os.path.expanduser("~")
        flt = "Programs (*.exe);;All files (*)" if sys.platform.startswith("win") else "All files (*)"
        path, _f = QFileDialog.getOpenFileName(self, "Select 7z.exe / WinRAR.exe / UnRAR.exe", start, flt)
        if path:
            self._save_archive_tool(path)

    def _on_clear_archive_tool(self):
        self._save_archive_tool("")

    def _refresh_library_panel(self):
        invalidate_library_roots()
        combo = self.install_combo
        combo.blockSignals(True)
        combo.clear()
        combo.addItem(f"Launcher folder (default)", DEFAULT_GAMES_DIR)
        known = {os.path.abspath(DEFAULT_GAMES_DIR)}
        for mp in mounted_partitions():
            path = os.path.abspath(partition_library_path(mp))
            try:
                free = shutil.disk_usage(mp).free / 1024 ** 3
                if not (os.access(mp, os.W_OK) or os.path.isdir(path)):
                    continue   # e.g. "/" owned by root: can't create NCZLibrary there
            except OSError:
                continue
            combo.addItem(f"{mp}  \u2022  {free:,.0f} GB free", path)
            known.add(path)
        for extra in load_launcher_settings().get("library_dirs", []):
            if os.path.abspath(extra) not in known:
                combo.addItem(extra, extra)
                known.add(os.path.abspath(extra))
        if os.path.abspath(GAMES_DIR) not in known:
            combo.addItem(GAMES_DIR, GAMES_DIR)
        combo.addItem("Choose another folder...", "")
        idx = combo.findData(GAMES_DIR)
        if idx < 0:
            idx = max(0, min([i for i in range(combo.count()) if combo.itemData(i)
                              and os.path.abspath(combo.itemData(i)) == os.path.abspath(GAMES_DIR)] or [0]))
        combo.setCurrentIndex(idx)
        combo.blockSignals(False)
        found = [r for r in library_roots() if r != os.path.abspath(GAMES_DIR)]
        self.library_status.setText(
            f"New games install to: {GAMES_DIR}" + (("\nAlso scanning: " + ", ".join(found)) if found else ""))

    def _on_install_location_chosen(self, _index):
        path = self.install_combo.currentData()
        if path == "":
            path = QFileDialog.getExistingDirectory(self, "Choose where to install games", os.path.expanduser("~"))
            if not path:
                self._refresh_library_panel()
                return
            if os.path.basename(path.rstrip("/\\")) != LIBRARY_FOLDER_NAME:
                path = os.path.join(path, LIBRARY_FOLDER_NAME)
        try:
            os.makedirs(path, exist_ok=True)
            if not os.access(path, os.W_OK):
                raise PermissionError(path)
        except OSError as e:
            QMessageBox.warning(self, "Game Library",
                                f"Can't use that folder:\n{path}\n\n{e}\n\n"
                                "If it's a partition that isn't yours to write to, mount it with your user's permissions.")
            self._refresh_library_panel()
            return
        settings = load_launcher_settings()
        settings["install_dir"] = "" if os.path.abspath(path) == os.path.abspath(DEFAULT_GAMES_DIR) else path
        extras = settings.setdefault("library_dirs", [])
        if settings["install_dir"] and path not in extras:
            extras.append(path)
        save_launcher_settings(settings)
        apply_install_dir()
        self._refresh_library_panel()

    def _on_add_library_folder(self):
        path = QFileDialog.getExistingDirectory(self, f"Choose a folder that contains installed games",
                                                os.path.expanduser("~"))
        if not path:
            return
        settings = load_launcher_settings()
        extras = settings.setdefault("library_dirs", [])
        if path not in extras:
            extras.append(path)
        save_launcher_settings(settings)
        self._refresh_library_panel()

