# ── Top-left wordmark: the "NCZ Games" lettering (lavender gradient with a thin white outline), recoloured to the current accent.
# The outline (pure white) turns black on light themes. Embedded so there is nothing extra to download.
_NCZ_WORDMARK_B64 = ""
_NCZ_WORDMARK_H = 23                      # height in the top bar (logical pixels)
_ncz_wordmark_cache = {}

def _ncz_wordmark_pixmap(accent, light, dpr=2.0):
    key = (str(accent).lower(), bool(light), dpr)
    if key in _ncz_wordmark_cache:
        return _ncz_wordmark_cache[key]
    import colorsys    # lazy: saves memory/startup until used
    src = QImage.fromData(base64.b64decode(_NCZ_WORDMARK_B64))
    if src.isNull():
        return None
    img = src.convertToFormat(QImage.Format.Format_ARGB32).scaledToHeight(
        int(_NCZ_WORDMARK_H * dpr), Qt.TransformationMode.SmoothTransformation)
    target = QColor(accent)
    if not target.isValid():
        target = QColor("#a666ff")
    tr, tg, tb = target.redF(), target.greenF(), target.blueF()
    th, ts, tv = colorsys.rgb_to_hsv(tr, tg, tb)
    for y in range(img.height()):
        for x in range(img.width()):
            px = img.pixel(x, y)
            a = (px >> 24) & 255
            if a == 0:
                continue
            r, g, b = (px >> 16) & 255, (px >> 8) & 255, px & 255
            t = max(0.0, min(1.0, (min(r, g, b) - 170) / 80.0))       # how white this pixel is (1 = the outline)
            if t < 1.0:                                              # lavender -> accent, keeping the gradient's light / dark steps
                _h, s_, v_ = colorsys.rgb_to_hsv(r / 255.0, g / 255.0, b / 255.0)
                lr, lg, lb = colorsys.hsv_to_rgb(th, min(1.0, max(0.0, ts + (s_ - 0.60))), min(1.0, max(0.0, tv + (v_ - 0.941))))
            else:
                lr = lg = lb = 0.0
            wr, wg, wb = (0.0, 0.0, 0.0) if light else (r / 255.0, g / 255.0, b / 255.0)     # the white part: black on light themes
            R = int(round((lr * (1 - t) + wr * t) * 255))
            G = int(round((lg * (1 - t) + wg * t) * 255))
            B = int(round((lb * (1 - t) + wb * t) * 255))
            img.setPixel(x, y, (a << 24) | (R << 16) | (G << 8) | B)
    pm = QPixmap.fromImage(img)
    pm.setDevicePixelRatio(dpr)
    _ncz_wordmark_cache[key] = pm
    return pm

def _ncz_apply_wordmark(win):
    """Puts the wordmark in the top-left label, in the current accent colour and light / dark mode."""
    app = QApplication.instance()
    light = app.palette().window().color().lightness() >= 128
    accent = THEMES["light" if light else "dark"].get("accent", "#a666ff")
    pm = _ncz_wordmark_pixmap(accent, light)
    if pm is None:
        win.brand_logo.setVisible(False)
        return
    win.brand_logo.setFixedSize(int(round(pm.width() / pm.devicePixelRatio())), int(round(pm.height() / pm.devicePixelRatio())))
    win.brand_logo.setPixmap(pm)
    win.brand_logo.setVisible(True)

def set_windows_taskbar_identity(window):
    """Windows only: makes the taskbar right-click menu show "NCZ Games Launcher" + its icon instead of "Python".
    Needs pywin32 (pip install pywin32); silently does nothing if it's missing."""
    if not sys.platform.startswith("win"):
        return
    try:
        from win32com.propsys import propsys, pscon    # lazy: saves memory/startup until used
        import pythoncom    # lazy: saves memory/startup until used
        target, args, _workdir = get_launch_command()
        command = subprocess.list2cmdline([target] + list(args))
        icon = prepare_shortcut_icon()
        store = propsys.SHGetPropertyStoreForWindow(int(window.winId()), propsys.IID_IPropertyStore)

        def put(key, text):
            store.SetValue(key, propsys.PROPVARIANTType(text, pythoncom.VT_LPWSTR))

        put(pscon.PKEY_AppUserModel_ID, "NCZ.GamesLauncher")                 # same ID as in main()
        put(pscon.PKEY_AppUserModel_RelaunchCommand, command)                # required, or the two below are ignored
        put(pscon.PKEY_AppUserModel_RelaunchDisplayNameResource, "NCZ Games Launcher")
        if icon:
            put(pscon.PKEY_AppUserModel_RelaunchIconResource, f"{icon},0")
        store.Commit()
    except Exception:    # expected: optional module may be missing
        pass

UPDATE_URL_WIN = "https://raw.githubusercontent.com/justmm33/FNaNCZ-AE-Releases/refs/heads/main/build/NCZ%20Games%20Launcher.exe"
UPDATE_URL_DEB = "https://raw.githubusercontent.com/justmm33/FNaNCZ-AE-Releases/refs/heads/main/build/ncz-games-launcher_7.0_all.deb"
UPDATE_URL_ARCH = "https://raw.githubusercontent.com/justmm33/FNaNCZ-AE-Releases/refs/heads/main/build/ncz-games-launcher-7.0-1-any.pkg.tar.zst"
UPDATE_URL_FALLBACK = "https://github.com/justmm33/FNaNCZ-AE-Releases/tree/main/build"


def _launcher_update_url():
    """Download link for the current platform (Windows exe, Debian/Ubuntu .deb, Arch package)."""
    if sys.platform.startswith("win"):
        return UPDATE_URL_WIN
    if sys.platform.startswith("linux"):
        ids = set()
        try:
            with open("/etc/os-release", encoding="utf-8") as f:
                for line in f:
                    k, _, v = line.strip().partition("=")
                    if k in ("ID", "ID_LIKE"):
                        ids.update(v.strip().strip('"').lower().split())
        except OSError:    # expected: file may not exist yet or be unreadable
            pass
        if ids & {"arch", "manjaro", "endeavouros", "cachyos", "garuda", "artix"}:
            return UPDATE_URL_ARCH
        if ids & {"debian", "ubuntu", "linuxmint", "pop", "zorin", "elementary", "kali", "raspbian"}:
            return UPDATE_URL_DEB
    return UPDATE_URL_FALLBACK


