_original_get_steam_download_link = get_steam_download_link

def _patched_get_steam_download_link(appid):
    if not FIREBASE_DB_URL:
        return None, 0
    base = FIREBASE_DB_URL.strip().rstrip("/")
    url = f"{base}/steam_links/{appid}.json"
    try:
        data = _http_json(url, "GET")
        if isinstance(data, dict):
            link = data.get("link") or data.get("url") or data.get("download_link")
            cover_url = data.get("cover_url")
            size_val = data.get("size") or data.get("file_size") or data.get("bytes") or data.get("length") or 0
            try:
                size = int(size_val)
            except (TypeError, ValueError):
                size = 0
            
            if cover_url and isinstance(cover_url, str):
                try:
                    req = urllib.request.Request(cover_url, headers={'User-Agent': 'Mozilla/5.0'})
                    with urllib.request.urlopen(req, timeout=10, context=_NCZ_SSL_CTX) as resp:
                        img_data = resp.read()
                    os.makedirs(get_library_cover_dir(), exist_ok=True)
                    local_path = os.path.join(get_library_cover_dir(), f"{appid}.img")
                    with open(local_path, 'wb') as f:
                        f.write(img_data)
                except Exception:    # expected: offline or the server did not answer
                    pass

            if isinstance(link, str) and link.strip():
                return link.strip(), size
    except Exception:    # expected: offline or the server did not answer
        pass
    return _original_get_steam_download_link(appid)

get_steam_download_link = _patched_get_steam_download_link

def _is_landscape_image(path):
    """True for a wide picture (Steam's header art), which looks wrong as a vertical library cover."""
    try:
        img = QImage(path)
        return (not img.isNull()) and img.width() > img.height() * 1.2
    except Exception:
        return False

class _LibCoverBus(QObject):
    ready = pyqtSignal(int, str)        # appid, saved cover path

def _lib_fill_missing_covers(app):
    """Library games with no cover (never had one, or the file is gone) get one the same way the Store does:
    SteamGridDB, then Steam's own art, then whatever the store page lists. The card is rebuilt once it arrives."""
    bus = _LibCoverBus(app)
    app._lib_cover_bus = bus

    def apply(appid, path):
        games = load_steam_library()
        title = ""
        for g in games:
            if g["appid"] == appid:
                g["cover"] = path
                title = g["title"]
        if not title:
            return
        save_steam_library(games)
        if appid in app.steam_cards:
            _rebuild_steam_card_in_place(app, appid, title, path)
            app.apply_filter()
    bus.ready.connect(apply)

    def work():
        for g in load_steam_library():
            cover = g.get("cover") or ""
            have = bool(cover and os.path.exists(cover))
            if have and not _is_landscape_image(cover):
                continue                    # a vertical cover already: nothing to do
            appid = g["appid"]
            local = os.path.join(get_library_cover_dir(), f"{appid}.img")
            if not os.path.exists(local) or _is_landscape_image(local):
                try:
                    data = _fetch_library_cover_bytes(appid, g["title"])      # vertical art only
                    if not data:
                        continue        # keep a landscape cover rather than none
                    os.makedirs(get_library_cover_dir(), exist_ok=True)
                    with open(local, "wb") as f:
                        f.write(data)
                except Exception:
                    continue
            try:
                bus.ready.emit(appid, local)
            except RuntimeError:        # expected: the window was closed meanwhile
                return
    threading.Thread(target=work, daemon=True).start()

_original_build_library_page = AdaptiveApp.build_library_page

def _patched_build_library_page(self):
    widget = _original_build_library_page(self)
    
    def fetch_missing_covers():
        for game in load_steam_library():
            appid = game["appid"]
            local_cover = os.path.join(get_library_cover_dir(), f"{appid}.img")
            if not os.path.exists(local_cover) and FIREBASE_DB_URL:
                try:
                    base = FIREBASE_DB_URL.strip().rstrip("/")
                    url = f"{base}/steam_links/{appid}.json"
                    data = _http_json(url, "GET")
                    if isinstance(data, dict):
                        cover_url = data.get("cover_url")
                        if cover_url and isinstance(cover_url, str):
                            req = urllib.request.Request(cover_url, headers={'User-Agent': 'Mozilla/5.0'})
                            with urllib.request.urlopen(req, timeout=10, context=_NCZ_SSL_CTX) as resp:
                                img_data = resp.read()
                            os.makedirs(get_library_cover_dir(), exist_ok=True)
                            with open(local_cover, 'wb') as f:
                                f.write(img_data)
                except Exception:    # expected: offline or the server did not answer
                    pass

    threading.Thread(target=fetch_missing_covers, daemon=True).start()
    try:
        _lib_fill_missing_covers(self)
    except Exception:
        _log_exc("_patched_build_library_page")
    return widget

AdaptiveApp.build_library_page = _patched_build_library_page    # kept as patch chain: a replacement patch sits in the middle of the chain, so it is not a plain wrapper chain

COMPAT_CONFIG_FILE = os.path.abspath(os.path.join(os.path.dirname(__file__), "steam_compat_config.json"))

def load_compat_config():
    if os.path.exists(COMPAT_CONFIG_FILE):
        try:
            with open(COMPAT_CONFIG_FILE) as f:
                data = json.load(f)
                if isinstance(data, dict):
                    return data
        except Exception:    # expected: file may not exist yet or be unreadable
            pass
    return {}

def save_compat_config(config):
    try:
        with open(COMPAT_CONFIG_FILE, 'w') as f:
            json.dump(config, f, indent=2)
    except Exception:    # expected: file may not exist yet or be unreadable
        pass

def get_available_compatibility_tools():
    tools = {}
    base_paths = [
        os.path.expanduser("~/.local/share/Steam/compatibilitytools.d"),
        os.path.expanduser("~/.steam/root/compatibilitytools.d"),
        os.path.expanduser("~/.local/share/Steam/steamapps/common"),
        os.path.expanduser("~/.steam/steam/steamapps/common")
    ]
    for base in base_paths:
        if os.path.exists(base):
            try:
                for entry in os.listdir(base):
                    full_path = os.path.join(base, entry)
                    if os.path.isdir(full_path):
                        proton_bin = os.path.join(full_path, "proton")
                        if os.path.exists(proton_bin):
                            tools[entry] = proton_bin
            except Exception:    # expected: file may not exist yet or be unreadable
                pass
    for name, wine_bin in wine_installed_builds().items():
        tools[f"{name} (Wine)"] = wine_bin
    return tools

class GameDownloadWorker(QThread):
    progress = pyqtSignal(object, object, float)
    status_update = pyqtSignal(str)
    finished = pyqtSignal(str)
    failed = pyqtSignal(str)

    def __init__(self, game_id, title, version_url, linux_cmd, existing_zip_path=None, wine_extract_dir=None, download_only=False):
        super().__init__()
        self.game_id = game_id
        self.title = title
        self.version_url = version_url
        self.linux_cmd = linux_cmd
        self.existing_zip_path = existing_zip_path
        self.wine_extract_dir = wine_extract_dir
        self.download_only = download_only
        self.remote_version = ""
        self._is_cancelled = False
        self._response = None

    def cancel(self):
        self._is_cancelled = True
        if self._response:
            try:
                self._response.close()
            except Exception:    # expected: cleanup that may already be done
                pass

    # run() is _new_game_worker_run, assigned further down


class DownloadCard(QFrame):
    CARD_W, CARD_H = 60, 90

    def __init__(self, title, download_url, expected_size=0, cover_path="", parent=None, worker=None, existing_zip_path=None):
        super().__init__(parent)
        self.setObjectName("Panel")
        self.setFixedHeight(120)
        self.title = title
        
        main_layout = QHBoxLayout(self)
        main_layout.setContentsMargins(14, 12, 14, 12)
        main_layout.setSpacing(14)

        self.cover = QLabel()
        self.cover.setObjectName("CoverPlaceholder")
        self.cover.setFixedSize(self.CARD_W, self.CARD_H)
        self.cover.setAlignment(Qt.AlignmentFlag.AlignCenter)
        if cover_path and os.path.exists(cover_path):
            pix = rounded_cover_pixmap(cover_path, self.CARD_W, self.CARD_H, 6)
            if pix:
                self.cover.setPixmap(pix)
            else:
                self.cover.setText("No\nCover")
        else:
            self.cover.setText("No\nCover")
        main_layout.addWidget(self.cover)

        layout = QVBoxLayout()
        layout.setSpacing(6)

        top_row = QHBoxLayout()
        self.title_label = QLabel(title)
        self.title_label.setObjectName("RowTitle")
        self.status_label = QLabel("Connecting...")
        self.status_label.setObjectName("RowDesc")
        top_row.addWidget(self.title_label, 1)
        top_row.addWidget(self.status_label, 0, Qt.AlignmentFlag.AlignRight)
        layout.addLayout(top_row)

        self.progress_bar = QProgressBar()
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.progress_bar.setTextVisible(False)
        layout.addWidget(self.progress_bar)

        bottom_row = QHBoxLayout()
        self.info_label = QLabel("Speed: 0 KB/s | 0 MB / 0 MB")
        self.info_label.setObjectName("RowDesc")
        bottom_row.addWidget(self.info_label, 1)
        
        self.state = "active"   # active (incl. paused) / done / failed
        self.pause_btn = QPushButton("Pause")
        self.pause_btn.setFixedSize(80, 28)
        self.pause_btn.clicked.connect(self.toggle_pause)
        bottom_row.addWidget(self.pause_btn)

        self.action_btn = QPushButton("Cancel")
        self.action_btn.setFixedSize(80, 28)
        self.action_btn.clicked.connect(self.cancel_download)
        bottom_row.addWidget(self.action_btn)
        self.clear_btn = QPushButton("Clear")
        self.clear_btn.setFixedSize(80, 28)
        self.clear_btn.setToolTip("Remove this card from the list")
        self.clear_btn.clicked.connect(self.clear_card)
        self.clear_btn.hide()   # shown once the download is finished or failed (Cancel covers running ones)
        bottom_row.addWidget(self.clear_btn)
        layout.addLayout(bottom_row)

        main_layout.addLayout(layout, 1)

        if worker is not None:
            self.worker = worker
        else:
            self.worker = FirebaseDownloadWorker(title, download_url, expected_size, existing_zip_path=existing_zip_path)
            
        if not hasattr(self.worker, "pause"):
            self.pause_btn.hide()
        self.worker.progress.connect(self.on_progress)
        self.worker.status_update.connect(self.on_status_update)
        self.worker.finished.connect(self.on_finished)
        self.worker.failed.connect(self.on_failed)
        self.worker.start()

    def clear_card(self):
        parent = self.parentWidget()
        self.setParent(None)
        self.deleteLater()
        page = parent
        while page is not None and not hasattr(page, "empty_label"):
            page = page.parentWidget()
        try:
            lay = getattr(page, "container_layout", None)
            if page is not None and lay is not None and not any(
                    isinstance(lay.itemAt(i).widget(), DownloadCard) for i in range(lay.count())):
                page.empty_label.show()
        except Exception:
            _log_exc("clear_card")

    def toggle_pause(self):
        if not hasattr(self.worker, "pause"):
            return
        if getattr(self.worker, "_paused", False):
            self.worker.resume()
            self.pause_btn.setText("Pause")
        else:
            self.worker.pause()
            self.pause_btn.setText("Resume")
            self.status_label.setText("Paused")

    def cancel_download(self):
        if hasattr(self.worker, "cancel"):
            self.worker.cancel()
        file_name = f"{re.sub(r'[^a-zA-Z0-9_-]', '_', self.title)}.zip"
        dest_path = os.path.abspath(os.path.join(DOWNLOAD_DIR, file_name))
        if os.path.exists(dest_path):
            try:
                os.remove(dest_path)
            except Exception:    # expected: cleanup that may already be done
                pass
        self.setParent(None)
        self.deleteLater()

    def on_status_update(self, message):
        self.status_label.setText(message)

    def on_progress(self, downloaded, total, speed):
        speed_str = f"{speed / 1024:.1f} KB/s" if speed < 1024 * 1024 else f"{speed / (1024 * 1024):.2f} MB/s"

        if total > 0:
            percent = int((downloaded / total) * 100)
            self.progress_bar.setValue(percent)
            self.status_label.setText(f"{percent}%")
            self.info_label.setText(f"Speed: {speed_str} | {_fmt_size(downloaded)} / {_fmt_size(total)}")
        else:
            self.progress_bar.setRange(0, 0)
            self.status_label.setText("Downloading...")
            self.info_label.setText(f"Speed: {speed_str} | Downloaded: {_fmt_size(downloaded)}")

    def on_finished(self, zip_path):
        self.state = "done"
        self.pause_btn.hide()
        self.status_label.setText("Installed")
        self.status_label.setStyleSheet(f"color: {GREEN};")
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(100)
        self.action_btn.setText("Open Folder")
        self.clear_btn.show()
        try:
            self.action_btn.clicked.disconnect()
        except Exception:    # expected: cleanup that may already be done
            pass
        self.action_btn.clicked.connect(lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(GAMES_DIR)))

    def on_failed(self, error_msg):
        if error_msg == "CANCELLED":
            self.setParent(None)
            self.deleteLater()
            return
        self.state = "failed"
        self.pause_btn.hide()
        self.status_label.setText("Game is unreleased" if error_msg.strip() == "Game is unreleased" else "Failed")
        self.status_label.setStyleSheet(f"color: {RED};")
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.action_btn.setText("Copy Error")
        self.clear_btn.show()
        try:
            self.action_btn.clicked.disconnect()
        except Exception:    # expected: cleanup that may already be done
            pass
        self.action_btn.clicked.connect(lambda: QApplication.clipboard().setText(error_msg))

class GameDownloadCard(DownloadCard):
    def __init__(self, game_id, title, version_url, linux_cmd, expected_size=0, cover_path="", parent=None, existing_zip_path=None, wine_extract_dir=None):
        worker = GameDownloadWorker(game_id, title, version_url, linux_cmd, existing_zip_path, wine_extract_dir)
        super().__init__(title, "", expected_size, cover_path, parent, worker=worker)


# ── free Steam games: downloaded straight from Steam with DepotDownloader ──
_dd_free_cache = {}

def steam_game_is_free(appid):
    """True when Steam lists this app as a free game, False when it isn't, None when we can't tell (offline etc.)."""
    if appid in _dd_free_cache:
        return _dd_free_cache[appid]
    free = None
    # the store API is rate limited (the Store page asks it for prices all the time), so one failed answer isn't final:
    # try again with another region before giving up
    for extra in ("", "&cc=us"):
        try:
            raw = _http_get(f"https://store.steampowered.com/api/appdetails?appids={appid}&l=english{extra}",
                            headers=_ART_COOKIE, timeout=12)
            entry = json.loads(raw.decode("utf-8", errors="replace")).get(str(appid)) or {}
            info = entry.get("data")
            if not entry.get("success") or not isinstance(info, dict):
                continue
            free = bool(info.get("is_free")) and info.get("type", "game") == "game"
            break
        except Exception as e:
            _ncz_log(f"free check for {appid} failed: {e!r}")
    if free is None:
        return None
    _dd_free_cache[appid] = free
    return free

def _dd_dir():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "depotdownloader")

def _dd_command():
    """Command prefix that runs DepotDownloader, or None if it isn't installed yet.
    Order: path set in launcher settings ("depotdownloader_path"), our own copy, then PATH."""
    custom = (load_launcher_settings().get("depotdownloader_path") or "").strip()
    if custom and os.path.isfile(custom):
        return [custom] if not custom.lower().endswith(".dll") else ["dotnet", custom]
    exe_name = "DepotDownloader.exe" if sys.platform.startswith("win") else "DepotDownloader"
    for folder, _d, files in os.walk(_dd_dir()):
        if exe_name in files:
            return [os.path.join(folder, exe_name)]
        if "DepotDownloader.dll" in files and shutil.which("dotnet"):
            return ["dotnet", os.path.join(folder, "DepotDownloader.dll")]
    found = shutil.which("DepotDownloader") or shutil.which("depotdownloader")
    return [found] if found else None

def _dd_install(status=lambda _m: None):
    """Downloads the latest DepotDownloader release for this OS from GitHub into the launcher folder."""
    import zipfile
    machine = platform.machine().lower()
    arm = "arm" in machine or "aarch" in machine
    if sys.platform.startswith("win"):
        tag = "windows-arm64" if arm else "windows-x64"
    elif sys.platform.startswith("linux"):
        tag = "linux-arm64" if arm else "linux-x64"
    else:
        tag = "macos-arm64" if arm else "macos-x64"
    status("Getting DepotDownloader...")
    release = json.loads(_http_get("https://api.github.com/repos/SteamRE/DepotDownloader/releases/latest",
                                   headers={"Accept": "application/vnd.github+json"}, timeout=20).decode("utf-8"))
    asset = next((a for a in release.get("assets", []) if tag in a.get("name", "").lower()
                  and a["name"].lower().endswith(".zip")), None)
    if not asset:
        raise RuntimeError(f"No DepotDownloader build for {tag} in the latest release.")
    data = _http_get(asset["browser_download_url"], timeout=120)
    target = _dd_dir()
    shutil.rmtree(target, ignore_errors=True)
    os.makedirs(target, exist_ok=True)
    zip_path = os.path.join(target, "dd.zip")
    with open(zip_path, "wb") as f:
        f.write(data)
    with zipfile.ZipFile(zip_path) as z:
        z.extractall(target)
    os.remove(zip_path)
    if not sys.platform.startswith("win"):
        for folder, _d, files in os.walk(target):
            for n in files:
                if n == "DepotDownloader":
                    os.chmod(os.path.join(folder, n), 0o755)

_DD_PCT_RE = re.compile(r"^\s*(\d{1,3}(?:\.\d+)?)%\s")

class DepotDownloadWorker(QThread):
    progress = pyqtSignal(object, object, float)    # downloaded bytes, total bytes (0 = not known yet), bytes/s
    status_update = pyqtSignal(str)
    finished = pyqtSignal(str)
    failed = pyqtSignal(str)

    def __init__(self, appid, title):
        super().__init__()
        self.appid = int(appid)
        self.title = title
        self.game_exe = None
        self._is_cancelled = False
        self._paused = False
        self._proc = None

    def _signal_proc(self, suspend):
        proc = self._proc
        if proc is None or proc.poll() is not None:
            return
        try:
            if sys.platform.startswith("win"):
                import ctypes    # lazy: saves memory/startup until used
                handle = ctypes.windll.kernel32.OpenProcess(0x0800, False, proc.pid)   # PROCESS_SUSPEND_RESUME
                if handle:
                    (ctypes.windll.ntdll.NtSuspendProcess if suspend else ctypes.windll.ntdll.NtResumeProcess)(handle)
                    ctypes.windll.kernel32.CloseHandle(handle)
            else:
                import signal
                os.kill(proc.pid, signal.SIGSTOP if suspend else signal.SIGCONT)
        except Exception:
            _log_exc("DepotDownloadWorker._signal_proc")

    def pause(self):
        self._paused = True
        self._signal_proc(True)

    def resume(self):
        self._paused = False
        self._signal_proc(False)

    def cancel(self):
        self._is_cancelled = True
        if self._paused:
            self.resume()
        proc = self._proc
        if proc is not None and proc.poll() is None:
            try:
                proc.terminate()
            except Exception:    # expected: it may have just exited
                pass

    def run(self):
        dest = installed_game_dir(sanitize_folder_name(self.title))
        created = not os.path.isdir(dest)
        try:
            cmd = _dd_command()
            if cmd is None:
                _dd_install(self.status_update.emit)
                cmd = _dd_command()
            if cmd is None:
                raise RuntimeError("DepotDownloader isn't installed and couldn't be set up "
                                   "(on Linux it needs the .NET runtime if the download isn't self-contained).")
            if self._is_cancelled:
                raise RuntimeError("CANCELLED")
            os.makedirs(dest, exist_ok=True)
            self.status_update.emit("Starting...")
            flags = 0x08000000 if sys.platform.startswith("win") else 0       # no console window
            self._proc = subprocess.Popen(
                cmd + ["-app", str(self.appid), "-os", "windows", "-dir", dest, "-max-downloads", "16"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, encoding="utf-8", errors="replace",
                bufsize=1, creationflags=flags, cwd=dest)
            tail = []
            # DepotDownloader prints "<overall %> <file>" as files complete but never says how many bytes there are, so the
            # total is estimated: sizes of the files listed so far divided by the percentage reached.
            done_before, started, samples = 0, time.time(), []
            for line in self._proc.stdout:
                line = line.rstrip()
                if not line:
                    continue
                tail.append(line)
                del tail[:-25]
                m = _DD_PCT_RE.match(line)
                if not m:
                    continue
                pct = min(100.0, float(m.group(1)))
                try:
                    path = line.split("%", 1)[1].strip()
                    size = os.path.getsize(path if os.path.isabs(path) else os.path.join(dest, path))
                except (OSError, IndexError):
                    size = 0
                done_before += size
                if pct < 0.5 or done_before <= 0:
                    self.progress.emit(0, 0, 0.0)       # still unknown: the card shows an indeterminate bar
                    continue
                total = done_before / (pct / 100.0)
                got = done_before
                now = time.time()
                samples.append((now, got))
                del samples[:-12]
                t0, b0 = samples[0]
                speed = (got - b0) / (now - t0) if now - t0 >= 1.0 else got / max(now - started, 1e-6)
                self.progress.emit(got, total, max(speed, 0.0))
            code = self._proc.wait()
            if self._is_cancelled:
                raise RuntimeError("CANCELLED")
            text = "\n".join(tail)
            if code != 0:
                low = text.lower()
                if any(s in low for s in ("not available from this account", "no subscription",
                                          "access denied", "accessdenied", "requires login", "not owned")):
                    raise RuntimeError("Steam won't let an anonymous account download this game.\n" + text)
                raise RuntimeError(text or f"DepotDownloader exited with code {code}.")
            got_files = any(n != ".DepotDownloader" for n in os.listdir(dest))
            if not got_files:
                raise RuntimeError("DepotDownloader finished but no files were downloaded.\n" + text)
            # same exe detection as the other installs: pick the game's exe (installers / crash handlers skipped) and
            # remember it, so Launch works straight away
            self.game_exe = _find_game_exe(dest) or find_best_game_exe(dest, self.title)
            if self.game_exe:
                record_installed_exe(self.title, self.game_exe)
            try:
                invalidate_library_roots()
            except Exception:
                _log_exc("DepotDownloadWorker.run")
            self.progress.emit(1, 1, 0.0)
            self.finished.emit(dest)
        except Exception as e:
            if self._is_cancelled or str(e) == "CANCELLED":
                if created:
                    shutil.rmtree(dest, ignore_errors=True)
                self.failed.emit("CANCELLED")
                return
            self.failed.emit(str(e))

class DepotDownloadCard(DownloadCard):
    def __init__(self, appid, title, cover_path="", parent=None):
        super().__init__(title, "", 0, cover_path, parent, worker=DepotDownloadWorker(appid, title))

    def on_progress(self, downloaded, total, speed):
        if total <= 0:
            self.progress_bar.setRange(0, 0)
            self.status_label.setText("Downloading...")
            self.info_label.setText("Starting the Steam download...")
            return
        super().on_progress(downloaded, total, speed)       # same bar, percent, speed and MB / MB as the other downloads

    def on_finished(self, path):
        super().on_finished(path)
        if getattr(self.worker, "game_exe", None):
            return
        self.status_label.setText("Game not found")
        if QMessageBox.question(
                self, "Game not found",
                "Download finished, but the launcher couldn't find the game's .exe.\n\n"
                "Do you want to pick it yourself?\n"
                "(You can also use \"Locate Game\" in the game's 3-dot menu.)") == QMessageBox.StandardButton.Yes:
            if locate_installed_game(self, self.title, path):
                self.worker.game_exe = installed_exe_for(self.title)
                self.status_label.setText("Installed")

class _FreeCheckSignal(QObject):
    done = pyqtSignal(object)

def get_custom_games_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "custom_games.json")

def load_custom_games():
    try:
        with open(get_custom_games_path(), encoding="utf-8") as f:
            data = json.load(f)
        return [g for g in data if isinstance(g, dict) and g.get("exe_path")]
    except Exception:
        return []

def save_custom_games(games):
    path = get_custom_games_path()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(games, f, indent=4)

class AddCustomGameDialog(QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Add Custom Game")
        self.setFixedSize(420, 320)
        self.result_data = None

        layout = QVBoxLayout(self)
        layout.setContentsMargins(20, 20, 20, 20)
        layout.setSpacing(12)

        form = QFormLayout()
        form.setSpacing(10)

        self.title_edit = QLineEdit()
        form.addRow(QLabel("Game Title"), self.title_edit)

        exe_layout = QHBoxLayout()
        self.exe_edit = QLineEdit()
        exe_btn = QPushButton("Browse...")
        exe_btn.clicked.connect(self.browse_exe)
        exe_layout.addWidget(self.exe_edit, 1)
        exe_layout.addWidget(exe_btn)
        form.addRow(QLabel("Executable"), exe_layout)

        cover_layout = QHBoxLayout()
        self.cover_edit = QLineEdit()
        cover_btn = QPushButton("Browse...")
        cover_btn.clicked.connect(self.browse_cover)
        cover_layout.addWidget(self.cover_edit, 1)
        cover_layout.addWidget(cover_btn)
        form.addRow(QLabel("Cover Image"), cover_layout)

        if sys.platform.startswith("linux"):
            self.compat_combo = QComboBox()
            self.compat_combo.addItem("Default (System Wine / Native)", "")
            tools = get_available_compatibility_tools()
            for name, path in sorted(tools.items()):
                self.compat_combo.addItem(name, path)
            form.addRow(QLabel("Compatibility Tool"), self.compat_combo)
        else:
            self.compat_combo = None

        layout.addLayout(form)

        btn_layout = QHBoxLayout()
        btn_ok = QPushButton("Add Game")
        btn_ok.setObjectName("Primary")
        btn_cancel = QPushButton("Cancel")
        btn_ok.clicked.connect(self.accept_data)
        btn_cancel.clicked.connect(self.reject)
        btn_layout.addStretch()
        btn_layout.addWidget(btn_cancel)
        btn_layout.addWidget(btn_ok)
        layout.addLayout(btn_layout)

    def browse_exe(self):
        path, _ = QFileDialog.getOpenFileName(self, "Select Executable", os.path.expanduser("~"))
        if path:
            self.exe_edit.setText(path)
            if not self.title_edit.text().strip():
                base = os.path.splitext(os.path.basename(path))[0]
                self.title_edit.setText(base.replace("_", " ").title())

    def browse_cover(self):
        path, _ = QFileDialog.getOpenFileName(self, "Select Cover Image", os.path.expanduser("~"), "Images (*.png *.jpg *.jpeg *.webp)")
        if path:
            self.cover_edit.setText(path)

    def accept_data(self):
        title = self.title_edit.text().strip()
        exe = self.exe_edit.text().strip()
        if not title or not exe or not os.path.exists(exe):
            QMessageBox.warning(self, "Invalid Input", "Please provide a valid game title and existing executable path.")
            return
        cover = self.cover_edit.text().strip()
        compat = self.compat_combo.currentData() if self.compat_combo else ""
        self.result_data = {
            "id": f"custom_{int(time.time())}",
            "title": title,
            "exe_path": exe,
            "cover_path": cover,
            "compat_tool": compat
        }
        self.accept()



def _custom_tool(game_id, fallback=""):
    """The compatibility tool currently saved for a custom game (it can change after the card was built)."""
    for g in load_custom_games():
        if g.get("id") == game_id:
            return g.get("compat_tool", "")
    return fallback



class CompatToolDialog(QDialog):
    def __init__(self, current_tool, tools_dict, parent=None, current_d3d=""):
        super().__init__(parent)
        self.setWindowTitle("Switch Compatibility Tool")
        self.setFixedSize(460, 230)
        
        layout = QVBoxLayout(self)
        layout.setContentsMargins(16, 16, 16, 16)
        layout.setSpacing(12)
        
        layout.addWidget(QLabel("Select Proton / Wine Tool:"))
        
        self.combo = QComboBox()
        self.combo.addItem("Default (System Wine / Auto)", "")
        
        self.tools_map = tools_dict
        sorted_tools = sorted(tools_dict.keys())
        
        idx = 0
        for i, name in enumerate(sorted_tools):
            self.combo.addItem(name, tools_dict[name])
            if tools_dict[name] == current_tool:
                idx = i + 1
        self.combo.setCurrentIndex(idx)
        layout.addWidget(self.combo)

        layout.addWidget(QLabel("Direct3D renderer (Wine / Proton):"))
        self.d3d_combo = QComboBox()
        self.d3d_combo.addItem("Launcher setting", "")
        for mode, label in WINE_D3D_MODES.items():
            if mode != "default":
                self.d3d_combo.addItem(label, mode)
        self.d3d_combo.setCurrentIndex(max(0, self.d3d_combo.findData(current_d3d)))
        layout.addWidget(self.d3d_combo)
        
        btn_layout = QHBoxLayout()
        btn_ok = QPushButton("OK")
        btn_ok.setObjectName("Primary")
        btn_cancel = QPushButton("Cancel")
        btn_ok.clicked.connect(self.accept)
        btn_cancel.clicked.connect(self.reject)
        btn_layout.addStretch()
        btn_layout.addWidget(btn_cancel)
        btn_layout.addWidget(btn_ok)
        layout.addLayout(btn_layout)

    def get_selected(self):
        return self.combo.currentData()

    def get_d3d(self):
        return self.d3d_combo.currentData() or ""

def prompt_compat_tool(app, current="", current_d3d=""):
    """Asks which compatibility tool and Direct3D renderer to use.
    Returns (tool path or '' for default, renderer or '' for the launcher setting), or None if cancelled."""
    dlg = CompatToolDialog(current, get_available_compatibility_tools(), app, current_d3d)
    if dlg.exec() != int(QDialog.DialogCode.Accepted):
        return None
    return dlg.get_selected() or "", dlg.get_d3d()

def save_game_d3d(key, mode):
    config = load_compat_config()
    if mode:
        config["d3d:" + key] = mode
    else:
        config.pop("d3d:" + key, None)
    save_compat_config(config)

def find_existing_archive(prefixes):
    if not os.path.isdir(DOWNLOAD_DIR):
        return None
    for f in sorted(os.listdir(DOWNLOAD_DIR)):
        if f.lower().endswith((".zip", ".rar")) and f.lower().startswith(prefixes):
            return os.path.join(DOWNLOAD_DIR, f)
    return None

# ── finding archive tools (7-Zip / WinRAR aren't on PATH on Windows) ──
_ARCHIVE_DIR_RE = re.compile(r"7-?zip|7z|winrar|rarlab|roshal|unrar|peazip|nanazip|bandizip|p7zip", re.I)
_ARCHIVE_APP_RE = re.compile(r"7-?zip|winrar|unrar|peazip|nanazip|bandizip", re.I)
_TOOL_CACHE = {}        # names -> (time found, [paths])
_FOLDER_CACHE = {"t": 0.0, "folders": []}
_TOOL_MISS_TTL = 60     # a "not found" is re-checked after this many seconds (the user may have just installed it)
_FOLDER_TTL = 120

def _exe_dir_from_command(cmd):
    """'"C:\\Program Files\\7-Zip\\7zFM.exe" "%1"' / 'C:\\x\\WinRAR.exe,0' -> the folder of that exe."""
    if not cmd:
        return None
    cmd = os.path.expandvars(str(cmd).strip())
    m = re.match(r'\s*"([^"]+)"', cmd) or re.match(r'\s*(.+?\.(?:exe|dll|ico))', cmd, re.I) or re.match(r'\s*([^,\s]+)', cmd)
    if not m:
        return None
    p = m.group(1).strip().strip('"')
    if os.path.isdir(p):
        return p
    d = os.path.dirname(p)
    return d if d and os.path.isdir(d) else None

def _windows_tool_folders():
    folders = []
    env = os.environ.get
    prog_roots = [env(k) for k in ("ProgramFiles", "ProgramW6432", "ProgramFiles(x86)", "ProgramData")]
    user_roots = [env("LOCALAPPDATA") and os.path.join(env("LOCALAPPDATA"), "Programs"), env("LOCALAPPDATA"), env("APPDATA"),
                  env("USERPROFILE")]
    # every fixed drive: people install to D:\Program Files, D:\Apps, ...
    for letter in "CDEFGHIJKLMNOPQRSTUVWXYZAB":
        drive = letter + ":\\"
        if os.path.isdir(drive):
            prog_roots += [os.path.join(drive, s) for s in
                           ("Program Files", "Program Files (x86)", "Programs", "Apps", "Software", "Tools", "Portable", "")]
    subs = ("7-Zip", "7-Zip-Zstandard", "7-Zip (Zstandard)", "7zip", "7z", "7-Zip-ZS", "WinRAR", "RAR", "UnRAR", "RARLAB",
            "NanaZip", "PeaZip", "Bandizip", "Portable7-Zip", "7-ZipPortable", "WinRARPortable",
            os.path.join("PeaZip", "res", "bin", "7z"), os.path.join("PeaZip", "res", "7z"),
            os.path.join("7-ZipPortable", "App", "7-Zip64"), os.path.join("7-ZipPortable", "App", "7-Zip"))
    for root in filter(None, prog_roots + user_roots):
        for sub in subs:
            folders.append(os.path.join(root, sub))
    # package managers
    home = env("USERPROFILE") or os.path.expanduser("~")
    local = env("LOCALAPPDATA") or ""
    scoops = [env("SCOOP"), os.path.join(home, "scoop"), env("SCOOP_GLOBAL"), os.path.join(env("ProgramData") or "C:\\ProgramData", "scoop")]
    for sc in filter(None, scoops):
        folders.append(os.path.join(sc, "shims"))
        for app in ("7zip", "7zip-zstd", "winrar", "unrar", "peazip", "nanazip", "bandizip"):
            folders.append(os.path.join(sc, "apps", app, "current"))
    choco = env("ChocolateyInstall") or os.path.join(env("ProgramData") or "C:\\ProgramData", "chocolatey")
    folders.append(os.path.join(choco, "bin"))
    import glob    # lazy: saves memory/startup until used
    for pattern in (os.path.join(choco, "lib", "*7zip*", "tools"), os.path.join(choco, "lib", "*winrar*", "tools"),
                    os.path.join(choco, "lib", "*unrar*", "tools"), os.path.join(choco, "lib", "*peazip*", "tools"),
                    os.path.join(local, "Microsoft", "WinGet", "Packages", "*7zip*"),
                    os.path.join(local, "Microsoft", "WinGet", "Packages", "*NanaZip*"),
                    os.path.join(local, "Microsoft", "WinGet", "Packages", "*WinRAR*"),
                    os.path.join(local, "Microsoft", "WinGet", "Packages", "*RARLab*")):
        try:
            folders += glob.glob(pattern)
        except Exception:
            _log_exc("_windows_tool_folders")
    folders += [os.path.join(local, "Microsoft", "WinGet", "Links"), os.path.join(local, "Microsoft", "WindowsApps")]
    # the registry: install keys, App Paths, uninstall entries and file associations
    try:
        import winreg    # lazy: optional module: the except below handles it missing
        views = (0, getattr(winreg, "KEY_WOW64_64KEY", 0), getattr(winreg, "KEY_WOW64_32KEY", 0))
        value_names = ("Path64", "Path", "exe64", "exe32", "InstallLocation", "InstallDir", "InstallPath")
        for hive in (winreg.HKEY_LOCAL_MACHINE, winreg.HKEY_CURRENT_USER):
            for key in (r"SOFTWARE\7-Zip", r"SOFTWARE\7-Zip-Zstandard", r"SOFTWARE\WinRAR", r"SOFTWARE\RARLAB",
                        r"SOFTWARE\WOW6432Node\7-Zip", r"SOFTWARE\WOW6432Node\WinRAR", r"SOFTWARE\Giorgiotani\Peazip",
                        r"SOFTWARE\Bandizip", r"SOFTWARE\NanaZip"):
                for view in views:
                    try:
                        with winreg.OpenKey(hive, key, 0, winreg.KEY_READ | view) as k:
                            for val in value_names:
                                try:
                                    d = _exe_dir_from_command(winreg.QueryValueEx(k, val)[0])
                                except OSError:
                                    continue
                                if d:
                                    folders.append(d)
                    except OSError:
                        _log_exc("_windows_tool_folders")
            apps = r"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths"
            for exe in ("WinRAR.exe", "UnRAR.exe", "Rar.exe", "7zFM.exe", "7z.exe", "7zG.exe", "PeaZip.exe", "NanaZip.exe", "Bandizip.exe"):
                for view in views:
                    try:
                        with winreg.OpenKey(hive, apps + "\\" + exe, 0, winreg.KEY_READ | view) as k:
                            for val in ("", "Path"):
                                try:
                                    d = _exe_dir_from_command(winreg.QueryValueEx(k, val)[0])
                                except OSError:
                                    continue
                                if d:
                                    folders.append(d)
                    except OSError:
                        _log_exc("_windows_tool_folders")
            # Add/Remove Programs entries that look like an archiver
            unin = r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"
            for sub in (unin, r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"):
                try:
                    with winreg.OpenKey(hive, sub, 0, winreg.KEY_READ) as parent:
                        i = 0
                        while True:
                            try:
                                name = winreg.EnumKey(parent, i)
                            except OSError:
                                break
                            i += 1
                            try:
                                with winreg.OpenKey(parent, name) as k:
                                    try:
                                        shown = str(winreg.QueryValueEx(k, "DisplayName")[0])
                                    except OSError:
                                        shown = name
                                    if not _ARCHIVE_APP_RE.search(shown) and not _ARCHIVE_APP_RE.search(name):
                                        continue
                                    for val in ("InstallLocation", "DisplayIcon", "UninstallString"):
                                        try:
                                            d = _exe_dir_from_command(winreg.QueryValueEx(k, val)[0])
                                        except OSError:
                                            continue
                                        if d:
                                            folders.append(d)
                            except OSError:
                                continue
                except OSError:
                    _log_exc("_windows_tool_folders")
        for cls in (r"WinRAR\shell\open\command", r"7-Zip.7z\shell\open\command", r"7-Zip.zip\shell\open\command",
                    r"WinRAR.RAR\shell\open\command", r"WinRAR.ZIP\shell\open\command",
                    r"Applications\7zFM.exe\shell\open\command", r"Applications\WinRAR.exe\shell\open\command"):
            try:
                with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT, cls) as k:
                    d = _exe_dir_from_command(winreg.QueryValueEx(k, "")[0])
                    if d:
                        folders.append(d)
            except OSError:
                _log_exc("_windows_tool_folders")
    except ImportError:    # expected: optional module may be missing
        pass
    # last resort: look at what's actually inside the install roots (odd names like "7-Zip 24.09" or "RARLAB\\WinRAR"),
    # two levels deep at most so this stays quick
    scan_roots = [r for r in prog_roots + user_roots[:2] if r and os.path.isdir(r)]
    for root in scan_roots:
        try:
            with os.scandir(root) as it:
                for e in it:
                    try:
                        if not e.is_dir(follow_symlinks=False):
                            continue
                    except OSError:
                        continue
                    if _ARCHIVE_DIR_RE.search(e.name):
                        folders.append(e.path)
                        continue
                    if root.endswith("") and e.name.lower() in ("rarlab", "alexander roshal", "igor pavlov", "giorgiotani"):
                        try:
                            with os.scandir(e.path) as it2:
                                for e2 in it2:
                                    if e2.is_dir(follow_symlinks=False):
                                        folders.append(e2.path)
                        except OSError:
                            _log_exc("_windows_tool_folders")
        except OSError:
            continue
    return folders

def _tool_folders(force=False):
    """Every folder worth looking in for 7-Zip / WinRAR / unrar & co.; cached for a couple of minutes."""
    if not force and _FOLDER_CACHE["folders"] and time.time() - _FOLDER_CACHE["t"] < _FOLDER_TTL:
        return _FOLDER_CACHE["folders"]
    folders = []
    for getter in (_bundled_dir, _writable_dir):
        try:
            folders.append(getter())
        except Exception:
            _log_exc("_tool_folders")
    for base in (ASSETS_DIR, os.path.join(SCRIPT_DIR, "tools"), SCRIPT_DIR):
        folders.append(base)
        for sub in ("7z", "7-Zip", "7zip", "WinRAR", "unrar", "tools", "bin"):
            folders.append(os.path.join(base, sub))
    if sys.platform.startswith("win"):
        try:
            folders += _windows_tool_folders()
        except Exception:
            _log_exc("_tool_folders")
    else:
        home = os.path.expanduser("~")
        folders += ["/usr/bin", "/usr/local/bin", "/opt/homebrew/bin", "/opt/local/bin", "/snap/bin",
                    "/var/lib/flatpak/exports/bin", "/run/current-system/sw/bin", "/usr/lib/p7zip", "/usr/libexec/p7zip",
                    os.path.join(home, ".local", "bin"), os.path.join(home, "bin"), os.path.join(home, ".nix-profile", "bin"),
                    "/Applications/Keka.app/Contents/Resources", "/Applications/The Unarchiver.app/Contents/Resources"]
    seen, out = set(), []
    for f in folders:
        if not f:
            continue
        key = os.path.normcase(os.path.normpath(f))
        if key in seen or not os.path.isdir(f):
            continue
        seen.add(key)
        out.append(f)
    _FOLDER_CACHE["t"], _FOLDER_CACHE["folders"] = time.time(), out
    return out

def find_all_tools(*names, refresh=False):
    """Every distinct copy of the named tools we can find: PATH first, then next to the launcher, the usual install
    folders on every drive, package managers (Scoop / Chocolatey / WinGet), and the Windows registry."""
    key = tuple(n.lower() for n in names)
    hit = _TOOL_CACHE.get(key)
    if not refresh and hit and (hit[1] or time.time() - hit[0] < _TOOL_MISS_TTL):
        return [p for p in hit[1] if os.path.isfile(p)] or []
    found, seen = [], set()

    def add(path):
        k = os.path.normcase(os.path.realpath(path))
        if k not in seen and os.path.isfile(path):
            seen.add(k)
            found.append(path)

    for n in names:
        w = shutil.which(n)
        if w:
            add(w)
    exts = ("", ".exe", ".cmd", ".bat") if sys.platform.startswith("win") else ("",)
    for folder in _tool_folders(force=refresh):
        for n in names:
            for ext in exts:
                add(os.path.join(folder, n + ext))
    _TOOL_CACHE[key] = (time.time(), list(found))
    return found

def find_tool(*names):
    """Full path of the first tool found, or None."""
    found = find_all_tools(*names)
    return found[0] if found else None

_SEVENZIP_NAMES = ("7z", "7za", "7zz", "7zr", "NanaZipC", "7z-zstd", "7zG-console")
_UNRAR_NAMES = ("unrar", "UnRAR", "unrar-free", "unrar-nonfree")

def get_custom_archive_tool():
    """The 7-Zip / WinRAR exe the user picked in Settings (or None if unset / the file is gone)."""
    try:
        p = load_launcher_settings().get("archive_tool", "")
    except Exception:
        return None
    p = os.path.expandvars(os.path.expanduser((p or "").strip().strip('"')))
    return p if p and os.path.isfile(p) else None

def _custom_tool_attempts(tool, path, out_dir):
    """Command lines for the exe the user picked by hand. We don't know which tool it is, so go by its name and then
    try the other style too. Several ways of passing the destination, because WinRAR is picky about paths with
    spaces and trailing backslashes."""
    folder, base = os.path.split(tool)
    low = base.lower()
    attempts = []
    sevenzip = [tool, "x", "-y", f"-o{out_dir}", path]
    rar_cwd = ([tool, "x", "-y", "-ibck", path], out_dir)               # extracts into the working directory
    rar_op = [tool, "x", "-y", "-ibck", f"-op{out_dir}", path]
    rar_slash = [tool, "x", "-y", "-ibck", path, out_dir + os.sep]
    if low.startswith(("7zfm", "7zg", "7-zip")) and not low.startswith("7zg-console"):
        # 7zFM.exe / 7zG.exe are GUI programs: the command-line one (7z.exe) sits next to them
        for cli in ("7z.exe", "7zz.exe", "7za.exe", "7z", "7zz"):
            c = os.path.join(folder, cli)
            if os.path.isfile(c):
                attempts.append([c, "x", "-y", f"-o{out_dir}", path])
                break
        attempts.append(sevenzip)
    elif low.startswith(("7z", "nanazip", "peazip")):
        attempts.append(sevenzip)
    elif low.startswith(("winrar", "rar", "unrar")):
        # WinRAR.exe is the GUI one; Rar.exe / UnRAR.exe next to it are console versions that are even more reliable
        for cli in ("UnRAR.exe", "Rar.exe", "unrar"):
            c = os.path.join(folder, cli)
            if os.path.isfile(c) and os.path.normcase(c) != os.path.normcase(tool):
                attempts += [[c, "x", "-y", f"-op{out_dir}", path], ([c, "x", "-y", path], out_dir)]
        attempts += [rar_cwd, rar_op, rar_slash]
    else:
        attempts += [sevenzip, rar_cwd, rar_op]
    return attempts

_LAST_EXTRACT_ERROR = {"msg": ""}

def _extraction_attempts(path, out_dir, rar=True):
    attempts = []
    custom = get_custom_archive_tool()
    if custom:
        attempts += _custom_tool_attempts(custom, path, out_dir)         # the user's own pick always goes first
    for exe in find_all_tools(*_SEVENZIP_NAMES):        # every copy: if one can't do the format, the next might
        attempts.append([exe, "x", "-y", f"-o{out_dir}", path])
    if rar:
        for unrar in find_all_tools(*_UNRAR_NAMES):
            attempts.append([unrar, "x", "-y", path, out_dir + os.sep])
        for winrar in find_all_tools("WinRAR", "Rar"):
            attempts.append([winrar, "x", "-y", "-ibck", path, out_dir + os.sep])
    for unar in find_all_tools("unar"):
        attempts.append([unar, "-f", "-o", out_dir, path])
    for tar in find_all_tools("bsdtar", "tar"):         # Windows 10+ ships a tar.exe that can read rar and 7z
        attempts.append([tar, "-xf", path, "-C", out_dir])
    return attempts

def _extract_with_tools(path, out_dir, rar=True):
    """Tries every extractor we can find. Returns True on success."""
    os.makedirs(out_dir, exist_ok=True)
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    _LAST_EXTRACT_ERROR["msg"] = ""

    def _cmd_of(a):
        return a[0] if isinstance(a, tuple) else a

    attempts = _extraction_attempts(path, out_dir, rar)
    if not any(os.path.basename(_cmd_of(c)[0]).lower().startswith(("7z", "nanazip", "unrar", "winrar", "rar", "unar"))
               for c in attempts):
        # nothing archive-specific found: rescan from scratch (they may have installed 7-Zip / WinRAR a minute ago)
        _TOOL_CACHE.clear()
        _FOLDER_CACHE["t"] = 0.0
        attempts = _extraction_attempts(path, out_dir, rar)
    for attempt in attempts:
        cmd, cwd = attempt if isinstance(attempt, tuple) else (attempt, None)
        try:
            res = subprocess.run(cmd, capture_output=True, timeout=3600, creationflags=flags, cwd=cwd)
            if res.returncode == 0:
                return True
            out = (res.stderr or res.stdout or b"").decode("utf-8", "replace").strip()
            _LAST_EXTRACT_ERROR["msg"] = f"{os.path.basename(cmd[0])} exited with code {res.returncode}" + \
                                         (f": {out[-300:]}" if out else "")
        except Exception as e:
            _LAST_EXTRACT_ERROR["msg"] = f"{os.path.basename(cmd[0])}: {e}"
            continue
    return False

def extract_archive(dest_path, extract_dir):
    os.makedirs(extract_dir, exist_ok=True)
    if zipfile.is_zipfile(dest_path):
        with zipfile.ZipFile(dest_path, 'r') as zip_ref:
            zip_ref.extractall(extract_dir)
        return

    is_rar = dest_path.lower().endswith('.rar')
    if not is_rar:
        try:
            with open(dest_path, 'rb') as f:
                if f.read(7).startswith(b'Rar!\x1a\x07'):
                    is_rar = True
        except Exception:    # expected: file may not exist yet or be unreadable
            pass

    if is_rar:
        if _extract_with_tools(dest_path, extract_dir):
            return
        try:  # last resort: the rarfile package, pointed at whatever extractor we found
            import rarfile    # lazy: saves memory/startup until used
            for attr, names in (("UNRAR_TOOL", ("unrar", "UnRAR")), ("SEVENZIP_TOOL", ("7z", "7za", "7zz")),
                                ("UNAR_TOOL", ("unar",)), ("BSDTAR_TOOL", ("bsdtar", "tar"))):
                found = find_tool(*names)
                if found and hasattr(rarfile, attr):
                    setattr(rarfile, attr, found)
            custom = get_custom_archive_tool()
            if custom:
                low = os.path.basename(custom).lower()
                attr = "SEVENZIP_TOOL" if low.startswith(("7z", "nanazip", "peazip")) else "UNRAR_TOOL"
                if hasattr(rarfile, attr):
                    setattr(rarfile, attr, custom)
            with rarfile.RarFile(dest_path) as rf:
                rf.extractall(extract_dir)
            return
        except Exception:    # expected: optional module may be missing
            pass
        if sys.platform.startswith("win"):
            hint = "Install 7-Zip (7-zip.org) or WinRAR, then try again. If it's already installed, reinstall it so it's registered."
        else:
            hint = "Install 7-Zip (p7zip) or unrar."
        if get_custom_archive_tool():
            hint = "The 7-Zip/WinRAR you picked in Settings couldn't open it. Check that it's the right .exe, or try the other one."
        elif load_launcher_settings().get("archive_tool"):
            hint = "The 7-Zip/WinRAR path set in Settings doesn't exist any more. Pick it again in Settings."
        detail = _LAST_EXTRACT_ERROR.get("msg")
        raise ValueError("RAR archive detected, but no extraction tool could open it. " + hint +
                         (f"\n\nLast error: {detail}" if detail else ""))

    raise ValueError("Downloaded file is neither a valid ZIP nor a supported RAR archive.")





class FirebaseDownloadWorker(QThread):
    progress = pyqtSignal(object, object, float)
    status_update = pyqtSignal(str)
    finished = pyqtSignal(str)
    failed = pyqtSignal(str)

    def __init__(self, title, download_url, expected_size=0, existing_zip_path=None):
        super().__init__()
        self.title = title
        self.download_url = download_url
        self.expected_size = expected_size
        self.existing_zip_path = existing_zip_path
        self._is_cancelled = False
        self._response = None

    def cancel(self):
        self._is_cancelled = True
        if self._response:
            try:
                self._response.close()
            except Exception:    # expected: cleanup that may already be done
                pass

    # run() is assigned further down (FirebaseDownloadWorker.run = ...)


def safe_filename_from_headers(response, fallback_title, ext=".zip"):
    cd = response.headers.get('Content-Disposition')
    raw_name = ""
    if cd:
        for part in cd.split(';'):
            part = part.strip()
            if part.lower().startswith('filename='):
                raw_name = part.split('=', 1)[1].strip()
                if raw_name.startswith('"') and raw_name.endswith('"'):
                    raw_name = raw_name[1:-1]
                elif raw_name.startswith("'") and raw_name.endswith("'"):
                    raw_name = raw_name[1:-1]
                break
    
    if not raw_name:
        url_path = urllib.parse.unquote(response.geturl().split('?')[0])
        raw_name = os.path.basename(url_path)
    
    if not raw_name or not raw_name.lower().endswith(('.zip', '.rar')):
        safe_title_clean = re.sub(r'[<>:"/\\|?*]', '_', fallback_title)
        raw_name = f"{safe_title_clean}{ext}"
    
    # Final cleanup of illegal Windows characters
    return re.sub(r'[<>:"/\\|?*]', '_', raw_name).strip()

# Let's cleanly patch FirebaseDownloadWorker.run to use safe_filename_from_headers
def _new_fb_run(self):
    dest_path = None
    try:
        total_size = self.expected_size
        if total_size <= 0 and not self._is_cancelled:
            try:
                head_req = urllib.request.Request(self.download_url, method='HEAD', headers={'User-Agent': 'Mozilla/5.0'})
                with urllib.request.urlopen(head_req, timeout=10, context=_NCZ_SSL_CTX) as head_resp:
                    total_size = int(head_resp.headers.get('Content-Length', 0))
            except Exception:    # expected: offline or the server did not answer
                pass

        if self._is_cancelled:
            self.failed.emit("CANCELLED")
            return

        ext = ".rar" if self.download_url.lower().endswith('.rar') else ".zip"
        headers = {'User-Agent': 'Mozilla/5.0'}
        dest_path = resumable_download(
            self, lambda: (self.download_url, headers),
            lambda response, url: safe_filename_from_headers(response, self.title, ext), total_size)

        if self._is_cancelled:
            if dest_path and os.path.exists(dest_path):
                try:
                    os.remove(dest_path)
                except Exception:    # expected: cleanup that may already be done
                    pass
            self.failed.emit("CANCELLED")
            return

        self.status_update.emit("Extracting...")
        safe_title = sanitize_folder_name(self.title)
        extract_dir = installed_game_dir(safe_title)
        extract_archive(dest_path, extract_dir)

        if self._is_cancelled:
            self.failed.emit("CANCELLED")
            return

        self.finished.emit(dest_path)
    except Exception as e:
        if self._is_cancelled:
            self.failed.emit("CANCELLED")
        else:
            self.failed.emit(str(e))

FirebaseDownloadWorker.run = _new_fb_run

# --- Firebase games: find the real file link with a hidden Playwright browser, then download it normally ---
# Every game except Five Nights at NCZ / NCZFront opens PW_BASE_URL + game-slug (e.g. .../dying-light-the-beast).
# Playwright clicks through to the file host, copies the final download link (plus the cookies the host needs),
# cancels the browser's own download, and the launcher's normal downloader fetches that link.
PW_BASE_URL = "https://steamrip.com/"                   # <-- server 1 (direct download): change this
PW_BASE_URL_2 = "https://fitgirl-repacks.site/"                # <-- server 2 (magnet -> torrent): change this
PW_BASE_URL_3 = "https://ankergames.net/game/"                        # <-- server 3 (Download x2, captcha, direct download): change this
PW_MAGNET_TEXT = r"\[?\s*magnet\s*\]?"                    # label of the magnet button on a server 2 game page
PW_BUTTON_TEXT = "DOWNLOAD HERE"                       # button on the game page
PW_BLOCKED_HOSTS = ("megadb.net",)           # buttons leading here are skipped for the next DOWNLOAD HERE button
PW_RELAY_HOSTS = ("filecrypt.cc",)                     # link-container sites: you solve the captcha in the browser window
PW_RELAY_BUTTONS = 'button.download, a.download, [onclick*="openLink"]'  # link buttons on the container page
PW_ALLOWED_HOSTS = ("gofile.io", "bzzhr.to", "pixeldrain.com", "itsfileditchfiles.st")           # file hosts; PW_BASE_URL's site is allowed too, anything else is closed
PW_HEADLESS = True                                     # True hides the browser; it only pops up while you solve a captcha
PW_USER_AGENT = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
                 "Chrome/124.0.0.0 Safari/537.36")

# ── "Ask every time": pick the server in a popup for each download ──
PW_SERVER_NAMES = {"1": ("SteamRIP", "direct download"), "2": ("FitGirl", "repacked torrent"),
                   "3": ("AnkerGames", "direct download after a captcha")}

def _pw_probe_server(title, sid):
    """Does this server have the game? 'ok', '404' (not there) or 'unknown' (blocked / offline / couldn't tell)."""
    try:
        req = urllib.request.Request(pw_game_url(title, sid), headers={"User-Agent": PW_USER_AGENT})
        with urllib.request.urlopen(req, timeout=15, context=_NCZ_SSL_CTX) as r:
            r.read(1)
        return "ok"
    except urllib.error.HTTPError as e:
        return "404" if e.code in (404, 410) else "unknown"     # 403 etc. (captcha walls) are not proof the game is missing
    except Exception:
        return "unknown"

class _ServerPickDialog(QDialog):
    probed = pyqtSignal(str, str)

    def __init__(self, parent, title):
        super().__init__(parent)
        self.setWindowTitle("Choose download server")
        self.setModal(True)
        self.setMinimumWidth(440)
        self.chosen = ""
        self.title_text = title
        lay = QVBoxLayout(self)
        lay.setSpacing(10)
        head = QLabel(f"Where do you want to download {title} from?")
        head.setObjectName("RowTitle")
        head.setWordWrap(True)
        lay.addWidget(head)
        self.btns = {}
        for sid, (name, desc) in PW_SERVER_NAMES.items():
            b = QPushButton(f"{name}\n{desc}  -  checking...")
            b.setMinimumHeight(56)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.setStyleSheet("QPushButton:disabled { color: #777777; }")
            b.clicked.connect(lambda _=False, i=sid: self._pick(i))
            lay.addWidget(b)
            self.btns[sid] = b
        cancel = QPushButton("Cancel")
        cancel.clicked.connect(self.reject)
        lay.addWidget(cancel)
        self.probed.connect(self._on_probed)
        for sid in self.btns:
            threading.Thread(target=self._probe, args=(sid,), daemon=True).start()

    def _probe(self, sid):
        state = _pw_probe_server(self.title_text, sid)
        try:
            self.probed.emit(sid, state)
        except RuntimeError:
            pass      # the popup was closed already

    def _on_probed(self, sid, state):
        b = self.btns[sid]
        name, desc = PW_SERVER_NAMES[sid]
        if state == "404":
            b.setText(f"{name}\nNot found (404)")
            b.setEnabled(False)            # greyed out
        elif state == "ok":
            b.setText(f"{name}\n{desc}  -  available")
        else:
            b.setText(f"{name}\n{desc}  -  couldn't check")

    def _pick(self, sid):
        self.chosen = sid
        self.accept()

class _ServerAsker(QObject):
    request = pyqtSignal(object, object, object)      # title, result box, done event

    def __init__(self):
        super().__init__()
        self.request.connect(self._show)              # created in the GUI thread, so _show runs there

    def _show(self, title, box, ev):
        try:
            dlg = _ServerPickDialog(QApplication.activeWindow(), title)
            if dlg.exec() == QDialog.DialogCode.Accepted:
                box["v"] = dlg.chosen
        except Exception:
            _log_exc("_show")
        finally:
            ev.set()

_PW_ASKER = _ServerAsker()

# kept: used at import time before the later definition at line 31965
def _pw_ask_server(worker):
    """Called from the download thread: shows the popup in the GUI thread and waits for the pick."""
    box, ev = {"v": ""}, threading.Event()
    _PW_ASKER.request.emit(worker.title, box, ev)
    while not ev.wait(0.3):
        if worker.__dict__.get("_cancel_flag"):
            raise RuntimeError("CANCELLED")
    if box["v"] not in ("1", "2", "3"):
        raise RuntimeError("CANCELLED")
    return box["v"]


_fb_direct_run = FirebaseDownloadWorker.run  # previous behaviour, still used for the NCZ games

# Games whose page on PW_BASE_URL doesn't match their title: (regex on the lowercase title, slug to use instead).
PW_SLUG_OVERRIDES = (
    (r"dying light (2|two)\b.*", "dying-l-two-stay-human"),                    # any edition of Dying Light 2
    (r"dying light( the following)?( enhanced edition)?", "dying-light-the-following"),
    (r"risk of rain (2|two)\b.*", "risk-of-rain-two"),
)

# Server 3 has its own, shorter list (servers 1 and 2 keep PW_SLUG_OVERRIDES above).
PW_SLUG_OVERRIDES_3 = (
    (r"dying light (2|two)\b.*", "dying-light-2-stay-human"),                    # any edition of Dying Light 2
)

_pw_tls = threading.local()      # the server picked in the "Ask every time" popup, per download thread

# kept: used at import time before the later definition at line 31959
def pw_server():
    v = getattr(_pw_tls, "server", None)
    if v in ("1", "2", "3"):
        return v
    v = load_launcher_settings().get("download_server")
    return v if v in ("2", "3") else "1"     # "ask" is resolved per download before anything calls this

def pw_game_url(title, server=None):
    base = {"2": PW_BASE_URL_2, "3": PW_BASE_URL_3}.get(server or pw_server(), PW_BASE_URL)
    t = title.lower().replace("'", "")
    plain = re.sub(r"\s+", " ", re.sub(r"[^a-z0-9]+", " ", t)).strip()
    for pattern, slug in (PW_SLUG_OVERRIDES_3 if base == PW_BASE_URL_3 else PW_SLUG_OVERRIDES):
        if re.fullmatch(pattern, plain):
            return base.rstrip("/") + "/" + slug
    if base == PW_BASE_URL_3:      # server 3: an apostrophe counts as a space (five-nights-at-freddy-s)
        t = title.lower().replace("\u2019", "'").replace("'", " ")
    slug = re.sub(r"[^a-z0-9]+", "-", t).strip("-")
    return base.rstrip("/") + "/" + slug

# Describes the block around a DOWNLOAD HERE button (its label, logo, link...): which host does it mention?
PW_LABEL_JS = r"""el => {
    const hits = n => ((n.innerText || "").toLowerCase().split("download here").length - 1);
    let node = el;
    for (let i = 0; i < 4; i++) {
        const p = node.parentElement;
        if (!p || p === document.body || hits(p) > 1) break;
        node = p;
    }
    const h = node.outerHTML;
    return {mega: /mega\s*-?db/i.test(h), bzzhr: /bzzhr/i.test(h), gofile: /go\s*-?file/i.test(h), pixeldrain: /pixel\s*-?drain/i.test(h), fileditch: /file\s*-?ditch/i.test(h)};
}"""

def _pw_host_ok(url, hosts):
    if not url or url.startswith(("about:", "blob:", "data:", "magnet:")):
        return True
    host = (urllib.parse.urlparse(url).hostname or "").lower()
    return any(host == h or host.endswith("." + h) for h in hosts if h)

def _pw_on(url, hosts):
    """Strict version of _pw_host_ok: the page really is on one of these hosts (about:blank doesn't count)."""
    host = (urllib.parse.urlparse(url or "").hostname or "").lower()
    return any(host == h or host.endswith("." + h) for h in hosts if h)

def _pw_captcha_shown(pg):
    loc = pg.locator('iframe[src*="captcha"], .captcha, #captcha, [class*="captcha"], input[name*="captcha"]')
    try:
        return any(loc.nth(i).is_visible() for i in range(min(loc.count(), 10)))
    except Exception:
        return False

def _pw_wait_captcha(self, pg):
    self.status_update.emit("Solve the captcha in the browser window...")
    try:
        pg.bring_to_front()
    except Exception:
        _log_exc("_pw_wait_captcha")
    deadline = time.time() + 600
    while _pw_captcha_shown(pg):
        if self._is_cancelled:
            raise RuntimeError("CANCELLED")
        if time.time() > deadline:
            raise RuntimeError("The captcha wasn't solved in time.")
        pg.wait_for_timeout(1000)
    pg.wait_for_timeout(1500)

def _pw_pick_link(self, context, tab):
    """Presses the Download buttons on a container page until one reaches a file host; returns that tab."""
    self.status_update.emit("Pressing Download...")
    btns = tab.locator(PW_RELAY_BUTTONS)
    if btns.count() == 0:  # fall back to anything that just says "Download"
        btns = tab.get_by_text(re.compile(r"^\s*download\s*$", re.IGNORECASE))
    for i in range(btns.count()):
        try:
            with context.expect_page(timeout=10000) as info:
                btns.nth(i).click()
            new = info.value
            end = time.time() + 20
            while time.time() < end and not new.is_closed():
                if _pw_on(new.url, PW_ALLOWED_HOSTS):
                    return new
                new.wait_for_timeout(500)
        except Exception:
            tab.wait_for_timeout(500)
    return None

def _pw_through_relay(self, context, tab, p):
    """Container page (filecrypt.cc): you solve the captcha, Download is pressed on that same page, and the
    file-host link it opens is used. With PW_HEADLESS the captcha window is a temporary visible browser; once
    the link is found it closes and the hidden browser carries on from there."""
    tab.wait_for_timeout(3000)  # let the captcha load
    if not _pw_captcha_shown(tab):
        return _pw_pick_link(self, context, tab)
    if not PW_HEADLESS:
        _pw_wait_captcha(self, tab)
        return _pw_pick_link(self, context, tab)
    vb = p.chromium.launch(headless=False, args=["--disable-blink-features=AutomationControlled"])
    try:
        vctx = vb.new_context(user_agent=PW_USER_AGENT)
        vctx.add_cookies(context.cookies())
        vtab = vctx.new_page()
        _pw_guard(vctx, vtab)
        vtab.goto(tab.url, timeout=60000)
        vtab.wait_for_timeout(3000)
        if _pw_captcha_shown(vtab):
            _pw_wait_captcha(self, vtab)
        found = _pw_pick_link(self, vctx, vtab)
        if not found:
            return None
        final_url = found.url
        context.add_cookies(vctx.cookies())
    finally:
        vb.close()
    self.status_update.emit("Captcha solved, continuing in the background...")
    page = context.new_page()
    page.goto(final_url, timeout=60000)
    return page

def _pw_guard(context, page):
    """Watches every tab: a popup that lands anywhere unexpected is closed, the main tab is sent back."""
    allowed = (urllib.parse.urlparse(PW_BASE_URL).hostname, urllib.parse.urlparse(PW_BASE_URL_2).hostname) + tuple(PW_ALLOWED_HOSTS) + tuple(PW_RELAY_HOSTS)
    state = {"closed": 0, "blocked": [], "allow": set()}  # extra tabs closed so far, the blocked URLs, hosts allowed later
    def ok(url):
        return _pw_host_ok(url, allowed + tuple(state["allow"]))
    def watch(pg):
        if pg is not page:
            pg.on("close", lambda _p=None: state.__setitem__("closed", state["closed"] + 1))
        def on_nav(frame):
            if frame != pg.main_frame or ok(frame.url):
                return
            state["blocked"].append(frame.url)
            try:
                if pg is page:
                    pg.go_back()
                else:
                    pg.close()
            except Exception:    # expected: cleanup that may already be done
                pass
        pg.on("framenavigated", on_nav)
        if pg is not page and not ok(pg.url):  # popup that was already on a bad site
            state["blocked"].append(pg.url)
            try:
                pg.close()
            except Exception:    # expected: cleanup that may already be done
                pass
    watch(page)
    context.on("page", watch)
    return state

PW_MEGADB = ("megadb.net",)

def _pw_find_visible(pg, rx):
    """First visible button / link / plain text on the page (any frame) whose text matches rx, else None."""
    for fr in pg.frames:
        for loc in (fr.get_by_role("button", name=rx), fr.get_by_role("link", name=rx), fr.get_by_text(rx)):
            try:
                for i in range(min(loc.count(), 10)):
                    if loc.nth(i).is_visible():
                        return loc.nth(i)
            except Exception:
                continue
    return None

def _pw_visible_labels(pg):
    out = []
    try:
        loc = pg.locator("button, a, input[type=submit], input[type=button]")
        for i in range(min(loc.count(), 40)):
            el = loc.nth(i)
            if el.is_visible():
                t = (el.inner_text() or el.get_attribute("value") or "").strip().replace("\n", " ")
                if t:
                    out.append(t[:30])
    except Exception:    # expected: cleanup that may already be done
        pass
    return out[:10]

def _pw_press(el):
    try:
        el.click(timeout=5000)
    except Exception:
        try:
            el.click(timeout=3000, force=True)   # something (an ad overlay) is on top of it
        except Exception:
            el.evaluate("e => e.click()")

def _pw_megadb_button(self, pg, guard):
    """MegaDB page: press DOWNLOAD, then return the DOWNLOAD NOW button once it shows up."""
    first_rx = re.compile(r"^\s*(free\s+)?download\s*$", re.IGNORECASE)
    now_rx = re.compile(r"^\s*(free\s+)?download\s*now\s*$", re.IGNORECASE)
    self.status_update.emit("MegaDB: looking for the DOWNLOAD button...")
    deadline = time.time() + 60
    pressed, seen_closed = False, guard["closed"]
    while True:
        if self._is_cancelled:
            raise RuntimeError("CANCELLED")
        now = _pw_find_visible(pg, now_rx)
        if now is not None:
            return now
        if time.time() > deadline:
            raise RuntimeError(f"Couldn't find the MegaDB download button on {pg.url}. "
                               f"Buttons on the page: {', '.join(_pw_visible_labels(pg)) or 'none'}")
        if not pressed or guard["closed"] > seen_closed:  # first time, or an ad tab ate the click
            seen_closed = guard["closed"]
            first = _pw_find_visible(pg, first_rx)
            if first is not None:
                self.status_update.emit("MegaDB: pressing DOWNLOAD...")
                _pw_press(first)
                pressed = True
        pg.wait_for_timeout(500)

def _pw_is_ncz(title):
    t = title.lower()
    return "five nights at ncz" in t or "nczfront" in t

def _pw_find_link(self, start_url):
    """Returns (download_url, headers) copied from the browser."""
    try:
        from playwright.sync_api import sync_playwright    # lazy: optional module: the except below handles it missing
    except ImportError:
        raise RuntimeError("Playwright isn't installed. Run: pip install playwright && playwright install chromium")
    with sync_playwright() as p:
        self.status_update.emit("Starting browser...")
        browser = p.chromium.launch(headless=PW_HEADLESS, args=["--disable-blink-features=AutomationControlled"])
        try:
            context = browser.new_context(user_agent=PW_USER_AGENT)
            page = context.new_page()
            guard = _pw_guard(context, page)
            self.status_update.emit("Opening download page...")
            page.goto(start_url, timeout=60000)
            try:
                self._pw_build = parse_build(page.title())   # "(game) ... (Build 123)" -> 123
            except Exception:
                self._pw_build = ""

            target = None
            idx, bad, order = 0, set(), None  # idx = which DOWNLOAD HERE button to click; bad = ones to skip (MegaDB)
            mega_only = False                 # every DOWNLOAD HERE button is MegaDB, so MegaDB is used after all
            for attempt in range(1, 11):
                if self._is_cancelled:
                    raise RuntimeError("CANCELLED")
                self.status_update.emit(f"Finding download link (attempt {attempt})...")
                blocked_before = len(guard["blocked"])
                tab = None
                try:
                    buttons = page.get_by_text(PW_BUTTON_TEXT, exact=False)
                    n = buttons.count()
                    if n and order is None:  # BZZHR is preferred, then GoFile, then whatever is left; MegaDB is skipped
                        flags = [buttons.nth(i).evaluate(PW_LABEL_JS) for i in range(n)]
                        if all(f["mega"] for f in flags):
                            mega_only = True
                            guard["allow"].update(PW_MEGADB)
                            self.status_update.emit("MegaDB is the only option, using it...")
                        else:
                            bad |= {i for i, f in enumerate(flags) if f["mega"]}
                        order = ([i for i, f in enumerate(flags) if f["bzzhr"]] +
                                 [i for i, f in enumerate(flags) if f["pixeldrain"]] +
                                 [i for i, f in enumerate(flags) if f["gofile"]] +
                                 [i for i, f in enumerate(flags) if f.get("fileditch")] + list(range(n)))
                        if any(f["bzzhr"] for f in flags):
                            self.status_update.emit("Found a BZZHR button, using it...")
                        elif any(f["pixeldrain"] for f in flags):
                            self.status_update.emit("No BZZHR button, using Pixeldrain...")
                        elif any(f["gofile"] for f in flags):
                            self.status_update.emit("No BZZHR or Pixeldrain button, using GoFile...")
                        elif any(f.get("fileditch") for f in flags):
                            self.status_update.emit("No BZZHR, Pixeldrain or GoFile button, using Fileditch...")
                    idx = next((i for i in (order or range(n)) if i not in bad), None) if n else 0
                    if idx is None:
                        raise RuntimeError("No other DOWNLOAD HERE button found.")
                    with context.expect_page(timeout=10000) as info:
                        buttons.nth(idx).click()
                    tab = info.value
                    tab.wait_for_load_state("domcontentloaded")
                    if _pw_on(tab.url, PW_RELAY_HOSTS):
                        target = _pw_through_relay(self, context, tab, p)
                        if target:
                            break
                    elif _pw_on(tab.url, PW_ALLOWED_HOSTS):
                        target = tab
                        break
                    elif mega_only:
                        end = time.time() + 15
                        while time.time() < end and not tab.is_closed() and not _pw_on(tab.url, PW_MEGADB):
                            tab.wait_for_timeout(500)
                        if _pw_on(tab.url, PW_MEGADB):
                            target = tab
                            break
                    if not tab.is_closed():
                        tab.close()
                except RuntimeError:
                    raise
                except Exception:
                    page.wait_for_timeout(1000)
                blocked_hosts = () if mega_only else PW_BLOCKED_HOSTS
                if any(h in u for u in guard["blocked"][blocked_before:] for h in blocked_hosts) or \
                        (tab is not None and any(h in (tab.url or "") for h in blocked_hosts)):
                    self.status_update.emit("Got a blocked site, trying a different DOWNLOAD HERE button...")
                    bad.add(idx)
            if not target:
                raise RuntimeError("Couldn't reach a valid download link.")

            if _pw_on(target.url, ("itsfileditchfiles.st",)):
                # Fileditch has a Cloudflare check that blocks Playwright's Chromium, so (like server 3) the page is
                # opened in your own browser; you pass the check, "⬇️ Download" is pressed for you, the launcher takes the link.
                fd_url = target.url
                try:
                    target.close()
                except Exception:    # expected: cleanup that may already be done
                    pass
                self.status_update.emit("Fileditch has a Cloudflare check, opening it in your browser...")
                return _pw_s3_capture_in_browser(self, fd_url, auto_click=True)
            self.status_update.emit("Getting file link...")
            mega = _pw_on(target.url, PW_MEGADB)
            if mega:
                btn = _pw_megadb_button(self, target, guard)
            elif "gofile.io" in target.url or "pixeldrain.com" in target.url:
                btn = target.get_by_role("button", name=re.compile("Download", re.IGNORECASE)).first
            else:
                btn = target.get_by_text("Download File", exact=False).first
            btn.wait_for(state="visible", timeout=30000)
            if "bzzhr.to" in target.url or mega:
                # Ads open in new tabs and get closed; click Download File again every time one closes.
                got = {}
                target.on("download", lambda d: got.setdefault("d", d))
                seen = guard["closed"]
                btn.click()
                deadline = time.time() + 90
                while "d" not in got and time.time() < deadline:
                    if self._is_cancelled:
                        raise RuntimeError("CANCELLED")
                    target.wait_for_timeout(300)
                    if guard["closed"] > seen:
                        seen = guard["closed"]
                        self.status_update.emit("Ad tab closed, clicking Download File again...")
                        try:
                            btn.click()
                        except Exception:
                            _log_exc("_pw_find_link")
                if "d" not in got:
                    raise RuntimeError("The download didn't start.")
                download = got["d"]
            else:
                with target.expect_download(timeout=60000) as dl_info:
                    btn.click()
                download = dl_info.value
            url = download.url
            cookies = "; ".join(f"{c['name']}={c['value']}" for c in context.cookies(url))
            try:
                download.cancel()  # the launcher downloads it itself
            except Exception:    # expected: offline or the server did not answer
                pass
            headers = {"User-Agent": PW_USER_AGENT, "Referer": target.url}
            if cookies:
                headers["Cookie"] = cookies
            return url, headers
        finally:
            browser.close()

# ── build numbers (server 1 update check) ──
_BUILD_RX = re.compile(r"\(?\bbuild\s*#?\s*([0-9][\w.\-]*)", re.IGNORECASE)

def parse_build(text):
    m = _BUILD_RX.search(text or "")
    return m.group(1) if m else ""

def installed_builds_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "installed_builds.json")

def _load_installed_builds():
    try:
        with open(installed_builds_path(), encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def get_installed_build(title):
    data = _load_installed_builds()
    return data.get(title) or data.get(sanitize_folder_name(title)) or ""

def record_installed_build(title, build):
    if not build:
        return
    with _versions_lock:
        data = _load_installed_builds()
        data[title] = build
        data[sanitize_folder_name(title)] = build
        path = installed_builds_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)
        os.replace(tmp, path)

# Server 3 shows the version in a green box ("V 19i") above the first Download button.
_S3_VER_BOX_RX = re.compile(r">\s*V\s*([0-9][\w.\-]*)\s*<", re.IGNORECASE)                       # <span>V 19i</span>
_S3_VER_TEXT_RX = re.compile(r"\b(?:version|ver\.?)\s*[:#]?\s*v?\s*([0-9][\w.\-]*)", re.IGNORECASE)   # fallback: "Version 19i"
S3_BUILD_PREFIX = "s3:"       # server 3 builds are saved as "s3:19i" so they're never compared with a server 1 build

def parse_s3_version(html):
    """Version from the green box on a server 3 game page ('' if it isn't there)."""
    m = _S3_VER_BOX_RX.search(html or "")
    if not m:
        m = _S3_VER_TEXT_RX.search(re.sub(r"<[^>]+>", " ", html or ""))
    return m.group(1) if m else ""

def build_server(build):
    """Which server a saved build came from: '3' or '1'."""
    return "3" if (build or "").startswith(S3_BUILD_PREFIX) else "1"

def fetch_site_build(title, server="1"):
    """Build number currently shown on the server's page for this game ('' if it can't be read).
    Server 1: the number in the page title. Server 3: the version in the green box (returned as 's3:<version>')."""
    try:
        url = pw_game_url(title, "3" if server == "3" else "1")
        req = urllib.request.Request(url, headers={"User-Agent": PW_USER_AGENT})
        with urllib.request.urlopen(req, timeout=20, context=_NCZ_SSL_CTX) as r:
            html = r.read(400000).decode("utf-8", "ignore")
        if server == "3":
            ver = parse_s3_version(html)
            return S3_BUILD_PREFIX + ver if ver else ""
        m = re.search(r"<title[^>]*>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
        return parse_build(html_lib.unescape(m.group(1))) if m else ""
    except Exception:
        return ""

# ── server 3: Download, Download, then your own browser on a redirect / new tab ──
class _PwRedirect(Exception):
    """The site redirected us off itself or opened a new tab (captcha / verification). args[0] is that page."""

_PW_MAYBE_LATER_RX = re.compile(r"^\s*maybe\s*later\s*$", re.IGNORECASE)

def _pw_s3_dismiss(pg):
    """Clicks a 'Maybe later' button if one is showing. True if one was clicked."""
    try:
        btn = _pw_find_visible(pg, _PW_MAYBE_LATER_RX)
        if btn is not None:
            _pw_press(btn)
            pg.wait_for_timeout(500)
            return True
    except Exception:
        _log_exc("_pw_s3_dismiss")
    return False

def _pw_s3_press_download(pg, exact=False):
    """Presses a Download button. With exact=True only a button whose whole text is 'Download' is pressed
    (nothing like 'Download Now', 'Download Free' or 'Download Manager')."""
    _pw_s3_dismiss(pg)
    rx = re.compile(r"^\s*download\s*$" if exact else r"download", re.IGNORECASE)
    btn = _pw_find_visible(pg, rx)
    if btn is None:
        return False
    _pw_press(btn)
    return True

def _pw_s3_describe(pg):
    """What the page looked like, for the error message when nothing happens."""
    try:
        frames = [fr.url for fr in pg.frames[1:]][:6]
    except Exception:
        frames = []
    return (f"Page: {pg.url}\nButtons: {', '.join(_pw_visible_labels(pg)) or 'none'}\n"
            f"Frames: {', '.join(frames) or 'none'}")

def _pw_s3_attempt(self, start_url):
    """Hidden browser: Download, Download (exact). The moment the browser is on any page that isn't the original
    game page (a redirect, or a new tab), _PwRedirect is raised with that page (it is then finished in the user's
    own browser).
    If a download starts right in the hidden browser instead, returns (download_url, headers)."""
    from playwright.sync_api import sync_playwright    # lazy: saves memory/startup until used
    got = {}

    def norm(url):
        """host + path of a URL (no scheme, query, fragment, 'www.' or trailing slash), to compare pages."""
        u = urllib.parse.urlparse(url or "")
        return ((u.hostname or "").lower().removeprefix("www.") + u.path.rstrip("/")).lower()

    original = norm(start_url)

    def moved(url):
        """True when url is a real web page that is NOT the original game page."""
        return (url or "").startswith(("http://", "https://")) and norm(url) != original

    def watch_ctx(ctx):
        def hook(pg):
            pg.on("download", lambda d, _p=pg: got.setdefault("d", (d, _p)))
        for pg in ctx.pages:
            hook(pg)
        ctx.on("page", hook)
    def newest(ctx, fallback):
        live = [pg for pg in ctx.pages if not pg.is_closed()]
        return live[-1] if live else fallback
    def check_cancel():
        if self._is_cancelled:
            raise RuntimeError("CANCELLED")

    with sync_playwright() as p:
        self.status_update.emit("Starting browser...")
        browser = p.chromium.launch(headless=False, args=["--headless=new", "--disable-blink-features=AutomationControlled"])   # hidden, but the real browser: the site only redirects / shows the captcha to that
        try:
            context = browser.new_context(user_agent=PW_USER_AGENT, accept_downloads=True)
            page = context.new_page()
            watch_ctx(context)
            def find_redirect():
                """The URL to finish in the user's browser, or ''. That is whatever page the browser is on when it
                isn't the original game page anymore: the main tab after a redirect, or a new tab. The main tab
                wins. Waits for the page to load so the final address is used."""
                try:
                    if not page.is_closed() and moved(page.url):
                        page.wait_for_load_state("domcontentloaded", timeout=8000)
                        page.wait_for_timeout(1500)
                        if moved(page.url):
                            return page.url
                except Exception:
                    _log_exc("find_redirect")
                for pg in list(context.pages):
                    if pg is page or pg.is_closed() or not moved(pg.url):   # still about:blank / original page: skip
                        continue
                    try:
                        pg.wait_for_load_state("domcontentloaded", timeout=8000)
                        pg.wait_for_timeout(1500)
                    except Exception:
                        _log_exc("find_redirect")
                    if not pg.is_closed() and moved(pg.url):
                        return pg.url
                return ""

            def redirected():
                url = find_redirect()
                if url:
                    raise _PwRedirect(url)

            self.status_update.emit("Opening download page...")
            page.goto(start_url, timeout=60000)
            try:
                page.wait_for_timeout(1000)       # the green version box can be drawn by scripts
                self._pw_build = parse_s3_version(page.content())
            except Exception:
                self._pw_build = ""
            cur = page
            try:
                for n in (1, 2):
                    check_cancel()
                    self.status_update.emit(f"Clicking Download ({n}/2)...")
                    deadline = time.time() + 30
                    while not _pw_s3_press_download(cur, exact=(n == 2)):   # 2nd press: only a button that says exactly "Download"
                        check_cancel()
                        redirected()
                        if time.time() > deadline:
                            raise RuntimeError(f"Couldn't find the Download button on {cur.url}")
                        cur.wait_for_timeout(700)
                    settle_end = time.time() + 3
                    while time.time() < settle_end and "d" not in got:
                        redirected()
                        cur.wait_for_timeout(300)
                    cur = newest(context, cur)
                    if "d" in got:
                        break

                if "d" not in got:
                    self.status_update.emit("Waiting for a redirect or new tab...")
                    end = time.time() + 90
                    while "d" not in got:
                        check_cancel()
                        redirected()
                        if time.time() > end:
                            raise RuntimeError("The site neither redirected, opened a new tab nor started a download.\n"
                                               + _pw_s3_describe(newest(context, cur)))
                        now_pg = newest(context, cur)
                        _pw_s3_dismiss(now_pg)
                        now_pg.wait_for_timeout(500)
            except _PwRedirect as e:
                try:
                    e.cookies = context.cookies()     # keep the session so the visible browser continues where we left off
                except Exception:
                    e.cookies = []
                raise    # the hidden browser closes first, then _pw_find_link_s3 opens that page in a visible browser

            download, src = got["d"]
            url = download.url
            cookies = "; ".join(f"{c['name']}={c['value']}" for c in src.context.cookies(url))
            try:
                download.cancel()      # the launcher downloads it itself
            except Exception:    # expected: offline or the server did not answer
                pass
            headers = {"User-Agent": PW_USER_AGENT, "Referer": src.url or start_url}
            if cookies:
                headers["Cookie"] = cookies
            return url, headers
        finally:
            browser.close()

# --- hand-off: the page we were redirected / sent to opens in the default browser, and the launcher takes over once a download shows up
PW_BROWSER_DOWNLOAD_DIRS = ()    # extra folders to watch if your browser saves somewhere unusual
_PW_PARTIAL_EXT = (".crdownload", ".part", ".opdownload", ".download")   # Chrome/Edge/Brave, Firefox, Opera, Safari
_PW_ARCHIVE_EXT = (".zip", ".rar", ".7z")

def _win_downloads_dir():
    try:
        import ctypes    # lazy: saves memory/startup until used
        from ctypes import wintypes    # lazy: saves memory/startup until used
        class GUID(ctypes.Structure):
            _fields_ = [("Data1", wintypes.DWORD), ("Data2", wintypes.WORD), ("Data3", wintypes.WORD),
                        ("Data4", ctypes.c_ubyte * 8)]
        guid = GUID(0x374DE290, 0x123F, 0x4565, (ctypes.c_ubyte * 8)(0x91, 0x64, 0x39, 0xC4, 0x92, 0x5E, 0x46, 0x7B))
        buf = ctypes.c_wchar_p()
        if ctypes.windll.shell32.SHGetKnownFolderPath(ctypes.byref(guid), 0, None, ctypes.byref(buf)) == 0:
            path = buf.value
            ctypes.windll.ole32.CoTaskMemFree(buf)
            return path or ""
    except Exception:    # expected: optional module may be missing
        pass
    return ""

def _pw_browser_download_dirs():
    """Folders where the user's browser is likely to save files."""
    cands = []
    if sys.platform.startswith("win"):
        cands.append(_win_downloads_dir())
    elif sys.platform.startswith("linux"):
        cands.append(_run_quiet(["xdg-user-dir", "DOWNLOAD"]))
    cands += [os.path.join(os.path.expanduser("~"), "Downloads"), DOWNLOAD_DIR] + list(PW_BROWSER_DOWNLOAD_DIRS)
    out = []
    for d in cands:
        if d and os.path.isdir(d) and os.path.normcase(os.path.abspath(d)) not in [os.path.normcase(os.path.abspath(x)) for x in out]:
            out.append(d)
    return out

def _pw_list_files(dirs):
    """{path: (size, mtime)} for the files directly inside these folders."""
    out = {}
    for d in dirs:
        try:
            with os.scandir(d) as it:
                for e in it:
                    try:
                        if e.is_file(follow_symlinks=False):
                            st = e.stat()
                            out[e.path] = (st.st_size, st.st_mtime)
                    except OSError:
                        _log_exc("_pw_list_files")
        except OSError:
            _log_exc("_pw_list_files")
    return out

def _pw_s3_browser_handoff(self, url, wait_minutes=30):
    """Opens url in the default browser and waits for a new download to appear in the browser's download folder
    (a .crdownload / .part file, or a finished archive). Shows its progress, and returns the finished file's path."""
    dirs = _pw_browser_download_dirs()
    if not dirs:
        raise RuntimeError("Couldn't find your browser's download folder.")
    before = set(_pw_list_files(dirs))
    t0 = time.time()
    self.status_update.emit("Finish the page in your browser (captcha, then download). The launcher picks the download up automatically.")
    webbrowser.open(url)

    def check_cancel():
        if self._is_cancelled:
            raise RuntimeError("CANCELLED")

    def new_files():
        files = _pw_list_files(dirs)
        return {p: v for p, v in files.items() if p not in before}

    def settle(path):
        """Waits until the finished file stops changing size, then returns it."""
        last, steady = -1, 0
        while steady < 3:
            check_cancel()
            try:
                size = os.path.getsize(path)
            except OSError:
                raise RuntimeError("The downloaded file disappeared.")
            steady = steady + 1 if size == last else 0
            last = size
            time.sleep(1.0)
        return path

    deadline = t0 + wait_minutes * 60
    partial, last_size, last_t = None, 0, time.time()
    while True:
        check_cancel()
        if time.time() > deadline:
            raise RuntimeError("No download started in your browser. If your browser asks where to save each file, "
                               "turn that off (or add its folder to PW_BROWSER_DOWNLOAD_DIRS).")
        fresh = new_files()
        if partial is None:
            partials = [p for p, v in fresh.items() if p.lower().endswith(_PW_PARTIAL_EXT)]
            if partials:
                partial = max(partials, key=lambda p: fresh[p][0])
                last_size, last_t = 0, time.time()
                self.status_update.emit("Download started in your browser, tracking it...")
            else:
                done = [p for p in fresh if p.lower().endswith(_PW_ARCHIVE_EXT)]   # one that finished before we looked
                if done:
                    return settle(max(done, key=lambda p: fresh[p][0]))
                time.sleep(1.0)
                continue
        # a download is running: follow its size
        if os.path.exists(partial):
            size = os.path.getsize(partial)
            now = time.time()
            speed = max(0.0, (size - last_size) / max(now - last_t, 0.001))
            last_size, last_t = size, now
            self.progress.emit(int(size), 0, float(speed))
            time.sleep(1.0)
            continue
        # the partial file is gone: the browser renamed it to the finished file (or the download was cancelled)
        base = partial[:-len(next(e for e in _PW_PARTIAL_EXT if partial.lower().endswith(e)))]
        end = time.time() + 15
        final = None
        while time.time() < end and final is None:
            fresh = new_files()
            if base in fresh and not base.lower().endswith(_PW_PARTIAL_EXT):
                final = base
            else:
                rest = [p for p, v in fresh.items() if not p.lower().endswith(_PW_PARTIAL_EXT) and v[1] >= t0 - 2]
                if rest:
                    final = max(rest, key=lambda p: fresh[p][0])
            if final is None:
                time.sleep(1.0)
        if final:
            return settle(final)
        partial = None   # cancelled or restarted in the browser: keep waiting for a new download

def _pw_adopt_local_file(path):
    """Moves a browser-downloaded archive into the launcher's downloads folder when that is instant (same drive);
    otherwise it is used right where it is."""
    try:
        os.makedirs(DOWNLOAD_DIR, exist_ok=True)
        dest = os.path.join(DOWNLOAD_DIR, os.path.basename(path))
        if os.path.abspath(dest) == os.path.abspath(path) or os.path.exists(dest):
            return path
        if os.stat(path).st_dev == os.stat(DOWNLOAD_DIR).st_dev:
            os.replace(path, dest)
            return dest
    except OSError:    # expected: cleanup that may already be done
        pass
    return path

def _pw_real_browser_exe():
    """Path of an installed Chrome / Edge / Chromium (the real thing passes Cloudflare), or ''."""
    cands = []
    if sys.platform.startswith("win"):
        for base in (os.environ.get("PROGRAMFILES"), os.environ.get("PROGRAMFILES(X86)"), os.environ.get("LOCALAPPDATA")):
            if base:
                cands += [os.path.join(base, r"Google\Chrome\Application\chrome.exe"),
                          os.path.join(base, r"Microsoft\Edge\Application\msedge.exe"),
                          os.path.join(base, r"BraveSoftware\Brave-Browser\Application\brave.exe")]
    elif sys.platform == "darwin":
        cands += ["/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
                  "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge"]
    for name in ("google-chrome", "google-chrome-stable", "chrome", "chromium", "chromium-browser", "microsoft-edge", "brave-browser"):
        w = shutil.which(name)
        if w:
            cands.append(w)
    return next((c for c in cands if c and os.path.isfile(c)), "")

def _pw_free_port():
    import socket    # lazy: saves memory/startup until used
    with socket.socket() as sk:
        sk.bind(("127.0.0.1", 0))
        return sk.getsockname()[1]

class _MiniWS:
    """Tiny WebSocket client (no extra package needed), just enough to talk to Chrome's DevTools port."""
    def __init__(self, host, port, path):
        import socket, base64 as _b64    # lazy: saves memory/startup until used
        self.sock = socket.create_connection((host, port), timeout=10)
        key = _b64.b64encode(os.urandom(16)).decode()
        self.sock.sendall((f"GET {path} HTTP/1.1\r\nHost: {host}:{port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
                           f"Sec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n").encode())
        self.buf = b""
        while b"\r\n\r\n" not in self.buf:
            chunk = self.sock.recv(4096)
            if not chunk:
                raise RuntimeError("DevTools handshake failed")
            self.buf += chunk
        head, self.buf = self.buf.split(b"\r\n\r\n", 1)
        if b" 101 " not in head.split(b"\r\n")[0]:
            raise RuntimeError("DevTools refused the connection")

    def _read(self, n):
        self.sock.settimeout(15)
        while len(self.buf) < n:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise RuntimeError("DevTools connection closed")
            self.buf += chunk
        out, self.buf = self.buf[:n], self.buf[n:]
        return out

    def send(self, text):
        data = text.encode()
        n = len(data)
        head = bytearray([0x81])
        if n < 126:
            head.append(0x80 | n)
        elif n < 65536:
            head += bytes([0x80 | 126]) + n.to_bytes(2, "big")
        else:
            head += bytes([0x80 | 127]) + n.to_bytes(8, "big")
        mask = os.urandom(4)
        self.sock.settimeout(10)
        self.sock.sendall(bytes(head) + mask + bytes(b ^ mask[i % 4] for i, b in enumerate(data)))

    def recv(self, timeout=1.0):
        """Next text message, or None if nothing arrived within timeout."""
        import select    # lazy: saves memory/startup until used
        if not self.buf and not select.select([self.sock], [], [], timeout)[0]:
            return None
        msg = b""
        while True:
            b1, b2 = self._read(2)
            op, n = b1 & 0x0F, b2 & 0x7F
            if n == 126:
                n = int.from_bytes(self._read(2), "big")
            elif n == 127:
                n = int.from_bytes(self._read(8), "big")
            payload = self._read(n)
            if op == 8:
                raise RuntimeError("DevTools connection closed")
            if op == 9:      # ping -> pong
                self.sock.sendall(bytes([0x8A, 0x80 | len(payload)]) + b"\0\0\0\0" + payload[:125])
                continue
            if op in (0, 1, 2):
                msg += payload
                if b1 & 0x80:
                    return msg.decode("utf-8", "replace")

    def close(self):
        try:
            self.sock.close()
        except Exception:    # expected: cleanup that may already be done
            pass

def _pw_close_browser(proc):
    """Closes the browser started for a capture, with all of its processes (on Linux the main process is often a
    launcher script and Chrome's helpers live on, so the whole process group is ended)."""
    try:
        if os.name == "nt":
            subprocess.run(["taskkill", "/PID", str(proc.pid), "/T", "/F"], stdout=subprocess.DEVNULL,
                           stderr=subprocess.DEVNULL, timeout=10)
        else:
            import signal
            try:
                os.killpg(proc.pid, signal.SIGTERM)
            except (ProcessLookupError, PermissionError):
                proc.terminate()
            try:
                proc.wait(timeout=5)
            except Exception:    # expected: still shutting down
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except (ProcessLookupError, PermissionError):
                    proc.kill()
    except Exception:    # expected: cleanup that may already be done
        try:
            proc.terminate()
        except Exception:
            pass

def _pw_s3_capture_in_browser(self, url, cookies=None, wait_minutes=30, auto_click=False):
    """Opens url in your real, normally launched Chrome / Edge / Brave and does NOT automate it at all (no Playwright
    attached to the page, no navigation by script), so Cloudflare's captcha sees a normal browser. The launcher only
    listens on the browser-level DevTools port for 'a download is about to start': that event carries the download
    link. The browser's own download is denied, the link + the browser's cookies / user agent are copied, and
    (url, headers) is returned so the launcher downloads the file itself.
    auto_click: once the page shows a button that says Download (so any Cloudflare check is already passed), it is
    pressed with a real browser-level mouse click (no script on the page, no Runtime.enable), a few tries at most."""
    exe = _pw_real_browser_exe()
    if not exe:
        raise RuntimeError("Couldn't find Chrome, Edge or Brave on this PC. Install one of them for this server.")
    port = _pw_free_port()
    profile = os.path.join(os.path.dirname(get_launcher_settings_path()), "server3_browser_profile")   # kept, so a solved captcha is remembered
    os.makedirs(profile, exist_ok=True)
    self.status_update.emit("Opening the page in your browser. Finish the captcha / verification there...")
    proc = subprocess.Popen([exe, f"--remote-debugging-port={port}", f"--remote-debugging-address=127.0.0.1",
                             f"--user-data-dir={profile}", "--no-first-run", "--no-default-browser-check", url],
                            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                            start_new_session=(os.name != "nt"))    # own process group, so it can be closed whole
    ws = None
    click = {"ws": None, "page": None, "last": 0.0, "n": 0}
    try:
        info = None
        for _ in range(60):          # wait for the debug port to come up
            if proc.poll() is not None:
                raise RuntimeError("The browser closed right away. Close other windows of it that use the same profile and retry.")
            try:
                with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/version", timeout=2) as r:
                    info = json.loads(r.read().decode())
                break
            except Exception:
                time.sleep(0.5)
        if not info:
            raise RuntimeError("Couldn't connect to the browser window.")
        ua = info.get("User-Agent") or PW_USER_AGENT
        wsu = urllib.parse.urlparse(info["webSocketDebuggerUrl"])
        ws = _MiniWS(wsu.hostname, wsu.port, wsu.path)
        ids = {"n": 0}
        def call(method, params=None, wait=False):
            ids["n"] += 1
            mid = ids["n"]
            ws.send(json.dumps({"id": mid, "method": method, "params": params or {}}))
            if not wait:
                return None
            end = time.time() + 10
            while time.time() < end:
                m = ws.recv(1.0)
                if m:
                    d = json.loads(m)
                    if d.get("id") == mid:
                        return d.get("result") or {}
            return {}
        # Browser-level only: deny the browser's own download, but report it (with its link) first
        call("Browser.setDownloadBehavior", {"behavior": "deny", "eventsEnabled": True})

        click_host = (urllib.parse.urlparse(url).hostname or "").lower()
        click_js = r"""(() => {
            const re = /^\s*(\u2B07\uFE0F?\s*)?download\s*$/i;
            const txt = e => (e.innerText || e.value || "").trim();
            let el = [...document.querySelectorAll('button,a,[role=button],input[type=button],input[type=submit]')].find(e => re.test(txt(e)));
            if (!el) el = [...document.querySelectorAll('div,span,p')].find(e => !e.children.length && re.test(txt(e)));
            if (!el) return null;
            el.scrollIntoView({block: 'center'});
            const r = el.getBoundingClientRect();
            if (r.width < 2 || r.height < 2) return null;
            return [r.left + r.width / 2, r.top + r.height / 2];
        })()"""
        def page_call(method, params):
            w = click["ws"]
            ids["n"] += 1
            mid = ids["n"]
            w.send(json.dumps({"id": mid, "method": method, "params": params}))
            end = time.time() + 5
            while time.time() < end:
                m = w.recv(0.5)
                if m:
                    d = json.loads(m)
                    if d.get("id") == mid:
                        return d.get("result") or {}
            return {}
        def try_click():
            """Looks for the Download button on the page in the browser and presses it with a real mouse click."""
            with urllib.request.urlopen(f"http://127.0.0.1:{port}/json", timeout=3) as r:
                pages = [t for t in json.loads(r.read().decode()) if t.get("type") == "page"
                         and (urllib.parse.urlparse(str(t.get("url", ""))).hostname or "").lower().endswith(click_host)]
            if not pages:
                return
            pg = pages[-1]
            if click["page"] != pg["id"]:
                if click["ws"]:
                    click["ws"].close()
                u = urllib.parse.urlparse(pg["webSocketDebuggerUrl"])
                click["ws"] = _MiniWS(u.hostname, u.port, u.path)
                click["page"] = pg["id"]
            val = ((page_call("Runtime.evaluate", {"expression": click_js, "returnByValue": True}).get("result") or {}).get("value"))
            if not val:
                return
            x, y = val
            self.status_update.emit("Pressing Download...")
            page_call("Input.dispatchMouseEvent", {"type": "mouseMoved", "x": x, "y": y})
            page_call("Input.dispatchMouseEvent", {"type": "mousePressed", "x": x, "y": y, "button": "left", "clickCount": 1})
            page_call("Input.dispatchMouseEvent", {"type": "mouseReleased", "x": x, "y": y, "button": "left", "clickCount": 1})
            click["n"] += 1
            click["last"] = time.time() + 4      # give the download a few seconds before looking again

        dl_url = ""
        deadline = time.time() + wait_minutes * 60
        while not dl_url:
            if self._is_cancelled:
                raise RuntimeError("CANCELLED")
            if time.time() > deadline:
                raise RuntimeError("No download started in the browser window.")
            if auto_click and click["n"] < 5 and time.time() - click["last"] > 1.5:
                click["last"] = time.time()
                try:
                    try_click()
                except Exception:    # expected: page navigating, or the browser not ready yet
                    click["ws"], click["page"] = None, None
            if proc.poll() is not None:
                raise RuntimeError("The browser window was closed before a download started.")
            m = ws.recv(0.5)
            if not m:
                continue
            d = json.loads(m)
            if d.get("method") == "Browser.downloadWillBegin":
                dl_url = (d.get("params") or {}).get("url") or ""

        if dl_url.startswith(("blob:", "data:")):
            raise RuntimeError("The browser's download has no direct link (it's a blob), so the launcher can't take it over.")
        ref = url
        try:      # the page the download came from
            with urllib.request.urlopen(f"http://127.0.0.1:{port}/json", timeout=3) as r:
                pages = [t for t in json.loads(r.read().decode()) if t.get("type") == "page" and str(t.get("url", "")).startswith("http")]
            if pages:
                ref = pages[-1]["url"]
        except Exception:    # expected: offline or the server did not answer
            pass
        host = (urllib.parse.urlparse(dl_url).hostname or "").lower()
        path = urllib.parse.urlparse(dl_url).path or "/"
        pairs = []
        for c in (call("Storage.getCookies", wait=True).get("cookies") or []):
            dom = (c.get("domain") or "").lower().lstrip(".")
            if dom and (host == dom or host.endswith("." + dom)) and path.startswith(c.get("path") or "/"):
                pairs.append(f"{c['name']}={c['value']}")
        headers = {"User-Agent": ua, "Referer": ref}
        if pairs:
            headers["Cookie"] = "; ".join(pairs)
        self.status_update.emit("Got the download link from your browser, downloading it in the launcher...")
        return dl_url, headers
    finally:
        if ws:
            ws.close()
        try:
            if click["ws"]:
                click["ws"].close()
        except Exception:    # expected: cleanup that may already be done
            pass
        _pw_close_browser(proc)

def _pw_find_link_s3(self, start_url):
    """Server 3. Stays in the hidden Playwright browser (Download, Download) until the site redirects away from the
    original game URL (or opens a new tab). THEN that page is opened in a visible browser window, the download it
    starts is captured: its link is copied, the browser download is cancelled and the launcher downloads from the
    link itself. Returns (download_url, headers) like the other servers."""
    try:
        import playwright.sync_api  # noqa: F401
    except ImportError:
        # no Playwright: fall back to the old behaviour (your default browser downloads it, the launcher watches the folder)
        return _pw_s3_browser_handoff(self, start_url), None
    try:
        return _pw_s3_attempt(self, start_url)       # a download started right in the hidden browser
    except _PwRedirect as r:
        target = r.args[0]
        self.status_update.emit("Redirected, opening it in your browser...")
        return _pw_s3_capture_in_browser(self, target, getattr(r, "cookies", []))

_MAGNET_RX = re.compile(r"magnet:\?[^\s\"'<>]+", re.IGNORECASE)

def _pw_scan_magnet(page):
    """Looks for a magnet link in the page's links / data attributes / raw HTML (any frame)."""
    for fr in page.frames:
        try:
            href = fr.evaluate("""() => {
                const a = document.querySelector('a[href^="magnet:"]');
                if (a) return a.getAttribute('href');
                const d = document.querySelector('[data-magnet],[data-clipboard-text^="magnet:"]');
                return d ? (d.getAttribute('data-magnet') || d.getAttribute('data-clipboard-text')) : '';
            }""")
            if href and href.lower().startswith("magnet:"):
                return html_lib.unescape(href)
            m = _MAGNET_RX.search(fr.content())
            if m:
                return html_lib.unescape(m.group(0))
        except Exception:
            continue
    return ""

def _pw_find_magnet(self, start_url):
    """Server 2: opens the game page in the hidden browser, presses [magnet], returns the magnet link."""
    try:
        from playwright.sync_api import sync_playwright    # lazy: optional module: the except below handles it missing
    except ImportError:
        raise RuntimeError("Playwright isn't installed. Run: pip install playwright && playwright install chromium")
    with sync_playwright() as p:
        self.status_update.emit("Starting browser...")
        browser = p.chromium.launch(headless=PW_HEADLESS, args=["--disable-blink-features=AutomationControlled"])
        try:
            context = browser.new_context(user_agent=PW_USER_AGENT)
            page = context.new_page()
            _pw_guard(context, page)
            self.status_update.emit("Opening download page...")
            page.goto(start_url, timeout=60000)
            rx = re.compile(PW_MAGNET_TEXT, re.IGNORECASE)
            for attempt in range(1, 9):
                if self._is_cancelled:
                    raise RuntimeError("CANCELLED")
                self.status_update.emit(f"Finding magnet link (attempt {attempt})...")
                magnet = _pw_scan_magnet(page)
                if magnet:
                    return magnet
                btn = _pw_find_visible(page, rx)   # the [magnet] button/link
                if btn is not None:
                    _pw_press(btn)                 # JS pages only fill the link in after the click
                page.wait_for_timeout(1500)
                magnet = _pw_scan_magnet(page)
                if magnet:
                    return magnet
            raise RuntimeError("Couldn't find a [magnet] link on " + start_url)
        finally:
            browser.close()

def _fb_torrent(self, magnet):
    """Downloads a magnet link with libtorrent into <downloads>/<title>.torrent (re-running resumes it).
    Returns (staging_dir, content_path)."""
    try:
        import libtorrent as lt    # lazy: optional module: the except below handles it missing
    except ImportError:
        raise RuntimeError("libtorrent isn't installed. Run: pip install libtorrent")
    stage = os.path.join(DOWNLOAD_DIR, sanitize_folder_name(self.title) + ".torrent")
    os.makedirs(stage, exist_ok=True)
    ses = lt.session({"listen_interfaces": "0.0.0.0:6881,[::]:6881", "enable_dht": True,
                      "enable_lsd": True, "enable_upnp": True, "enable_natpmp": True})
    flag = lambda k: self.__dict__.get(k, False)   # not self._is_cancelled: that one blocks while paused
    handle = None
    try:
        params = lt.parse_magnet_uri(magnet)
        params.save_path = stage
        handle = ses.add_torrent(params)
        self.status_update.emit("Getting torrent info...")
        deadline = time.time() + 300
        while not handle.status().has_metadata:
            if flag("_cancel_flag"):
                raise RuntimeError("CANCELLED")
            if time.time() > deadline:
                raise RuntimeError("Couldn't get the torrent info (no peers found).")
            time.sleep(0.5)
        info = handle.torrent_file() if hasattr(handle, "torrent_file") else handle.get_torrent_info()
        total, name = info.total_size(), info.name()
        paused = False
        while True:
            if flag("_cancel_flag"):
                raise RuntimeError("CANCELLED")
            if flag("_paused") != paused:
                paused = flag("_paused")
                handle.pause() if paused else handle.resume()
            if paused:
                time.sleep(0.3)
                continue
            st = handle.status()
            self.progress.emit(int(st.total_done), int(total), float(st.download_rate))
            if st.is_finished or st.is_seeding:
                break
            time.sleep(0.5)
        return stage, os.path.join(stage, name)
    finally:
        try:
            if handle is not None:
                ses.remove_torrent(handle)   # no seeding
        except Exception:
            _log_exc("_fb_torrent")
        del ses

def _find_setup_exe(folder):
    """setup.exe (or the shallowest setup*.exe) inside the game folder, else None."""
    best = None
    for root, dirs, files in os.walk(folder):
        depth = os.path.relpath(root, folder).count(os.sep) + (0 if root == folder else 1)
        if depth > 2:
            dirs[:] = []
            continue
        for f in files:
            low = f.lower()
            if low.endswith(".exe") and low.startswith("setup") and "unins" not in low:
                key = (low != "setup.exe", depth, len(low))
                if best is None or key < best[0]:
                    best = (key, os.path.join(root, f))
    return best[1] if best else None


# ── server 2: run setup.exe, find where it installed, find the game .exe ──
def installed_exes_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "installed_exes.json")

def _load_installed_exes():
    try:
        with open(installed_exes_path(), encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def record_installed_exe(title, exe):
    with _versions_lock:
        data = _load_installed_exes()
        data[title] = exe
        data[sanitize_folder_name(title)] = exe
        path = installed_exes_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)
        os.replace(tmp, path)

# The library looks for a game's exe inside its game folder. Server 2 games install wherever setup.exe put them,
# so the exe recorded after setup wins; anything else behaves exactly as before.
_find_best_game_exe_orig = find_best_game_exe
def find_best_game_exe(root, title):
    try:
        data = _load_installed_exes()
        exe = data.get(title) or data.get(sanitize_folder_name(title))
        if exe and os.path.isfile(exe):
            return exe
    except Exception:
        _log_exc("find_best_game_exe")
    return _find_best_game_exe_orig(root, title)

def installed_exe_for(title):
    data = _load_installed_exes()
    exe = data.get(title) or data.get(sanitize_folder_name(title))
    return exe if exe and os.path.isfile(exe) else None

def forget_installed_exe(title):
    with _versions_lock:
        data = _load_installed_exes()
        if data.pop(title, None) is None and data.pop(sanitize_folder_name(title), None) is None:
            return
        data.pop(sanitize_folder_name(title), None)
        path = installed_exes_path()
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)

def locate_installed_game(parent, title, start=""):
    """Lets the user point the launcher at an already installed game's .exe. Returns True if one was chosen."""
    if not start:
        cur = installed_exe_for(title)
        start = os.path.dirname(cur) if cur else ""
    picked, _ = QFileDialog.getOpenFileName(parent, "Select the installed game's .exe", start,
                                            "Executables (*.exe);;All files (*)")
    if not picked:
        return False
    record_installed_exe(title, picked)
    try:
        invalidate_library_roots()
    except Exception:
        _log_exc("locate_installed_game")
    return True

_SETUP_BAD_EXE = ("unins", "uninstall", "crash", "redist", "dxsetup", "dxwebsetup", "setup", "install", "updater",
                  "helper", "dotnet", "oalinst", "directx", "vc_redist", "vcredist", "ndp", "7z", "notification")
_SETUP_SKIP_DIRS = ("redist", "directx", "dotnet", "_commonredist", "commonredist", "vcredist", "__installer")

def _norm(p):
    return os.path.normcase(os.path.abspath(p))

def _is_inside(path, folder):
    p, f = _norm(path), _norm(folder)
    return p == f or p.startswith(f.rstrip("\\/") + os.sep)

def _ignored_install_path(p, setup_dir):
    """Temp folders, system folders and the setup folder itself are never the install location."""
    n = _norm(p)
    if _is_inside(n, setup_dir):
        return True
    for bad in (os.environ.get("TEMP"), os.environ.get("TMP"), os.environ.get("WINDIR"), os.environ.get("SystemRoot"),
                "/tmp", "/proc", "/dev", "/usr", "/lib", "/lib64", "/etc", "/sys", "/run", "/var", "/bin", "/opt"):
        if bad and _is_inside(n, bad):
            return True
    low = n.replace("\\", "/")
    return any(x in low for x in ("/appdata/local/temp", "/$recycle.bin", "/windows/installer", "/winsxs",
                                  "/programdata/microsoft", "/drive_c/windows"))

def _too_broad(p):
    """Folders we must never treat as 'the game folder' (drive roots, Program Files itself, home...)."""
    n = _norm(p)
    if os.path.dirname(n) == n:
        return True
    broad = [os.environ.get(k) for k in ("ProgramFiles", "ProgramFiles(x86)", "ProgramW6432", "LOCALAPPDATA", "APPDATA",
                                         "ProgramData", "USERPROFILE", "SystemDrive")]
    broad += [os.path.expanduser("~"), os.path.join(_wine_prefix(), "drive_c"),
              os.path.join(_wine_prefix(), "drive_c", "Program Files"),
              os.path.join(_wine_prefix(), "drive_c", "Program Files (x86)")]
    try:
        broad += library_roots()
    except Exception:
        _log_exc("_too_broad")
    if os.environ.get("LOCALAPPDATA"):
        broad.append(os.path.join(os.environ["LOCALAPPDATA"], "Programs"))
    return any(b and _norm(b) == n for b in broad)

def _pick_game_exe(folder, title, max_depth=4):
    """The game's .exe inside an install folder: installers, uninstallers, redists and crash handlers are skipped,
    then the name closest to the title wins (bigger and shallower break ties)."""
    if not folder or not os.path.isdir(folder):
        return None
    tokens = set(re.findall(r"[a-z0-9]+", title.lower()))
    best, best_key = None, None
    for root, dirs, files in os.walk(folder):
        depth = 0 if root == folder else os.path.relpath(root, folder).count(os.sep) + 1
        dirs[:] = [d for d in dirs if not any(s in d.lower() for s in _SETUP_SKIP_DIRS)] if depth < max_depth else []
        for f in files:
            low = f.lower()
            if not low.endswith(".exe") or any(w in low for w in _SETUP_BAD_EXE):
                continue
            full = os.path.join(root, f)
            try:
                size = os.path.getsize(full)
            except OSError:
                continue
            stem = set(re.findall(r"[a-z0-9]+", os.path.splitext(low)[0]))
            key = (len(tokens & stem), -depth, size)
            if best_key is None or key > best_key:
                best, best_key = full, key
    return best

def _uninstall_snapshot():
    """Windows: {key: {InstallLocation, DisplayIcon, UninstallString}} for every entry in Apps & Features."""
    out = {}
    if not sys.platform.startswith("win"):
        return out
    try:
        import winreg    # lazy: optional module: the except below handles it missing
    except ImportError:
        return out
    path = r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"
    for hive, flag in ((winreg.HKEY_LOCAL_MACHINE, winreg.KEY_WOW64_64KEY),
                       (winreg.HKEY_LOCAL_MACHINE, winreg.KEY_WOW64_32KEY),
                       (winreg.HKEY_CURRENT_USER, 0)):
        try:
            key = winreg.OpenKey(hive, path, 0, winreg.KEY_READ | flag)
        except OSError:
            continue
        with key:
            i = 0
            while True:
                try:
                    name = winreg.EnumKey(key, i)
                except OSError:
                    break
                i += 1
                try:
                    with winreg.OpenKey(key, name) as sub:
                        d = {}
                        for v in ("InstallLocation", "DisplayIcon", "UninstallString"):
                            try:
                                d[v] = str(winreg.QueryValueEx(sub, v)[0])
                            except OSError:
                                _log_exc("_uninstall_snapshot")
                        out[(int(hive), flag, name)] = d
                except OSError:
                    _log_exc("_uninstall_snapshot")
    return out

def _uninstall_entry_dir(d):
    loc = (d.get("InstallLocation") or "").strip().strip('"')
    if loc and os.path.isdir(loc):
        return loc
    for k in ("DisplayIcon", "UninstallString"):
        v = (d.get(k) or "").strip()
        m = re.match(r'^"([^"]+)"', v) or re.match(r"^(.+?\.exe)", v, re.I)
        if m:
            p = os.path.dirname(m.group(1).split(",")[0])
            if p and os.path.isdir(p):
                return p
    return None

def _watch_roots():
    """[(folder, depth)] where a fresh install may appear."""
    roots = []
    if sys.platform.startswith("win"):
        for k in ("ProgramFiles", "ProgramFiles(x86)"):
            if os.environ.get(k):
                roots.append((os.environ[k], 2))
        if os.environ.get("LOCALAPPDATA"):
            roots.append((os.path.join(os.environ["LOCALAPPDATA"], "Programs"), 2))
        try:
            import ctypes    # lazy: saves memory/startup until used
            mask = ctypes.windll.kernel32.GetLogicalDrives()
            for i in range(26):
                drv = chr(65 + i) + ":\\"
                if mask & (1 << i) and ctypes.windll.kernel32.GetDriveTypeW(drv) == 3:   # fixed drives only
                    roots.append((drv, 1))
        except Exception:    # expected: optional module may be missing
            pass
    else:
        c = os.path.join(_wine_prefix(), "drive_c")
        roots += [(os.path.join(c, "Program Files"), 2), (os.path.join(c, "Program Files (x86)"), 2), (c, 1)]
    try:
        roots += [(r, 1) for r in library_roots()]
    except Exception:
        _log_exc("_watch_roots")
    return roots

def _dir_snapshot(roots):
    seen = set()
    def walk(path, depth):
        try:
            with os.scandir(path) as it:
                for e in it:
                    try:
                        if e.is_dir(follow_symlinks=False):
                            seen.add(_norm(e.path))
                            if depth > 1:
                                walk(e.path, depth - 1)
                    except OSError:
                        _log_exc("walk")
        except OSError:
            _log_exc("walk")
    for r, d in roots:
        walk(r, d)
    return seen

def _start_setup(exe):
    """Starts setup.exe and returns (pid, popen or None). Windows asks for admin rights itself if the installer wants them."""
    cwd = os.path.dirname(exe)
    if sys.platform.startswith("win"):
        try:
            p = subprocess.Popen([exe], cwd=cwd)
            return p.pid, p
        except OSError as e:
            if getattr(e, "winerror", 0) != 740:        # 740 = needs elevation
                raise
        import ctypes    # lazy: saves memory/startup until used
        from ctypes import wintypes    # lazy: saves memory/startup until used
        class SEI(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD), ("fMask", wintypes.ULONG), ("hwnd", wintypes.HWND),
                        ("lpVerb", wintypes.LPCWSTR), ("lpFile", wintypes.LPCWSTR), ("lpParameters", wintypes.LPCWSTR),
                        ("lpDirectory", wintypes.LPCWSTR), ("nShow", ctypes.c_int), ("hInstApp", wintypes.HINSTANCE),
                        ("lpIDList", ctypes.c_void_p), ("lpClass", wintypes.LPCWSTR), ("hkeyClass", wintypes.HKEY),
                        ("dwHotKey", wintypes.DWORD), ("hIconOrMonitor", wintypes.HANDLE), ("hProcess", wintypes.HANDLE)]
        sei = SEI()
        sei.cbSize = ctypes.sizeof(sei)
        sei.fMask = 0x40                                # SEE_MASK_NOCLOSEPROCESS
        sei.lpVerb, sei.lpFile, sei.lpDirectory, sei.nShow = "runas", exe, cwd, 1
        k32 = ctypes.windll.kernel32
        k32.GetProcessId.argtypes, k32.GetProcessId.restype = [wintypes.HANDLE], wintypes.DWORD
        k32.CloseHandle.argtypes = [wintypes.HANDLE]
        if not ctypes.windll.shell32.ShellExecuteExW(ctypes.byref(sei)) or not sei.hProcess:
            raise OSError("setup.exe was not started (admin prompt declined?)")
        pid = int(k32.GetProcessId(sei.hProcess))
        k32.CloseHandle(sei.hProcess)
        return pid, None
    found = find_wine()
    if not found:
        raise OSError("wine not found")
    p = subprocess.Popen([found[0], exe], cwd=cwd, env=wine_game_env())
    return p.pid, p

def _run_setup_and_find_install(worker, setup_exe, title):
    """Runs ONLY setup.exe, waits until it (and everything it spawned) has closed, and works out where it installed:
      1. new Apps & Features entries (InstallLocation / icon / uninstaller folder)   [Windows]
      2. new folders in Program Files, the library folders and the drive roots
      3. folders the installer processes had files open in while running
    Returns (started, install_dir, game_exe)."""
    setup_dir = os.path.dirname(setup_exe)
    try:
        import psutil    # lazy: saves memory/startup until used
    except Exception:
        psutil = None
    reg_before = _uninstall_snapshot()
    roots = _watch_roots()
    dirs_before = _dir_snapshot(roots)
    try:
        pid, _popen = _start_setup(setup_exe)
    except Exception:
        return False, None, None

    worker.status_update.emit("Setup is running...\nFinish the installer. The launcher will find the game when it closes.")
    observed = []                       # folders the installer had files open in
    if psutil is not None:
        known, idle = {}, 0
        try:
            known[pid] = psutil.Process(pid)
        except Exception:    # expected: the process may already have exited
            pass
        while idle < 3:                 # ~2s with nothing alive = the installer is really done
            if getattr(worker, "_is_cancelled", False):
                return True, None, None
            alive = False
            for p in list(known.values()):
                try:
                    if not p.is_running():
                        continue
                    alive = True
                    for c in p.children(recursive=True):
                        known.setdefault(c.pid, c)
                    for f in p.open_files():
                        d = os.path.dirname(f.path)
                        if d not in observed and not _ignored_install_path(d, setup_dir):
                            observed.append(d)
                except Exception:    # expected: the process may already have exited
                    pass
            idle = 0 if alive else idle + 1
            time.sleep(0.7)
    else:                               # no psutil: wait on the process we started
        while _popen is not None and _popen.poll() is None:
            if getattr(worker, "_is_cancelled", False):
                return True, None, None
            time.sleep(0.7)
        time.sleep(2)

    worker.status_update.emit("Setup closed. Looking for the game's .exe...")
    cands = []
    def add(p):
        if p and os.path.isdir(p) and not _too_broad(p) and not _ignored_install_path(p, setup_dir) \
                and _norm(p) not in [_norm(c) for c in cands]:
            cands.append(p)
    reg_after = _uninstall_snapshot()
    for k, d in reg_after.items():
        if reg_before.get(k) != d:
            add(_uninstall_entry_dir(d))
    for p in sorted(_dir_snapshot(roots) - dirs_before, key=lambda s: s.count(os.sep)):
        add(p)
    for d in sorted(observed, key=lambda s: -s.count(os.sep)):      # deepest first, then climb up
        cur = d
        for _ in range(3):
            if _too_broad(cur):
                break
            add(cur)
            cur = os.path.dirname(cur)
    for folder in cands:
        exe = _pick_game_exe(folder, title)
        if exe:
            return True, folder, exe
    return True, None, None

def _delete_folder_async(path):
    def onerr(func, p, _exc):
        try:
            os.chmod(p, 0o700)
            func(p)
        except Exception:    # expected: cleanup that may already be done
            pass
    threading.Thread(target=lambda: shutil.rmtree(path, onerror=onerr), daemon=True).start()

def _fb_install_torrent(self, stage, content):
    """Moves what the torrent downloaded into the game's folder (an archive is extracted first)."""
    target = installed_game_dir(sanitize_folder_name(self.title))
    os.makedirs(target, exist_ok=True)
    self.status_update.emit("Installing...")
    if os.path.isfile(content):
        if content.lower().endswith((".zip", ".rar")):
            extract_archive(content, target)
        else:
            shutil.move(content, os.path.join(target, os.path.basename(content)))
    else:
        for entry in os.listdir(content):
            dst = os.path.join(target, entry)
            if os.path.isdir(dst):
                shutil.rmtree(dst, ignore_errors=True)
            elif os.path.exists(dst):
                os.remove(dst)
            shutil.move(os.path.join(content, entry), dst)
    shutil.rmtree(stage, ignore_errors=True)

def _fb_stream(self, url, headers, relink=None):
    """Downloads url; relink() (optional) finds a brand-new link if this one dies mid-download."""
    def name(response, u):
        ext = ".rar" if u.lower().split("?")[0].endswith(".rar") else ".zip"
        return safe_filename_from_headers(response, self.title, ext)
    return resumable_download(self, relink or (lambda: (url, headers)), name, self.expected_size, first=(url, headers))

def _fb_pw_run(self):
    if _pw_is_ncz(self.title):
        return _fb_direct_run(self)
    dest_path = self.existing_zip_path if self.existing_zip_path and os.path.exists(self.existing_zip_path) else None
    fresh = False
    _pw_tls.server = None
    try:
        if not dest_path and load_launcher_settings().get("download_server") == "ask":
            _pw_tls.server = _pw_ask_server(self)      # popup: pick a server for this download
        if not dest_path and pw_server() == "2":       # server 2: [magnet] -> torrent
            magnet = _pw_find_magnet(self, pw_game_url(self.title))
            stage, content = _fb_torrent(self, magnet)
            _fb_install_torrent(self, stage, content)
            game_dir = installed_game_dir(sanitize_folder_name(self.title))
            setup = _find_setup_exe(game_dir)
            if setup:
                # Only setup.exe is launched. When it closes, the game's .exe is searched for where it installed.
                self.setup_exe = setup
                self.setup_dir = os.path.dirname(setup)
                self.status_update.emit("Starting setup.exe...")
                self.setup_started, self.install_dir, self.game_exe = _run_setup_and_find_install(self, setup, self.title)
                if self.game_exe:
                    record_installed_exe(self.title, self.game_exe)
            self.finished.emit(game_dir)
            return
        if not dest_path:
            find = _pw_find_link_s3 if pw_server() == "3" else _pw_find_link
            url, headers = find(self, pw_game_url(self.title))
            if headers is None:      # server 3 hand-off: the user's own browser downloaded it, url is the local file
                dest_path = _pw_adopt_local_file(url)
                fresh = False
            else:
                self.download_url = url  # bridged: the copied link becomes this download's link
                dest_path = _fb_stream(self, url, headers, lambda: find(self, pw_game_url(self.title)))
                fresh = True
        if self._is_cancelled:
            if fresh and os.path.exists(dest_path):
                os.remove(dest_path)
            self.failed.emit("CANCELLED")
            return
        self.status_update.emit("Extracting...")
        extract_archive(dest_path, installed_game_dir(sanitize_folder_name(self.title)))
        if pw_server() == "1":
            try:
                record_installed_build(self.title, getattr(self, "_pw_build", "") or "")
            except Exception:
                _log_exc("_fb_pw_run")
        elif pw_server() == "3":
            try:
                ver = getattr(self, "_pw_build", "") or fetch_site_build(self.title, "3").removeprefix(S3_BUILD_PREFIX)
                if ver:
                    record_installed_build(self.title, S3_BUILD_PREFIX + ver)
            except Exception:    # expected: offline or the server did not answer
                pass
        self.finished.emit(dest_path)
    except Exception as e:
        if self._is_cancelled or str(e) == "CANCELLED":
            if pw_server() == "2":
                shutil.rmtree(os.path.join(DOWNLOAD_DIR, sanitize_folder_name(self.title) + ".torrent"), ignore_errors=True)
            self.failed.emit("CANCELLED")
            return
        msg = str(e)
        try:  # keep the full traceback so customers can send it over
            import traceback    # lazy: saves memory/startup until used
            log = os.path.join(os.path.dirname(get_launcher_settings_path()), "download_error.log")
            with open(log, "a", encoding="utf-8") as f:
                f.write(f"--- {time.strftime('%Y-%m-%d %H:%M:%S')} | {self.title} | Python {sys.version.split()[0]}\n")
                f.write(traceback.format_exc() + "\n")
            msg += f"\n\nFull details saved to:\n{log}"
        except Exception:    # expected: optional module may be missing
            pass
        self.failed.emit(msg)

FirebaseDownloadWorker.run = _fb_pw_run

_card_on_finished_orig = DownloadCard.on_finished
def _card_on_finished_setup(self, path):
    _card_on_finished_orig(self, path)
    setup = getattr(self.worker, "setup_exe", None)
    if not setup:
        return
    w = self.worker
    started = getattr(w, "setup_started", False)
    exe = getattr(w, "game_exe", None)
    setup_dir = getattr(w, "setup_dir", os.path.dirname(setup))

    def locate_game():
        start = os.path.dirname(getattr(w, "game_exe", "") or "") or getattr(w, "install_dir", None) or ""
        if locate_installed_game(self, self.title, start):
            w.game_exe = installed_exe_for(self.title)
            self.status_label.setText("Installed")

    if not started:
        self.status_label.setText("Run setup")
        QMessageBox.information(
            self, "Finish installing " + self.title,
            "Download finished, but setup.exe couldn't be started automatically "
            "(on Linux it needs wine).\n\nRun it yourself to set up the game:\n" + setup)
        return
    if not exe:
        self.status_label.setText("Setup closed")
        if QMessageBox.question(
                self, "Game not found",
                "Setup closed, but the launcher couldn't tell where the game was installed.\n\n"
                "Do you want to pick the game's .exe yourself?\n"
                "(The setup folder is kept. You can also use \"Locate Game\" in the game's 3-dot menu.)") == QMessageBox.StandardButton.Yes:
            locate_game()
        return
    self.status_label.setText("Installed")
    # Delete the setup folder only if the game isn't inside it and it isn't a folder the launcher needs.
    safe = (os.path.isdir(setup_dir) and not _too_broad(setup_dir)
            and not _is_inside(exe, setup_dir)
            and not (getattr(w, "install_dir", None) and _is_inside(setup_dir, w.install_dir)))
    if not safe:
        QMessageBox.information(self, "Installed " + self.title, "Installed. Game:\n" + exe)
        return
    if QMessageBox.question(
            self, "Delete setup files?",
            "Installed. Game:\n" + exe + "\n\nDelete the setup folder now?\n" + setup_dir
    ) == QMessageBox.StandardButton.Yes:
        _delete_folder_async(setup_dir)
        try:
            invalidate_library_roots()
        except Exception:
            _log_exc("_card_on_finished_setup")
DownloadCard.on_finished = _card_on_finished_setup


def _new_game_worker_run(self):
    dest_path = self.existing_zip_path
    try:
        downloaded_here = False
        if not dest_path or not os.path.exists(dest_path):
            downloaded_here = True
            dest_path = resumable_download(
                self, lambda: _resolve_version_link(self),
                lambda response, url: safe_filename_from_headers(response, self.title))

        if self._is_cancelled:
            if downloaded_here and dest_path and os.path.exists(dest_path):
                try:
                    os.remove(dest_path)
                except Exception:    # expected: cleanup that may already be done
                    pass
            self.failed.emit("CANCELLED")
            return

        if self.download_only:
            self.finished.emit(dest_path)
            return

        if self.wine_extract_dir:
            self.status_update.emit("Extracting game files...")
            part_dir = self.wine_extract_dir + ".part"
            shutil.rmtree(part_dir, ignore_errors=True)
            extract_archive(dest_path, part_dir)
            shutil.rmtree(self.wine_extract_dir, ignore_errors=True)
            os.rename(part_dir, self.wine_extract_dir)
            if downloaded_here:
                try:
                    os.remove(dest_path)
                except OSError:    # expected: cleanup that may already be done
                    pass
        elif sys.platform.startswith("linux") and self.linux_cmd:
            self.status_update.emit("Linux Conversion Script Running...\nPlease complete installation in the new terminal window.")
            os.makedirs(GAMES_DIR, exist_ok=True)
            linux_install_terminal(self.linux_cmd, os.path.abspath(DOWNLOAD_DIR), dest_path).wait()
        else:
            self.status_update.emit("Extracting game files...")
            extract_dir = installed_game_dir(self.title)
            extract_archive(dest_path, extract_dir)

        if downloaded_here and self.remote_version and not self.wine_extract_dir:
            record_installed_version(self.title, self.remote_version)
        
        self.finished.emit(dest_path)
    except Exception as e:
        if self._is_cancelled:
            self.failed.emit("CANCELLED")
        else:
            self.failed.emit(str(e))

GameDownloadWorker.run = _new_game_worker_run
class AddExistingGameConfigDialog(QDialog):
    def __init__(self, appid, title, cover_path, parent=None):
        super().__init__(parent)
        self.setWindowTitle(f"Configure Existing Game: {title}")
        self.setFixedSize(440, 260)
        self.appid = appid
        self.game_title = title
        self.cover_path = cover_path
        self.result_data = None

        layout = QVBoxLayout(self)
        layout.setContentsMargins(20, 20, 20, 20)
        layout.setSpacing(12)

        form = QFormLayout()
        form.setSpacing(10)

        exe_layout = QHBoxLayout()
        self.exe_edit = QLineEdit()
        exe_btn = QPushButton("Browse...")
        exe_btn.clicked.connect(self.browse_exe)
        exe_layout.addWidget(self.exe_edit, 1)
        exe_layout.addWidget(exe_btn)
        form.addRow(QLabel("Executable"), exe_layout)

        if sys.platform.startswith("linux"):
            self.compat_combo = QComboBox()
            self.compat_combo.addItem("Default (System Wine / Native)", "")
            tools = get_available_compatibility_tools()
            for name, path in sorted(tools.items()):
                self.compat_combo.addItem(name, path)
            form.addRow(QLabel("Compatibility Tool"), self.compat_combo)
        else:
            self.compat_combo = None

        layout.addLayout(form)

        btn_layout = QHBoxLayout()
        btn_ok = QPushButton("Add to Library")
        btn_ok.setObjectName("Primary")
        btn_cancel = QPushButton("Cancel")
        btn_ok.clicked.connect(self.accept_data)
        btn_cancel.clicked.connect(self.reject)
        btn_layout.addStretch()
        btn_layout.addWidget(btn_cancel)
        btn_layout.addWidget(btn_ok)
        layout.addLayout(btn_layout)

    def browse_exe(self):
        path, _ = QFileDialog.getOpenFileName(self, "Select Executable", os.path.expanduser("~"))
        if path:
            self.exe_edit.setText(path)

    def accept_data(self):
        exe = self.exe_edit.text().strip()
        if not exe or not os.path.exists(exe):
            QMessageBox.warning(self, "Invalid Input", "Please provide a valid, existing executable path.")
            return
        compat = self.compat_combo.currentData() if self.compat_combo else ""
        self.result_data = {
            "appid": self.appid,
            "title": self.game_title,
            "cover": self.cover_path,
            "exe_path": exe,
            "compat_tool": compat
        }
        self.accept()

class SteamStorePickerDialog(QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Select Steam Game")
        self.resize(600, 500)
        self.selected_game = None
        self._workers = []

        layout = QVBoxLayout(self)
        layout.setContentsMargins(20, 20, 20, 20)
        layout.setSpacing(12)

        search_layout = QHBoxLayout()
        self.search_edit = QLineEdit()
        self.search_edit.setPlaceholderText("Search Steam store...")
        self.search_edit.returnPressed.connect(self.do_search)
        search_btn = QPushButton("Search")
        search_btn.setObjectName("Primary")
        search_btn.clicked.connect(self.do_search)
        search_layout.addWidget(self.search_edit, 1)
        search_layout.addWidget(search_btn)
        layout.addLayout(search_layout)

        self.scroll = QScrollArea()
        self.scroll.setWidgetResizable(True)
        self.scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.container = QWidget()
        self.grid = QGridLayout(self.container)
        self.grid.setAlignment(Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignLeft)
        self.scroll.setWidget(self.container)
        layout.addWidget(self.scroll, 1)

        self.loader = CoverLoader()
        self.loader.set_key(get_steamgriddb_key())
        self.loader.loaded.connect(self._on_cover_loaded)
        self.cards = {}

        self.do_search()

    def do_search(self):
        term = self.search_edit.text().strip()
        while self.grid.count():
            item = self.grid.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        self.cards = {}

        def work():
            try:
                games, _ = fetch_steam_games(term, 0, 30)
                return games
            except Exception:
                return []

        worker = TaskWorker(work)
        worker.done.connect(self._on_games_loaded)
        self._workers.append(worker)
        worker.start()

    def _on_games_loaded(self, games):
        cols = 3
        for idx, (appid, title, img_base) in enumerate(games):
            card = StoreCard(appid, title)
            card.clicked.connect(self.on_card_clicked)
            self.cards[appid] = card
            self.grid.addWidget(card, idx // cols, idx % cols)
            self.loader.request(appid, img_base, title)

    def _on_cover_loaded(self, appid, path):
        card = self.cards.get(appid)
        if card:
            card.set_cover(path)

    def on_card_clicked(self, appid, title, cover_path):
        saved_cover = cover_path
        if cover_path and os.path.exists(cover_path):
            try:
                os.makedirs(get_library_cover_dir(), exist_ok=True)
                saved_cover = os.path.join(get_library_cover_dir(), f"{appid}.img")
                shutil.copyfile(cover_path, saved_cover)
            except Exception:
                _log_exc("on_card_clicked")

        cfg_dlg = AddExistingGameConfigDialog(appid, title, saved_cover, self)
        if cfg_dlg.exec() == QDialog.DialogCode.Accepted and cfg_dlg.result_data:
            self.selected_game = cfg_dlg.result_data
            self.accept()



AdaptiveApp._original_create_steam_card_compat = AdaptiveApp.create_steam_card

def _patched_create_steam_card_combined(self, appid, title_text, cover_path):
    AdaptiveApp._original_create_steam_card_compat(self, appid, title_text, cover_path)
    card = self.steam_cards.get(appid)
    if card:
        btn_play = card.findChild(QPushButton, "Primary")
        status_label = card.findChild(QLabel, "CardStatus")
        
        custom_exe = None
        for g in load_steam_library():
            if g.get("appid") == appid and g.get("exe_path"):
                custom_exe = g.get("exe_path")
                break

        if custom_exe:
            btn_play.setText("Launch")
            if status_label:
                status_label.setText("● Installed")
                status_label.setStyleSheet(f"color: {GREEN};")

            try:
                btn_play.clicked.disconnect()
            except Exception:    # expected: cleanup that may already be done
                pass

            def launch_existing_game():
                if not os.path.exists(custom_exe):
                    QMessageBox.warning(self, "Launch Error", f"Executable not found:\n{custom_exe}")
                    return
                if sys.platform.startswith("win"):
                    try:
                        subprocess.Popen([custom_exe] + launch_args_for(str(appid)), cwd=os.path.dirname(custom_exe))
                    except Exception as e:
                        QMessageBox.warning(self, "Launch Game", f"Couldn't launch game: {e}")
                elif sys.platform.startswith("linux"):
                    _launch_exe(self, custom_exe, load_compat_config().get(str(appid), ""), _d3d_for(str(appid)),
                                launch_args_for(str(appid)))

            btn_play.clicked.connect(launch_existing_game)

        if sys.platform.startswith("linux"):
            more_btn = card.findChild(QPushButton, "MoreButton")
            if more_btn and more_btn.menu():
                menu = more_btn.menu()
                has_compat_action = any("Compatibility Tool" in action.text() for action in menu.actions())
                if not has_compat_action:
                    def open_compat_dialog():
                        self.switch_compat_tool(str(appid))

                    menu.addAction("Switch Compatibility Tool").triggered.connect(open_compat_dialog)

AdaptiveApp.create_steam_card = _patched_create_steam_card_combined    # kept as patch chain: a replacement patch sits in the middle of the chain, so it is not a plain wrapper chain

# Every custom-card patch before this one was removed; wrap the plain library page.
AdaptiveApp._true_original_build_library_page = AdaptiveApp.build_library_page

def _unified_build_library_page(self):
    widget = AdaptiveApp._true_original_build_library_page(self)
    
    main_layout = widget.layout()
    if main_layout and main_layout.count() > 0:
        header_item = main_layout.itemAt(0)
        if header_item and header_item.layout():
            header_layout = header_item.layout()
            
            # Remove ALL existing '+' buttons left over from previous patches
            buttons_to_remove = []
            for i in range(header_layout.count()):
                item = header_layout.itemAt(i)
                if item and item.widget() and isinstance(item.widget(), QPushButton):
                    if item.widget().text() == "+":
                        buttons_to_remove.append(item.widget())
            
            for btn in buttons_to_remove:
                header_layout.removeWidget(btn)
                btn.setParent(None)
                btn.deleteLater()
            
            # Add exactly ONE clean '+' button
            add_btn = QPushButton("+")
            add_btn.setFixedSize(28, 28)
            add_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            add_btn.setToolTip("Add game")
            add_btn.setStyleSheet("font-size: 18px; font-weight: bold; border-radius: 14px; padding: 0px;")
            
            menu = QMenu(add_btn)
            menu.addAction("Add Custom Game").triggered.connect(self.open_add_custom_game_dialog)
            menu.addAction("Add Existing Game").triggered.connect(self.open_add_existing_game_dialog)
            menu.addAction("Add Existing Fan Game").triggered.connect(lambda _c=False: self._fan_add_existing())
            
            def show_menu():
                pos = add_btn.mapToGlobal(add_btn.rect().bottomLeft())
                if hasattr(menu, "exec"):
                    menu.exec(pos)
                else:
                    menu.exec_(pos)
                
            add_btn.clicked.connect(show_menu)
            header_layout.insertWidget(2, add_btn)

    for game in load_custom_games():
        self.create_custom_card(game.get("id"), game.get("title"), game.get("exe_path"), game.get("cover_path"), game.get("compat_tool"))
        
    self.apply_filter()
    return widget

AdaptiveApp.build_library_page = _unified_build_library_page    # kept as patch chain: a replacement patch sits in the middle of the chain, so it is not a plain wrapper chain

# ── friends system ──
import secrets as _secrets

FRIEND_CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
FRIEND_ONLINE_WINDOW_MS = 100000     # heartbeat is every 30 s

def _friends_cache_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "friends.json")

def _fdb(path, token, query=""):
    base = FIREBASE_DB_URL.strip().rstrip("/")
    q = ("&" + query) if query else ""
    return f"{base}/{path}.json?auth={urllib.parse.quote(token, safe='')}{q}"

def friend_code_cached():
    acct = load_account()
    if not acct:
        return ""
    try:
        with open(_friends_cache_path(), encoding="utf-8") as f:
            data = json.load(f)
        if data.get("uid") == acct["uid"]:
            return str(data.get("code") or "")
    except Exception:    # expected: file may not exist yet or be unreadable
        pass
    return ""

def _save_friend_code_cache(uid, code):
    os.makedirs(os.path.dirname(_friends_cache_path()), exist_ok=True)
    with open(_friends_cache_path(), "w", encoding="utf-8") as f:
        json.dump({"uid": uid, "code": code}, f)

def cloud_ensure_friend_code():
    token, uid = get_id_token()
    cached = friend_code_cached()
    if cached:
        return cached
    code = _http_json(_fdb(f"public/{uid}/code", token))
    if not (isinstance(code, str) and code):
        for _ in range(8):
            cand = "".join(_secrets.choice(FRIEND_CODE_ALPHABET) for _ in range(8))
            if _http_json(_fdb(f"codes/{cand}", token)) is None:
                _http_json(_fdb(f"codes/{cand}", token), "PUT", uid)
                code = cand
                break
        else:
            raise CloudError("Couldn't create a friend code, try again.", "NO_CODE")
        _http_json(_fdb(f"public/{uid}/code", token), "PUT", code)
    _save_friend_code_cache(uid, code)
    return code

# --- what the player is currently playing
_now_playing = {"name": None}
_running_dirs = {}           # game name -> the folder the launcher started it from
_playing_listeners = []

def pretty_game_name(name):
    """'deltarune' -> 'Deltarune'. Names that already have any capitals are left alone."""
    name = str(name or "")
    if name and name == name.lower():
        return re.sub(r"(^|[\s\-_:.])([a-z])", lambda m: m.group(1) + m.group(2).upper(), name)
    return name

_library_snapshot = []  # every game card in the launcher, kept up to date from the GUI thread

def _canonical_title(name):
    low = str(name).lower()
    for t in _library_snapshot:
        if t.lower() == low:
            return t
    return name

def friends_library_titles():
    if _library_snapshot:
        return list(_library_snapshot)
    titles = []
    for info in GAME_INFO.values():
        if os.path.isdir(installed_game_dir(info["name"])) or os.path.isdir(wine_game_dir(info["name"])):
            titles.append(info["name"])
    for g in load_steam_library() + load_custom_games() + load_fan_library():
        t = g.get("title")
        if t and t not in titles:
            titles.append(t)
    return [pretty_game_name(t) for t in titles]

_NOT_A_GAME_EXE = re.compile(r"^(setup|install|installer|unins\w*|uninstall\w*|vc_?redist\w*|dxsetup|dxwebsetup|dotnet\w*|"
                             r"7z\w*|7-?zip\w*|nanazip\w*|peazip\w*|winrar|unrar|rar|unar|bsdtar|tar|unzip|msiexec|"
                             r"explorer|cmd|powershell|pwsh|wget|curl|xdg-open)(\.exe|\.sh|\.bat|\.cmd)?$", re.I)
_ARCHIVE_EXTS = (".zip", ".rar", ".7z", ".part", ".tar", ".gz", ".xz", ".zst", ".torrent")

def _is_not_a_game_launch(args):
    """setup.exe / extractors / anything that just touches an archive is not 'playing' a game."""
    try:
        first = next((a for a in args if isinstance(a, str) and a), "")
        if _NOT_A_GAME_EXE.match(re.split(r"[\\/]", first.strip('"'))[-1]):
            return True
        for a in args:
            if isinstance(a, str) and a.lower().strip('"').endswith(_ARCHIVE_EXTS):
                return True
    except Exception:
        pass
    return False

def _game_name_for_args(args):
    if _is_not_a_game_launch(args):
        return None
    known = {}
    try:
        fan = load_fan_library()
    except Exception:
        fan = []
    for g in load_steam_library() + load_custom_games() + fan:
        if g.get("exe_path") and g.get("title"):
            known[os.path.normcase(os.path.abspath(g["exe_path"]))] = g["title"]
    for a in args:
        if not isinstance(a, str):
            continue
        full = os.path.abspath(a)
        norm = os.path.normcase(full)
        if norm in known:
            return _canonical_title(known[norm])
        for root in library_roots():
            if norm.startswith(os.path.normcase(root) + os.sep):
                first = os.path.relpath(full, root).split(os.sep)[0]
                for info in GAME_INFO.values():
                    if first.lower().startswith(info["name"].lower()):
                        return _canonical_title(info["name"])
                return _canonical_title(first)
    return None

_running = {}  # game name -> Popen of the running game
_tracked_members = {}   # game name -> {pid: psutil.Process} of every process currently counted as that game

# helpers a game can leave behind or start that must not keep "playing" on (browsers it opened, wine/console helpers)
_TRACK_IGNORE = {
    "conhost.exe", "werfault.exe", "explorer.exe", "svchost.exe", "services.exe", "winedevice.exe", "plugplay.exe",
    "rpcss.exe", "wineserver", "xdg-open", "chrome.exe", "msedge.exe", "firefox.exe", "brave.exe", "opera.exe",
    "vivaldi.exe", "iexplore.exe", "chrome", "chromium", "firefox", "brave", "microsoft-edge",
}
_TRACK_GRACE = 8.0      # seconds with no game process alive before the game counts as closed (covers exe -> exe hand-offs)

def _game_folder_for(args, cwd):
    """The game's own folder (used to recognise the next .exe it starts), or None if it can't be told apart safely."""
    folder = None
    if isinstance(cwd, str) and os.path.isdir(cwd):
        folder = cwd
    else:
        for a in args:
            if isinstance(a, str) and os.path.isabs(a) and os.path.isfile(a) and \
                    a.lower().endswith((".exe", ".sh", ".x86_64", ".appimage", ".bat", ".cmd")):
                folder = os.path.dirname(a)
                break
    if not folder:
        return None
    f = os.path.normcase(os.path.abspath(folder))
    try:
        roots = {os.path.normcase(os.path.abspath(r)) for r in library_roots()}
    except Exception:
        roots = set()
    if f in roots or os.path.dirname(f) == f or f == os.path.normcase(os.path.expanduser("~")):
        return None     # the shared library folder, a drive root or home would match unrelated programs
    return f

def _watch_game(name, proc, folder, t0):
    """Blocks until the game is really over. Unlike proc.wait() this survives a launcher/stub that starts the real
    .exe and quits: any process started by the game (even after its parent died), or started from the game's folder
    after the launch, keeps the game counted as running. Over once nothing is left for _TRACK_GRACE seconds."""
    import psutil    # lazy: saves memory/startup until used
    me = os.getpid()
    fol = (folder + os.sep) if folder else None
    members = {}
    ever = {proc.pid}
    rejected = {}                 # pid -> create_time of processes already checked and found unrelated
    try:
        members[proc.pid] = psutil.Process(proc.pid)
    except psutil.Error:    # expected: the process may already have exited
        pass
    _tracked_members[name] = members

    def ignored(p_):
        try:
            return p_.name().lower() in _TRACK_IGNORE
        except psutil.Error:
            return True

    def in_folder(p_):
        try:
            exe = p_.exe()
            if exe and os.path.normcase(exe).startswith(fol):
                return True
            return any(os.path.normcase(a).startswith(fol) for a in p_.cmdline())
        except psutil.Error:
            return False

    def refresh():
        alive, stack = {}, []
        for pid, p_ in list(members.items()):
            try:
                if p_.is_running() and p_.status() != psutil.STATUS_ZOMBIE:
                    alive[pid] = p_
                    stack.append(p_)
            except psutil.Error:    # expected: the process may already have exited
                pass
        while stack:                                   # everything the game started
            p_ = stack.pop()
            try:
                kids = p_.children()
            except psutil.Error:
                continue
            for c in kids:
                if c.pid in alive or c.pid == me or ignored(c):
                    continue
                alive[c.pid] = c
                ever.add(c.pid)
                stack.append(c)
        try:                                           # started by a member that already quit, or from the game's folder
            for c in psutil.process_iter(["pid", "ppid", "create_time"]):
                pid, ct = c.info["pid"], c.info["create_time"] or 0
                if pid in alive or pid == me or ct < t0 - 2 or rejected.get(pid) == ct:
                    continue
                if c.info["ppid"] in ever or (fol and in_folder(c)):
                    if not ignored(c):
                        alive[pid] = c
                        ever.add(pid)
                        continue
                rejected[pid] = ct
        except Exception:    # expected: the process may already have exited
            pass
        members.clear()
        members.update(alive)
        return bool(alive)

    gone_at = None
    try:
        while True:
            try:
                proc.poll()                            # also reaps the original process
            except Exception:
                _log_exc("_watch_game")
            try:
                ok = refresh()
            except Exception:
                ok = proc.poll() is None
            if ok:
                gone_at = None
                time.sleep(1.0 if time.time() - t0 < 60 else 3.0)     # every process on the PC is scanned: 1 s only at first
            else:
                if gone_at is None:
                    gone_at = time.time()
                if time.time() - gone_at >= _TRACK_GRACE:
                    break
                time.sleep(0.5)
    finally:
        if _tracked_members.get(name) is members:
            del _tracked_members[name]

# kept: used at import time before the later definition at line 26355
def _track_playing(name, proc, folder=None):
    name = pretty_game_name(name)
    _running[name] = proc
    _running_dirs[name] = folder
    _now_playing["name"] = name
    for cb in _playing_listeners:
        cb()
    t0 = time.time()
    def wait():
        try:
            try:
                import psutil  # noqa: F401
            except ImportError:
                proc.wait()                            # without psutil only the launched process itself can be followed
            else:
                _watch_game(name, proc, folder, t0)
        except Exception:
            try:
                proc.wait()
            except Exception:    # expected: cleanup that may already be done
                pass
        if _running.get(name) is proc:
            del _running[name]
        if _now_playing["name"] == name:
            _now_playing["name"] = next(iter(_running), None)
            for cb in _playing_listeners:
                cb()
    threading.Thread(target=wait, daemon=True).start()

_RealPopen = subprocess.Popen

class _TrackedPopen(_RealPopen):
    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        try:
            args = a[0] if a else k.get("args")
            if isinstance(args, (list, tuple)):
                name = _game_name_for_args(args)
                if name:
                    _track_playing(name, self, _game_folder_for(args, k.get("cwd")))
        except Exception:
            _log_exc("__init__")

subprocess.Popen = _TrackedPopen

import hashlib as _hashlib

_library_covers = {}   # pretty game title -> cover image path (kept up to date from the GUI thread)
_covers_sig = {"v": None}
_cover_enc_cache = {}

def _cover_key(title):
    return _hashlib.md5(str(title).lower().encode("utf-8")).hexdigest()[:12]

def _encode_cover(path):
    """Small JPEG (base64) of a cover image, cached until the file changes."""
    try:
        mt = os.path.getmtime(path)
    except OSError:
        return None
    cached = _cover_enc_cache.get(path)
    if cached and cached[0] == mt:
        return cached[1]
    img = QImage(path)
    enc = None
    if not img.isNull():
        img = img.scaledToWidth(120, Qt.TransformationMode.SmoothTransformation)
        img = img.convertToFormat(QImage.Format.Format_RGB32)
        buf = QBuffer()
        buf.open(QIODevice.OpenModeFlag.WriteOnly)
        if img.save(buf, "JPEG", 72) and buf.data():
            enc = base64.b64encode(bytes(buf.data())).decode("ascii")
            if len(enc) > 60000:
                enc = None
    _cover_enc_cache[path] = (mt, enc)
    return enc

def cloud_publish_covers(token, uid):
    covers = {}
    for title, path in list(_library_covers.items()):
        enc = _encode_cover(path)
        if enc:
            covers[_cover_key(title)] = enc
    sig = (uid, tuple(sorted((k, hash(v)) for k, v in covers.items())))
    if not covers or sig == _covers_sig["v"]:
        return
    _http_json(_fdb(f"covers/{uid}", token), "PUT", covers)
    _covers_sig["v"] = sig

def cloud_fetch_covers(friend_uid):
    token, _uid = get_id_token()
    data = _http_json(_fdb(f"covers/{friend_uid}", token))
    return data if isinstance(data, dict) else {}

def library_cover_paths():
    """{game title: cover image path} for every game in the library, one method for all of them:
    NCZ games (assets folder), store games + Add Existing Game, and custom games."""
    out = {}
    for name, fname in ((AE_GAME_NAME, "fnanczaecover.png"), (NCZ2_GAME_NAME, "fnancz2cover.png"),
                        ("Five Nights at NCZ: The Return", "fnancz-tr.png"), ("NCZ Chess", "nczchess.png"),
                        ("NCZFront", "nczfront-cover.png")):
        path = asset_path(fname)
        if os.path.exists(path):
            out[pretty_game_name(name)] = path
    for g in load_steam_library():
        if g.get("title") and g.get("cover") and os.path.exists(g["cover"]):
            out[pretty_game_name(g["title"])] = g["cover"]
    for g in load_custom_games():
        if g.get("title") and g.get("cover_path") and os.path.exists(g["cover_path"]):
            out[pretty_game_name(g["title"])] = g["cover_path"]
    for g in load_fan_library():
        if g.get("title") and g.get("cover") and os.path.exists(g["cover"]):
            out[pretty_game_name(g["title"])] = g["cover"]
    return out

def _friend_cover_file(uid, key, b64):
    """Writes a friend's cover to a small cache file so the normal cover renderer can draw it."""
    raw = _decode_photo(b64)
    if not raw:
        return None
    folder = os.path.join(os.path.dirname(get_launcher_settings_path()), "friend_covers")
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, re.sub(r"[^A-Za-z0-9]", "_", uid) + "_" + key + ".jpg")
    try:
        if not os.path.exists(path) or os.path.getsize(path) != len(raw):
            with open(path, "wb") as f:
                f.write(raw)
    except OSError:
        return None
    return path

# Idle = the launcher window is minimized (or hidden in the tray).
_window_state = {"minimized": False}

def is_idle():
    return _window_state["minimized"]

def workshop_mods_for_game(appid):
    """[{'id', 'title'}] for the Workshop mods of one game that are downloaded on this PC."""
    out = []
    try:
        for d in ws_load_downloads():
            if d["appid"] == appid and os.path.isdir(workshop_item_dir(d["appid"], d["id"])):
                out.append({"id": str(d["id"]), "title": str(d.get("title") or "")[:120]})
    except Exception:
        _log_exc("workshop_mods_for_game")
    return out

def workshop_parse_mods(raw):
    """[(id, title)] from a shared mod list, tolerant of Firebase turning lists into dicts."""
    found = []
    for r in (raw.values() if isinstance(raw, dict) else raw if isinstance(raw, list) else []):
        if isinstance(r, dict) and str(r.get("id", "")).isdigit():
            found.append((str(r["id"]), str(r.get("title") or "")))
    return found

_presence_lock = threading.Lock()
_presence_state = {"offline": False, "full_sig": None, "full_at": 0.0}
_clock_skew = {"ms": 0.0}          # server time minus this PC's time, so a wrong PC clock can't fake "online"
PRESENCE_FULL_EVERY = 600          # seconds: re-send the whole profile at least this often

def cloud_publish_presence():
    """Light heartbeat (seen/playing/idle) normally. The heavy profile (photo, library, covers, playtime)
    is only sent when it changed, or every PRESENCE_FULL_EVERY seconds."""
    if _presence_state["offline"]:
        return                         # the launcher is quitting; a late heartbeat must not undo "offline"
    with _presence_lock:
        if _presence_state["offline"]:
            return
        try:
            cloud_autoset_country()
        except Exception:    # expected: offline or the server did not answer
            pass
        token, uid = get_id_token()
        username, avatar = load_profile_cache()
        username = username or (load_account() or {}).get("email", "").split("@")[0] or "Player"
        library = friends_library_titles()
        installed = _dg_installed_titles(library)
        country = load_profile_country() or None
        ptime = profile_ptime_payload()
        try:
            avatar_sig = (avatar, os.path.getmtime(avatar)) if avatar and os.path.exists(avatar) else None
        except OSError:
            avatar_sig = None
        sig = (uid, username, json.dumps(library, sort_keys=True, default=str), json.dumps(installed), country,
               json.dumps(ptime, sort_keys=True, default=str), avatar_sig)
        full = (sig != _presence_state["full_sig"]
                or time.time() - _presence_state["full_at"] > PRESENCE_FULL_EVERY)
        payload = {
            "playing": _now_playing["name"] or "",
            "idle": is_idle(),
            "seen": {".sv": "timestamp"},
        }
        if full:
            payload.update({"username": username, "library": library, "installed": installed, "country": country, "ptime": ptime,
                            "photo": None})
            if avatar_sig:
                with open(avatar, "rb") as f:
                    payload["photo"] = base64.b64encode(f.read()).decode("ascii")
        t0 = time.time() * 1000
        resp = _http_json(_fdb(f"public/{uid}", token), "PATCH", payload)
        if full:
            _presence_state["full_sig"] = sig
            _presence_state["full_at"] = time.time()
        try:    # if Firebase echoes the resolved server timestamp, use it to measure this PC's clock error
            srv = resp.get("seen") if isinstance(resp, dict) else None
            if isinstance(srv, (int, float)) and srv > 0:
                _clock_skew["ms"] = srv - (t0 + (time.time() * 1000 - t0) / 2)
        except Exception:
            _log_exc("cloud_publish_presence")
        if full:
            try:
                cloud_publish_covers(token, uid)
            except CloudError:
                pass  # covers are optional; never break presence over them

def cloud_publish_offline():
    _presence_state["offline"] = True       # stops any heartbeat that is still in flight or starts later
    token, uid = get_id_token()
    with _presence_lock:                    # waits for an in-flight heartbeat so "offline" is always the last write
        _http_json(_fdb(f"public/{uid}", token), "PATCH", {"seen": 0, "idle": False, "playing": ""})

def cloud_accept_friend(other):
    token, uid = get_id_token()
    _http_json(_fdb(f"friends/{uid}/{other}", token), "PUT", True)
    _http_json(_fdb(f"friends/{other}/{uid}", token), "PUT", True)
    _http_json(_fdb(f"requests/{uid}/{other}", token), "DELETE")

