# --- mod sharing: A asks B, B's launcher pops up a yes/no, and only on yes B's mod list is written for A.
def cloud_modshare_send_request(friend, appid, game):
    token, uid = get_id_token()
    _http_json(_fdb(f"modshare_replies/{uid}/{friend}", token), "DELETE")   # drop any stale answer
    _http_json(_fdb(f"modshare_requests/{friend}/{uid}", token), "PUT",
               {"appid": int(appid), "game": str(game)[:80], "username": _my_display_name(),
                "time": {".sv": "timestamp"}})

def cloud_modshare_check_reply(friend):
    """The friend's answer if there is one (and clears the exchange), else None."""
    token, uid = get_id_token()
    data = _http_json(_fdb(f"modshare_replies/{uid}/{friend}", token))
    if not isinstance(data, dict):
        return None
    _http_json(_fdb(f"modshare_replies/{uid}/{friend}", token), "DELETE")
    _http_json(_fdb(f"modshare_requests/{friend}/{uid}", token), "DELETE")
    return data

def cloud_modshare_cancel_request(friend):
    token, uid = get_id_token()
    _http_json(_fdb(f"modshare_requests/{friend}/{uid}", token), "DELETE")

def cloud_modshare_fetch_requests():
    token, uid = get_id_token()
    data = _http_json(_fdb(f"modshare_requests/{uid}", token))
    return data if isinstance(data, dict) else {}

def cloud_modshare_answer(requester, appid, game, accept):
    token, uid = get_id_token()
    reply = {"appid": int(appid), "game": str(game)[:80], "accepted": bool(accept),
             "time": {".sv": "timestamp"}}
    if accept:
        reply["username"] = _my_display_name()
        reply["mods"] = workshop_mods_for_game(int(appid))
    _http_json(_fdb(f"modshare_replies/{requester}/{uid}", token), "PUT", reply)
    _http_json(_fdb(f"modshare_requests/{uid}/{requester}", token), "DELETE")

def cloud_decline_friend(other):
    token, uid = get_id_token()
    _http_json(_fdb(f"requests/{uid}/{other}", token), "DELETE")

def cloud_add_friend(code):
    """Sends a friend request. Returns 'sent', or 'accepted' if they had already asked us."""
    code = re.sub(r"[^A-Za-z0-9]", "", code or "").upper()
    if len(code) != 8:
        raise CloudError("Friend codes are 8 characters long.", "BAD_CODE")
    token, uid = get_id_token()
    other = _http_json(_fdb(f"codes/{code}", token))
    if not isinstance(other, str):
        raise CloudError("No one has that friend code.", "NO_SUCH_CODE")
    if other == uid:
        raise CloudError("That's your own code!", "SELF")
    if _http_json(_fdb(f"friends/{uid}/{other}", token)):
        raise CloudError("You're already friends.", "ALREADY")
    if _http_json(_fdb(f"requests/{uid}/{other}", token)):
        cloud_accept_friend(other)
        return "accepted"
    _http_json(_fdb(f"requests/{other}/{uid}", token), "PUT", True)
    return "sent"

def cloud_fetch_requests():
    token, uid = get_id_token()
    ids = _http_json(_fdb(f"requests/{uid}", token))
    ids = list(ids.keys()) if isinstance(ids, dict) else []
    out = {}
    for rid in ids:
        try:
            d = _http_json(_fdb(f"public/{rid}", token))
        except CloudError:
            d = {}
        out[rid] = d if isinstance(d, dict) else {}
    return out

_friends_last_good = {}

def cloud_fetch_friends():
    token, uid = get_id_token()
    ids = _http_json(_fdb(f"friends/{uid}", token))
    ids = list(ids.keys()) if isinstance(ids, dict) else []
    def one(fid):
        for attempt in range(2):
            try:
                d = _http_json(_fdb(f"public/{fid}", token))
                if isinstance(d, dict):
                    _friends_last_good[fid] = d
                    return fid, d
                break
            except CloudError:
                continue
        # fetch failed: keep showing what we knew instead of a blank "Unknown / Offline" profile
        return fid, _friends_last_good.get(fid, {})
    with ThreadPoolExecutor(max_workers=4) as ex:
        return dict(ex.map(one, ids))

def _chat_id(a, b):
    return "_".join(sorted([a, b]))

def cloud_get_messages(other):
    token, uid = get_id_token()
    data = _http_json(_fdb(f"chats/{_chat_id(uid, other)}", token,
                           'orderBy=%22%24key%22&limitToLast=60'))
    if not isinstance(data, dict):
        return uid, [], None
    keys = [k for k in sorted(data) if isinstance(data[k], dict)]
    for k in keys:
        data[k]["_key"] = k
    return uid, [data[k] for k in keys], (keys[-1] if keys else None)

def cloud_set_typing(other, on):
    """The "<me> is typing..." flag. It lives in the user's own public/<uid>/typing node: only its owner writes there and
    friends already read it for presence, so the database rules need no change. A failure only costs the indicator."""
    token, uid = get_id_token()
    url = _fdb(f"public/{uid}/typing", token)
    if on:
        _http_json(url, "PUT", {"to": other, "at": {".sv": "timestamp"}})
    else:
        _http_json(url, "DELETE")

def cloud_get_typing(other):
    """Server timestamp of the newest "typing" ping that friend `other` aimed at me, or None."""
    token, uid = get_id_token()
    d = _http_json(_fdb(f"public/{other}/typing", token))
    if isinstance(d, dict) and d.get("to") == uid and isinstance(d.get("at"), (int, float)):
        return d["at"]
    return None

