def _friends_invite_to_game(self):
    """One click: finds the game you're playing, its cover and the join link, and sends the invite.
    If the join link can't be found, a small dialog opens with everything else already filled in."""
    uid = self.current_uid
    if not uid or self._sending:
        return
    clip = normalize_steam_join(QApplication.clipboard().text())      # fallback: a link you just copied from the game
    self._set_status("Finding your game and join link...")
    def done(info, err):
        if uid != self.current_uid:
            return
        info = info or {}
        game, appid, link = info.get("game", ""), info.get("appid", 0), info.get("link", "") or clip     # the link you just copied: fallback
        if game and link:
            self._send_invite(uid, game, link, appid)
            return
        self._set_status("")
        note = ("Steam has no join link right now. Be in a joinable lobby or server (and set your Steam profile's Game "
                "details to public), or check the key below."
                if load_launcher_settings().get("steam_web_api_key") else
                "Enter a Steam Web API key and the launcher will find the join link for you.")
        if SteamApiKeyDialog(self, note).exec() == QDialog.DialogCode.Accepted:
            self.invite_to_game()
    self._run(detect_invite_info, done, key="invite-detect")

FriendsPage.invite_to_game = _friends_invite_to_game




