import io as _io
_tarfile = _LazyModule("tarfile")

STEAMCMD_WIN_URL = "https://client-update.steamstatic.com/installer/steamcmd.zip"
STEAMCMD_LINUX_URL = "https://steamcdn-a.akamaihd.net/client/installer/steamcmd_linux.tar.gz"
WS_SORTS = (("Trending", "trend"), ("Most Recent", "mostrecent"),
            ("Most Subscribed", "totaluniquesubscribers"), ("Recently Updated", "lastupdated"))

# The launcher's load_launcher_settings() drops unknown keys, so these tabs keep their own small file.
def _ws_cfg_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "workshop_tools.json")

def _ws_cfg_load():
    try:
        with open(_ws_cfg_path(), encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def ws_cfg_get(key, default=""):
    return _ws_cfg_load().get(key, default)

def ws_cfg_set(key, value):
    data = _ws_cfg_load()
    if value is None:
        data.pop(key, None)
    else:
        data[key] = value
    os.makedirs(os.path.dirname(_ws_cfg_path()), exist_ok=True)
    with open(_ws_cfg_path(), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=4)

def ws_downloads_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "workshop_downloads.json")

def ws_load_downloads():
    try:
        with open(ws_downloads_path(), encoding="utf-8") as f:
            data = json.load(f)
        return [d for d in data if isinstance(d, dict) and d.get("id") and d.get("appid")]
    except Exception:
        return []

def ws_save_downloads(items):
    os.makedirs(os.path.dirname(ws_downloads_path()), exist_ok=True)
    with open(ws_downloads_path(), "w", encoding="utf-8") as f:
        json.dump(items, f, indent=4)

def steamcmd_dir():
    return os.path.join(SCRIPT_DIR, "steamcmd")

def steamcmd_exe():
    return os.path.join(steamcmd_dir(), "steamcmd.exe" if sys.platform.startswith("win") else "steamcmd.sh")

def workshop_dir():
    return os.path.join(SCRIPT_DIR, "workshop")

def workshop_item_dir(appid, item_id):
    return os.path.join(workshop_dir(), "steamapps", "workshop", "content", str(appid), str(item_id))

def ensure_steamcmd(status):
    exe = steamcmd_exe()
    if os.path.exists(exe):
        return exe
    os.makedirs(steamcmd_dir(), exist_ok=True)
    win = sys.platform.startswith("win")
    status("Downloading SteamCMD...")
    data = _http_get(STEAMCMD_WIN_URL if win else STEAMCMD_LINUX_URL, timeout=120)
    status("Extracting SteamCMD...")
    if win:
        with zipfile.ZipFile(_io.BytesIO(data)) as z:
            z.extractall(steamcmd_dir())
    else:
        with _tarfile.open(fileobj=_io.BytesIO(data), mode="r:gz") as t:
            try:
                t.extractall(steamcmd_dir(), filter="data")
            except TypeError:
                t.extractall(steamcmd_dir())
        try:
            os.chmod(exe, 0o755)
        except OSError:    # expected: cleanup that may already be done
            pass
    if not os.path.exists(exe):
        raise RuntimeError("SteamCMD could not be extracted")
    return exe

def _ws_has_files(path):
    if not os.path.isdir(path):
        return False
    for _folder, _dirs, names in os.walk(path):
        if names:
            return True
    return False

def locate_workshop_item(appid, item_id):
    """Path of a downloaded Workshop item, or None. Also rescues items SteamCMD put in its own folder."""
    canon = workshop_item_dir(appid, item_id)
    if _ws_has_files(canon):
        return canon
    alt = os.path.join(steamcmd_dir(), "steamapps", "workshop", "content", str(appid), str(item_id))
    if _ws_has_files(alt):
        try:
            shutil.rmtree(canon, ignore_errors=True)
            os.makedirs(os.path.dirname(canon), exist_ok=True)
            shutil.move(alt, canon)
            return canon
        except Exception:
            return None
    return None

def ws_steamcmd_log_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "workshop_steamcmd.log")

_WS_ID_RE = re.compile(r'data-publishedfileid="(\d+)"')
_WS_TITLE_RE = re.compile(r'class="workshopItemTitle[^"]*"[^>]*>(.*?)</div>', re.S)
_WS_AUTHOR_RE = re.compile(r'class="workshopItemAuthorName[^"]*"[^>]*>(.*?)</div>', re.S)

def _ws_text(fragment):
    text = html_lib.unescape(re.sub(r"<[^>]+>", "", fragment or "")).replace("\xa0", " ").strip()
    return re.sub(r"\s+", " ", text)

def _parse_workshop_items_legacy(page):
    """Old Workshop markup (data-publishedfileid attributes)."""
    starts, seen = [], set()
    for m in _WS_ID_RE.finditer(page):
        if m.group(1) not in seen:
            seen.add(m.group(1))
            starts.append((m.start(), m.group(1)))
    items = []
    for i, (pos, fid) in enumerate(starts):
        end = starts[i + 1][0] if i + 1 < len(starts) else len(page)
        chunk = page[pos:end]
        title = _WS_TITLE_RE.search(chunk)
        img = _IMG_RE.search(chunk)
        author = _WS_AUTHOR_RE.search(chunk)
        author_text = re.sub(r"^by\s+", "", _ws_text(author.group(1)) if author else "", flags=re.I)
        items.append({"id": fid, "title": _ws_text(title.group(1)) if title else f"Item {fid}",
                      "preview": html_lib.unescape(img.group(1)) if img else "", "author": author_text})
    return items

_WS_A_RE = re.compile(r'<a\b([^>]*)>(.*?)</a>', re.S)
_WS_HREF_RE = re.compile(r'\bhref="([^"]*)"')
_WS_FILE_RE = re.compile(r'filedetails/\?id=(\d+)')
_WS_ALT_RE = re.compile(r'<img\b[^>]*?\balt="([^"]*)"', re.S)

def parse_workshop_items(page):
    """Reads Workshop items from the links Steam renders: each item is a link to
    sharedfiles/filedetails/?id=ID (image + title) followed by an author link."""
    order, info, current = [], {}, None
    for m in _WS_A_RE.finditer(page):
        hm = _WS_HREF_RE.search(m.group(1))
        if not hm:
            continue
        href, inner = html_lib.unescape(hm.group(1)), m.group(2)
        fm = _WS_FILE_RE.search(href)
        if fm:
            fid = fm.group(1)
            if fid not in info:
                info[fid] = {"id": fid, "title": "", "preview": "", "author": "", "author_url": ""}
                order.append(fid)
            current = info[fid]
            img = _IMG_RE.search(inner)
            if img and not current["preview"]:
                current["preview"] = re.sub(r"(imw|imh)=\d+", r"\1=288", html_lib.unescape(img.group(1)))
            text = _ws_text(inner)
            if not text:
                alt = _WS_ALT_RE.search(inner)
                text = html_lib.unescape(alt.group(1)).strip() if alt else ""
            if text and not current["title"]:
                current["title"] = text
        elif "myworkshopfiles" in href and current is not None and not current["author"]:
            current["author"] = re.sub(r"^by\s+", "", _ws_text(inner), flags=re.I)
            um = re.search(r"(/(?:id|profiles)/[^/?#]+)/myworkshopfiles", href)
            if um:
                current["author_url"] = "https://steamcommunity.com" + um.group(1)
    items = []
    for fid in order:
        d = info[fid]
        d["title"] = d["title"] or f"Item {fid}"
        items.append(d)
    return items or _parse_workshop_items_legacy(page)

def _ws_installed_games():
    out = []
    for g in load_steam_library():
        exe = g.get("exe_path")
        installed = bool(exe and os.path.exists(exe))
        if not installed:
            installed = bool(find_best_game_exe(_safe_installed_game_dir(g["title"]), g["title"]))
        if installed:
            out.append(g)
    return out

def _fmt_size(n):
    """Format a byte count: MB below 1 GB, GB from 1 GB up."""
    n = float(n)
    if n >= 1024 ** 3:
        return f"{n / 1024 ** 3:.2f} GB"
    return f"{n / (1024 * 1024):.1f} MB"

def _ws_fmt_size(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024

def _ws_dir_size(path):
    total = 0
    for folder, _d, names in os.walk(path):
        for n in names:
            try:
                total += os.path.getsize(os.path.join(folder, n))
            except OSError:    # expected: file may not exist yet or be unreadable
                pass
    return total

def _ws_crop_round(pm, w, h, radius=8):
    scale = _screen_dpr()
    sw, sh = int(round(w * scale)), int(round(h * scale))
    scaled = pm.scaled(sw, sh, Qt.AspectRatioMode.KeepAspectRatioByExpanding,
                       Qt.TransformationMode.SmoothTransformation)
    out = QPixmap(sw, sh)
    out.fill(Qt.GlobalColor.transparent)
    p = QPainter(out)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    clip = QPainterPath()
    clip.addRoundedRect(QRectF(0, 0, sw, sh), radius * scale, radius * scale)
    p.setClipPath(clip)
    p.drawPixmap((sw - scaled.width()) // 2, (sh - scaled.height()) // 2, scaled)
    p.end()
    out.setDevicePixelRatio(scale)
    return out

class _WsImages(QObject):
    loaded = pyqtSignal(str, bytes)

    def __init__(self):
        super().__init__()
        self.pool = ThreadPoolExecutor(max_workers=4)
        self.cache, self.pending = {}, {}
        self.loaded.connect(self._on_loaded)
        QApplication.instance().aboutToQuit.connect(lambda: self.pool.shutdown(wait=False, cancel_futures=True))

    def request(self, url, setter):
        if not url:
            return
        if url in self.cache:
            setter(self.cache[url])
        elif url in self.pending:
            self.pending[url].append(setter)
        else:
            self.pending[url] = [setter]
            self.pool.submit(self._fetch, url)

    def _fetch(self, url):
        try:
            data = _http_get(url, timeout=15)
        except Exception:
            data = b""
        self.loaded.emit(url, data)

    def _on_loaded(self, url, data):
        setters = self.pending.pop(url, [])
        pm = QPixmap()
        if not data or not pm.loadFromData(data):
            return
        self.cache[url] = pm
        for s in setters:
            try:
                s(pm)
            except RuntimeError:  # the label was deleted meanwhile
                pass

class WorkshopFetchWorker(QThread):
    done = pyqtSignal(int, list, str)

    def __init__(self, token, appid, query, sort, page, parent=None):
        super().__init__(parent)
        self.token, self.appid, self.query, self.sort, self.page = token, appid, query, sort, page

    def run(self):
        try:
            params = {"appid": self.appid, "searchtext": self.query, "childpublishedfileid": 0,
                      "browsesort": self.sort, "section": "readytouseitems", "p": self.page,
                      "numperpage": 30, "l": "english"}
            if self.sort == "trend":
                params["days"] = 7
            headers = {"Accept-Language": "en-US,en;q=0.9", "Cookie": "birthtime=568022401; lastagecheckage=1-0-1988"}
            url = "https://steamcommunity.com/workshop/browse/?" + urllib.parse.urlencode(params)
            page = _http_get(url, headers=headers, timeout=20).decode("utf-8", "replace")
            items = parse_workshop_items(page)
            if not items and self.page == 1 and not self.query:  # fall back to the game's Workshop hub page
                page = _http_get(f"https://steamcommunity.com/app/{self.appid}/workshop/?l=english",
                                 headers=headers, timeout=20).decode("utf-8", "replace")
                items = parse_workshop_items(page)
            if not items and not self.query:
                dump = os.path.join(os.path.dirname(get_launcher_settings_path()), "workshop_debug.html")
                try:
                    os.makedirs(os.path.dirname(dump), exist_ok=True)
                    with open(dump, "w", encoding="utf-8") as f:
                        f.write(page)
                except OSError:
                    _log_exc("run")
                self.done.emit(self.token, [], f"Steam's page had no items I could read (saved a copy to {dump})")
                return
            self.done.emit(self.token, items, "")
        except Exception as e:
            self.done.emit(self.token, [], str(e))

_WS_HEADERS = {"Accept-Language": "en-US,en;q=0.9", "Cookie": "birthtime=568022401; lastagecheckage=1-0-1988"}

def ws_profile_base(text):
    """Steam profile base URL from a pasted profile link or a 17-digit SteamID64, else ''."""
    t = (text or "").strip()
    m = re.search(r"steamcommunity\.com/(id|profiles)/([^/?#\s]+)", t, re.I)
    if m:
        return f"https://steamcommunity.com/{m.group(1).lower()}/{m.group(2)}"
    if re.fullmatch(r"7656\d{13}", t):
        return f"https://steamcommunity.com/profiles/{t}"
    return ""

class WorkshopAuthorWorker(QThread):
    """Lists one author's Workshop items for a game. Takes a profile link/SteamID64, a known profile
    base (clicked author name), or a plain name (scans search results for a matching author)."""
    done = pyqtSignal(int, list, str)
    resolved = pyqtSignal(int, str)     # profile base used for paging ("" when the results are just filtered)

    def __init__(self, token, appid, query, base, page, parent=None):
        super().__init__(parent)
        self.token, self.appid, self.query, self.base, self.page = token, appid, query, base, page

    def _get(self, url):
        return _http_get(url, headers=_WS_HEADERS, timeout=20).decode("utf-8", "replace")

    def _author_items(self, base, page, name):
        url = f"{base}/myworkshopfiles/?" + urllib.parse.urlencode(
            {"appid": self.appid, "p": page, "browsefilter": "myfiles", "l": "english"})
        html = self._get(url)
        items = parse_workshop_items(html)
        if not name:
            m = re.search(r"<title>(.*?)</title>", html, re.S)
            parts = [p.strip() for p in html_lib.unescape(m.group(1)).split("::")] if m else []
            name = parts[1] if len(parts) >= 3 else ""
        for it in items:
            if not it.get("author"):
                it["author"] = name
            it["author_url"] = base
        return items

    def run(self):
        try:
            link_base = ws_profile_base(self.query)
            base = self.base or link_base
            if base:
                name = "" if link_base else self.query
                items = self._author_items(base, self.page, name)
                self.resolved.emit(self.token, base)
                self.done.emit(self.token, items, "")
                return
            needle = self.query.casefold()
            hits, seen, exact = [], set(), None
            for text, page in ((self.query, 1), (self.query, 2), ("", 1), ("", 2), ("", 3)):
                params = {"appid": self.appid, "searchtext": text, "childpublishedfileid": 0,
                          "browsesort": "totaluniquesubscribers", "section": "readytouseitems",
                          "p": page, "numperpage": 30, "l": "english"}
                html = self._get("https://steamcommunity.com/workshop/browse/?" + urllib.parse.urlencode(params))
                for it in parse_workshop_items(html):
                    if it["id"] in seen:
                        continue
                    seen.add(it["id"])
                    if needle in (it.get("author") or "").casefold():
                        hits.append(it)
                        if (it["author"].casefold() == needle and it.get("author_url")) and exact is None:
                            exact = it
                if exact:
                    break
            if exact:
                items = self._author_items(exact["author_url"], 1, exact["author"])
                self.resolved.emit(self.token, exact["author_url"])
                self.done.emit(self.token, items or hits, "")
                return
            self.resolved.emit(self.token, "")
            self.done.emit(self.token, hits, "")
        except Exception as e:
            self.done.emit(self.token, [], str(e))

def ws_parse_item_ids(text):
    """Workshop item IDs from pasted links (…filedetails/?id=123) or bare numeric IDs, in order."""
    ids = []
    for tok in re.split(r"[\s,;]+", text or ""):
        m = re.search(r"[?&]id=(\d+)", tok)
        fid = m.group(1) if m else (tok if tok.isdigit() and len(tok) >= 5 else "")
        if fid and fid not in ids:
            ids.append(fid)
    return ids

class _SyncFriendCard(QFrame):
    """One friend as a clickable card: profile picture, username and status."""
    picked = pyqtSignal(str)
    confirmed = pyqtSignal(str)

    def __init__(self, uid, name, status, color, avatar_path):
        super().__init__()
        self.uid, self.name = uid, name
        self.setObjectName("SyncCard")
        self.setProperty("selected", False)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedHeight(84)
        h = QHBoxLayout(self)
        h.setContentsMargins(14, 10, 14, 10)
        h.setSpacing(12)
        av = QLabel("?")
        av.setObjectName("SyncAvatar")
        av.setFixedSize(56, 56)
        av.setAlignment(Qt.AlignmentFlag.AlignCenter)
        apply_avatar(av, avatar_path, name[:1].upper(), 56)
        col = QVBoxLayout()
        col.setSpacing(2)
        n = QLabel(name)
        n.setObjectName("SyncName")
        n.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        n.setToolTip(name)
        st = QLabel(f"\u25CF  {status}")
        st.setObjectName("SyncStatus")
        st.setStyleSheet(f"color: {color};")
        st.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        col.addStretch()
        col.addWidget(n)
        col.addWidget(st)
        col.addStretch()
        h.addWidget(av)
        h.addLayout(col, 1)
        for w in (av, n, st):
            w.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)

    def set_selected(self, on):
        self.setProperty("selected", bool(on))
        self.style().unpolish(self)
        self.style().polish(self)

    def mousePressEvent(self, _e):
        self.picked.emit(self.uid)

    def mouseDoubleClickEvent(self, _e):
        self.confirmed.emit(self.uid)

def _pick_sync_friend(parent, rows, game, heading="Sync mods with friend", blurb=None, ask="Ask ", note=None):
    """Card picker. rows = [(uid, name, status, color, avatar_path)]. Returns the chosen uid or None."""
    dlg = QDialog(parent)
    dlg.setWindowTitle(heading)
    dlg.resize(580, 470)
    lay = QVBoxLayout(dlg)
    lay.setContentsMargins(24, 22, 24, 20)
    lay.setSpacing(12)
    title = QLabel(heading)
    title.setObjectName("PageTitle")
    sub = QLabel(blurb or f"Request a friend to share their {game} mods with you, they have to accept first")
    sub.setObjectName("RowDesc")
    sub.setWordWrap(True)
    lay.addWidget(title)
    lay.addWidget(sub)
    scroll = QScrollArea()
    scroll.setWidgetResizable(True)
    scroll.setFrameShape(QFrame.Shape.NoFrame)
    holder = QWidget()
    grid = QGridLayout(holder)
    grid.setContentsMargins(0, 4, 0, 4)
    grid.setSpacing(10)
    grid.setColumnStretch(0, 1)
    grid.setColumnStretch(1, 1)
    cards, state = [], {"uid": None}
    go = QPushButton("Pick a friend")
    go.setObjectName("Primary")
    go.setFixedHeight(34)
    go.setEnabled(False)

    def pick(uid):
        state["uid"] = uid
        for c in cards:
            c.set_selected(c.uid == uid)
        go.setEnabled(True)
        go.setText(ask + next(c.name for c in cards if c.uid == uid))

    for i, (uid, name, status, color, avatar) in enumerate(rows):
        c = _SyncFriendCard(uid, name, status, color, avatar)
        c.picked.connect(pick)
        c.confirmed.connect(lambda u: (pick(u), dlg.accept()))
        cards.append(c)
        grid.addWidget(c, i // 2, i % 2)
    grid.setRowStretch((len(rows) + 1) // 2, 1)
    scroll.setWidget(holder)
    lay.addWidget(scroll, 1)
    note = QLabel(note or "Your friend needs the launcher open to answer. The request expires after 2 minutes.")
    note.setObjectName("RowDesc")
    note.setWordWrap(True)
    lay.addWidget(note)
    btns = QHBoxLayout()
    btns.addStretch()
    cancel = QPushButton("Cancel")
    cancel.setFixedHeight(34)
    cancel.clicked.connect(dlg.reject)
    go.clicked.connect(dlg.accept)
    btns.addWidget(cancel)
    btns.addWidget(go)
    lay.addLayout(btns)
    return state["uid"] if dlg.exec() == QDialog.DialogCode.Accepted else None

class WorkshopFriendsWorker(QThread):
    """Fetches the friend list (with each friend's shared Workshop mods) from the cloud."""
    done = pyqtSignal(dict, str)   # {uid: public profile}, error text

    def run(self):
        try:
            self.done.emit(cloud_fetch_friends(), "")
        except CloudError as e:
            self.done.emit({}, str(e))
        except Exception as e:
            self.done.emit({}, f"Couldn't reach your friends: {e}")

class WorkshopModshareWorker(QThread):
    """Sends a mod-share request to a friend and waits for their yes/no."""
    done = pyqtSignal(dict, str)   # friend's answer, error ("timeout" / "cancelled" / message)
    TIMEOUT = 120

    def __init__(self, friend_uid, appid, game, parent=None):
        super().__init__(parent)
        self.friend, self.appid, self.game = friend_uid, appid, game
        self._cancelled = False

    def cancel(self):
        self._cancelled = True

    def run(self):
        try:
            cloud_modshare_send_request(self.friend, self.appid, self.game)
        except Exception as e:
            self.done.emit({}, str(e) or "Couldn't send the request.")
            return
        deadline, err = time.time() + self.TIMEOUT, "timeout"
        while time.time() < deadline:
            if self._cancelled:
                err = "cancelled"
                break
            try:
                reply = cloud_modshare_check_reply(self.friend)
            except Exception:
                reply = None        # a hiccup: keep waiting
            if reply is not None:
                self.done.emit(reply, "")
                return
            for _ in range(6):
                if self._cancelled:
                    break
                time.sleep(0.5)
        try:
            cloud_modshare_cancel_request(self.friend)
        except Exception:    # expected: offline or the server did not answer
            pass
        self.done.emit({}, err)

class WorkshopLinkWorker(QThread):
    """Looks up pasted Workshop items (title, preview, game) through Steam's public item-details API."""
    done = pyqtSignal(list, list)   # [(appid, game title, item dict)], [error strings]

    def __init__(self, ids, known_games, parent=None):
        super().__init__(parent)
        self.ids, self.known = list(ids), dict(known_games)

    def _author_name(self, steamid):
        try:
            xml = _http_get(f"https://steamcommunity.com/profiles/{steamid}/?xml=1", timeout=8).decode("utf-8", "replace")
            m = re.search(r"<steamID><!\[CDATA\[(.*?)\]\]></steamID>", xml, re.S)
            return m.group(1).strip() if m else ""
        except Exception:
            return ""

    def _game_name(self, appid):
        try:
            js = json.loads(_http_get(f"https://store.steampowered.com/api/appdetails?appids={appid}&filters=basic",
                                      timeout=8).decode("utf-8", "replace"))
            return js[str(appid)]["data"]["name"]
        except Exception:
            return f"App {appid}"

    def run(self):
        results, errors = [], []
        try:
            body = {"itemcount": len(self.ids)}
            body.update({f"publishedfileids[{i}]": v for i, v in enumerate(self.ids)})
            req = urllib.request.Request(
                "https://api.steampowered.com/ISteamRemoteStorage/GetPublishedFileDetails/v1/",
                data=urllib.parse.urlencode(body).encode(), headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req, timeout=20, context=_NCZ_SSL_CTX) as resp:
                details = json.loads(resp.read().decode("utf-8", "replace")).get("response", {}).get(
                    "publishedfiledetails", [])
        except Exception as e:
            self.done.emit([], [f"Couldn't reach Steam: {e}"])
            return
        by_id = {str(d.get("publishedfileid")): d for d in details if isinstance(d, dict)}
        authors, games = {}, dict(self.known)
        for fid in self.ids:
            d = by_id.get(fid)
            if not d or d.get("result") != 1:
                errors.append(f"{fid}: not found (it may be private or deleted)")
                continue
            if d.get("file_type") == 2:
                errors.append(f"{fid}: that's a collection, not a single mod")
                continue
            try:
                appid = int(d.get("consumer_app_id") or d.get("creator_app_id") or 0)
            except (TypeError, ValueError):
                appid = 0
            if not appid:
                errors.append(f"{fid}: couldn't tell which game it belongs to")
                continue
            creator = str(d.get("creator") or "")
            if creator and creator not in authors:
                authors[creator] = self._author_name(creator)
            if appid not in games:
                games[appid] = self._game_name(appid)
            results.append((appid, games[appid],
                            {"id": fid, "title": d.get("title") or f"Workshop item {fid}",
                             "preview": d.get("preview_url") or "", "author": authors.get(creator, "")}))
        self.done.emit(results, errors)

class WorkshopDepsWorker(QThread):
    """Finds a Workshop item's 'Required items' (and theirs, recursively) through Steam's public item-details API,
    falling back to the item page when the API doesn't list them."""
    done = pyqtSignal(str, list)   # the item's id, [(appid, game title, item dict)] still to download

    MAX_DEPTH, MAX_ITEMS = 5, 40

    def __init__(self, item_id, appid, game, skip_ids, parent=None):
        super().__init__(parent)
        self.item_id, self.appid, self.game, self.skip = str(item_id), appid, game, set(skip_ids)
        self._games = {appid: game}

    def _details(self, ids):
        body = {"itemcount": len(ids)}
        body.update({f"publishedfileids[{i}]": v for i, v in enumerate(ids)})
        req = urllib.request.Request(
            "https://api.steampowered.com/ISteamRemoteStorage/GetPublishedFileDetails/v1/",
            data=urllib.parse.urlencode(body).encode(), headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=20, context=_NCZ_SSL_CTX) as resp:
            ds = json.loads(resp.read().decode("utf-8", "replace")).get("response", {}).get("publishedfiledetails", [])
        return {str(d.get("publishedfileid")): d for d in ds if isinstance(d, dict)}

    def _children(self, fid, details):
        kids = [str(c.get("publishedfileid")) for c in ((details or {}).get("children") or [])
                if isinstance(c, dict) and c.get("publishedfileid")]
        if kids:
            return kids
        try:     # the API had nothing: read the "Required items" box on the item's page
            page = _http_get(f"https://steamcommunity.com/sharedfiles/filedetails/?id={fid}",
                             headers={"User-Agent": "Mozilla/5.0", "Cookie": "birthtime=0; wants_mature_content=1"},
                             timeout=10).decode("utf-8", "replace")
            i = page.find('id="RequiredItems"')
            if i < 0:
                return []
            chunk = page[i:i + 4000]
            for marker in ('<div class="rightDetailsBlock', '<div class="detailBox', '<div class="workshopItemDescription'):
                j = chunk.find(marker, 20)
                if j > 0:
                    chunk = chunk[:j]
            out = []
            for m in re.finditer(r"workshop/filedetails/\?id=(\d+)", chunk):
                if m.group(1) not in out:
                    out.append(m.group(1))
            return out
        except Exception:
            return []

    def _game_name(self, appid):
        if appid not in self._games:
            try:
                js = json.loads(_http_get(f"https://store.steampowered.com/api/appdetails?appids={appid}&filters=basic",
                                          timeout=8).decode("utf-8", "replace"))
                self._games[appid] = js[str(appid)]["data"]["name"]
            except Exception:
                self._games[appid] = f"App {appid}"
        return self._games[appid]

    def run(self):
        found = []
        try:
            seen = set(self.skip) | {self.item_id}
            frontier, depth = [self.item_id], 0
            infos = self._details(frontier)
            while frontier and depth < self.MAX_DEPTH and len(found) < self.MAX_ITEMS:
                nxt = []
                for fid in frontier:
                    for kid in self._children(fid, infos.get(fid)):
                        if kid not in seen:
                            seen.add(kid)
                            nxt.append(kid)
                nxt = nxt[:self.MAX_ITEMS]
                if not nxt:
                    break
                infos = self._details(nxt)
                frontier = []
                for kid in nxt:
                    d = infos.get(kid)
                    if not d or d.get("result") != 1 or d.get("file_type") == 2:
                        continue
                    try:
                        appid = int(d.get("consumer_app_id") or d.get("creator_app_id") or self.appid or 0)
                    except (TypeError, ValueError):
                        appid = self.appid
                    if not appid:
                        continue
                    found.append((appid, self._game_name(appid),
                                  {"id": kid, "title": d.get("title") or f"Workshop item {kid}",
                                   "preview": d.get("preview_url") or "", "author": ""}))
                    frontier.append(kid)
                depth += 1
        except Exception:
            _log_exc("run")
        self.done.emit(self.item_id, found)

class SteamCmdWorker(QThread):
    status = pyqtSignal(str)
    progress = pyqtSignal(float)
    finished_item = pyqtSignal(bool, str)

    def __init__(self, appid, item_id, login, parent=None):
        super().__init__(parent)
        self.appid, self.item_id, self.login = appid, str(item_id), login or "anonymous"
        self.proc = None
        self._cancel = False

    def cancel(self):
        self._cancel = True
        try:
            if self.proc:
                self.proc.kill()
        except Exception:    # expected: cleanup that may already be done
            pass

    def run(self):
        log = []
        try:
            exe = ensure_steamcmd(self.status.emit)
            os.makedirs(workshop_dir(), exist_ok=True)
            cmd = [exe, "+force_install_dir", workshop_dir(), "+login", self.login,
                   "+workshop_download_item", str(self.appid), self.item_id, "+quit"]
            kwargs = {"creationflags": 0x08000000} if sys.platform.startswith("win") else {}
            err, rc = "", None
            for attempt in range(3):  # the first run(s) may self-update and exit before downloading
                if self._cancel:
                    break
                self.status.emit("Downloading..." if attempt == 0 else "Retrying...")
                log.append(f"--- attempt {attempt + 1}: {' '.join(cmd)}")
                self.proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                             stdin=subprocess.DEVNULL, text=True, errors="replace",
                                             cwd=steamcmd_dir(), **kwargs)
                for raw in self.proc.stdout:
                    line = raw.strip()
                    if not line:
                        continue
                    log.append(line)
                    m = re.search(r"progress:\s*([\d.]+)", line)
                    if m:
                        self.progress.emit(float(m.group(1)))
                    if re.search(r"ERROR!|^Failure|Login Failure", line):
                        err = line
                    self.status.emit(line[:100])
                rc = self.proc.wait()
                if locate_workshop_item(self.appid, self.item_id) or (err and attempt >= 1):
                    break
            try:
                with open(ws_steamcmd_log_path(), "w", encoding="utf-8") as f:
                    f.write("\n".join(log))
            except OSError:
                _log_exc("run")
            if self._cancel:
                self.finished_item.emit(False, "Cancelled")
            elif locate_workshop_item(self.appid, self.item_id):
                self.finished_item.emit(True, "")
            else:
                tail = [l for l in log if not l.startswith("---")][-3:]
                msg = err or ("SteamCMD finished without downloading the item. Last output: " + " | ".join(tail)
                              if tail else f"SteamCMD printed nothing (exit code {rc})")
                if any(k in msg for k in ("Failure", "No subscription", "Access Denied", "not logged")):
                    msg += " (this game's Workshop may need a Steam account that owns it)"
                self.finished_item.emit(False, f"{msg} [log: {ws_steamcmd_log_path()}]")
        except Exception as e:
            self.finished_item.emit(False, str(e))

class _WsClickFrame(QFrame):
    clicked = pyqtSignal()

    def mouseReleaseEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton and self.rect().contains(e.position().toPoint()):
            self.clicked.emit()
        super().mouseReleaseEvent(e)

_WS_MOD_COUNTS = {}   # appid -> number of Workshop items (only successful lookups are cached)
_WS_COUNT_APPROX = set()   # appids whose count is only a lower bound / estimate (shown as "30+")
WS_MIN_MODS = 3       # a game is listed in the Workshop picker only with MORE than 2 mods
_WS_STORE_CACHE = {}  # appid -> True/False: does the Store list the game as supporting the Steam Workshop?


def _ws_store_has_workshop(appid):
    """Store category 30 = 'Steam Workshop'. True / False, or None when the Store couldn't tell."""
    if appid in _WS_STORE_CACHE:
        return _WS_STORE_CACHE[appid]
    res = None
    try:
        raw = _http_get("https://store.steampowered.com/api/appdetails?" + urllib.parse.urlencode(
            {"appids": appid, "filters": "categories", "l": "english"}), timeout=15)
        d = (json.loads(raw.decode("utf-8", "replace")) or {}).get(str(appid)) or {}
        if d.get("success"):
            data = d.get("data")
            cats = data.get("categories") if isinstance(data, dict) else []
            res = any(int(c.get("id", 0)) == 30 for c in (cats or []))
    except Exception:
        res = None
    if res is not None:
        _WS_STORE_CACHE[appid] = res
    return res


def _ws_page_total(text):
    """Total from the page's own 'Showing 1-30 of N entries' line (and nothing else on the page)."""
    m = re.search(r'workshopBrowsePagingInfo[^>]*>([^<]{0,160})<', text)
    if m:
        n = re.search(r'of\s+([\d][\d,\.\s]*)', m.group(1))
        if n:
            digits = re.sub(r"[^\d]", "", n.group(1))
            if digits:
                return int(digits)
    return None


class WorkshopCountWorker(QThread):
    done = pyqtSignal(int, int)   # appid, count (-1 = lookup failed)

    def __init__(self, appid, parent=None):
        super().__init__(parent)
        self.appid = appid

    def _api_total(self):
        key = (load_launcher_settings().get("steam_web_api_key") or "").strip()
        if not key:
            return None
        try:
            raw = _http_get("https://api.steampowered.com/IPublishedFileService/QueryFiles/v1/?" + urllib.parse.urlencode(
                {"key": key, "appid": self.appid, "page": 1, "numperpage": 1, "query_type": 1,
                 "return_total": "true", "filetype": 0}), timeout=20)
            r = (json.loads(raw.decode("utf-8", "replace")) or {}).get("response") or {}
            if "total" in r:
                return int(r["total"])
        except Exception:    # expected: offline or the server did not answer
            pass
        return None

    def _fetch(self, p):
        import html as _html_mod    # lazy: saves memory/startup until used
        params = {"appid": self.appid, "searchtext": "", "childpublishedfileid": 0,
                  "browsesort": "mostrecent", "section": "readytouseitems", "p": p,
                  "numperpage": 30, "l": "english"}
        headers = {"Accept-Language": "en-US,en;q=0.9", "Cookie": "birthtime=568022401; lastagecheckage=1-0-1988"}
        page = _http_get("https://steamcommunity.com/workshop/browse/?" + urllib.parse.urlencode(params),
                         headers=headers, timeout=20).decode("utf-8", "replace")
        text = _html_mod.unescape(page).replace("\xa0", " ").replace("\u202f", " ")
        return page, text

    def _page_count(self):
        page, text = self._fetch(1)
        items = parse_workshop_items(page)
        if not items:
            return 0                                   # no items on the page = no Workshop
        total = _ws_page_total(text)
        if total is not None:
            return total
        # no total on the page: walk to the real last page and count exactly ((pages - 1) * 30 + items on the last page)
        last = max([int(x) for x in re.findall(r"[?&;]p=(\d+)", text)] or [1])
        if last <= 1:
            return len(items)
        for _ in range(5):
            pg, tx = self._fetch(last)
            nxt = max([int(x) for x in re.findall(r"[?&;]p=(\d+)", tx)] or [last])
            if nxt > last:
                last = nxt
                continue
            return (last - 1) * 30 + len(parse_workshop_items(pg))
        _WS_COUNT_APPROX.add(self.appid)
        return last * 30

    def run(self):
        try:
            if _ws_store_has_workshop(self.appid) is False:      # the game has no Workshop at all
                self.done.emit(self.appid, 0)
                return
            total = self._api_total()                            # exact, when a Steam Web API key is saved
            self.done.emit(self.appid, total if total is not None else self._page_count())
        except Exception:
            self.done.emit(self.appid, -1)


class WorkshopBrowserWorker(QThread):
    """Opens the game's Steam Workshop in a visible Playwright browser and reports every item the user subscribes to.
    The window stays open until the user closes it; the login is kept in a persistent profile."""
    subscribed = pyqtSignal(str)    # Workshop item id that was just subscribed to
    status = pyqtSignal(str)        # non-fatal hint (e.g. Steam refused the subscribe)
    failed = pyqtSignal(str)        # the browser couldn't be started

    def __init__(self, url, profile_dir, parent=None):
        super().__init__(parent)
        self.url, self.profile_dir = url, profile_dir
        self._stop = False

    def stop(self):
        self._stop = True

    @staticmethod
    def _item_id(req):
        try:
            body = req.post_data or ""
        except Exception:
            body = ""
        m = re.search(r"(?:^|&)id=(\d+)", body) or re.search(r'name="id"\s+(\d+)', body)
        return m.group(1) if m else ""

    def run(self):
        try:
            from playwright.sync_api import sync_playwright    # lazy: optional module: the except below handles it missing
        except ImportError:
            self.failed.emit("Playwright isn't installed. Run: pip install playwright && playwright install chromium")
            return
        try:
            with sync_playwright() as p:
                os.makedirs(self.profile_dir, exist_ok=True)
                ctx = p.chromium.launch_persistent_context(
                    self.profile_dir, headless=False, no_viewport=True,
                    args=["--disable-blink-features=AutomationControlled"])
                state = {"closed": False}
                ctx.on("close", lambda *_: state.__setitem__("closed", True))

                def on_response(resp):
                    try:
                        req = resp.request
                        if req.method != "POST" or "/sharedfiles/subscribe" not in resp.url:
                            return
                        fid = self._item_id(req)
                        if not fid:
                            return
                        ok = True
                        try:
                            js = resp.json()
                            if isinstance(js, dict) and "success" in js and int(js["success"]) != 1:
                                ok = False
                        except Exception:
                            _log_exc("on_response")                      # not JSON: a 200 is good enough
                        if ok:
                            self.subscribed.emit(fid)
                        else:
                            self.status.emit("Steam didn't accept that subscribe. Log in to Steam in the browser window and try again.")
                    except Exception:
                        _log_exc("on_response")
                ctx.on("response", on_response)

                page = ctx.pages[0] if ctx.pages else ctx.new_page()
                try:
                    page.goto(self.url, timeout=60000)
                except Exception:
                    _log_exc("run")
                while not self._stop and not state["closed"]:
                    if not ctx.pages:
                        break
                    try:
                        ctx.pages[0].wait_for_timeout(300)
                    except Exception:
                        time.sleep(0.3)
                try:
                    ctx.close()
                except Exception:    # expected: cleanup that may already be done
                    pass
        except Exception as e:
            self.failed.emit(f"Couldn't start the browser: {e}")

