# kept: used at import time before the later definition at line 24190
def _launch_exe(app, exe, compat_tool="", d3d="", args=None):
    if not exe or not os.path.exists(exe):
        QMessageBox.warning(app, "Launch Error", f"Executable not found:\n{exe}")
        return
    args = list(args or [])
    argv, cwd, extra = _launch_spec(app, exe, compat_tool)
    linux = sys.platform.startswith("linux")
    is_exe = exe.lower().endswith(".exe")
    if linux and is_exe and argv[0] == exe:
        QMessageBox.warning(app, "Wine Required",
                            "Wine wasn't found to run this Windows game.\nInstall it, or download a build in the Wine tab.")
        return
    _d3d_override["mode"] = d3d if d3d in WINE_D3D_MODES else ""
    try:
        if extra:  # Proton
            env = _clean_proton_env()
            compat = extra["STEAM_COMPAT_DATA_PATH"]
            os.makedirs(compat, exist_ok=True)
            env.update(extra)
            env.setdefault("PROTON_LOG", "1")            # Proton's own log (steam-*.log) goes next to the prefix
            env.setdefault("PROTON_LOG_DIR", compat)
            apply_proton_d3d(env)
            log_path = os.path.join(compat, "ncz_proton_launch.log")
            with open(log_path, "w", encoding="utf-8", errors="replace") as lf:
                lf.write("Command: " + " ".join(shlex.quote(a) for a in argv + args) + "\n")
                lf.write(f"Working dir: {cwd}\nSTEAM_COMPAT_DATA_PATH={compat}\n\n")
                lf.flush()
                proc = subprocess.Popen(argv + args, cwd=cwd, env=env, stdout=lf, stderr=subprocess.STDOUT)
            _watch_proton_start(app, proc, log_path)
        elif linux and is_exe:  # wine (system or a Wine tab build): applies the chosen D3D renderer
            launch_wine(argv[0], exe, cwd, args)
        else:
            subprocess.Popen(argv + args, cwd=cwd, env=os.environ.copy())
    except Exception as e:
        QMessageBox.warning(app, "Launch Error", f"Couldn't launch the game: {e}")
    finally:
        _d3d_override["mode"] = ""

# ── icon of an .exe (reads the PE resource table; no extra libraries) ──
def extract_exe_icon_ico(exe_path):
    import struct    # lazy: saves memory/startup until used
    try:
        with open(exe_path, "rb") as f:
            d = f.read()
        if d[:2] != b"MZ":
            return None
        pe = struct.unpack_from("<I", d, 0x3C)[0]
        if d[pe:pe + 4] != b"PE\0\0":
            return None
        nsec = struct.unpack_from("<H", d, pe + 6)[0]
        optsz = struct.unpack_from("<H", d, pe + 20)[0]
        opt = pe + 24
        magic = struct.unpack_from("<H", d, opt)[0]
        dd = opt + (112 if magic == 0x20b else 96)
        res_rva = struct.unpack_from("<II", d, dd + 16)[0]
        if not res_rva:
            return None
        secs = []
        for i in range(nsec):
            vs, va, rs, ro = struct.unpack_from("<IIII", d, opt + optsz + i * 40 + 8)
            secs.append((va, max(vs, rs), ro))

        def off(rva):
            for va, sz, ro in secs:
                if va <= rva < va + sz:
                    return rva - va + ro
            raise ValueError("rva")
        base = off(res_rva)

        def entries(o):
            named, ids = struct.unpack_from("<HH", d, base + o + 12)
            return [struct.unpack_from("<II", d, base + o + 16 + i * 8) for i in range(named + ids)]

        def leaf(o):
            while o & 0x80000000:
                o = entries(o & 0x7fffffff)[0][1]
            rva, size = struct.unpack_from("<II", d, base + o)
            fo = off(rva)
            return d[fo:fo + size]
        root = entries(0)
        groups = [e for e in root if e[0] == 14 and e[1] & 0x80000000]
        icons = [e for e in root if e[0] == 3 and e[1] & 0x80000000]
        if not groups or not icons:
            return None
        icon_map = {nm: ofs for nm, ofs in entries(icons[0][1] & 0x7fffffff)}
        grp = leaf(entries(groups[0][1] & 0x7fffffff)[0][1])
        count = struct.unpack_from("<H", grp, 4)[0]
        imgs = []
        for i in range(count):
            w, h, cc, _r, pl, bc, _br, iid = struct.unpack_from("<BBBBHHIH", grp, 6 + i * 14)
            if iid in icon_map:
                imgs.append((w or 256, h or 256, cc, pl, bc, leaf(icon_map[iid])))
        if not imgs:
            return None
        imgs.sort(key=lambda x: (x[0], x[4]), reverse=True)   # biggest first
        out = struct.pack("<HHH", 0, 1, len(imgs))
        pos, body = 6 + 16 * len(imgs), b""
        for w, h, cc, pl, bc, data in imgs:
            out += struct.pack("<BBBBHHII", w % 256, h % 256, cc, 0, pl, bc, len(data), pos + len(body))
            body += data
        return out + body
    except Exception:
        return None

def _exe_icon_png(exe, name):
    ico = extract_exe_icon_ico(exe)
    if not ico:
        return ""
    try:
        from PyQt6.QtGui import QImage    # lazy: saves memory/startup until used
        img = QImage()
        if not img.loadFromData(ico):
            return ""
        folder = os.path.expanduser("~/.local/share/icons/game-launcher")
        os.makedirs(folder, exist_ok=True)
        path = os.path.join(folder, re.sub(r"[^A-Za-z0-9_-]+", "_", name) + ".png")
        return path if img.save(path, "PNG") else ""
    except Exception:
        return ""

# kept: used at import time before the later definition at line 51041
def create_game_shortcut(app, title, exe, compat_tool="", fallback_icon="", launch_args=None):
    """Desktop shortcut for one library game. It opens the launcher (or tells the running one) and the launcher starts
    the game: `main.py --launch-game <title>`. The launcher applies the game's compatibility tool and launch options itself."""
    if not exe or not os.path.exists(exe):
        QMessageBox.warning(app, "Desktop Shortcut", "Couldn't find the game's executable. Is it installed?")
        return
    from PyQt6.QtCore import QStandardPaths    # lazy: saves memory/startup until used
    desktop = QStandardPaths.writableLocation(QStandardPaths.StandardLocation.DesktopLocation) or os.path.expanduser("~/Desktop")
    os.makedirs(desktop, exist_ok=True)
    safe = sanitize_folder_name(title) or "Game"
    try:
        argv, workdir = _ncz_game_launch_argv(title)
        if sys.platform.startswith("win"):
            q = lambda t: t.replace("'", "''")
            lnk = os.path.join(desktop, safe + ".lnk")
            ps = (f"$s=(New-Object -ComObject WScript.Shell).CreateShortcut('{q(lnk)}');"
                  f"$s.TargetPath='{q(argv[0])}';$s.WorkingDirectory='{q(workdir)}';"
                  f"$s.Arguments='{q(subprocess.list2cmdline(argv[1:]))}';"
                  f"$s.IconLocation='{q(exe)},0';$s.Description='{q(title)}';$s.Save()")
            subprocess.run(["powershell", "-NoProfile", "-Command", ps], check=True,
                           creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            target = lnk
        else:
            icon = _exe_icon_png(exe, safe) or (fallback_icon if fallback_icon and os.path.exists(fallback_icon) else "")
            target = os.path.join(desktop, safe + ".desktop")
            with open(target, "w", encoding="utf-8") as f:
                f.write("[Desktop Entry]\nType=Application\n"
                        f"Name={title}\nExec={_ncz_desktop_exec(argv)}\nPath={workdir}\n"
                        + (f"Icon={icon}\n" if icon else "") + "Terminal=false\nCategories=Game;\n")
            os.chmod(target, 0o755)
            try:  # GNOME: mark it trusted so it launches on double-click
                subprocess.run(["gio", "set", target, "metadata::trusted", "true"], capture_output=True, timeout=5)
            except Exception:
                _log_exc("create_game_shortcut")
        QMessageBox.information(app, "Desktop Shortcut", f"Shortcut created:\n{target}")
    except Exception as e:
        QMessageBox.warning(app, "Desktop Shortcut", f"Couldn't create the shortcut: {e}")

# ── winetricks for any game (Linux) ──
def _winetricks_env(app, exe, compat_tool):
    """(env, prefix, kind) for running winetricks inside the Wine/Proton prefix this game launches in.
    Proton games use the game's own Proton prefix and Proton's own wine (what protontricks does under the hood).
    Raises RuntimeError with a message for the user if that isn't possible."""
    kind = compat_tool_kind(compat_tool)
    if kind == "proton":
        wbin = _proton_wine_bin(compat_tool)
        if not wbin:
            raise RuntimeError("Couldn't find wine inside this Proton version:\n" + compat_tool)
        compat = compat_data_dir_for(exe)
        pfx = os.path.join(compat, "pfx")
        if not os.path.isdir(pfx):
            raise RuntimeError("This game's Proton prefix doesn't exist yet.\n"
                               "Launch the game once so Proton creates it, then try again.")
        files = os.path.dirname(os.path.dirname(wbin))          # .../files (or .../dist)
        env = _proton_redist_env((compat_tool, compat))
        env["WINEPREFIX"] = pfx
        env["WINE"] = wbin
        env["WINELOADER"] = wbin
        ws = os.path.join(files, "bin", "wineserver")
        if os.path.isfile(ws):
            env["WINESERVER"] = ws
        dll = [d for d in (os.path.join(files, "lib64", "wine"), os.path.join(files, "lib", "wine")) if os.path.isdir(d)]
        if dll:
            env["WINEDLLPATH"] = ":".join(dll)
        libs = [d for d in (os.path.join(files, "lib64"), os.path.join(files, "lib")) if os.path.isdir(d)]
        if libs:
            env["LD_LIBRARY_PATH"] = ":".join(libs + ([env["LD_LIBRARY_PATH"]] if env.get("LD_LIBRARY_PATH") else []))
        return env, pfx, "proton"
    if kind != "wine" and not (exe or "").lower().endswith(".exe"):
        raise RuntimeError("This looks like a native Linux game, so it doesn't use a Wine prefix.")
    wine = compat_tool if kind == "wine" else default_wine_path(app)
    if not wine:
        raise RuntimeError("Wine isn't installed, so there's no prefix to open winetricks in.")
    env = system_env()                  # no DLL overrides: winetricks should see the prefix as it is
    env["WINE"] = wine
    ws = os.path.join(os.path.dirname(wine), "wineserver")
    if os.path.isfile(ws):
        env["WINESERVER"] = ws
    prefix = env.get("WINEPREFIX") or _wine_prefix()
    env["WINEPREFIX"] = prefix
    return env, prefix, "wine"

def open_winetricks_for_game(app, title, exe, compat_tool=""):
    """Menu action (Linux): opens the winetricks window for the Wine/Proton prefix this game runs in."""
    if not sys.platform.startswith("linux"):
        return
    tricks = shutil.which("winetricks")
    if not tricks:
        QMessageBox.warning(app, "Winetricks", "winetricks isn't installed.\n\n"
                            "Install it with your package manager (for example: sudo apt install winetricks, "
                            "sudo pacman -S winetricks, or sudo dnf install winetricks), then try again.")
        return
    if not exe or not os.path.exists(exe):
        QMessageBox.warning(app, "Winetricks", f"{title} isn't installed yet, so it has no Wine/Proton prefix.")
        return
    try:
        env, prefix, kind = _winetricks_env(app, exe, compat_tool)
    except Exception as e:
        QMessageBox.warning(app, "Winetricks", str(e))
        return
    cmd = [tricks, "--gui"]
    if not (shutil.which("zenity") or shutil.which("kdialog")):
        QMessageBox.information(app, "Winetricks", "winetricks needs zenity or kdialog installed to show its window. "
                                "Install one of them and try again.")
        return
    try:
        subprocess.Popen(cmd, env=env, cwd=os.path.dirname(exe), stdin=subprocess.DEVNULL,
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
    except Exception as e:
        QMessageBox.warning(app, "Winetricks", f"Couldn't start winetricks: {e}")

def _winetricks_target(app, key, exe_fn, tool_fn):
    """(exe, compat tool) for a library card, resolved when the menu item is clicked."""
    if key in ("ae", "ncz2"):               # the built-in games run their Windows build from the wine folder
        name = AE_GAME_NAME if key == "ae" else NCZ2_GAME_NAME
        return _ae_launch_info(key, name)
    return exe_fn(), tool_fn()

# kept: used at import time before the later definition at line 31600
def _add_shortcut_action(app, card, title, exe_fn, tool_fn=lambda: "", cover="", key=None):
    more = card.findChild(QPushButton, "MoreButton") if card is not None else None
    if not more or not more.menu():
        return
    menu = more.menu()
    if key is not None:
        opts = menu.addAction("Launch Options")
        opts.setToolTip("Command-line arguments passed to the game when it starts")
        opts.triggered.connect(lambda _c=False: LaunchOptionsDialog(key, title, app).exec())
    menu.addAction("Create Desktop Shortcut").triggered.connect(
        lambda _c=False: create_game_shortcut(app, title, exe_fn(), tool_fn(), cover,
                                              launch_args_for(key) if key is not None else None))
    if sys.platform.startswith("linux"):
        wt = menu.addAction("Open Winetricks")
        wt.setToolTip("Install Windows components (DLLs, fonts, runtimes) into this game's Wine / Proton prefix")
        wt.triggered.connect(lambda _c=False: open_winetricks_for_game(app, title, *_winetricks_target(app, key, exe_fn, tool_fn)))

