class _TitleBarDrag(QObject):
    """Makes the top nav bar act as the title bar: drag to move, double-click to maximize / restore."""
    def __init__(self, window, bar):
        super().__init__(bar)
        self._window = window
        self._last_press = 0.0
        bar.installEventFilter(self)

    def _toggle_maximized(self):
        if self._window.isMaximized():
            self._window.showNormal()
        else:
            self._window.showMaximized()

    def eventFilter(self, obj, event):
        et = event.type()
        left = hasattr(event, "button") and event.button() == Qt.MouseButton.LeftButton
        if et == QEvent.Type.MouseButtonDblClick and left:
            self._last_press = 0.0
            self._toggle_maximized()
            return True
        if et == QEvent.Type.MouseButtonPress and left:
            now = time.monotonic()
            if now - self._last_press < QApplication.doubleClickInterval() / 1000.0:
                self._last_press = 0.0
                self._toggle_maximized()
                return True
            self._last_press = now
            handle = self._window.windowHandle()
            if handle is not None and not self._window.isMaximized():
                handle.startSystemMove()
            return True
        return False

def _caption_icon(restore):
    """Maximize (one square) / restore down (two squares) glyph, drawn so it doesn't depend on a font."""
    icon = QIcon()
    for mode, color in ((QIcon.Mode.Normal, _theme_state["nav_text"]), (QIcon.Mode.Active, _theme_state["nav_active"])):
        pm = QPixmap(24, 24)
        pm.setDevicePixelRatio(2.0)
        pm.fill(Qt.GlobalColor.transparent)
        p = QPainter(pm)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(QPen(QColor(color), 1.2))
        if restore:
            p.drawRect(QRectF(1.5, 3.5, 7, 7))
            p.drawPolyline([QPointF(3.5, 3.5), QPointF(3.5, 1.5), QPointF(10.5, 1.5),
                            QPointF(10.5, 8.5), QPointF(8.5, 8.5)])
        else:
            p.drawRect(QRectF(1.5, 1.5, 9, 9))
        p.end()
        icon.addPixmap(pm, mode)
    return icon

def _restart_icon():
    """Circular 'restart' arrow, drawn so it doesn't depend on a font."""
    icon = QIcon()
    for mode, color in ((QIcon.Mode.Normal, _theme_state["nav_text"]), (QIcon.Mode.Active, _theme_state["nav_active"])):
        pm = QPixmap(24, 24)
        pm.setDevicePixelRatio(2.0)
        pm.fill(Qt.GlobalColor.transparent)
        p = QPainter(pm)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        pen = QPen(QColor(color), 1.3)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        p.drawArc(QRectF(1.8, 1.8, 8.4, 8.4), 30 * 16, 300 * 16)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(color))
        p.drawPolygon([QPointF(10.64, 6.37), QPointF(11.07, 9.62), QPointF(7.61, 7.62)])
        p.end()
        icon.addPixmap(pm, mode)
    return icon

def restart_launcher(window, use_demo=False):
    """Starts a fresh copy of the launcher and closes this one. The new copy takes over through the normal
    'a newer launcher replaces the running one' path, so it waits for this process to let go of the instance lock.
    use_demo=True (the top-right restart button) starts demo.py instead of main.py when running from source."""
    frozen = getattr(sys, "frozen", False)
    args = [a for a in sys.argv[1:] if a not in ("--startup", "--friends")]   # --startup would make it bail out
    if "--launch-game" in args:                                               # don't start the game again after a restart
        _i = args.index("--launch-game")
        del args[_i:_i + 2]
    cmd = [sys.executable] + args if frozen else [sys.executable] + _launcher_script_args() + args     # cached compile
    demo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "demo.py")
    if use_demo and not frozen and not os.environ.get("APPIMAGE") and os.path.isfile(demo):
        cmd = [sys.executable, demo]        # demo.py (sign-in / installer) starts main.py itself once signed in
    env = dict(os.environ)
    if frozen:
        env["PYINSTALLER_RESET_ENVIRONMENT"] = "1"      # a onefile build must unpack itself again
    kwargs = {}
    if sys.platform.startswith("win"):
        kwargs["creationflags"] = 0x00000008 | 0x00000200       # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
    else:
        kwargs["start_new_session"] = True
    try:
        subprocess.Popen(cmd, env=env, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                         stderr=subprocess.DEVNULL, close_fds=True, **kwargs)
    except Exception as e:
        QMessageBox.warning(window, "Restart", f"Couldn't restart the launcher:\n{e}")
        return
    window._really_quit = True          # skip "close to tray"
    tray = getattr(window, "_tray", None)
    if tray is not None:
        tray.hide()
    QApplication.instance().quit()
    QTimer.singleShot(3000, lambda: os._exit(0))    # don't hang on a stuck background thread

class _WindowStateWatcher(QObject):
    def __init__(self, window, callback):
        super().__init__(window)
        self._callback = callback
        window.installEventFilter(self)

    def eventFilter(self, obj, event):
        if event.type() == QEvent.Type.WindowStateChange:
            self._callback()
        return False





