def _overlay_show_chess_invite(uid, name, tc, avatar):
    global _ov_chess_bridge
    if _ov_chess_bridge is None:
        _ov_chess_bridge = _OvChessBridge()
        _ov_chess_bridge.done.connect(_overlay_chess_ready)
    bridge = _ov_chess_bridge

    def work():
        gid, label = "", tc
        for _try in range(3):                        # the inbox entry is written just before the message: allow a moment
            try:
                found = _chess_find_invite(uid)
            except Exception:
                found = None
            if found:
                gid, label = found[0], (found[1].get("tc") or tc)
                break
            time.sleep(1.0)
        bridge.done.emit(name, label or "", avatar or "", gid, uid)
    threading.Thread(target=work, daemon=True).start()

def _overlay_group_look(page, gid, group_name, msg):
    """Group chat message -> (group icon file, sender picture file, sender uid, sender name)."""
    g = (getattr(page, "groups", None) or {}).get(gid) or {}
    try:
        icon = _grp_icon_of(gid, g) or _grp_letter_icon(gid, group_name)
    except Exception:
        icon = None
    sender = msg.get("from") if isinstance(msg, dict) else None
    prof = {}
    if sender:
        gp = getattr(page, "group_page", None)
        for src in ((gp.profiles if gp else {}), page.friends, {u: c[1] for u, c in _grp_prof_cache.items()}):
            if src.get(sender):
                prof = src[sender]
                break
    photo = _friend_avatar_file(sender, prof.get("photo")) if sender and prof.get("photo") else None
    return icon, photo, sender, (_grp_name_of(prof) if prof else "")

def _overlay_friend_event(page, name, text, uid):
    """Every friend notification (playing / online / friend request / message) -> overlay toast.
    A message with a picture (png / jpg / gif ...) shows the picture in the toast; a video says "sent a video"."""
    global _ov_image_bridge
    if _overlay is None:
        return
    msg = (page.__dict__.get("_ov_msgs") or {}).pop(uid, None)
    mode = get_overlay_mode()
    if mode == "off":
        return
    prefix, hl = _overlay_classify(text)
    inv = parse_invite(str(msg.get("text") or "")) if isinstance(msg, dict) else None
    g_icon = g_badge = None
    inviter = None                           # group chat: the toast names whoever wrote, not the group
    if not (isinstance(uid, str) and uid.startswith("group:")) and hasattr(_overlay, "notify_chess_invite"):
        ch_tc = _chess_challenge_tc((msg.get("text") if isinstance(msg, dict) else "") or text)
        if ch_tc is not None:
            if mode == "inject":                 # the injected in-game toast is text only, so the clickable one comes on top
                try:
                    from overlay import send_to_injected    # lazy: saves memory/startup until used
                    send_to_injected(name, "chess", "challenged you to ")
                except Exception:    # expected: optional module may be missing
                    pass
            _overlay_show_chess_invite(uid, name, ch_tc, _friend_avatar_file(uid, (page.friends.get(uid) or {}).get("photo")))
            return
    if isinstance(uid, str) and uid.startswith("group:"):
        g_icon, g_badge, s_uid, s_name = _overlay_group_look(page, uid[6:], name, msg)
        if s_uid and s_name:
            inviter = (s_uid, s_name, g_badge)
    if inv and hasattr(_overlay, "notify_invite"):
        if mode == "inject":                 # the injected in-game toast is text only, so the clickable one comes on top
            try:
                from overlay import send_to_injected    # lazy: saves memory/startup until used
                if inviter:
                    send_to_injected(inviter[1], inv.get("game") or "a game", "invited you to play ")
                else:
                    send_to_injected(name, hl, prefix)
            except Exception:    # expected: optional module may be missing
                pass
        if inviter:
            _overlay_show_invite(inviter[0], inviter[1], inv, inviter[2])
        else:
            _overlay_show_invite(uid, name, inv, g_icon or _friend_avatar_file(uid, ((page.friends.get(uid) or {}).get("photo"))))
        return
    att = None
    if isinstance(msg, dict):
        atts = [a for a in (msg.get("att") if isinstance(msg.get("att"), list) else []) if isinstance(a, dict)]
        if atts and atts[0].get("k") in ("img", "gif", "vid"):
            att = atts[0]
            caption = " ".join(str(msg.get("text") or "").split())
            if att.get("k") == "vid":
                prefix, hl = "sent a video", ""
            elif caption:
                prefix, hl = (caption if len(caption) <= 32 else caption[:29] + "..."), ""
            else:
                prefix, hl = ("sent a GIF" if att.get("k") == "gif" else "sent an image"), ""
    if mode == "inject":
        from overlay import send_to_injected    # lazy: saves memory/startup until used
        if send_to_injected(name, hl, prefix):
            return                       # shown inside the game (text only)
    info = (page.friends.get(uid) or page.requests.get(uid) or {})
    avatar = g_icon or _friend_avatar_file(uid, info.get("photo"))
    if att is None or att.get("k") == "vid":
        _overlay_show(name, hl, avatar, prefix, badge=g_badge)
        return
    if _ov_image_bridge is None:         # picture: download it (cached on disk) off the GUI thread, then show the toast
        _ov_image_bridge = _OvImageBridge()
        _ov_image_bridge.done.connect(lambda n, h, a, p, i, b: _overlay_show(n, h, a, p, i, b))
    bridge = _ov_image_bridge

    def work():
        try:
            path = cloud_fetch_media(uid, att)
        except Exception:
            path = ""
        bridge.done.emit(name, hl, avatar or "", prefix, path, g_badge or "")
    threading.Thread(target=work, daemon=True).start()

_ov_prev_launch_exe = _launch_exe

def _launch_exe(app, exe, compat_tool="", d3d="", args=None):
    linux = sys.platform.startswith("linux")
    if linux and _overlay is not None and exe and os.path.exists(exe):
        try:       # has to happen before the game starts: Wine reads AppInit_DLLs while the process is loading
            pfx = _overlay_prepare_wine(app, exe, compat_tool, get_overlay_mode() == "inject")
            _ov_log(f"overlay mode={get_overlay_mode()}, wine prefix prepared: {pfx}")
        except Exception as e:
            _ncz_log(f"overlay: couldn't set up the Wine prefix: {e}")
            _ov_log(f"couldn't set up the Wine prefix: {e!r}")
    _ov_prev_launch_exe(app, exe, compat_tool, d3d, args)
    if exe and os.path.exists(exe):
        # on Linux the Wine process takes a while to appear: look again a few times
        for ms in ((2500, 6000, 12000, 25000, 45000, 70000) if linux else (1500,)):
            QTimer.singleShot(ms, lambda: _overlay_game_launched(exe))

