        self.avatar = QLabel("?")
        self.avatar.setFixedSize(88, 88)
        self.avatar.setAlignment(Qt.AlignmentFlag.AlignCenter)
        rl.addWidget(self.avatar, 0, Qt.AlignmentFlag.AlignCenter)
        hl.addWidget(self.ring, 0, Qt.AlignmentFlag.AlignVCenter)
        col = QVBoxLayout()
        col.setSpacing(5)
