def _legacy_icon_path():
    """Classic icon (assets/icon-cl.png) with the N and the glow turned mint; white outline, stars and sky stay.
    Generated once, cached in the config folder."""
    src = os.path.join(ASSETS_DIR, "icon-cl.png")
    if not os.path.isfile(src):
        return ""
    try:
        dest = os.path.join(os.path.dirname(get_launcher_settings_path()), f"icon_legacy_v3_{os.path.getsize(src)}.png")
        if os.path.isfile(dest):
            return dest
        img = _hue_shift_icon(src, QColor(_LEGACY_MINT).hueF(), 1.3, 512)
        if img is None:
            return ""
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        img.save(dest, "PNG")
        return dest
    except Exception:
        return ""

def _theme_icon_file(kind):
    """Icon shown for a theme: new -> icon.png, sunset -> icon-ss.png, classic -> icon-cl.png, legacy -> mint version of classic."""
    if kind == "legacy":
        return _legacy_icon_path()
    f = os.path.join(ASSETS_DIR, {"sunset": "icon-ss.png", "new": "icon.png"}.get(kind, "icon-cl.png"))
    return f if os.path.isfile(f) else ""

_CLASSIC_ACCOUNT = bool(_classic_account_key())            # an account theme on the Classic layout: Classic look, fixed colours, always dark
_ACTIVE_THEME_AT_START = _active_theme_key() if (_UI_STYLE_AT_START == "new" or _CLASSIC_ACCOUNT) else ""
if _UI_STYLE_AT_START in ("legacy", "sunset"):
    SUNSET_THEME, _SUNSET_EXTRA = (_LEGACY_THEME, _LEGACY_EXTRA) if _UI_STYLE_AT_START == "legacy" else (_SS_THEME, _SS_EXTRA)
    SUNSET_ACCENT = SUNSET_THEME["accent"]
    THEMES["dark"].update(SUNSET_THEME)
if _ACTIVE_THEME_AT_START:                    # this account's own theme, or the one an admin account picked
    _look = _ACCOUNT_THEMES[_ACTIVE_THEME_AT_START]
    SUNSET_THEME, _SUNSET_EXTRA = _look["theme"], _look["extra"]
    SUNSET_ACCENT = SUNSET_THEME["accent"]
    THEMES["dark" if QColor(SUNSET_THEME["bg"]).lightness() < 128 else "light"].update(SUNSET_THEME)   # widgets that pick light/dark by the window colour follow it too


_ui_prev_set_accent = set_accent
def set_accent(color):
    """The theme always uses its own accent (chat bubbles, in-game toasts etc. follow THEMES / overlay, not the stylesheet)."""
    _ui_prev_set_accent(SUNSET_ACCENT if (_SIDE_UI or _CLASSIC_ACCOUNT) else color)

_ui_prev_apply_accent_to_icon = apply_accent_to_icon
def apply_accent_to_icon(color):
    if _SIDE_UI or _CLASSIC_ACCOUNT:
        return False                                 # the theme icon is never recoloured
    return _ui_prev_apply_accent_to_icon(color)

_ui_prev_apply_dark_mode = apply_dark_mode
def apply_dark_mode(mode):
    _ui_prev_apply_dark_mode(_ct_forced_dark_mode() or ("on" if _CLASSIC_ACCOUNT else mode))      # the Omar V4 theme is always dark; a custom theme sets light/dark itself
    if _CLASSIC_ACCOUNT:                  # Classic-layout custom theme with a background gradient
        try:
            _gcss = (_ACCOUNT_THEMES.get(_ACTIVE_THEME_AT_START) or {}).get("grad_css")
            _app = QApplication.instance()
            if _gcss and _app is not None:
                _app.setStyleSheet(_app.styleSheet() + _gcss)
        except Exception:
            _log_exc("apply_dark_mode")
    if _SIDE_UI:
        _ui_apply_sunset()                # the theme is always dark

# Icons: the UI always uses assets/icon.png (or the active account theme's own icon).
_icon_download_tried = set()

def _ensure_theme_icon(entry):
    """Path of a theme's own icon. If it isn't in assets/ (or the config folder) it is downloaded once per run;
    '' when it isn't there and can't be downloaded (the normal icon is used then)."""
    if entry.get("icon_make"):                 # custom themes: icon made from the Classic icon + the theme's accent
        return entry["icon_make"]()
    name = entry.get("icon")
    if not name:
        return ""
    dirs = [ASSETS_DIR, os.path.dirname(get_launcher_settings_path())]
    for d in dirs:
        if os.path.isfile(os.path.join(d, name)):
            return os.path.join(d, name)
    if name in _icon_download_tried:
        return ""
    _icon_download_tried.add(name)
    for url in [x for u in entry.get("icon_urls", []) for x in ((_ncz_jsdelivr(u), u) if _ncz_jsdelivr(u) else (u,))]:
        try:
            data = _http_get(url, timeout=6)
        except Exception:
            continue
        if len(data) < 1000 or data[:8] != b"\x89PNG\r\n\x1a\n":
            continue
        for d in dirs:                       # assets/ first; the config folder if assets/ can't be written to
            try:
                os.makedirs(d, exist_ok=True)
                path = os.path.join(d, name)
                with open(path + ".part", "wb") as f:
                    f.write(data)
                os.replace(path + ".part", path)
                return path
            except OSError:
                continue
    return ""

_ui_prev_asset_path = asset_path
def asset_path(filename):
    if filename == "icon.png":
        if _UI_STYLE_AT_START == "legacy":
            return _legacy_icon_path() or os.path.join(ASSETS_DIR, "icon.png")
        if _UI_STYLE_AT_START == "sunset":
            return _theme_icon_file("sunset") or os.path.join(ASSETS_DIR, "icon.png")
        if _UI_STYLE_AT_START == "new":
            themed = _ensure_theme_icon(_ACCOUNT_THEMES.get(_ACTIVE_THEME_AT_START) or {})   # the active theme's own icon
            return themed or os.path.join(ASSETS_DIR, "icon.png")
        if _CLASSIC_ACCOUNT:
            themed = _ensure_theme_icon(_ACCOUNT_THEMES.get(_ACTIVE_THEME_AT_START) or {})   # the theme's own icon (icon-v4.png)
            if themed:
                return themed
        if not os.path.exists(accent_icon_path()):
            cl = _theme_icon_file("classic")             # Classic: icon-cl.png until the accent colour is changed
            if cl:
                return cl
            old = os.path.join(ASSETS_DIR, "icon_default.png")
            if os.path.exists(old):
                return old
    return _ui_prev_asset_path(filename)

# ── Five Nights at NCZ 2: alternate cover when its settings.json has "color" = 1 / 1.0 ──
NCZ2_COVER_DEFAULT = "fnancz2cover.png"
NCZ2_COVER_ALT = "fnancz2-cover2.png"       # assets/fnancz2-cover2.png
NCZ2_RPC_ART_DEFAULT = "fnancz_2"
NCZ2_RPC_ART_ALT = "fnancz2_cover2"         # Discord art asset

def ncz2_color_is_one():
    """True when FNaNCZ 2's settings.json has the key "color" set to 1 or 1.0 (also accepts "1" / "1.0")."""
    try:
        path = get_ncz2_settings_path()
        if not os.path.exists(path):
            return False
        data, _nul = load_game_json(path)      # same reader as the settings editor (handles the trailing null byte)
        if not isinstance(data, dict):
            return False
        val = next((v for k, v in data.items() if str(k).strip().lower() == "color"), None)
        if isinstance(val, bool):
            return False
        if isinstance(val, (int, float)):
            return float(val) == 1.0
        if isinstance(val, str):
            return float(val.strip()) == 1.0
    except Exception:
        pass
    return False

def _ncz2_alt_cover_file():
    for d in (ASSETS_DIR, os.path.join(_writable_dir(), "assets"),
              os.path.join(os.path.dirname(os.path.abspath(__file__)), "assets")):
        p = os.path.join(d, NCZ2_COVER_ALT)
        if os.path.exists(p):
            return p
    return None

_ncz2c_logged = set()
def _ncz2_cover_log(msg):
    if msg in _ncz2c_logged:
        return
    _ncz2c_logged.add(msg)
    try:
        with open(os.path.join(os.path.dirname(get_launcher_settings_path()), "ncz2_cover.log"), "a", encoding="utf-8") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + msg + "\n")
    except Exception:
        pass

_ncz2c_prev_asset_path = asset_path
def asset_path(filename):
    if filename == NCZ2_COVER_DEFAULT and ncz2_color_is_one():
        alt = _ncz2_alt_cover_file()
        if alt:
            return alt
        _ncz2_cover_log(f"color is 1 but {NCZ2_COVER_ALT} was not found (looked in {ASSETS_DIR})")
    return _ncz2c_prev_asset_path(filename)

def _ncz2_track_cover(app, label):
    """Swaps the Library card's cover live when settings.json's color changes (no restart needed)."""
    state = {"v": ncz2_color_is_one()}
    def tick():
        try:
            want = ncz2_color_is_one()
            if want == state["v"]:
                return
            state["v"] = want
            pm = app.get_rounded_pixmap(asset_path(NCZ2_COVER_DEFAULT), COVER_W, COVER_H, 8)
            if pm:
                label.setPixmap(pm)
        except RuntimeError:     # the card was deleted
            pass
    t = QTimer(label)
    t.timeout.connect(tick)
    t.start(2000)

