class _UiRailLayout(QVBoxLayout):
    """Vertical tab list that keeps a trailing stretch; tabs added later (profile tabs) land above it."""
    def addWidget(self, w, *args, **kwargs):
        w.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)
        self.insertWidget(max(0, self.count() - 1), w)

def _ui_move_nav_to_rail(self):
    root_layout = self.centralWidget().layout()          # [top bar, pages]
    old = self._nav_center_layout                        # the strip that holds the tab buttons
    items = []
    while old.count():
        w = old.takeAt(0).widget()
        if w is not None:
            items.append(w)

    root_layout.removeWidget(self.pages)
    body = QWidget()
    bl = QHBoxLayout(body)
    bl.setContentsMargins(0, 0, 0, 0)
    bl.setSpacing(0)
    rail = QFrame()
    rail.setObjectName("SideRail")
    rail.setFixedWidth(236 if _UI_STYLE_AT_START == "legacy" else 208)
    rv = _UiRailLayout(rail)
    rv.setContentsMargins(0, 16, 0, 16)
    rv.setSpacing(2)
    rv.addStretch()
    self._nav_center_layout = rv                         # profile tabs add themselves here later
    self._ui_rail = rail

    prev = None
    for w in items:
        if isinstance(w, QPushButton):
            w.setFixedHeight(44)
            w.setIconSize(QSize(1, 1) if _UI_STYLE_AT_START == "legacy" else QSize(18, 18))   # Legacy: text-only list
            rv.addWidget(w)
            prev = w
        elif prev is not None:                           # the red unread badge: sits on the right end of the Friends tab
            hl = QHBoxLayout(prev)
            hl.setContentsMargins(0, 0, 12, 0)
            hl.addStretch()
            hl.addWidget(w)
            w.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
    bl.addWidget(rail)
    bl.addWidget(self.pages, 1)
    root_layout.addWidget(body, 1)
    try:
        self._nav_center_filter.center.hide()            # the old centred strip is empty now
    except Exception:    # expected: cleanup that may already be done
        pass

def _ui_add_setting(self):
    sp = self.settings_page
    panel = sp.dark_mode_combo.parentWidget()
    lay = panel.layout()
    row = QHBoxLayout()
    col = QVBoxLayout()
    col.setSpacing(2)
    title = QLabel("Theme")
    title.setObjectName("RowTitle")
    desc = QLabel("New, Sunset, Classic (pick your own accent colour) or Legacy. Needs a restart.")
    desc.setObjectName("RowDesc")
    desc.setWordWrap(True)
    col.addWidget(title)
    col.addWidget(desc)
    combo = QComboBox()
    combo.setFixedWidth(160)
    combo.addItem("New", "new")
    for key in _allowed_theme_keys():      # account themes this account may use (admin accounts get all of them)
        combo.addItem(_ACCOUNT_THEMES[key]["label"], key)
    combo.addItem("Sunset", "sunset")
    combo.addItem("Classic", "classic")
    combo.addItem("Legacy", "legacy")
    start_data = (_active_theme_key() if _CLASSIC_ACCOUNT else
                  _UI_STYLE_AT_START if _UI_STYLE_AT_START in ("sunset", "classic", "legacy") else (_active_theme_key() or "new"))
    combo.setCurrentIndex(max(0, combo.findData(start_data)))
    if _custom_theme_locked():             # this account's theme is fixed
        key = _locked_theme_key()
        combo.clear()
        combo.addItem(_ACCOUNT_THEMES[key]["label"], key)
        combo.setEnabled(False)
        desc.setText("Your custom theme. Other themes are locked for this account.")
        try:
            sp.dark_mode_combo.setEnabled(False)
        except Exception:
            _log_exc("_ui_add_setting")

    def changed():
        d = combo.currentData()
        s = load_launcher_settings()
        s["ui_style"] = "new"
        s["ui_theme_choice"] = d if d in ("sunset", "classic", "legacy") else "new"
        s["ui_theme"] = d if d in _ACCOUNT_THEMES else ""
        save_launcher_settings(s)
        _ncz_refresh_launcher_shortcut(d)               # delete the old desktop shortcut, add one with the new theme's icon
        if d != start_data:
            QMessageBox.information(sp, "Interface Style", "Restart the launcher to apply the new theme.")
    combo.currentIndexChanged.connect(changed)
    row.addLayout(col, 1)
    row.addWidget(combo)
    lay.insertLayout(1, row)                             # right under Dark Mode
    lay.insertSpacing(1, 12)
    lay.insertSpacing(3, 12)
    sp.ui_style_combo = combo
    if _CLASSIC_ACCOUNT:
        sp.accent_btn.setEnabled(False)
        sp.accent_reset_btn.setEnabled(False)
        sp.accent_desc.setText("Locked to this theme's color.")
        try:
            sp.dark_mode_combo.setEnabled(False)             # always dark
        except Exception:
            _log_exc("_ui_add_setting")
    elif _SIDE_UI:
        sp.accent_btn.setEnabled(False)
        sp.accent_reset_btn.setEnabled(False)
        sp.accent_desc.setText("Locked to your custom theme." if _custom_theme_locked() else
                               "Locked to this theme's color."
                               if _active_theme_key() else
                               "Locked to the New theme's color.")

