# ── Store: Trending / Most Popular / Works on your PC ──
# Trending = Steam's current top sellers, Most Popular = most reviewed. "Works on your PC" keeps only games whose
# listed RAM and disk needs fit this PC (the same check as the game's page, so it's RAM + free space only).
_steam_req_cache = {}

_chart_cache = {}

def _steam_api_json(url, timeout=20):
    return json.loads(_http_get(url, timeout=timeout).decode("utf-8", errors="replace"))

def _steam_chart_ranks():
    """Steam's own Most Played chart: [{rank, last_week_rank, appid}], cached 10 min."""
    hit = _chart_cache.get("ranks")
    if hit and time.time() - hit[0] < 600:
        return hit[1]
    data = _steam_api_json("https://api.steampowered.com/ISteamChartsService/GetMostPlayedGames/v1/")
    ranks = []
    for r in (data.get("response") or {}).get("ranks", []):
        if r.get("appid"):
            ranks.append({"rank": int(r.get("rank") or 10 ** 6), "last": int(r.get("last_week_rank") or 0),
                          "appid": int(r["appid"])})
    ranks.sort(key=lambda r: r["rank"])
    if not ranks:
        raise RuntimeError("Steam's Most Played chart came back empty")
    _chart_cache["ranks"] = (time.time(), ranks)
    return ranks

def _steam_most_played_ids():
    return [r["appid"] for r in _steam_chart_ranks()]

def _steam_trending_ids():
    """Games climbing the chart fastest this week (new entries count as big climbs), biggest climb first."""
    ranks = _steam_chart_ranks()
    def climb(r):
        before = r["last"] if r["last"] > 0 else len(ranks) + 50
        return before - r["rank"]
    return [r["appid"] for r in sorted(ranks, key=lambda r: (-climb(r), r["rank"]))]

def _steam_names(appids):
    """{appid: (name, type)} for these ids in ONE request. type 0 = a game (software/tools/DLC are other numbers)."""
    cache = _chart_cache.setdefault("names", {})
    need = [a for a in appids if a not in cache]
    if need:
        inp = json.dumps({"ids": [{"appid": a} for a in need],
                          "context": {"language": "english", "country_code": "US"}, "data_request": {}})
        data = _steam_api_json("https://api.steampowered.com/IStoreBrowseService/GetItems/v1?" +
                               urllib.parse.urlencode({"input_json": inp}))
        for it in (data.get("response") or {}).get("store_items", []):
            if it.get("appid") and it.get("name"):
                cache[int(it["appid"])] = (str(it["name"]), it.get("type", 0))
    return cache

_NOT_GAMES = ("wallpaper engine", "steam", "blender", "aseprite", "livesplash", "soundpad", "vtube studio")

def _steam_chart_page(ids, start, count):
    """One page of a ranked chart, in the order Steam ranks them: [(appid, title, image_base)], total."""
    page = ids[start:start + count]
    names = _steam_names(page)
    games = []
    for a in page:
        if a not in names:
            continue
        name, kind = names[a]
        if kind not in (0, None, "game") or name.lower() in _NOT_GAMES:
            continue                                # games only: no software, tools or DLC
        games.append((a, name, f"https://cdn.cloudflare.steamstatic.com/steam/apps/{a}"))
    return games, len(ids)

def fetch_steam_games_mode(term, start, tags=None, mode="", count=STORE_PAGE_SIZE):
    """popular = Steam's Most Played chart (rank order); trending = Steam's top sellers. With a search word or
    tags the chart can't be filtered, so those go through Steam's search instead."""
    if mode in ("popular", "trending") and not term and not tags:
        try:
            ids = _steam_most_played_ids() if mode == "popular" else _steam_trending_ids()
            return _steam_chart_page(ids, start, count)
        except Exception:
            _log_exc("fetch_steam_games_mode")                                    # chart unavailable: use the search below
    base = {"query": "", "term": term, "start": start, "count": count, "dynamic_data": "",
            "category1": 998, "l": "english", "infinite": 1}
    if tags:
        base["tags"] = ",".join(str(int(t)) for t in tags)
    if mode == "popular":
        tries = [{"filter": "topsellers"}]          # chart failed or filtered: best sellers is a fair stand-in
    elif mode == "trending":
        tries = [{"filter": "topsellers"}, {"filter": "popularnew"}]
    else:
        tries = [{"sort_by": "_ASC"}]
    last = None
    for extra in tries:
        try:
            url = STEAM_SEARCH_URL + "?" + urllib.parse.urlencode({**base, **extra})
            data = json.loads(_http_get(url, timeout=20).decode("utf-8", errors="replace"))
            games = parse_steam_results(data.get("results_html", ""))
            if games:
                return games, int(data.get("total_count") or 0)
        except Exception as e:
            last = e
    if last:
        raise last
    return [], 0

_steam_busy = {"until": 0.0}
_fits_lock = threading.Lock()

def _fits_cache_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "store_cache", "fits_pc.json")

def _fits_signature():
    sp = get_system_specs()
    return f"v2|{sp.get('cpu')}|{sp.get('gpu')}|{round(sp.get('ram_gb') or 0)}|{round(sp.get('free_gb') or 0)}"

def _fits_load():
    if _steam_req_cache.get("_loaded"):
        return
    _steam_req_cache["_loaded"] = True
    try:
        with open(_fits_cache_path(), encoding="utf-8") as f:
            data = json.load(f)
        if data.get("sig") == _fits_signature():
            for k, v in (data.get("games") or {}).items():
                _steam_req_cache[int(k)] = bool(v)
    except Exception:    # expected: file may not exist yet or be unreadable
        pass

def _fits_save():
    try:
        os.makedirs(os.path.dirname(_fits_cache_path()), exist_ok=True)
        games = {str(k): v for k, v in _steam_req_cache.items() if isinstance(k, int)}
        with open(_fits_cache_path(), "w", encoding="utf-8") as f:
            json.dump({"sig": _fits_signature(), "games": games}, f)
    except Exception:    # expected: file may not exist yet or be unreadable
        pass

def steam_game_fits_pc(appid):
    """True when RAM, storage, processor and graphics look fine. None when Steam couldn't be asked (throttled)."""
    with _fits_lock:
        _fits_load()
        if appid in _steam_req_cache:
            return _steam_req_cache[appid]
    if time.time() < _steam_busy["until"]:
        return None
    try:
        time.sleep(0.15)        # be gentle: Steam throttles bursts of requests
        # pc_requirements come with the "basic" part of the details; "platforms" is separate
        url = f"https://store.steampowered.com/api/appdetails?appids={appid}&l=english&cc=us&filters=basic,platforms"
        data = json.loads(_http_get(url, timeout=15).decode("utf-8", errors="replace"))
        info = (data.get(str(appid)) or {}).get("data") or {}
        platforms = info.get("platforms") or {}
        src = info.get("pc_requirements")
        if sys.platform.startswith("linux") and platforms.get("linux"):
            lin = info.get("linux_requirements")
            if isinstance(lin, dict) and (lin.get("minimum") or lin.get("recommended")):
                src = lin
        reqs = {}
        if isinstance(src, dict):
            reqs = {"minimum": parse_steam_requirements(src.get("minimum")),
                    "recommended": parse_steam_requirements(src.get("recommended"))}
        _v, color, _n = assess_requirements(reqs, platforms, get_system_specs())
        ok = color in (GREEN, ORANGE)
        with _fits_lock:
            _steam_req_cache[appid] = ok
        return ok
    except urllib.error.HTTPError as e:
        if e.code in (429, 403):
            _steam_busy["until"] = time.time() + 120
        return None
    except Exception:
        return None

_store_prev_init = StorePage.__init__

def _store_modes_init(self, *a, **k):
    _store_prev_init(self, *a, **k)
    self._mode = ""             # "", "trending" or "popular"
    self._works = False
    if isinstance(self, FanGamesPage):
        return
    row = QHBoxLayout()
    row.setSpacing(8)
    self._mode_buttons = {}
    for key, label, tip in (("trending", "Trending", "What Steam is selling most right now"),
                            ("popular", "Most Popular", "Most reviewed games on Steam"),
                            ("works", "Works on your PC", "Only games whose RAM, storage, processor and graphics needs fit this PC")):
        b = QPushButton(label)
        b.setCursor(Qt.CursorShape.PointingHandCursor)
        b.setFixedHeight(32)
        b.setToolTip(tip)
        b.clicked.connect(lambda _c=False, kk=key: self._toggle_mode(kk))
        row.addWidget(b)
        self._mode_buttons[key] = b
    row.addStretch()
    lay = self.layout()
    lay.insertLayout(2, row)
    lay.insertSpacing(3, 10)

def _store_toggle_mode(self, key):
    if key == "works":
        self._works = not self._works
    else:
        self._mode = "" if self._mode == key else key
    for k, b in self._mode_buttons.items():
        on = self._works if k == "works" else self._mode == k
        b.setObjectName("Primary" if on else "")
        b.style().unpolish(b)
        b.style().polish(b)
    self._loaded_once = True
    self._start_search()

_store_prev_load_page = StorePage._load_page

def _store_load_page(self):
    if not getattr(self, "_mode", "") and not getattr(self, "_works", False):
        return _store_prev_load_page(self)      # no button on: exactly the original Store loading
    if self._loading or self._exhausted:
        return
    self._loading = True
    request_id, term, start = self._request_id, self._term, self._next_start
    tag_ids = [t for t, _ in self._tag_filter]
    mode, works = getattr(self, "_mode", ""), getattr(self, "_works", False)

    def work():
        try:
            s = start
            for _ in range(2 if works else 1):      # a filtered page can come up empty: look at up to 2 pages
                games, total = fetch_steam_games_mode(term, s, tag_ids, mode)
                if works and games:
                    with ThreadPoolExecutor(max_workers=3) as pool:
                        fits = list(pool.map(lambda g: steam_game_fits_pc(g[0]), games))
                    _fits_save()
                    games = [g for g, f in zip(games, fits) if f]
                if games or s + STORE_PAGE_SIZE >= total:
                    break
                s += STORE_PAGE_SIZE
            return (request_id, s, games, total, "")
        except Exception as e:
            return (request_id, start, [], 0, str(e) or e.__class__.__name__)

    worker = TaskWorker(work)
    worker.done.connect(self._on_page)
    self._workers = [w for w in self._workers if w.isRunning()] + [worker]
    worker.start()

_store_prev_on_page = StorePage._on_page

def _store_modes_on_page(self, result):
    _store_prev_on_page(self, result)
    try:
        if result[4] and result[0] == self._request_id and not isinstance(self, FanGamesPage):
            self._set_status("Couldn't load games from Steam: " + str(result[4])[:160] +
                             "\nIf this says 429 or 403, Steam is limiting requests: wait a few minutes.")
            with open(os.path.join(os.path.dirname(get_launcher_settings_path()), "store_debug.log"), "a", encoding="utf-8") as f:
                f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + str(result[4]) + "\n")
    except Exception:    # expected: offline or the server did not answer
        pass
    if getattr(self, "_works", False) and result[0] == self._request_id and not result[4]:
        self.count_label.setText(f"{len(self._cards)} games that fit your PC")
        if not self._cards:
            if time.time() < _steam_busy["until"]:
                self._set_status("Steam is limiting requests right now. Wait a couple of minutes and try again.")
            else:
                self._set_status("No games that fit your PC were found here. Try another tag or search.")

StorePage.__init__ = _store_modes_init
StorePage._toggle_mode = _store_toggle_mode
StorePage._load_page = _store_load_page
StorePage._on_page = _store_modes_on_page


# ── "Can I run it": processor + graphics card ──
# Compares this PC's CPU/GPU with the game's listed ones using an approximate built-in ranking (no internet needed).
# Close calls are a guess, and anything it can't read (e.g. "DirectX 11 compatible") is simply not judged.
_CPU_TIER = {"3": 0, "5": 6, "7": 12, "9": 18}
_RYZEN_GEN = {1: 7, 2: 8, 3: 10, 4: 11, 5: 12, 6: 13, 7: 13, 8: 14, 9: 15}

def _hw_cpu_score(text):
    t = (text or "").lower()
    m = re.search(r"core\W*(?:tm\W*)?i([3579])\W*(\d{3,5})", t)
    if m:
        d = m.group(2)
        gen = int(d[:2]) if len(d) == 5 else int(d[0]) if len(d) == 4 else 1
        return gen * 10 + _CPU_TIER[m.group(1)]
    m = re.search(r"ryzen\W*(?:threadripper\W*)?([3579])\W*(\d{4})", t)
    if m:
        return _RYZEN_GEN.get(int(m.group(2)[0]), 12) * 10 + _CPU_TIER[m.group(1)]
    m = re.search(r"\bfx\W*(\d{4})", t)
    if m:
        return 33 if int(m.group(1)) >= 8000 else 29
    if re.search(r"core\W*2\W*quad", t) or re.search(r"phenom\W*(?:ii)?\W*x[46]", t):
        return 18
    if re.search(r"core\W*2\W*duo|athlon\W*(?:ii\W*)?x2|athlon\W*64", t):
        return 14
    if re.search(r"pentium|celeron|atom", t):
        return 10
    return None

# rough relative speed, GTX 1060 = 100
_GPU_TABLE = {
    "gt 710": 6, "gt 730": 8, "gt 1030": 30, "gts 450": 14,
    "gtx 260": 14, "gtx 460": 20, "gtx 550": 15, "gtx 560": 25, "gtx 650": 17, "gtx 660": 30, "gtx 670": 38,
    "gtx 680": 45, "gtx 750": 28, "gtx 760": 38, "gtx 770": 50, "gtx 780": 60, "gtx 950": 45, "gtx 960": 55,
    "gtx 970": 80, "gtx 980": 95, "gtx 1050": 55, "gtx 1060": 100, "gtx 1070": 140, "gtx 1080": 185,
    "gtx 1650": 85, "gtx 1660": 125, "rtx 2060": 150, "rtx 2070": 190, "rtx 2080": 230, "rtx 3050": 120,
    "rtx 3060": 190, "rtx 3070": 280, "rtx 3080": 380, "rtx 3090": 430, "rtx 4060": 240, "rtx 4070": 340,
    "rtx 4080": 480, "rtx 4090": 700, "rtx 5070": 400, "rtx 5080": 560, "rtx 5090": 800,
    "hd 5770": 15, "hd 6850": 22, "hd 7770": 25, "hd 7850": 38, "hd 7870": 48, "hd 7950": 55, "hd 7970": 65,
    "r7 260": 35, "r9 270": 50, "r9 280": 70, "r9 290": 110, "r9 380": 70, "r9 390": 120,
    "rx 460": 45, "rx 470": 85, "rx 480": 100, "rx 560": 55, "rx 570": 95, "rx 580": 110, "rx 590": 125,
    "rx 5500": 100, "rx 5600": 150, "rx 5700": 190, "rx 6500": 110, "rx 6600": 220, "rx 6700": 300,
    "rx 6800": 380, "rx 6900": 450, "rx 7600": 250, "rx 7700": 330, "rx 7800": 400, "rx 7900": 520,
    "uhd 620": 14, "uhd 630": 16, "uhd 770": 25, "hd 4000": 6, "hd 4600": 9, "hd 520": 10, "hd 620": 12,
    "hd 630": 14, "iris xe": 40, "arc a380": 70, "arc a580": 150, "arc a750": 190, "arc a770": 210,
    "vega 8": 25, "vega 11": 32,
}

def _hw_gpu_scores(text):
    """Every graphics card named in the text, as a list of scores."""
    t = (text or "").lower().replace("geforce", " ").replace("nvidia", " ").replace("radeon", " ").replace("amd", " ")
    t = re.sub(r"\s+", " ", t)
    out = []

    def lookup(fam, num):
        key = f"{fam} {num}"
        if key in _GPU_TABLE:
            return _GPU_TABLE[key]
        cands = [(abs(int(k.split()[1]) - int(num)), v) for k, v in _GPU_TABLE.items()
                 if k.split()[0] == fam and k.split()[1].isdigit()]
        return min(cands)[1] if cands else None
    for m in re.finditer(r"\b(rtx|gtx|gts|gt)\s*(\d{3,4})\s*(ti super|ti|super)?", t):
        s = lookup(m.group(1), m.group(2)[:-1] + "0" if len(m.group(2)) == 4 and m.group(1) != "gt" else m.group(2))
        if s:
            mult = {"ti": 1.15, "super": 1.12, "ti super": 1.2}.get(m.group(3) or "", 1)
            out.append(s * mult)
    for m in re.finditer(r"\brx\s*(\d{3,4})\s*(xt)?", t):
        key = m.group(1)[:-2] + "00" if len(m.group(1)) == 4 else m.group(1)[:-1] + "0"
        s = lookup("rx", key)
        if s:
            out.append(s * (1.15 if m.group(2) else 1))
    for m in re.finditer(r"\b(hd|r[579])\s*(\d{3,4})(x)?\b", t):
        if m.group(1) == "hd" and len(m.group(2)) == 3:
            continue
        s = lookup(m.group(1), m.group(2)[:-1] + "0" if m.group(1) != "hd" else m.group(2))
        if s:
            out.append(s * (1.15 if m.group(3) else 1))
    for m in re.finditer(r"\b(uhd|hd) graphics\s*(\d{3,4})\b", t):
        s = lookup(m.group(1), m.group(2))
        if s:
            out.append(s)
    for m in re.finditer(r"\barc\s*a(\d{3})", t):
        s = lookup("arc", "a" + m.group(1))
        if s:
            out.append(s)
    if "iris xe" in t:
        out.append(40)
    m = re.search(r"vega\s*(\d+)", t)
    if m:
        out.append(25 if int(m.group(1)) <= 8 else 32)
    if re.search(r"intel\W+(?:r\W+)?hd graphics(?!\s*\d)", t):
        out.append(8)
    return out

def _hw_short(text, n=34):
    text = re.sub(r"\((?:r|tm)\)|\bcpu\b|@.*|\s+", " ", text or "", flags=re.I).strip()
    return text if len(text) <= n else text[:n - 1].rstrip() + "\u2026"

def _hw_split(value):
    return [p.strip() for p in re.split(r"\s*(?:/|;|,|\bor\b)\s*", value or "", flags=re.I) if p.strip()]

def _hw_req_options(items, kind):
    """Scores of the CPU/GPU options listed in these requirement lines, as [(score, text)]."""
    label_rx = r"processor|cpu" if kind == "cpu" else r"graphics|video card|gpu"
    found = []
    for label, value in items or []:
        if label:
            if not re.search(label_rx, label, re.I) or re.search(r"memory|vram", label, re.I):
                continue
            texts = _hw_split(value)
        else:
            m = re.search(r"(?:" + label_rx + r")\s*:\s*(.+)", value or "", re.I)
            if not m:
                continue
            texts = _hw_split(m.group(1))
        for t in texts:
            if kind == "cpu":
                s = _hw_cpu_score(t)
                if s is not None:
                    found.append((s, t))
            else:
                for s in _hw_gpu_scores(t):
                    found.append((s, t))
    return found

_hw_prev_assess = assess_requirements

def assess_requirements(reqs, platforms, system):
    verdict, color, notes = _hw_prev_assess(reqs, platforms, system)
    mn, rc = (reqs or {}).get("minimum") or [], (reqs or {}).get("recommended") or []
    my_cpu = _hw_cpu_score(system.get("cpu") or "")
    my_gpus = _hw_gpu_scores(system.get("gpu") or "")
    my_gpu = max(my_gpus) if my_gpus else None
    problems, below_rec, checked = [], [], []
    for kind, mine, label, shown in (("cpu", my_cpu, "processor", _hw_short(system.get("cpu") or "")),
                                     ("gpu", my_gpu, "graphics card", "")):
        if mine is None:
            continue
        low = 0.85
        min_opts = _hw_req_options(mn, kind) or _hw_req_options(rc, kind)
        rec_opts = _hw_req_options(rc, kind)
        if not min_opts:
            continue
        need, need_txt = min(min_opts)         # any one of the listed options is enough
        checked.append(label)
        if mine < need * low:
            problems.append(f"your {label} is below the minimum ({_hw_short(need_txt)})")
        elif rec_opts and mine < min(rec_opts)[0] * low:
            below_rec.append(label)
    if problems:
        base = verdict[len("May struggle: "):] if color == RED and verdict.startswith("May struggle: ") else ""
        verdict, color = "May struggle: " + "; ".join(([base] if base else []) + problems), RED
    elif color != RED:
        if below_rec and color in (GREEN, None, ORANGE):
            extra = "your " + " and ".join(below_rec) + " is below the recommended"
            verdict = (verdict + "; " + extra) if color == ORANGE else "Should run: meets the minimum, " + extra
            color = ORANGE
        elif checked and color is None:
            verdict, color = "Looks OK for " + " and ".join(checked), GREEN
        elif checked and color == GREEN:
            verdict = "Looks OK for RAM, storage, " + " and ".join(checked)
    notes = [n for n in notes if not n.startswith("Only RAM and free disk")]
    notes.insert(0, "Processor and graphics card are compared with an approximate ranking, so close calls are a guess.")
    return verdict, color, notes


# ── NCZ Big Picture mode ──
# Full-screen Library + Store for a couch / controller. Everything is painted by ONE widget (no widget per game), it only
# animates while something is moving, and it SLEEPS while a game runs (window hidden, controller closed, timers
# stopped) and wakes up again when the game closes.
# Tabs: Library (cover carousel), Store (Steam browser), Friends, Downloads and Workshop. LB/RB switch tabs.
# An on-screen keyboard opens for text input (Store search when a controller is in use, friend messages, Workshop search).
# Open it: "Big Picture" button in the Library header, Ctrl+Shift+B, or start the launcher with --bigpicture.
from PyQt6.QtCore import QVariantAnimation, QPropertyAnimation, QEasingCurve, QSocketNotifier
from PyQt6.QtGui import QShortcut, QFontMetrics


class _BPInput(QObject):
    """Controller -> 'left' 'right' 'up' 'down' 'accept' 'back' 'prev' 'next'.
    Linux: reads /dev/input/js* with a socket notifier (zero CPU while idle). Windows: XInput, slow poll until a pad shows up."""
    action = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._fd = None
        self._sn = None
        self._axes = {}
        self._dir = (0, 0)
        self._xi = None
        self._xi_prev = 0
        self._rep = QTimer(self)
        self._rep.timeout.connect(self._repeat)
        self._scan = QTimer(self)
        self._scan.timeout.connect(self._open_js)
        self._poll = QTimer(self)
        self._poll.timeout.connect(self._poll_xinput)

    def start(self):
        if sys.platform.startswith("win"):
            self._poll.start(1000)
        elif sys.platform.startswith("linux"):
            self._open_js()
            if self._fd is None:
                self._scan.start(2000)

    def stop(self):
        for t in (self._rep, self._scan, self._poll):
            t.stop()
        self._close_js()
        self._axes.clear()
        self._dir = (0, 0)
        self._xi_prev = 0

    # held direction: fires once, then repeats
    def _set_dir(self, d):
        if d == self._dir:
            return
        self._dir = d
        if d == (0, 0):
            self._rep.stop()
            return
        self._emit_dir()
        self._rep.start(380)

    def _emit_dir(self):
        dx, dy = self._dir
        if dx:
            self.action.emit("right" if dx > 0 else "left")
        if dy:
            self.action.emit("down" if dy > 0 else "up")

    def _repeat(self):
        self._rep.setInterval(110)
        self._emit_dir()

    # ── Linux joystick API ──
    def _open_js(self):
        import glob    # lazy: saves memory/startup until used
        for p in sorted(glob.glob("/dev/input/js*")):
            try:
                fd = os.open(p, os.O_RDONLY | os.O_NONBLOCK)
            except OSError:
                continue
            self._fd = fd
            self._sn = QSocketNotifier(fd, QSocketNotifier.Type.Read, self)
            self._sn.activated.connect(self._read_js)
            self._scan.stop()
            return

    def _close_js(self):
        if self._sn is not None:
            self._sn.setEnabled(False)
            self._sn.deleteLater()
            self._sn = None
        if self._fd is not None:
            try:
                os.close(self._fd)
            except OSError:    # expected: cleanup that may already be done
                pass
            self._fd = None

    def _read_js(self, *_):
        import struct    # lazy: saves memory/startup until used
        while self._fd is not None:
            try:
                data = os.read(self._fd, 128)
            except BlockingIOError:
                return
            except OSError:
                data = b""
            if not data:                                   # pad unplugged: look for it again
                self._close_js()
                self._set_dir((0, 0))
                self._scan.start(2000)
                return
            for off in range(0, len(data) - 7, 8):
                _t, val, typ, num = struct.unpack_from("<IhBB", data, off)
                if typ & 0x80:                             # initial-state events
                    continue
                if typ == 1 and val == 1:                  # button down (Xbox layout: A B X Y LB RB back start)
                    name = {0: "accept", 1: "back", 2: "x", 3: "alt", 4: "prev", 5: "next", 7: "start"}.get(num)
                    if name:
                        self.action.emit(name)
                elif typ == 2:                             # axis: 0/1 left stick, 6/7 d-pad
                    s = (val > 16000) - (val < -16000)
                    if num in (0, 6):
                        self._axes["x%d" % num] = s
                    elif num in (1, 7):
                        self._axes["y%d" % num] = s
                    self._set_dir((self._axes.get("x6", 0) or self._axes.get("x0", 0),
                                   self._axes.get("y7", 0) or self._axes.get("y1", 0)))

    # ── Windows XInput ──
    def _poll_xinput(self):
        import ctypes    # lazy: saves memory/startup until used
        if self._xi is None:
            try:
                try:
                    dll = ctypes.windll.xinput1_4
                except Exception:
                    dll = ctypes.windll.xinput1_3

                class _G(ctypes.Structure):
                    _fields_ = [("wButtons", ctypes.c_uint16), ("lt", ctypes.c_uint8), ("rt", ctypes.c_uint8),
                                ("lx", ctypes.c_int16), ("ly", ctypes.c_int16), ("rx", ctypes.c_int16), ("ry", ctypes.c_int16)]

                class _S(ctypes.Structure):
                    _fields_ = [("packet", ctypes.c_uint32), ("pad", _G)]
                self._xi = (dll, _S)
            except Exception:
                self._poll.stop()
                return
        dll, S = self._xi
        st = S()
        if dll.XInputGetState(0, ctypes.byref(st)) != 0:   # no pad: check once a second
            if self._poll.interval() != 1000:
                self._poll.setInterval(1000)
            self._xi_prev = 0
            self._set_dir((0, 0))
            return
        if self._poll.interval() != 16:
            self._poll.setInterval(16)
        b, g = st.pad.wButtons, st.pad
        new, self._xi_prev = b & ~self._xi_prev, b
        for mask, name in ((0x1000, "accept"), (0x2000, "back"), (0x0100, "prev"), (0x0200, "next"), (0x0010, "start"), (0x8000, "alt"), (0x4000, "x")):
            if new & mask:
                self.action.emit(name)
        dx = (1 if b & 8 else -1 if b & 4 else 0) or (1 if g.lx > 16000 else -1 if g.lx < -16000 else 0)
        dy = (1 if b & 2 else -1 if b & 1 else 0) or (-1 if g.ly > 16000 else 1 if g.ly < -16000 else 0)
        self._set_dir((dx, dy))


class _BPBridge(QObject):
    changed = pyqtSignal()      # _playing_listeners are called from a worker thread; this hops to the GUI thread



# Store categories shown as chips in Big Picture: (label, Steam sort order, tag ids)
_BP_CATS = (
    ("Popular", "Reviews_DESC", ()), ("New", "Released_DESC", ()),
    ("Action", "Reviews_DESC", (19,)), ("Adventure", "Reviews_DESC", (21,)), ("RPG", "Reviews_DESC", (122,)),
    ("Horror", "Reviews_DESC", (1667,)), ("Co-op", "Reviews_DESC", (1685,)), ("Shooter", "Reviews_DESC", (1774,)),
    ("Racing", "Reviews_DESC", (699,)), ("Survival", "Reviews_DESC", (1662,)), ("Puzzle", "Reviews_DESC", (1664,)),
    ("Platformer", "Reviews_DESC", (1625,)), ("Simulation", "Reviews_DESC", (599,)),
    ("Strategy", "Reviews_DESC", (9,)), ("Indie", "Reviews_DESC", (492,)), ("Story Rich", "Reviews_DESC", (1742,)),
    ("Open World", "Reviews_DESC", (1695,)),
)


def _bp_app_details(appid):
    """Short description / genres / release date for the store detail panel (Steam's public appdetails API)."""
    raw = json.loads(_http_get("https://store.steampowered.com/api/appdetails?appids=%d&l=english" % appid,
                               timeout=12).decode("utf-8", errors="replace"))
    d = (raw.get(str(appid)) or {}).get("data") or {}
    desc = html_lib.unescape(re.sub(r"<[^>]+>", "", d.get("short_description") or "")).strip()
    return {"desc": desc,
            "genres": [g.get("description", "") for g in (d.get("genres") or []) if g.get("description")],
            "date": (d.get("release_date") or {}).get("date", ""),
            "dev": ", ".join(d.get("developers") or [])}


_BP_LINUX_BOLD_TARGET = 500     # how heavy Big Picture "bold" text is on Linux (500 = Medium, 600 = SemiBold, 700 = Bold)
_bp_bold_cache = {}

def _bp_bold_weight(family):
    """Linux only: the weight to use for Big Picture bold text, or None to leave Qt's normal bold alone (Windows).
    Windows draws bold from the regular face with a light simulated bold, but on Linux Qt finds the font's real Bold
    (or adds a much heavier fake one), so the same text looks far heavier. Here bold is the real face closest to
    _BP_LINUX_BOLD_TARGET, so no fake embolden is ever added. Raise or lower the target to taste."""
    if sys.platform.startswith("win"):
        return None
    if family in _bp_bold_cache:
        return _bp_bold_cache[family]
    result = None
    try:
        weights = []
        for style in QFontDatabase.styles(family):
            try:
                w = int(QFontDatabase.weight(family, style))
                w = min(range(100, 1000, 100), key=lambda v: abs(v - w))     # QFont.Weight only takes 100, 200 ... 900
            except Exception:
                continue
            if w > 0 and w not in weights:
                weights.append(w)
        if weights:
            result = min(weights, key=lambda w: (abs(w - _BP_LINUX_BOLD_TARGET), w))
        else:
            result = _BP_LINUX_BOLD_TARGET
    except Exception:
        result = None
    _bp_bold_cache[family] = result
    return result


class _BigPicture(QWidget):
    LIB_TH = 0.36           # library tile height as a fraction of the window height

    def __init__(self, app):
        super().__init__(None, Qt.WindowType.Window | Qt.WindowType.FramelessWindowHint)
        self._app = app
        self.setWindowTitle("NCZ Big Picture")
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setMouseTracking(True)
        self._items, self._sel, self._pos = [], 0, 0.0
        self._cache = {}
        self._active = self._asleep = self._was_max = False
        self._toast = ""
        self._exit_rect = QRectF()
        self._aspect = COVER_W / float(COVER_H)

        # shared UI state
        self._tab = 0                       # 0 = Library, 1 = Store
        self._tabdir = 1
        self._tabt = 1.0                    # tab switch animation 0..1
        self._zone = "content"              # "tabs" | "chips" | "content"
        self._tab_rects = []
        self._lib_dirty = False

        # store state
        self._chip = 1                      # 0 = search box, 1.. = _BP_CATS[chip - 1]
        self._chip_rects = []
        self._chip_scroll = 0.0
        self._search = ""
        self._sitems, self._sbyid, self._spix = [], {}, {}
        self._ssel, self._sscroll = 0, 0.0
        self._stotal = self._snext = self._sreq = 0
        self._sloading = self._sexhausted = self._sstarted = False
        self._serror = ""
        self._workers = []
        self._details = {}                  # appid -> info dict (or {} while loading / failed)
        self._detail = None                 # open detail panel: {"item": store item}
        self._detail_btn = 0
        self._detail_rects = []

        # backdrop (blurred art of whatever is selected)
        self._bg_key, self._bg_cur, self._bg_prev, self._bg_t = None, None, None, 1.0

        self._loader = CoverLoader()
        self._loader.loaded.connect(self._on_cover)
        self._loader.nsfw_known.connect(self._on_nsfw)
        QApplication.instance().aboutToQuit.connect(self._loader.shutdown)

        self._anim = QVariantAnimation(self)
        self._anim.setDuration(240)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._anim.valueChanged.connect(self._on_anim)
        self._sanim = QVariantAnimation(self)
        self._sanim.setDuration(220)
        self._sanim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._sanim.valueChanged.connect(self._on_sanim)
        self._tanim = QVariantAnimation(self)
        self._tanim.setDuration(260)
        self._tanim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._tanim.valueChanged.connect(self._on_tanim)
        self._banim = QVariantAnimation(self)
        self._banim.setDuration(350)
        self._banim.valueChanged.connect(self._on_banim)
        self._fade = QPropertyAnimation(self, b"windowOpacity", self)
        self._fade.setDuration(180)
        self._clock = QTimer(self)
        self._clock.timeout.connect(self.update)
        self._toast_t = QTimer(self)
        self._toast_t.setSingleShot(True)
        self._toast_t.timeout.connect(lambda: self._say(""))
        self._stimer = QTimer(self)             # search-as-you-type debounce
        self._stimer.setSingleShot(True)
        self._stimer.setInterval(600)
        self._stimer.timeout.connect(self._store_reset)
        self._wheel = 0
        self._lfact, self._lfact_t, self._lseen = None, 0.0, False      # loading card: current fact, when it was picked, drawn this frame?
        self._ltimer = QTimer(self)                                      # ticks only while a loading card is on screen
        self._ltimer.setTimerType(Qt.TimerType.PreciseTimer)
        self._ltimer.setInterval(16)
        self._ltimer.timeout.connect(self.update)

        self._input = _BPInput(self)
        self._input.action.connect(self._act)
        self._bridge = _BPBridge(self)
        self._bridge.changed.connect(self._on_playing)
        _playing_listeners.append(self._bridge.changed.emit)

    # ── open / close / sleep ──
    def enter(self):
        if not self._active:
            self._was_max = self._app.isMaximized()
        self._active, self._asleep = True, False
        self._loader.set_key(get_steamgriddb_key())
        self._refresh()
        self._app.hide()
        self._show_awake()
        if self._tab == 1 and not self._sstarted:
            self._store_reset()

    def leave(self, show_main=True):
        self._active = self._asleep = False
        self._stop_awake()
        self._loader.cancel_pending()
        self._spix.clear()
        self._cache.clear()
        self._detail = None
        self.hide()
        if show_main:
            self._app.showMaximized() if self._was_max else self._app.showNormal()
            self._app.raise_()
            self._app.activateWindow()

    def _show_awake(self):
        self.setCursor(Qt.CursorShape.BlankCursor)
        self.setWindowOpacity(0.0)
        self.showFullScreen()
        self._fade.stop()
        self._fade.setStartValue(0.0)
        self._fade.setEndValue(1.0)
        self._fade.start()
        self.raise_()
        self.activateWindow()
        self.setFocus()
        self._input.start()
        self._clock.start(60000)
        self._sync_bg(animate=False)

    def _stop_awake(self):
        self._input.stop()
        self._clock.stop()
        self._ltimer.stop()
        for a in (self._anim, self._sanim, self._tanim, self._banim, self._fade):
            a.stop()
        self._stimer.stop()
        self._toast_t.stop()
        self._toast = ""
        self._tabt = self._bg_t = 1.0

    def _on_playing(self):
        playing = bool(_now_playing.get("name"))
        if not self._active:
            return
        if playing and not self._asleep:        # a game started: sleep (nothing runs while you play)
            self._asleep = True
            self._stop_awake()
            self._loader.cancel_pending()
            self.hide()
        elif not playing and self._asleep:      # the game closed: wake up
            self._asleep = False
            self._refresh()
            self._show_awake()

    # ── library data (read straight from the library cards) ──
    def _refresh(self):
        keep = self._items[self._sel]["card"] if self._items and self._sel < len(self._items) else None
        cards, seen, items = list(getattr(self._app, "cards", [])), set(), []
        fan = getattr(self._app, "fan_lib_cards", None)
        if isinstance(fan, dict):
            cards += [(c, None) for c in fan.values()]
        for card, title in cards:
            if id(card) in seen:
                continue
            seen.add(id(card))
            try:
                lab = card.findChild(QLabel, "CardTitle")
                title = title or (lab.text() if lab else "") or "Game"
                btn = card.findChild(QPushButton, "Primary")
                if btn is None:
                    btn = next((b for b in card.findChildren(QPushButton) if b.objectName() != "MoreButton"), None)
                st = card.findChild(QLabel, "CardStatus")
                pix = None
                for l in card.findChildren(QLabel):
                    pm = l.pixmap()
                    if pm is not None and not pm.isNull() and l.width() >= 100:
                        pix = pm
                        break
                items.append({"card": card, "title": title, "btn": btn, "pix": pix,
                              "status": st.text() if st else "", "action": btn.text().strip() if btn else ""})
            except RuntimeError:                # card was deleted
                continue
        items.sort(key=lambda i: 0 if i["action"].lower() in ("play", "launch", "open") else 1)   # playable first
        self._items = items
        self._cache.clear()
        self._sel = next((n for n, i in enumerate(items) if i["card"] is keep), 0)
        self._pos = float(self._sel)
        self._lib_dirty = False

    def _say(self, text, ms=0):
        self._toast = text
        self._toast_t.stop()
        if text and ms:
            self._toast_t.start(ms)
        self.update()

    # ── store data ──
    def _store_params(self):
        label, sort, tags = _BP_CATS[max(0, self._chip - 1)]
        if self._search:
            return self._search, "_ASC", ()
        return "", sort, tags

    def _store_reset(self):
        self._stimer.stop()
        self._sstarted = True
        self._sreq += 1
        self._loader.cancel_pending()
        self._sitems, self._sbyid = [], {}
        self._spix.clear()
        self._ssel, self._sscroll = 0, 0.0
        self._sanim.stop()
        self._stotal = self._snext = 0
        self._sloading = self._sexhausted = False
        self._serror = ""
        self._store_load_page()
        self._sync_bg()
        self.update()

    def _store_load_page(self):
        if self._sloading or self._sexhausted:
            return
        self._sloading, self._serror = True, ""
        rid, start = self._sreq, self._snext
        term, sort, tags = self._store_params()

        def work():
            try:
                games, total = fetch_steam_games(term, start, tags=list(tags) or None, sort_by=sort)
                return (rid, start, games, total, "")
            except Exception as e:
                return (rid, start, [], 0, str(e) or e.__class__.__name__)
        worker = TaskWorker(work)
        worker.done.connect(self._on_spage)
        self._workers = [w for w in self._workers if w.isRunning()] + [worker]
        worker.start()
        self.update()

    def _on_spage(self, result):
        rid, start, games, total, error = result
        if rid != self._sreq or not self._active:
            return
        self._sloading = False
        if error:
            self._serror = "Couldn't reach Steam. Press A to retry." if not self._sitems else "Couldn't load more games."
            self.update()
            return
        self._stotal = total
        for appid, title, img_base in games:
            if appid in self._sbyid:
                continue
            it = {"appid": appid, "title": title, "path": "", "nsfw": False, "done": False}
            self._sbyid[appid] = it
            self._sitems.append(it)
            self._loader.request(appid, img_base, title)
        self._snext = start + STORE_PAGE_SIZE
        if not games or self._snext >= total:
            self._sexhausted = True
        self._sync_bg()
        self.update()

    def _on_cover(self, appid, path):
        it = self._sbyid.get(appid)
        if it is None:
            return
        it["path"], it["done"] = path or "", True
        self._spix.pop(appid, None)
        if self._tab == 1:
            if self._sitems and self._sitems[min(self._ssel, len(self._sitems) - 1)] is it:
                self._sync_bg()
            self.update()

    def _on_nsfw(self, appid, flag):
        it = self._sbyid.get(appid)
        if it is not None:
            it["nsfw"] = bool(flag)

    def _load_details(self, appid):
        if appid in self._details:
            return
        self._details[appid] = {}

        def work():
            try:
                return (appid, _bp_app_details(appid))
            except Exception:
                return (appid, None)
        worker = TaskWorker(work)
        worker.done.connect(self._on_details)
        self._workers = [w for w in self._workers if w.isRunning()] + [worker]
        worker.start()

    def _on_details(self, res):
        appid, info = res
        if info is None:
            self._details.pop(appid, None)      # try again next time it is opened
        else:
            self._details[appid] = info
        self.update()

    # ── animation callbacks ──
    def _on_anim(self, v):
        self._pos = float(v)
        self.update()

    def _on_sanim(self, v):
        self._sscroll = float(v)
        self.update()

    def _on_tanim(self, v):
        self._tabt = float(v)
        self.update()

    def _on_banim(self, v):
        self._bg_t = float(v)
        self.update()

    # ── backdrop ──
    def _current_art(self):
        if self._tab == 0:
            if self._items and 0 <= self._sel < len(self._items):
                it = self._items[self._sel]
                return ("lib", it["title"]), it["pix"]
        elif self._tab == 1 and self._sitems and 0 <= self._ssel < len(self._sitems):
            it = self._sitems[self._ssel]
            if it["path"] and not (it["nsfw"] and not nsfw_revealed()):
                pm = QPixmap(it["path"])
                if not pm.isNull():
                    return ("store", it["appid"]), pm
            return ("store", it["appid"]), None
        return None, None

    def _sync_bg(self, animate=True):
        key, pix = self._current_art()
        if key == self._bg_key and (pix is None) == (self._bg_cur is None):
            return
        small = None
        if pix is not None and not pix.isNull():     # shrink twice = soft blur, tiny in memory
            small = _ncz_dominant_pixmap(pix)        # one flat colour: the cover's most repeated colour (no pixelated art)
        self._bg_prev, self._bg_cur, self._bg_key = self._bg_cur, small, key
        self._banim.stop()
        if animate and self.isVisible():
            self._bg_t = 0.0
            self._banim.setStartValue(0.0)
            self._banim.setEndValue(1.0)
            self._banim.start()
        else:
            self._bg_t = 1.0
        self.update()

    # ── navigation ──
    def _switch_tab(self, t):
        t %= _BP_NTABS
        if t == self._tab:
            return
        self._tabdir = 1 if t > self._tab else -1
        self._tab = t
        self._zone = "content"
        if t == 0 and self._lib_dirty:
            self._refresh()
        if t == 1 and not self._sstarted:
            self._store_reset()
        self._x_enter(t)
        self._tabt = 0.0
        self._tanim.stop()
        self._tanim.setStartValue(0.0)
        self._tanim.setEndValue(1.0)
        self._tanim.start()
        self._sync_bg()
        self.update()

    def _move_to(self, i):
        if not self._items:
            return
        i = max(0, min(len(self._items) - 1, i))
        if i == self._sel:
            return
        self._sel = i
        self._anim.stop()
        self._anim.setStartValue(self._pos)
        self._anim.setEndValue(float(i))
        self._anim.start()
        for k in [k for k in self._cache if abs(k - i) > 8]:      # keep memory small
            del self._cache[k]
        self._sync_bg()
        self.update()

    def _store_move(self, i):
        n = len(self._sitems)
        if not n:
            return
        i = max(0, min(n - 1, i))
        self._ssel = i
        self._scroll_to_sel()
        if i >= n - self._grid_geom()[4] * 2:       # near the end: fetch the next page
            self._store_load_page()
        for k in [k for k in self._spix if k not in {x["appid"] for x in self._sitems[max(0, i - 80):i + 80]}]:
            del self._spix[k]
        self._sync_bg()
        self.update()

    def _scroll_to_sel(self):
        _m, gap, _tw, th, cols, _x0, top, bottom, pad = self._grid_geom()
        row = self._ssel // cols
        row_top = row * (th + gap)
        view_h = bottom - top - 2 * pad
        target = self._sscroll
        if row_top < self._sscroll:
            target = row_top
        elif row_top + th > self._sscroll + view_h:
            target = row_top + th - view_h
        total_rows = (len(self._sitems) + cols - 1) // cols
        target = max(0.0, min(target, max(0.0, total_rows * (th + gap) - gap - view_h)))
        if abs(target - self._sscroll) > 0.5:
            self._sanim.stop()
            self._sanim.setStartValue(self._sscroll)
            self._sanim.setEndValue(float(target))
            self._sanim.start()

    def _launch(self):
        if not self._items:
            return
        it = self._items[self._sel]
        btn = it["btn"]
        if btn is None or not btn.isEnabled():
            self._say("Not available right now", 2500)
            return
        if btn.text().strip().lower() in ("play", "launch", "open"):
            self._say("Launching %s..." % it["title"], 20000)    # sleeps by itself once the game is running
            btn.click()
        else:                                                     # Install / Update / etc. need the normal launcher
            self.leave(True)
            btn.click()

    # ── store detail panel ──
    def _in_library(self, appid):
        return appid in getattr(self._app, "steam_cards", {})

    def _open_detail(self, i):
        if not (0 <= i < len(self._sitems)):
            return
        self._detail = {"item": self._sitems[i]}
        self._detail_btn = 0
        self._load_details(self._sitems[i]["appid"])
        self.update()

    def _detail_primary(self):
        it = self._detail["item"]
        if self._in_library(it["appid"]):
            card = self._app.steam_cards.get(it["appid"])
            self._detail = None
            self._switch_tab(0)
            if self._lib_dirty:
                self._refresh()
            for n, li in enumerate(self._items):
                if li["card"] is card:
                    self._sel = n
                    self._pos = float(n)
                    self._cache.clear()
                    self._sync_bg(animate=False)
                    break
            self.update()
            return
        try:
            self._app.add_steam_game(it["appid"], it["title"], it["path"])
            self._lib_dirty = True
            self._say("Added %s to your library" % it["title"], 3000)
        except Exception as ex:
            self._say("Couldn't add game: %s" % ex, 4000)
        self.update()

    def _detail_act(self, name):
        if name == "back":
            self._detail = None
        elif name in ("left", "right", "up", "down"):
            self._detail_btn = 1 - self._detail_btn
        elif name == "accept":
            if self._detail_btn == 0:
                self._detail_primary()
                return
            self._detail = None
        self.update()

    # ── input ──
    def _chip_count(self):
        return 1 + len(_BP_CATS)

    def _act(self, name):
        self.setCursor(Qt.CursorShape.BlankCursor)
        if self._detail is not None:
            self._detail_act(name)
            return
        if name == "prev":
            self._switch_tab(self._tab - 1)
            return
        if name == "next":
            self._switch_tab(self._tab + 1)
            return
        if name == "back":
            if self._tab == 1:                              # Store -> clear the search first, then go back to Library
                if self._search:
                    self._search = ""
                    self._store_reset()
                else:
                    self._switch_tab(0)
            else:
                self.leave(True)
            return
        if name == "alt":
            if self._tab == 1:
                self._zone, self._chip = "chips", 0
                self._say("Type to search, Enter to go", 3000)
            return
        z = self._zone
        if z == "tabs":
            if name in ("left", "right"):
                self._switch_tab(self._tab + (1 if name == "right" else -1))
                self._zone = "tabs"
            elif name == "down":
                self._zone = "chips" if self._tab == 1 else "content"
            self.update()
        elif z == "chips":
            if name == "left":
                self._chip = max(0, self._chip - 1)
            elif name == "right":
                self._chip = min(self._chip_count() - 1, self._chip + 1)
            elif name == "up":
                self._zone = "tabs"
            elif name == "down":
                if self._sitems:
                    self._zone = "content"
            elif name == "accept":
                self._chip_accept()
            self.update()
        elif self._tab == 0:
            if name == "left":
                self._move_to(self._sel - 1)
            elif name == "right":
                self._move_to(self._sel + 1)
            elif name == "up":
                self._zone = "tabs"
                self.update()
            elif name == "accept":
                self._launch()
        else:
            cols = self._grid_geom()[4]
            if name == "left":
                self._store_move(self._ssel - 1)
            elif name == "right":
                self._store_move(self._ssel + 1)
            elif name == "down":
                self._store_move(self._ssel + cols)
            elif name == "up":
                if self._ssel < cols:
                    self._zone = "chips"
                    self.update()
                else:
                    self._store_move(self._ssel - cols)
            elif name == "accept":
                if self._sitems:
                    self._open_detail(self._ssel)
                elif self._serror:
                    self._store_reset()

    def _chip_accept(self):
        if self._chip == 0:
            if self._search:
                self._store_reset()
            elif sys.platform.startswith("win"):
                try:
                    subprocess.Popen(["osk.exe"])
                except Exception:
                    _log_exc("_chip_accept")
            self._say("Type on your keyboard to search", 2500)
            return
        self._search = ""
        self._store_reset()

    def keyPressEvent(self, e):
        k = e.key()
        K = Qt.Key
        if self._detail is not None:
            if k in (K.Key_Left, K.Key_Right, K.Key_Up, K.Key_Down, K.Key_Tab):
                self._detail_act("left")
            elif k in (K.Key_Return, K.Key_Enter, K.Key_Space):
                self._detail_act("accept")
            elif k in (K.Key_Escape, K.Key_Backspace):
                self._detail_act("back")
            return
        if k == K.Key_Tab:
            self._switch_tab(self._tab + 1)
            return
        typing = (self._tab == 1 and self._zone == "chips" and self._chip == 0)
        if self._tab == 1 and (k == K.Key_Backspace) and self._search:
            self._search = self._search[:-1]
            self._stimer.start()
            self._chip = 0
            self.update()
            return
        if self._tab == 1 and k == K.Key_Slash:
            self._zone, self._chip = "chips", 0
            self.update()
            return
        if k == K.Key_Left or (k == K.Key_A and self._tab == 0):
            self._act("left")
        elif k == K.Key_Right or (k == K.Key_D and self._tab == 0):
            self._act("right")
        elif k == K.Key_Up:
            self._act("up")
        elif k == K.Key_Down:
            self._act("down")
        elif k == K.Key_PageUp:
            self._page(-1)
        elif k == K.Key_PageDown:
            self._page(1)
        elif k == K.Key_Home:
            self._move_to(0) if self._tab == 0 else self._store_move(0)
        elif k == K.Key_End:
            self._move_to(len(self._items) - 1) if self._tab == 0 else self._store_move(len(self._sitems) - 1)
        elif k in (K.Key_Return, K.Key_Enter) or (k == K.Key_Space and not typing):
            if self._tab == 1 and self._search and self._zone == "chips":
                self._store_reset()
            else:
                self._act("accept")
        elif k in (K.Key_Escape, K.Key_F11) or (k == K.Key_Backspace and not self._search):
            self._act("back")
        elif self._tab == 0 and e.text().isalnum() and self._items:      # type a letter: jump to the next game starting with it
            ch, n = e.text().lower(), len(self._items)
            for step in range(1, n + 1):
                j = (self._sel + step) % n
                if self._items[j]["title"].lower().startswith(ch):
                    self._move_to(j)
                    break
        elif self._tab == 1 and e.text() and e.text().isprintable():     # Store: any typing is a search
            self._search += e.text()
            self._zone, self._chip = "chips", 0
            self._stimer.start()
            self.update()

    def _page(self, d):
        if self._tab == 0:
            self._move_to(self._sel + 5 * d)
        else:
            cols = self._grid_geom()[4]
            self._store_move(self._ssel + cols * 3 * d)

    def closeEvent(self, e):
        e.ignore()
        self.leave(True)

    # ── geometry ──
    def _tile_rect(self, i):
        h, w = self.height(), self.width()
        th = h * self.LIB_TH
        tw = th * self._aspect
        d = i - self._pos
        s = 1 + 0.22 * max(0.0, 1 - abs(d))
        cx, cy = w / 2 + d * tw * 1.25, h * 0.43
        return QRectF(cx - tw * s / 2, cy - th * s / 2, tw * s, th * s)

    def _grid_geom(self):
        w, h = self.width(), self.height()
        m = w * 0.05
        gap = h * 0.022
        th = h * 0.27
        tw = th * self._aspect
        cols = max(2, int((w - 2 * m + gap) // (tw + gap)))
        gw = cols * tw + (cols - 1) * gap
        x0 = (w - gw) / 2
        top, bottom = h * 0.245, h * 0.86
        pad = th * 0.06
        return m, gap, tw, th, cols, x0, top, bottom, pad

    def _srect(self, i):
        _m, gap, tw, th, cols, x0, top, _b, pad = self._grid_geom()
        row, col = divmod(i, cols)
        return QRectF(x0 + col * (tw + gap), top + pad + row * (th + gap) - self._sscroll, tw, th)

    # ── mouse ──
    def mouseMoveEvent(self, e):
        if self.cursor().shape() != Qt.CursorShape.ArrowCursor:
            self.setCursor(Qt.CursorShape.ArrowCursor)

    def mousePressEvent(self, e):
        pt = e.position()
        if self._detail is not None:
            for n, r in enumerate(self._detail_rects):
                if r.contains(pt):
                    self._detail_btn = n
                    self._detail_act("accept")
                    return
            self._detail = None
            self.update()
            return
        if self._exit_rect.contains(pt):
            self.leave(True)
            return
        for n, r in enumerate(self._tab_rects):
            if r.contains(pt):
                self._zone = "content"
                self._switch_tab(n)
                return
        if self._tab == 0:
            best = None
            for i in range(len(self._items)):
                if self._tile_rect(i).contains(pt) and (best is None or abs(i - self._pos) < abs(best - self._pos)):
                    best = i
            if best is None:
                return
            if best == self._sel:
                self._launch()
            else:
                self._move_to(best)
            return
        for n, r in enumerate(self._chip_rects):
            if r.contains(pt):
                self._zone, self._chip = "chips", n
                self._chip_accept()
                self.update()
                return
        _m, _g, _tw, _th, _c, _x, top, bottom, _p = self._grid_geom()
        if top <= pt.y() <= bottom:
            for i in range(len(self._sitems)):
                if self._srect(i).contains(pt):
                    self._zone = "content"
                    if i == self._ssel:
                        self._open_detail(i)
                    else:
                        self._store_move(i)
                    return

    def wheelEvent(self, e):
        if self._detail is not None:
            return
        self._wheel += e.angleDelta().y() + e.angleDelta().x()
        while abs(self._wheel) >= 120:
            d = -1 if self._wheel > 0 else 1
            if self._tab == 0:
                self._move_to(self._sel + d)
            else:
                self._store_move(self._ssel + d * self._grid_geom()[4])
            self._wheel -= 120 if self._wheel > 0 else -120

    # ── painting helpers ──
    def resizeEvent(self, e):
        self._cache.clear()
        self._spix.clear()

    def _font(self, px, bold=False):
        f = QFont(self.font())
        f.setPixelSize(max(9, int(px)))
        w = _bp_bold_weight(f.family()) if bold else None
        if w is not None:
            f.setWeight(QFont.Weight(w))        # Linux: a real face, never Qt's heavy fake bold
        else:
            f.setBold(bold)
        return f

    def _make_tile(self, src, title, W, H, dpr):
        out = QPixmap(max(int(W * dpr), 8), max(int(H * dpr), 8))
        out.fill(Qt.GlobalColor.transparent)
        q = QPainter(out)
        q.setRenderHints(QPainter.RenderHint.Antialiasing | QPainter.RenderHint.SmoothPixmapTransform | QPainter.RenderHint.TextAntialiasing)
        pw, ph = out.width(), out.height()
        path = QPainterPath()
        path.addRoundedRect(QRectF(0, 0, pw, ph), pw * 0.05, pw * 0.05)
        q.setClipPath(path)
        if src is not None and not src.isNull():
            sc = src.scaled(pw, ph, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
            q.drawPixmap((pw - sc.width()) // 2, (ph - sc.height()) // 2, sc)
        else:
            g = QLinearGradient(0, 0, pw, ph)
            g.setColorAt(0, QColor(60, 50, 90))
            g.setColorAt(1, QColor(25, 20, 45))
            q.fillRect(0, 0, pw, ph, g)
            f = QFont(self.font())
            f.setPixelSize(max(10, int(pw * 0.11)))
            f.setBold(True)
            q.setFont(f)
            q.setPen(QColor(230, 230, 245))
            q.drawText(QRectF(pw * 0.08, 0, pw * 0.84, ph), int(Qt.AlignmentFlag.AlignCenter) | int(Qt.TextFlag.TextWordWrap), title)
        q.end()
        out.setDevicePixelRatio(dpr)
        return out

    def _tile_pix(self, i):
        pm = self._cache.get(i)
        if pm is not None:
            return pm
        th = self.height() * self.LIB_TH * 1.15
        pm = self._make_tile(self._items[i]["pix"], self._items[i]["title"], th * self._aspect, th, self.devicePixelRatioF())
        self._cache[i] = pm
        return pm

    def _store_src(self, it, w, h):
        if not it["path"]:
            return None
        if it["nsfw"] and not nsfw_revealed():
            return rounded_cover_pixmap(it["path"], int(w), int(h), 0, blur=True)
        pm = QPixmap(it["path"])
        return pm if not pm.isNull() else None

    def _store_pix(self, it, tw, th):
        pm = self._spix.get(it["appid"])
        if pm is None:
            pm = self._make_tile(self._store_src(it, tw, th), it["title"], tw * 1.08, th * 1.08, self.devicePixelRatioF())
            self._spix[it["appid"]] = pm
        return pm

    # ── painting ──
    def paintEvent(self, e):
        self._lseen = False
        p = QPainter(self)
        p.setRenderHints(QPainter.RenderHint.Antialiasing | QPainter.RenderHint.SmoothPixmapTransform | QPainter.RenderHint.TextAntialiasing)
        w, h = self.width(), self.height()
        acc = QApplication.palette().color(QPalette.ColorRole.Highlight)
        bg = QLinearGradient(0, 0, 0, h)
        bg.setColorAt(0, QColor(9, 9, 16))
        bg.setColorAt(1, QColor(12 + acc.red() // 7, 10 + acc.green() // 9, 20 + acc.blue() // 6))
        p.fillRect(self.rect(), bg)

        # blurred art of the selected game, crossfaded, with a dark fade so text stays readable
        for pm, op in ((self._bg_prev, (1 - self._bg_t) * 0.55), (self._bg_cur, self._bg_t * 0.55)):
            if pm is not None and op > 0.01:
                p.setOpacity(op)
                p.drawPixmap(QRectF(-w * 0.05, -h * 0.05, w * 1.1, h * 1.1), pm, QRectF(pm.rect()))
        p.setOpacity(1.0)
        fade = QLinearGradient(0, 0, 0, h)
        fade.setColorAt(0.0, QColor(6, 6, 12, 150))
        fade.setColorAt(0.45, QColor(6, 6, 12, 120))
        fade.setColorAt(1.0, QColor(6, 6, 12, 235))
        p.fillRect(self.rect(), fade)

        m = w * 0.05
        self._paint_header(p, w, h, m, acc)

        k = max(0.0, min(1.0, self._tabt))
        p.save()
        p.translate((1 - k) * self._tabdir * w * 0.04, 0)
        if self._tab == 0:
            self._paint_library(p, w, h, m, acc, k)
        elif self._tab == 1:
            self._paint_store(p, w, h, m, acc, k)
        else:
            self._paint_extra(p, w, h, m, acc, k)
        p.restore()
        p.setOpacity(1.0)

        self._paint_footer(p, w, h, m)
        if self._detail is not None:
            self._paint_detail(p, w, h, acc)
        if self._kb is not None:
            self._paint_kb(p, w, h, acc)
        if self._toast:
            p.setFont(self._font(h * 0.026, True))
            tw_ = QFontMetrics(p.font()).horizontalAdvance(self._toast) + h * 0.08
            box = QRectF(w / 2 - tw_ / 2, h * 0.88 if self._detail is None else h * 0.9, tw_, h * 0.06)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(0, 0, 0, 200))
            p.drawRoundedRect(box, h * 0.03, h * 0.03)
            p.setPen(QColor(245, 245, 252))
            p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), self._toast)
        if self._lseen:
            if not self._ltimer.isActive():
                self._ltimer.start()
        else:
            self._ltimer.stop()
            self._lfact = None
        p.end()

    def _paint_header(self, p, w, h, m, acc):
        al_r = int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        al_c = int(Qt.AlignmentFlag.AlignCenter)
        p.setFont(self._font(h * 0.03, True))
        p.setPen(QColor(240, 240, 250))

        # tab bar (centered pill); every tab has its own width and the font shrinks a little if five tabs don't fit
        labels = self._tab_labels()
        bh = h * 0.058
        left_b, right_b = m + w * 0.06, w - m - w * 0.07 - h * 0.17 - h * 0.02 - h * 0.062
        size = 0.026
        while True:
            tf = self._font(h * size, True)
            fm = QFontMetrics(tf)
            widths = [fm.horizontalAdvance(t) + h * 0.05 for t in labels]
            if sum(widths) + h * 0.012 <= right_b - left_b or size < 0.016:
                break
            size -= 0.002
        total = sum(widths) + h * 0.012
        x0, y0 = max(left_b, min((w - total) / 2, right_b - total)), h * 0.041
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 22))
        p.drawRoundedRect(QRectF(x0, y0, total, bh + h * 0.012), (bh + h * 0.012) / 2, (bh + h * 0.012) / 2)
        self._tab_rects = []
        tx = x0 + h * 0.006
        for n, t in enumerate(labels):
            r = QRectF(tx, y0 + h * 0.006, widths[n], bh)
            tx += widths[n]
            self._tab_rects.append(r)
            if n == self._tab:
                p.setBrush(acc)
                p.drawRoundedRect(r, bh / 2, bh / 2)
                if self._zone == "tabs" and not getattr(self, "_hsel", None):
                    p.setPen(QPen(QColor(255, 255, 255, 230), max(2.0, h * 0.004)))
                    p.setBrush(Qt.BrushStyle.NoBrush)
                    g = h * 0.005
                    p.drawRoundedRect(r.adjusted(-g, -g, g, g), (bh + 2 * g) / 2, (bh + 2 * g) / 2)
                    p.setPen(Qt.PenStyle.NoPen)
                p.setPen(QColor(_on_accent()))
            else:
                p.setPen(QColor(200, 200, 220))
            p.setFont(tf)
            p.drawText(r, al_c, t)
            p.setPen(Qt.PenStyle.NoPen)

        # clock + exit
        p.setFont(self._font(h * 0.026))
        p.setPen(QColor(200, 200, 220))
        p.drawText(QRectF(w - m - w * 0.07, h * 0.04, w * 0.07, h * 0.06), al_r, time.strftime("%H:%M"))
        self._exit_rect = QRectF(w - m - w * 0.07 - h * 0.17, h * 0.047, h * 0.15, h * 0.046)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 28))
        p.drawRoundedRect(self._exit_rect, h * 0.023, h * 0.023)
        p.setFont(self._font(h * 0.02))
        p.setPen(QColor(220, 220, 235))
        p.drawText(self._exit_rect, al_c, "Exit")
        # settings cog wheel (left of Exit)
        cs = self._exit_rect.height()
        self._cog_rect = QRectF(self._exit_rect.left() - h * 0.014 - cs, self._exit_rect.top(), cs, cs)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 28))
        p.drawEllipse(self._cog_rect)
        _bpe_draw_cog(p, self._cog_rect.adjusted(cs * 0.2, cs * 0.2, -cs * 0.2, -cs * 0.2), QColor(220, 220, 235))
        if self._zone == "tabs" and getattr(self, "_hsel", None):
            self._x_ring(p, self._cog_rect if self._hsel == "cog" else self._exit_rect,
                         cs / 2 if self._hsel == "cog" else h * 0.023)

    def _paint_footer(self, p, w, h, m):
        al_l = int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        al_r = int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        if self._kb is not None:
            hint = "Arrows  Move      A  Type      X  Delete      Y  Space      LB  Shift      RB  123      Start  Done      B  Close"
        elif self._detail is not None:
            hint = "Left / Right  Choose      A / Enter  Select      Y  Reviews      B / Esc  Close"
        elif self._tab == 0:
            hint = "Left / Right  Browse      A / Enter  Launch      X  Game options      Y  Library view      LB / RB  Switch tab      B / Esc  Exit"
        elif self._tab == 1:
            hint = "Arrows  Browse      A / Enter  Details      Y or type  Search      LB / RB  Switch tab      B / Esc  Back"
        else:
            hint = self._x_hint()
        p.setFont(self._font(h * 0.0185))
        p.setPen(QColor(150, 150, 175))
        p.drawText(QRectF(m, h * 0.93, w * 0.78, h * 0.04), al_l, hint)
        if self._detail is None and self._tab < 2 and self._kb is None:
            n, sel = (len(self._items), self._sel) if self._tab == 0 else (len(self._sitems), self._ssel)
            if n:
                txt = "%d / %d" % (sel + 1, n)
                if self._tab == 1 and self._stotal:
                    txt += "  (%s on Steam)" % format(self._stotal, ",")
                p.drawText(QRectF(w - m - w * 0.22, h * 0.93, w * 0.22, h * 0.04), al_r, txt)

    def _paint_library(self, p, w, h, m, acc, k):
        al_c = int(Qt.AlignmentFlag.AlignCenter)
        n = len(self._items)
        if n == 0:
            p.setOpacity(k)
            p.setFont(self._font(h * 0.035))
            p.setPen(QColor(200, 200, 220))
            p.drawText(self.rect(), al_c, "No games in your library yet\nOpen the Store tab to add some")
            return
        content_on = self._zone != "tabs"
        span = int(w / (h * self.LIB_TH * self._aspect * 1.25)) // 2 + 2
        lo, hi = max(0, int(self._pos) - span), min(n - 1, int(self._pos) + span)
        for i in sorted(range(lo, hi + 1), key=lambda q: -abs(q - self._pos)):
            r = self._tile_rect(i)
            if r.right() < 0 or r.left() > w:
                continue
            near = max(0.0, 1 - abs(i - self._pos))
            if near > 0.05:                              # soft accent glow under the selected tile
                glow = QRadialGradient(r.center().x(), r.bottom(), r.width() * 0.9)
                gc = QColor(acc)
                gc.setAlphaF(0.35 * near * k)
                glow.setColorAt(0, gc)
                gc.setAlpha(0)
                glow.setColorAt(1, gc)
                p.setOpacity(1.0)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(glow)
                p.drawEllipse(QPointF(r.center().x(), r.bottom()), r.width() * 0.9, r.width() * 0.3)
            p.setOpacity(k * (0.5 + 0.5 * near))
            if near > 0 and content_on:
                ring = QColor(acc)
                ring.setAlphaF(near)
                p.setPen(QPen(ring, max(2.0, h * 0.005)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                gap = h * 0.008
                p.drawRoundedRect(r.adjusted(-gap, -gap, gap, gap), r.width() * 0.06, r.width() * 0.06)
            pm = self._tile_pix(i)
            p.drawPixmap(r, pm, QRectF(pm.rect()))
            # mirror reflection, fading out
            if near > 0.5:
                refl = QRectF(r.left(), r.bottom() + h * 0.008, r.width(), r.height() * 0.16)
                p.save()
                p.setClipRect(refl)
                p.translate(0, r.bottom() * 2 + h * 0.008)
                p.scale(1, -1)
                p.setOpacity(k * 0.16 * near)
                p.drawPixmap(r, pm, QRectF(pm.rect()))
                p.restore()
        p.setOpacity(k)

        it = self._items[self._sel]
        f = self._font(h * 0.05, True)
        p.setFont(f)
        p.setPen(QColor(245, 245, 252))
        title = QFontMetrics(f).elidedText(it["title"], Qt.TextElideMode.ElideRight, int(w * 0.7))
        p.drawText(QRectF(0, h * 0.70, w, h * 0.07), al_c, title)
        p.setFont(self._font(h * 0.022))
        p.setPen(QColor(170, 170, 195))
        p.drawText(QRectF(0, h * 0.77, w, h * 0.035), al_c, it["status"])
        if it["action"]:
            pill = QRectF(w / 2 - h * 0.14, h * 0.82, h * 0.28, h * 0.065)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(acc)
            p.drawRoundedRect(pill, h * 0.032, h * 0.032)
            p.setFont(self._font(h * 0.028, True))
            p.setPen(QColor(_on_accent()))
            p.drawText(pill, al_c, it["action"])

    def _paint_chips(self, p, w, h, m, acc, k):
        al_c = int(Qt.AlignmentFlag.AlignCenter)
        al_l = int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
        ch = h * 0.05
        y = h * 0.165
        gap = h * 0.014
        cf = self._font(h * 0.021, True)
        fm = QFontMetrics(cf)
        widths = [w * 0.2] + [fm.horizontalAdvance(c[0]) + h * 0.05 for c in _BP_CATS]
        xs, x = [], 0.0
        for cw in widths:
            xs.append(x)
            x += cw + gap
        view_w = w - 2 * m
        sel_l, sel_r = xs[self._chip], xs[self._chip] + widths[self._chip]
        target = self._chip_scroll
        if sel_l < target:
            target = sel_l
        elif sel_r > target + view_w:
            target = sel_r - view_w
        self._chip_scroll += (target - self._chip_scroll) * 0.35
        if abs(target - self._chip_scroll) > 0.5:
            QTimer.singleShot(16, self.update)
        else:
            self._chip_scroll = target
        p.save()
        p.setClipRect(QRectF(m - h * 0.01, y - h * 0.01, view_w + h * 0.02, ch + h * 0.02))
        self._chip_rects = []
        focus = self._zone == "chips"
        for n, cw in enumerate(widths):
            r = QRectF(m + xs[n] - self._chip_scroll, y, cw, ch)
            self._chip_rects.append(r)
            if r.right() < 0 or r.left() > w:
                continue
            active = (n == 0 and bool(self._search)) or (n == self._chip and n != 0 and not self._search)
            p.setOpacity(k)
            p.setPen(Qt.PenStyle.NoPen)
            if active:
                p.setBrush(acc)
            else:
                p.setBrush(QColor(255, 255, 255, 26))
            p.drawRoundedRect(r, ch / 2, ch / 2)
            if focus and n == self._chip:
                p.setPen(QPen(QColor(255, 255, 255, 230), max(2.0, h * 0.004)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                g = h * 0.004
                p.drawRoundedRect(r.adjusted(-g, -g, g, g), (ch + 2 * g) / 2, (ch + 2 * g) / 2)
            p.setFont(cf)
            p.setPen(QColor(_on_accent()) if active else QColor(215, 215, 232))
            if n == 0:
                txt = (self._search + ("|" if focus and self._chip == 0 else "")) if (self._search or (focus and self._chip == 0)) else "Search"
                txt = QFontMetrics(cf).elidedText(txt, Qt.TextElideMode.ElideLeft, int(cw - h * 0.05))
                p.drawText(r.adjusted(h * 0.025, 0, -h * 0.02, 0), al_l, txt)
            else:
                p.drawText(r, al_c, _BP_CATS[n - 1][0])
        p.restore()

    def _paint_loading(self, p, w, h, area, msg):
        """Spinning NCZ logo + message + a Wikipedia fact. Drives its own 33 ms timer only while it is visible."""
        from PyQt6.QtGui import QTextOption    # lazy: saves memory/startup until used
        self._lseen = True
        now = time.time()
        if self._lfact is None or now - self._lfact_t > 10:
            self._lfact, self._lfact_t = lc_next_fact(), now
        age = now - self._lfact_t
        fa = max(0.0, min(1.0, age / 0.8, (10.0 - age) / 0.8))
        size = h * 0.17
        cx, cy = area.center().x(), area.top() + area.height() * 0.36
        pm = lc_logo_pixmap()
        side = max(8, int(size))
        dpr = self.devicePixelRatioF()
        key = (pm.cacheKey(), side, dpr)
        if getattr(self, "_lpm_key", None) != key:       # round logo rendered once, then only rotated + blitted each frame
            px = int(side * dpr)
            rp = QPixmap(px, px)
            rp.fill(Qt.GlobalColor.transparent)
            q = QPainter(rp)
            q.setRenderHints(QPainter.RenderHint.Antialiasing | QPainter.RenderHint.SmoothPixmapTransform)
            clip = QPainterPath()
            clip.addEllipse(QRectF(0, 0, px, px))
            q.setClipPath(clip)
            if pm.isNull():
                q.fillRect(QRectF(0, 0, px, px), QColor(166, 102, 255))
            else:
                q.drawPixmap(QRectF(0, 0, px, px), pm, QRectF(pm.rect()))
            q.end()
            rp.setDevicePixelRatio(dpr)
            self._lpm, self._lpm_key = rp, key
        p.save()
        p.translate(cx, cy)
        p.rotate((now * 140) % 360)
        p.drawPixmap(QPointF(-side / 2.0, -side / 2.0), self._lpm)
        p.restore()
        text, src = self._lfact
        y = cy + size / 2 + h * 0.025
        p.setFont(self._font(h * 0.032))
        p.setPen(QColor(200, 200, 220))
        p.drawText(QRectF(0, y, w, h * 0.05), int(Qt.AlignmentFlag.AlignCenter), msg)
        opt = QTextOption(Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop)
        opt.setWrapMode(QTextOption.WrapMode.WordWrap)
        p.setFont(self._font(h * 0.024))
        p.setPen(QColor(175, 175, 200, int(225 * fa)))
        p.drawText(QRectF(w * 0.26, y + h * 0.07, w * 0.48, h * 0.1), text, opt)
        if src:
            p.setFont(self._font(h * 0.017))
            p.setPen(QColor(150, 150, 175, int(170 * fa)))
            p.drawText(QRectF(w * 0.26, y + h * 0.175, w * 0.48, h * 0.03), int(Qt.AlignmentFlag.AlignCenter), src)

    def _paint_store(self, p, w, h, m, acc, k):
        al_c = int(Qt.AlignmentFlag.AlignCenter)
        p.setOpacity(k)
        self._paint_chips(p, w, h, m, acc, k)
        _m, gap, tw, th, cols, x0, top, bottom, pad = self._grid_geom()
        n = len(self._sitems)
        if n == 0:
            p.setOpacity(k)
            p.setFont(self._font(h * 0.032))
            p.setPen(QColor(200, 200, 220))
            msg = self._serror or ("Loading games..." if (self._sloading or not self._sstarted) else "No games found")
            if msg == "Loading games...":
                self._paint_loading(p, w, h, QRectF(0, top, w, bottom - top), msg)
            else:
                p.drawText(QRectF(0, top, w, bottom - top), al_c, msg)
            return
        p.save()
        p.setClipRect(QRectF(0, top, w, bottom - top))
        row_h = th + gap
        first = max(0, int(self._sscroll // row_h) - 1) * cols
        last = min(n, (int((self._sscroll + bottom - top) // row_h) + 2) * cols)
        focus = self._zone == "content"
        for i in range(first, last):
            it = self._sitems[i]
            r = self._srect(i)
            if r.bottom() < top or r.top() > bottom:
                continue
            sel = (i == self._ssel and focus)
            if sel:
                grow = tw * 0.04
                r = r.adjusted(-grow, -grow, grow, grow)
            p.setOpacity(k * (1.0 if sel or not focus else 0.78))
            if sel:
                ring = QColor(acc)
                p.setPen(QPen(ring, max(2.0, h * 0.005)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                g = h * 0.007
                p.drawRoundedRect(r.adjusted(-g, -g, g, g), r.width() * 0.06, r.width() * 0.06)
            pm = self._store_pix(it, tw, th)
            p.drawPixmap(r, pm, QRectF(pm.rect()))
            if self._in_library(it["appid"]):
                bf = self._font(h * 0.0155, True)
                p.setFont(bf)
                bw = QFontMetrics(bf).horizontalAdvance("IN LIBRARY") + h * 0.026
                b = QRectF(r.left() + h * 0.008, r.top() + h * 0.008, bw, h * 0.028)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(acc)
                p.drawRoundedRect(b, h * 0.014, h * 0.014)
                p.setPen(QColor(_on_accent()))
                p.drawText(b, al_c, "IN LIBRARY")
        p.restore()
        p.setOpacity(k)
        if self._sloading and n:                         # a quiet "more coming" hint at the end of the list
            p.setFont(self._font(h * 0.018))
            p.setPen(QColor(170, 170, 195))
            p.drawText(QRectF(0, bottom - h * 0.035, w, h * 0.03), al_c, "Loading more...")
        if self._serror and n:
            p.setFont(self._font(h * 0.018))
            p.setPen(QColor(230, 170, 170))
            p.drawText(QRectF(0, bottom - h * 0.035, w, h * 0.03), al_c, self._serror)

        # info bar for the selected game
        it = self._sitems[min(self._ssel, n - 1)]
        f = self._font(h * 0.03, True)
        p.setFont(f)
        p.setPen(QColor(245, 245, 252))
        title = QFontMetrics(f).elidedText(it["title"], Qt.TextElideMode.ElideRight, int(w * 0.8))
        p.drawText(QRectF(m, h * 0.865, w - 2 * m, h * 0.055), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter), title)

    def _paint_detail(self, p, w, h, acc):
        al_c = int(Qt.AlignmentFlag.AlignCenter)
        it = self._detail["item"]
        p.setOpacity(1.0)
        p.fillRect(self.rect(), QColor(4, 4, 10, 215))
        panel = QRectF(w * 0.14, h * 0.14, w * 0.72, h * 0.70)
        p.setPen(QPen(QColor(255, 255, 255, 40), 1.5))
        p.setBrush(QColor(20, 20, 32, 245))
        p.drawRoundedRect(panel, h * 0.025, h * 0.025)
        pad = h * 0.04
        ch = panel.height() - 2 * pad
        cw = ch * 0.72
        cover = QRectF(panel.left() + pad, panel.top() + pad, cw, ch)
        pm = self._store_pix(it, cover.width() / 1.08, cover.height() / 1.08)
        p.drawPixmap(cover, pm, QRectF(pm.rect()))

        tx = cover.right() + pad
        tw = panel.right() - pad - tx
        info = self._details.get(it["appid"]) or {}
        p.setPen(QColor(245, 245, 252))
        f = self._font(h * 0.042, True)
        p.setFont(f)
        p.drawText(QRectF(tx, cover.top(), tw, h * 0.1), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop) | int(Qt.TextFlag.TextWordWrap),
                   QFontMetrics(f).elidedText(it["title"], Qt.TextElideMode.ElideRight, int(tw * 2)))
        y = cover.top() + h * 0.115
        meta = "  ·  ".join(x for x in (", ".join(info.get("genres", [])[:4]), info.get("date", ""), info.get("dev", "")) if x)
        p.setFont(self._font(h * 0.02))
        p.setPen(QColor(acc.lighter(140)))
        p.drawText(QRectF(tx, y, tw, h * 0.05), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop) | int(Qt.TextFlag.TextWordWrap),
                   meta or ("Loading details..." if it["appid"] in self._details else ""))
        desc = info.get("desc", "")
        if len(desc) > 520:
            desc = desc[:517].rstrip() + "..."
        p.setFont(self._font(h * 0.0235))
        p.setPen(QColor(200, 200, 218))
        p.drawText(QRectF(tx, y + h * 0.065, tw, ch - h * 0.065 - h * 0.115 - h * 0.1),
                   int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop) | int(Qt.TextFlag.TextWordWrap), desc)

        # buttons
        in_lib = self._in_library(it["appid"])
        labels = ("Show in Library" if in_lib else "Add to Library", "Close")
        bh = h * 0.065
        bw = min(h * 0.3, tw / 2 - h * 0.01)
        by = cover.bottom() - bh
        self._detail_rects = []
        for n, text in enumerate(labels):
            r = QRectF(tx + n * (bw + h * 0.014), by, bw, bh)
            self._detail_rects.append(r)
            p.setPen(Qt.PenStyle.NoPen)
            if n == 0:
                p.setBrush(acc)
            else:
                p.setBrush(QColor(255, 255, 255, 30))
            p.drawRoundedRect(r, bh / 2, bh / 2)
            if n == self._detail_btn:
                p.setPen(QPen(QColor(255, 255, 255, 235), max(2.0, h * 0.004)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                g = h * 0.005
                p.drawRoundedRect(r.adjusted(-g, -g, g, g), (bh + 2 * g) / 2, (bh + 2 * g) / 2)
            p.setFont(self._font(h * 0.0245, True))
            p.setPen(QColor(_on_accent()) if n == 0 else QColor(225, 225, 240))
            p.drawText(r, al_c, text)


# ── Big Picture extras ──
# On-screen keyboard (controller friendly) + three more tabs: Friends, Downloads, Workshop.
# Added as a separate layer on top of _BigPicture (same pattern as _bp_open below): the original methods keep doing their
# job, these wrappers only take over when the keyboard is open or one of the new tabs (index >= 2) is showing.

_BP_NTABS = 5                       # Library, Store, Friends, Downloads, Workshop (+ Fan Games, GMod Addons: set at runtime)
_bp_friend_listeners = []           # called after FriendsPage finished a refresh


class _BPKeys:
    """On-screen keyboard model (no Qt): layouts, the highlighted key and the text being typed."""

    @staticmethod
    def layout(shift, sym):
        def ch(s, up=False):
            return [((c.upper() if up else c), (c.upper() if up else c), 1.0) for c in s]
        if sym:
            rows = [ch("1234567890"), ch("!@#$%^&*()"), ch("-_=+[]{}\\|"), ch(";:'\",.?/") + [("Del", "@del", 2.0)]]
            bottom = [("abc", "@sym", 1.5), ("<", "<", 1.0), ("Space", "@space", 4.5), (">", ">", 1.0), ("Done", "@done", 2.0)]
        else:
            rows = [ch("1234567890"), ch("qwertyuiop", shift), ch("asdfghjkl'", shift),
                    [("Shift", "@shift", 1.5)] + ch("zxcvbnm", shift) + [("Del", "@del", 1.5)]]
            bottom = [("123", "@sym", 1.5), (",", ",", 1.0), ("Space", "@space", 4.5), (".", ".", 1.0), ("Done", "@done", 2.0)]
        rows.append(bottom)
        return rows

    def __init__(self, text="", maxlen=120):
        self.text, self.maxlen = text, maxlen
        self.shift = self.sym = False
        self.r, self.c = 2, 4

    def rows(self):
        return self.layout(self.shift, self.sym)

    @staticmethod
    def _centers(row):
        tot, x, out = sum(k[2] for k in row), 0.0, []
        for k in row:
            out.append((x + k[2] / 2.0) / tot)
            x += k[2]
        return out

    def clamp(self):
        rows = self.rows()
        self.r = max(0, min(len(rows) - 1, self.r))
        self.c = max(0, min(len(rows[self.r]) - 1, self.c))

    def move(self, dx, dy):
        self.clamp()
        rows = self.rows()
        if dy:
            cx = self._centers(rows[self.r])[self.c]
            self.r = max(0, min(len(rows) - 1, self.r + dy))
            cs = self._centers(rows[self.r])
            self.c = min(range(len(cs)), key=lambda i: abs(cs[i] - cx))
        if dx:
            self.c = (self.c + dx) % len(rows[self.r])

    def insert(self, s):
        if len(self.text) + len(s) > self.maxlen:
            return False
        self.text += s
        return True

    def backspace(self):
        if not self.text:
            return False
        self.text = self.text[:-1]
        return True

    def toggle_shift(self):
        if not self.sym:
            self.shift = not self.shift

    def toggle_sym(self):
        self.sym, self.shift = not self.sym, False
        self.clamp()

    def press(self, r=None, c=None):
        """Presses the highlighted key (or key r, c). Returns 'done', 'changed' or ''."""
        if r is not None:
            self.r, self.c = r, c
        self.clamp()
        act = self.rows()[self.r][self.c][1]
        if act == "@done":
            return "done"
        if act == "@shift":
            self.toggle_shift()
            return ""
        if act == "@sym":
            self.toggle_sym()
            return ""
        if act == "@del":
            return "changed" if self.backspace() else ""
        if act == "@space":
            return "changed" if self.insert(" ") else ""
        if self.insert(act):
            self.shift = False
            return "changed"
        return ""


def _bpm(name):
    """Attach the decorated function to _BigPicture as method `name` (the original is kept in _bpx_o by the caller)."""
    def deco(f):
        setattr(_BigPicture, name, f)
        return f
    return deco


def _bpx_signed(fp):
    try:
        return bool(fp._signed_in())
    except Exception:
        return False


_bpx_o = {n: getattr(_BigPicture, n) for n in ("__init__", "enter", "leave", "_show_awake", "_stop_awake", "_act",
                                                "keyPressEvent", "mousePressEvent", "wheelEvent", "_chip_accept")}


def _bpx_connected(self):
    """True while a game controller is plugged in (Linux js device open / Windows XInput pad answering)."""
    if sys.platform.startswith("win"):
        return self._xi is not None and self._poll.interval() == 16
    return self._fd is not None


_BPInput.connected = _bpx_connected

# FriendsPage tells the Big Picture when a refresh finished (it runs on the GUI thread already)
_bpx_fp_fetched = FriendsPage._on_fetched


def _bpx_fp_on_fetched(self, res, err):
    _bpx_fp_fetched(self, res, err)
    for fn in list(_bp_friend_listeners):
        try:
            fn()
        except Exception:
            _log_exc("_bpx_fp_on_fetched")


FriendsPage._on_fetched = _bpx_fp_on_fetched


# ── setup / lifecycle ──
@_bpm("__init__")
def _bpx_init(self, app):
    _bpx_o["__init__"](self, app)
    self._kb = None                     # open on-screen keyboard: {"k": _BPKeys, "title", "on_change", "on_submit", "rects"}
    self._pad_last = False              # True while the controller was the last thing used
    self._from_key = False
    self._xhits = []                    # (rect, tag) of clickable things painted by the extra tabs
    self._xscroll = self._xtarget = 0.0
    self._xticks = 0
    self._xwheel = False
    self._xanim = QVariantAnimation(self)
    self._xanim.setDuration(200)
    self._xanim.setEasingCurve(QEasingCurve.Type.OutCubic)
    self._xanim.valueChanged.connect(self._x_on_scroll)
    self._xtimer = QTimer(self)         # runs only while Friends / Downloads / Workshop is showing
    self._xtimer.setInterval(600)
    self._xtimer.timeout.connect(self._x_tick)
    self._fr = {"rows": [], "sel": 0, "btn": 0, "chat": None, "cbtn": 0, "msgs": [], "me": "", "moff": 0,
                "loading": False, "sending": False, "av": {}}
    self._dl = {"sel": 0, "btn": 0}
    self._wk = {"mode": "games", "games": [], "gsel": 0, "appid": None, "title": "", "items": [], "seen": set(),
                "sel": 0, "page": 1, "token": 0, "loading": False, "err": "", "query": "", "sort": 0, "more": False,
                "pix": {}, "asked": set(), "workers": []}
    _bp_friend_listeners.append(self._fr_changed)


@_bpm("enter")
def _bpx_enter_w(self):
    _bpx_o["enter"](self)
    if self._tab >= 2:
        self._x_enter(self._tab)


@_bpm("_show_awake")
def _bpx_show_awake(self):
    _bpx_o["_show_awake"](self)
    if self._tab >= 2:
        self._xtimer.start()


@_bpm("_stop_awake")
def _bpx_stop_awake(self):
    _bpx_o["_stop_awake"](self)
    self._xtimer.stop()
    self._xanim.stop()
    self._kb = None


@_bpm("leave")
def _bpx_leave(self, show_main=True):
    _bpx_o["leave"](self, show_main)
    self._wk["pix"].clear()
    self._wk["asked"].clear()
    self._fr["av"].clear()
    self._fr["chat"] = None


@_bpm("_tab_labels")
def _bpx_tab_labels(self):
    fp = getattr(self._app, "friends_page", None)
    try:
        nreq = len(fp.requests or {}) if fp is not None else 0
    except Exception:
        nreq = 0
    try:
        nact = sum(1 for i in self._dl_infos() if i["state"] == "active")
    except Exception:
        nact = 0
    return ("Library", "Store", "Friends" + (" (%d)" % nreq if nreq else ""),
            "Downloads" + (" (%d)" % nact if nact else ""), "Workshop")


@_bpm("_use_vkb")
def _bpx_use_vkb(self):
    try:
        return bool(self._pad_last and self._input.connected())
    except Exception:
        return False


@_bpm("_x_on_scroll")
def _bpx_on_scroll(self, v):
    self._xscroll = float(v)
    self.update()


@_bpm("_x_ensure")
def _bpx_ensure(self, top, bot, vh):
    t = self._xtarget
    if top < t:
        t = top
    elif bot > t + vh:
        t = bot - vh
    t = max(0.0, t)
    if t != self._xtarget:
        self._xtarget = t
        self._xanim.stop()
        self._xanim.setStartValue(self._xscroll)
        self._xanim.setEndValue(t)
        self._xanim.start()


@_bpm("_x_reset_scroll")
def _bpx_reset_scroll(self):
    self._xanim.stop()
    self._xscroll = self._xtarget = 0.0


@_bpm("_x_enter")
def _bpx_x_enter(self, t):
    self._xtimer.stop()
    self._xticks = 0
    self._x_reset_scroll()
    if t == 2:
        self._fr_enter()
    elif t == 3:
        self._dl_ensure()
    elif t == 4:
        self._ws_enter()
    if t >= 2 and self._active and not self._asleep:
        self._xtimer.start()


@_bpm("_x_tick")
def _bpx_tick(self):
    self._xticks += 1
    if self._tab == 2:
        fp = getattr(self._app, "friends_page", None)
        if fp is not None and _bpx_signed(fp):
            if self._xticks % 25 == 0:
                fp.refresh()
            if self._fr["chat"] and self._xticks % 8 == 0 and self._kb is None:
                self._fr_load_chat(self._fr["chat"], quiet=True)
    if self._tab >= 2:
        self.update()


# ── input ──
@_bpm("_act")
def _bpx_act(self, name):
    if not self._from_key:
        self._pad_last = True
    if name == "start":                                   # Start = "Done" on the keyboard, otherwise the same as A
        name = "submit" if self._kb is not None else "accept"
    if self._kb is not None:
        self.setCursor(Qt.CursorShape.BlankCursor)
        self._kb_act(name)
        return
    if self._detail is None and name == "alt" and self._tab == 1 and self._use_vkb():
        self.setCursor(Qt.CursorShape.BlankCursor)
        self._zone, self._chip = "chips", 0
        self._kb_open_store()
        return
    if self._tab >= 2 and self._detail is None:
        self.setCursor(Qt.CursorShape.BlankCursor)
        if name == "prev":
            self._switch_tab(self._tab - 1)
        elif name == "next":
            self._switch_tab(self._tab + 1)
        elif self._zone == "tabs" and name in ("left", "right"):
            self._switch_tab(self._tab + (1 if name == "right" else -1))
            self._zone = "tabs"
        elif self._zone == "tabs" and name == "down":
            self._zone = "content"
        elif self._zone == "tabs" and name in ("up", "accept"):
            pass
        else:
            self._x_act(name)
        self.update()
        return
    _bpx_o["_act"](self, name)


@_bpm("_chip_accept")
def _bpx_chip_accept(self):
    if self._chip == 0 and self._use_vkb():
        self._kb_open_store()
        return
    _bpx_o["_chip_accept"](self)


@_bpm("keyPressEvent")
def _bpx_key_press(self, e):
    self._pad_last = False
    if self._kb is not None:
        self._kb_key(e)
        return
    if self._tab >= 2 and self._detail is None:
        self._x_key(e)
        return
    self._from_key = True
    try:
        _bpx_o["keyPressEvent"](self, e)
    finally:
        self._from_key = False


@_bpm("mousePressEvent")
def _bpx_mouse_press(self, e):
    self._pad_last = False
    pt = e.position()
    if self._kb is not None:
        for r, ri, ci in self._kb["rects"]:
            if r.contains(pt):
                self._kb_press(ri, ci)
                return
        self._kb_close()
        return
    if self._tab >= 2 and self._detail is None:
        if self._exit_rect.contains(pt):
            self.leave(True)
            return
        for n, r in enumerate(self._tab_rects):
            if r.contains(pt):
                self._zone = "content"
                self._switch_tab(n)
                return
        self._x_click(pt)
        return
    _bpx_o["mousePressEvent"](self, e)


@_bpm("wheelEvent")
def _bpx_wheel(self, e):
    if self._kb is not None:
        return
    if self._tab >= 2 and self._detail is None:
        self._wheel += e.angleDelta().y() + e.angleDelta().x()
        self._zone = "content"
        self._xwheel = True
        try:
            while abs(self._wheel) >= 120:
                self._x_act("up" if self._wheel > 0 else "down")
                self._wheel -= 120 if self._wheel > 0 else -120
        finally:
            self._xwheel = False
        return
    _bpx_o["wheelEvent"](self, e)


@_bpm("_x_key")
def _bpx_x_key(self, e):
    k, K = e.key(), Qt.Key
    self._from_key = True
    try:
        if k == K.Key_Tab:
            self._switch_tab(self._tab + 1)
        elif k == K.Key_Backtab:
            self._switch_tab(self._tab - 1)
        elif k == K.Key_Left:
            self._act("left")
        elif k == K.Key_Right:
            self._act("right")
        elif k == K.Key_Up:
            self._act("up")
        elif k == K.Key_Down:
            self._act("down")
        elif k in (K.Key_Return, K.Key_Enter, K.Key_Space):
            self._act("accept")
        elif k in (K.Key_Escape, K.Key_Backspace, K.Key_F11):
            self._act("back")
        elif k in (K.Key_Slash, K.Key_F):
            self._act("alt")
        elif k == K.Key_S:
            self._act("x")
    finally:
        self._from_key = False


@_bpm("_x_act")
def _bpx_x_act(self, name):
    if self._tab == 2:
        self._fr_act(name)
    elif self._tab == 3:
        self._dl_act(name)
    elif self._tab == 4:
        self._ws_act(name)
    self.update()


def _bpx_top(self):
    if not self._xwheel:
        self._zone = "tabs"


@_bpm("_x_click")
def _bpx_click(self, pt):
    for r, tag in reversed(self._xhits):
        if r.contains(pt):
            self._zone = "content"
            try:
                self._x_tag(tag)
            except (IndexError, KeyError):    # expected: missing or odd value: the default is fine
                pass
            return


@_bpm("_x_tag")
def _bpx_tag(self, tag):
    k = tag[0]
    fr = self._fr
    if k == "row":
        fr["sel"], fr["btn"] = tag[1], 0
        self._fr_ensure()
        if fr["rows"][tag[1]]["kind"] == "friend":
            self._fr_act("accept")
    elif k == "btn":
        fr["sel"], fr["btn"] = tag[1], tag[2]
        self._fr_act("accept")
    elif k == "cbtn":
        fr["cbtn"] = tag[1]
        self._fr_act("accept")
    elif k == "dbtn":
        self._dl["sel"], self._dl["btn"] = tag[1], tag[2]
        self._dl_act("accept")
    elif k == "drow":
        self._dl["sel"], self._dl["btn"] = tag[1], 0
    elif k == "tile":
        wk = self._wk
        key = "gsel" if wk["mode"] == "games" else "sel"
        if wk[key] == tag[1]:
            self._ws_act("accept")
        else:
            wk[key] = tag[1]
            self._ws_ensure()
    elif k == "wback":
        self._ws_act("back")
    elif k == "wsort":
        self._ws_act("x")
    elif k == "wsearch":
        self._ws_act("alt")
    self.update()


@_bpm("_x_hint")
def _bpx_hint(self):
    if self._tab == 2:
        if self._fr["chat"]:
            return "Up / Down  Scroll      Left / Right  Choose      A  Select      Y  Write message      B  Back"
        return "Up / Down  Browse      A  Chat / Accept      Y  Quick message      LB / RB  Switch tab      B  Library"
    if self._tab == 3:
        return "Up / Down  Select      Left / Right  Button      A  Press      Y  Clear finished      LB / RB  Switch tab      B  Library"
    if self._wk["mode"] == "games":
        return "Arrows  Browse      A  Open Workshop      LB / RB  Switch tab      B  Library"
    return "Arrows  Browse      A  Install      Y  Search      X  Sort      LB / RB  Switch tab      B  Games"


# ── on-screen keyboard ──
@_bpm("_kb_open")
def _bpx_kb_open(self, title, text, on_change, on_submit, maxlen=120):
    self._kb = {"k": _BPKeys(text, maxlen), "title": title, "on_change": on_change, "on_submit": on_submit, "rects": []}
    self.update()


@_bpm("_kb_open_store")
def _bpx_kb_open_store(self):
    def chg(t):
        self._search, self._chip = t, 0
        self._stimer.start()
        self.update()

    def sub(t):
        self._search = t
        self._store_reset()
    self._kb_open("Search the Store", self._search, chg, sub, 80)


@_bpm("_kb_close")
def _bpx_kb_close(self):
    self._kb = None
    self.update()


@_bpm("_kb_changed")
def _bpx_kb_changed(self):
    cb = self._kb["on_change"]
    if cb:
        cb(self._kb["k"].text)


@_bpm("_kb_submit")
def _bpx_kb_submit(self):
    kb, self._kb = self._kb, None
    if kb["on_submit"]:
        kb["on_submit"](kb["k"].text)
    self.update()


@_bpm("_kb_press")
def _bpx_kb_press(self, r=None, c=None):
    res = self._kb["k"].press(r, c)
    if res == "done":
        self._kb_submit()
        return
    if res == "changed":
        self._kb_changed()
    self.update()


@_bpm("_kb_act")
def _bpx_kb_act(self, name):
    K = self._kb["k"]
    if name == "left":
        K.move(-1, 0)
    elif name == "right":
        K.move(1, 0)
    elif name == "up":
        K.move(0, -1)
    elif name == "down":
        K.move(0, 1)
    elif name == "accept":
        self._kb_press()
        return
    elif name == "back":
        self._kb_close()
        return
    elif name == "x":                                     # X = backspace
        if K.backspace():
            self._kb_changed()
    elif name == "alt":                                   # Y = space
        if K.insert(" "):
            self._kb_changed()
    elif name == "prev":                                  # LB = shift
        K.toggle_shift()
    elif name == "next":                                  # RB = numbers / symbols
        K.toggle_sym()
    elif name == "submit":                                # Start = done
        self._kb_submit()
        return
    self.update()


@_bpm("_kb_key")
def _bpx_kb_key(self, e):
    k, K, kb = e.key(), Qt.Key, self._kb["k"]
    if k in (K.Key_Return, K.Key_Enter):
        self._kb_submit()
        return
    if k == K.Key_Escape:
        self._kb_close()
        return
    if k == K.Key_Backspace:
        if kb.backspace():
            self._kb_changed()
    elif k == K.Key_Left:
        kb.move(-1, 0)
    elif k == K.Key_Right:
        kb.move(1, 0)
    elif k == K.Key_Up:
        kb.move(0, -1)
    elif k == K.Key_Down:
        kb.move(0, 1)
    else:
        t = e.text()
        if t and t.isprintable() and kb.insert(t):
            self._kb_changed()
    self.update()


# ── shared painting helpers ──
@_bpm("_x_text")
def _bpx_text(self, p, r, text, size, color, bold=False, align=None, elide=True):
    f = self._font(self.height() * size, bold)
    p.setFont(f)
    p.setPen(color if isinstance(color, QColor) else QColor(color))
    if elide:
        text = QFontMetrics(f).elidedText(text, Qt.TextElideMode.ElideRight, int(r.width()))
    p.drawText(r, align if align is not None else int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter), text)


@_bpm("_x_msg")
def _bpx_msg(self, p, r, text):
    p.setFont(self._font(self.height() * 0.03))
    p.setPen(QColor(200, 200, 220))
    p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), text)


@_bpm("_x_pill")
def _bpx_pill(self, p, r, text, acc, sel=False, primary=False, size=0.0225):
    h = self.height()
    rad = r.height() / 2
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(acc if primary else QColor(255, 255, 255, 34))
    p.drawRoundedRect(r, rad, rad)
    if sel:
        g = h * 0.005
        p.setPen(QPen(QColor(255, 255, 255, 235), max(2.0, h * 0.004)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(r.adjusted(-g, -g, g, g), rad + g, rad + g)
    p.setFont(self._font(h * size, True))
    p.setPen(QColor(_on_accent()) if primary else QColor(225, 225, 240))
    p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), text)


@_bpm("_x_ring")
def _bpx_ring(self, p, r, rad):
    h = self.height()
    g = h * 0.005
    p.setPen(QPen(QApplication.palette().color(QPalette.ColorRole.Highlight), max(2.0, h * 0.005)))
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.drawRoundedRect(r.adjusted(-g, -g, g, g), rad + g, rad + g)


@_bpm("_x_avatar")
def _bpx_avatar(self, p, r, row):
    uid, d = row["uid"], row["d"]
    cache = self._fr["av"]
    if uid not in cache:
        pm = None
        try:
            path = _friend_avatar_file(uid, d.get("photo"))
            if path:
                q = QPixmap(path)
                if not q.isNull():
                    pm = q.scaled(128, 128, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
        except Exception:
            pm = None
        cache[uid] = pm
    pm = cache[uid]
    p.save()
    if pm is not None:
        clip = QPainterPath()
        clip.addEllipse(r)
        p.setClipPath(clip, Qt.ClipOperation.IntersectClip)    # keep the list's scroll clip so avatars can't draw over the header
        p.drawPixmap(r, pm, QRectF(pm.rect()))
    else:
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor.fromHsv(sum(map(ord, str(uid))) % 360, 150, 190))
        p.drawEllipse(r)
        p.setFont(self._font(r.height() * 0.5, True))
        p.setPen(QColor(255, 255, 255))
        p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), (row["name"][:1] or "?").upper())
    p.restore()


@_bpm("_paint_extra")
def _bpx_paint_extra(self, p, w, h, m, acc, k):
    self._xhits = []
    p.setOpacity(k)
    if self._tab == 2:
        self._paint_friends(p, w, h, m, acc)
    elif self._tab == 3:
        self._paint_downloads(p, w, h, m, acc)
    else:
        self._paint_workshop(p, w, h, m, acc)
    p.setOpacity(1.0)


@_bpm("_paint_kb")
def _bpx_paint_kb(self, p, w, h, acc):
    kb = self._kb
    K = kb["k"]
    al_c = int(Qt.AlignmentFlag.AlignCenter)
    p.setOpacity(1.0)
    px, pw, py, ph = w * 0.1, w * 0.8, h * 0.44, h * 0.48
    p.fillRect(QRectF(0, 0, w, py), QColor(0, 0, 0, 130))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(14, 14, 26, 246))
    p.drawRoundedRect(QRectF(px, py, pw, ph), h * 0.025, h * 0.025)
    pad = h * 0.022
    self._x_text(p, QRectF(px + pad, py + h * 0.012, pw - 2 * pad, h * 0.04), kb["title"], 0.022, QColor(170, 170, 200))
    fld = QRectF(px + pad, py + h * 0.056, pw - 2 * pad, h * 0.07)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(255, 255, 255, 28))
    p.drawRoundedRect(fld, h * 0.015, h * 0.015)
    f = self._font(h * 0.034)
    p.setFont(f)
    fm = QFontMetrics(f)
    shown = fm.elidedText(K.text, Qt.TextElideMode.ElideLeft, int(fld.width() - 2 * pad))
    p.setPen(QColor(245, 245, 252))
    p.drawText(QRectF(fld.left() + pad, fld.top(), fld.width() - 2 * pad, fld.height()),
               int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter), shown)
    cx = fld.left() + pad + fm.horizontalAdvance(shown) + 2
    p.setPen(QPen(acc, max(2.0, h * 0.003)))
    p.drawLine(QPointF(cx, fld.top() + fld.height() * 0.2), QPointF(cx, fld.bottom() - fld.height() * 0.2))
    rows = K.rows()
    ky0, kbot, gap = fld.bottom() + h * 0.018, py + ph - h * 0.02, h * 0.008
    kh = (kbot - ky0 - gap * (len(rows) - 1)) / len(rows)
    u = (pw - 2 * pad) / 10.0
    kb["rects"] = []
    for ri, row in enumerate(rows):
        x, y = px + pad, ky0 + ri * (kh + gap)
        for ci, (label, act, wgt) in enumerate(row):
            r = QRectF(x, y, wgt * u - gap, kh)
            x += wgt * u
            sel = (ri == K.r and ci == K.c)
            kb["rects"].append((r, ri, ci))
            p.setPen(Qt.PenStyle.NoPen)
            if sel:
                p.setBrush(acc)
            elif act == "@done":
                p.setBrush(QColor(acc.red(), acc.green(), acc.blue(), 120))
            elif act == "@shift" and K.shift:
                p.setBrush(QColor(255, 255, 255, 100))
            else:
                p.setBrush(QColor(255, 255, 255, 30))
            p.drawRoundedRect(r, kh * 0.2, kh * 0.2)
            p.setFont(self._font(h * (0.03 if len(label) == 1 else 0.021), True))
            p.setPen(QColor(_on_accent()) if sel else QColor(235, 235, 245))
            p.drawText(r, al_c, label)


# ── Friends tab ──
@_bpm("_fr_enter")
def _bpx_fr_enter(self):
    fp = getattr(self._app, "friends_page", None)
    if fp is None:
        return
    self._fr["chat"] = None
    signed = _bpx_signed(fp)
    self._fr["loading"] = bool(signed and not fp.friends)
    self._fr_build()
    self._fr_ensure()
    if signed:
        fp.refresh()


@_bpm("_fr_build")
def _bpx_fr_build(self):
    fp = getattr(self._app, "friends_page", None)
    fr = self._fr
    keep = None
    if fr["rows"] and 0 <= fr["sel"] < len(fr["rows"]):
        keep = (fr["rows"][fr["sel"]]["kind"], fr["rows"][fr["sel"]]["uid"])
    rows = []
    if fp is not None:
        for u, d in (fp.requests or {}).items():
            if isinstance(d, dict):
                rows.append({"kind": "req", "uid": u, "name": d.get("username") or "Unknown", "d": d})
        fl = [(u, d) for u, d in (fp.friends or {}).items() if isinstance(d, dict)]
        fl.sort(key=lambda kv: (_friend_status(kv[1])[0] == "Offline", (kv[1].get("username") or "").lower()))
        for u, d in fl:
            rows.append({"kind": "friend", "uid": u, "name": d.get("username") or "Unknown", "d": d})
    fr["rows"] = rows
    fr["sel"] = next((i for i, r in enumerate(rows) if keep and (r["kind"], r["uid"]) == keep),
                     min(fr["sel"], max(0, len(rows) - 1)))
    fr["btn"] = 0


@_bpm("_fr_changed")
def _bpx_fr_changed(self):
    try:
        self._fr["loading"] = False
        self._fr_build()
        if self._tab == 2:
            self.update()
    except RuntimeError:    # expected: the widget or object may already be deleted
        pass


@_bpm("_fr_ensure")
def _bpx_fr_ensure(self):
    h = self.height()
    pitch, i = h * 0.102, self._fr["sel"]
    self._x_ensure(i * pitch, (i + 1) * pitch, h * 0.86 - h * 0.19)


@_bpm("_fr_act")
def _bpx_fr_act(self, name):
    fr = self._fr
    if fr["chat"]:
        if name == "back":
            fr["chat"] = None
        elif name in ("left", "right"):
            fr["cbtn"] = 1 - fr["cbtn"]
        elif name == "up":
            fr["moff"] = min(max(0, len(fr["msgs"]) - 1), fr["moff"] + 1)
        elif name == "down":
            fr["moff"] = max(0, fr["moff"] - 1)
        elif name == "alt" or (name == "accept" and fr["cbtn"] == 0):
            self._fr_compose(fr["chat"])
        elif name == "accept":
            fr["chat"] = None
        return
    rows = fr["rows"]
    if name == "back":
        self._switch_tab(0)
    elif name == "up":
        if fr["sel"] <= 0:
            _bpx_top(self)
        else:
            fr["sel"] -= 1
            fr["btn"] = 0
            self._fr_ensure()
    elif name == "down":
        if fr["sel"] < len(rows) - 1:
            fr["sel"] += 1
            fr["btn"] = 0
            self._fr_ensure()
    elif name in ("left", "right") and rows and rows[fr["sel"]]["kind"] == "req":
        fr["btn"] = 0 if name == "left" else 1
    elif name == "accept" and rows:
        r = rows[fr["sel"]]
        if r["kind"] == "req":
            self._fr_answer(r["uid"], fr["btn"] == 0)
        else:
            fr["chat"], fr["cbtn"] = r["uid"], 0
            self._fr_load_chat(r["uid"])
    elif name == "alt" and rows and rows[fr["sel"]]["kind"] == "friend":
        self._fr_compose(rows[fr["sel"]]["uid"])


@_bpm("_fr_answer")
def _bpx_fr_answer(self, uid, accept):
    fp = getattr(self._app, "friends_page", None)
    if fp is None:
        return
    fn = cloud_accept_friend if accept else cloud_decline_friend

    def done(res, err):
        try:
            self._say(str(err) if err else ("Friend added" if accept else "Request declined"), 2500)
            fp.refresh()
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    fp._run(lambda: fn(uid), done)


@_bpm("_fr_compose")
def _bpx_fr_compose(self, uid):
    name = next((r["name"] for r in self._fr["rows"] if r["uid"] == uid), "friend")
    self._kb_open("Message to %s" % name, "", None, lambda t, u=uid: self._fr_send(u, t), 500)


@_bpm("_fr_send")
def _bpx_fr_send(self, uid, text):
    text = (text or "").strip()
    fp = getattr(self._app, "friends_page", None)
    if not text or fp is None:
        return
    fr = self._fr
    fr["sending"] = True
    self.update()

    def done(res, err):
        try:
            fr["sending"] = False
            if err:
                self._say("Couldn't send: %s" % err, 4000)
            else:
                self._say("Message sent", 1800)
                fr["moff"] = 0
                if fr["chat"] == uid:
                    self._fr_load_chat(uid, quiet=True)
            self.update()
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    fp._run(lambda: cloud_send_message(uid, text), done)


@_bpm("_fr_load_chat")
def _bpx_fr_load_chat(self, uid, quiet=False):
    fp = getattr(self._app, "friends_page", None)
    fr = self._fr
    if fp is None:
        return
    if not quiet:
        fr["msgs"], fr["moff"], fr["me"], fr["loading"] = [], 0, "", True

    def done(res, err, uid=uid):
        try:
            if fr["chat"] != uid:
                return
            fr["loading"] = False
            if not err and res:
                fr["me"], fr["msgs"] = res[0], res[1]
            if self._tab == 2:
                self.update()
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    fp._run(lambda: cloud_get_messages(uid), done, key="bp-chat")


@_bpm("_paint_friends")
def _bpx_paint_friends(self, p, w, h, m, acc):
    fr = self._fr
    fp = getattr(self._app, "friends_page", None)
    area = QRectF(0, h * 0.17, w, h * 0.69)
    if fp is None or not _bpx_signed(fp):
        self._x_msg(p, area, "Sign in from the main launcher to use Friends")
        return
    if fr["chat"]:
        self._paint_chat(p, w, h, acc)
        return
    rows = fr["rows"]
    online = sum(1 for r in rows if r["kind"] == "friend" and _friend_status(r["d"])[0] != "Offline")
    cx, cw = w * 0.18, w * 0.64
    self._x_text(p, QRectF(cx, h * 0.125, cw, h * 0.05), "Friends   %d online" % online, 0.028, QColor(235, 235, 245), True)
    top, bot, rh, pitch = h * 0.19, h * 0.86, h * 0.09, h * 0.102
    if not rows:
        if fr["loading"]:
            self._paint_loading(p, w, h, QRectF(0, top, w, bot - top), "Loading friends...")
        else:
            self._x_msg(p, area, "No friends yet. Add friends from the main launcher.")
        return
    focus = self._zone == "content"
    p.save()
    p.setClipRect(QRectF(0, top - h * 0.01, w, bot - top + h * 0.02))
    for i, r in enumerate(rows):
        y = top + i * pitch - self._xscroll
        if y + rh < top - h * 0.01 or y > bot:
            continue
        rect = QRectF(cx, y, cw, rh)
        sel = focus and i == fr["sel"]
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 48 if sel else 22))
        p.drawRoundedRect(rect, rh * 0.2, rh * 0.2)
        if sel:
            self._x_ring(p, rect, rh * 0.2)
        self._xhits.append((rect.intersected(QRectF(0, top, w, bot - top)), ("row", i)))
        ad = rh * 0.7
        ar = QRectF(cx + rh * 0.15, y + (rh - ad) / 2, ad, ad)
        self._x_avatar(p, ar, r)
        tx = ar.right() + rh * 0.22
        if r["kind"] == "friend":
            st, col = _friend_status(r["d"])
            self._x_text(p, QRectF(tx, y + rh * 0.08, cw - tx + cx - rh * 0.3, rh * 0.45), r["name"], 0.028, QColor(245, 245, 252), True)
            self._x_text(p, QRectF(tx, y + rh * 0.5, cw - tx + cx - rh * 0.3, rh * 0.4), st, 0.021, QColor(col))
        else:
            bw, bh = h * 0.13, rh * 0.55
            bx = rect.right() - rh * 0.2 - 2 * bw - h * 0.012
            self._x_text(p, QRectF(tx, y + rh * 0.08, bx - tx - rh * 0.2, rh * 0.45), r["name"], 0.028, QColor(245, 245, 252), True)
            self._x_text(p, QRectF(tx, y + rh * 0.5, bx - tx - rh * 0.2, rh * 0.4), "Wants to be your friend", 0.021, QColor(170, 170, 200))
            for j, t in enumerate(("Accept", "Decline")):
                br = QRectF(bx + j * (bw + h * 0.012), y + (rh - bh) / 2, bw, bh)
                self._x_pill(p, br, t, acc, sel=(sel and fr["btn"] == j), primary=(j == 0), size=0.02)
                self._xhits.append((br.intersected(QRectF(0, top, w, bot - top)), ("btn", i, j)))
    p.restore()


@_bpm("_paint_chat")
def _bpx_paint_chat(self, p, w, h, acc):
    fr = self._fr
    row = next((r for r in fr["rows"] if r["uid"] == fr["chat"]), None)
    cx, cw = w * 0.2, w * 0.6
    if row is not None:
        ad = h * 0.075
        self._x_avatar(p, QRectF(cx, h * 0.14, ad, ad), row)
        st, col = _friend_status(row["d"])
        self._x_text(p, QRectF(cx + ad * 1.25, h * 0.138, cw - ad * 1.25, h * 0.045), row["name"], 0.03, QColor(245, 245, 252), True)
        self._x_text(p, QRectF(cx + ad * 1.25, h * 0.18, cw - ad * 1.25, h * 0.035), st, 0.021, QColor(col))
    top = h * 0.24
    bot = h * 0.42 if self._kb is not None else h * 0.78
    p.save()
    p.setClipRect(QRectF(cx - h * 0.01, top, cw + h * 0.02, bot - top))
    msgs = fr["msgs"]
    if not msgs:
        self._x_msg(p, QRectF(cx, top, cw, bot - top), "Loading messages..." if fr["loading"] else "No messages yet. Press A to say hi!")
    f = self._font(h * 0.024)
    p.setFont(f)
    fm = QFontMetrics(f)
    maxw, padx, pady = cw * 0.72, h * 0.018, h * 0.012
    y, idx = bot, len(msgs) - 1 - fr["moff"]
    while idx >= 0 and y > top:
        mg = msgs[idx]
        idx -= 1
        text = str(mg.get("text") or "") or ("[attachment]" if mg.get("att") else "")
        if not text.strip():
            continue
        br = fm.boundingRect(QRect(0, 0, int(maxw - 2 * padx), 10000), int(Qt.TextFlag.TextWordWrap), text)
        bw, bh = min(maxw, br.width() + 2 * padx), br.height() + 2 * pady
        y -= bh
        mine = mg.get("from") == fr["me"]
        bx = cx + cw - bw if mine else cx
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(acc if mine else QColor(255, 255, 255, 36))
        p.drawRoundedRect(QRectF(bx, y, bw, bh), h * 0.02, h * 0.02)
        p.setPen(QColor(_on_accent()) if mine else QColor(235, 235, 245))
        p.drawText(QRectF(bx + padx, y + pady, bw - 2 * padx, br.height()),
                   int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop) | int(Qt.TextFlag.TextWordWrap), text)
        y -= h * 0.01
    p.restore()
    bh, bw = h * 0.065, h * 0.22
    for j, t in enumerate(("Sending..." if fr["sending"] else "Message", "Back")):
        r = QRectF(cx + j * (bw + h * 0.014), h * 0.81, bw, bh)
        self._x_pill(p, r, t, acc, sel=(self._zone == "content" and fr["cbtn"] == j), primary=(j == 0))
        self._xhits.append((r, ("cbtn", j)))


# ── Downloads tab ──
@_bpm("_dl_infos")
def _bpx_dl_infos(self):
    out = []
    dp = getattr(self._app, "downloads_page", None)
    if dp is not None:
        try:
            lay = dp.container_layout
            for i in range(lay.count()):
                wdg = lay.itemAt(i).widget()
                if not isinstance(wdg, DownloadCard):
                    continue
                try:
                    pb = wdg.progress_bar
                    mx = pb.maximum()
                    cpath = getattr(wdg, "cover_path", "") or ""
                    cpm = None
                    if not (cpath and os.path.exists(cpath)):
                        try:
                            cpm = wdg.cover.pixmap()
                            cpm = cpm if cpm is not None and not cpm.isNull() else None
                        except Exception:
                            cpm = None
                    out.append({"cover": cpath, "cover_pm": cpm,
                                "title": wdg.title, "status": wdg.status_label.text(),
                                "pct": None if mx == 0 else int(pb.value() * 100 / max(1, mx)),
                                "info": wdg.info_label.text(), "state": getattr(wdg, "state", "active"),
                                "btns": [(b.text(), b.click) for b in (wdg.pause_btn, wdg.action_btn, wdg.clear_btn)
                                         if not b.isHidden()]})
                except RuntimeError:    # expected: the widget or object may already be deleted
                    pass
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    wp = getattr(self._app, "workshop_page", None)
    if wp is not None:
        names = {"queued": ("Queued", "Remove"), "downloading": ("Downloading", "Cancel"), "failed": ("Failed", "Retry"),
                 "cancelled": ("Cancelled", "Retry"), "done": ("Installed", None)}
        for e in list(wp.queue):
            st = e.get("status", "")
            stxt, btn = names.get(st, (str(st).title(), None))
            pct = e.get("pct")
            pct = pct if isinstance(pct, (int, float)) else None
            try:
                hdr = _BPX_HDR % int(e.get("appid"))
            except (TypeError, ValueError):
                hdr = ""
            out.append({"hdr": hdr,
                        "title": "%s  (Workshop - %s)" % (e.get("title", "?"), e.get("game", "")),
                        "status": stxt + (" %d%%" % pct if st == "downloading" and pct is not None else ""),
                        "pct": 100 if st == "done" else (0 if st == "queued" else pct),
                        "info": e.get("msg") or e.get("line") or "",
                        "state": "active" if st in ("queued", "downloading") else ("done" if st == "done" else "failed"),
                        "btns": [(btn, lambda e=e: wp._queue_action(e))] if btn else []})
    return out


@_bpm("_dl_ensure")
def _bpx_dl_ensure(self):
    h = self.height()
    pitch = h * 0.135
    n = max(1, len(self._dl_infos()))
    i = max(0, min(n - 1, self._dl["sel"]))
    self._x_ensure(i * pitch, (i + 1) * pitch, h * 0.86 - h * 0.19)


@_bpm("_dl_act")
def _bpx_dl_act(self, name):
    dl = self._dl
    infos = self._dl_infos()
    n = len(infos)
    dl["sel"] = max(0, min(max(0, n - 1), dl["sel"]))
    if name == "back":
        self._switch_tab(0)
    elif name == "up":
        if dl["sel"] <= 0:
            _bpx_top(self)
        else:
            dl["sel"] -= 1
            dl["btn"] = 0
            self._dl_ensure()
    elif name == "down":
        if dl["sel"] < n - 1:
            dl["sel"] += 1
            dl["btn"] = 0
            self._dl_ensure()
    elif name in ("left", "right") and n:
        dl["btn"] = max(0, min(len(infos[dl["sel"]]["btns"]) - 1, dl["btn"] + (1 if name == "right" else -1)))
    elif name == "accept" and n:
        btns = infos[dl["sel"]]["btns"]
        if btns:
            btns[max(0, min(len(btns) - 1, dl["btn"]))][1]()
    elif name == "alt":
        for obj in (getattr(self._app, "downloads_page", None), getattr(self._app, "workshop_page", None)):
            try:
                if obj is not None:
                    (obj.clear_finished)()
            except Exception:
                _log_exc("_bpx_dl_act")
        self._say("Cleared finished downloads", 1800)


@_bpm("_paint_downloads")
def _bpx_paint_downloads(self, p, w, h, m, acc):
    dl = self._dl
    infos = self._dl_infos()
    n = len(infos)
    dl["sel"] = max(0, min(max(0, n - 1), dl["sel"]))
    cx, cw = w * 0.14, w * 0.72
    nact = sum(1 for i in infos if i["state"] == "active")
    self._x_text(p, QRectF(cx, h * 0.125, cw, h * 0.05), "Downloads" + ("   %d active" % nact if nact else ""),
                 0.028, QColor(235, 235, 245), True)
    top, bot, rh, pitch = h * 0.19, h * 0.86, h * 0.12, h * 0.135
    if not n:
        self._x_msg(p, QRectF(0, top, w, bot - top), "No active or recent downloads")
        return
    focus = self._zone == "content"
    p.save()
    p.setClipRect(QRectF(0, top - h * 0.01, w, bot - top + h * 0.02))
    pad = rh * 0.16
    for i, it in enumerate(infos):
        y = top + i * pitch - self._xscroll
        if y + rh < top - h * 0.01 or y > bot:
            continue
        rect = QRectF(cx, y, cw, rh)
        sel = focus and i == dl["sel"]
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 48 if sel else 22))
        p.drawRoundedRect(rect, rh * 0.14, rh * 0.14)
        if sel:
            self._x_ring(p, rect, rh * 0.14)
        self._xhits.append((rect.intersected(QRectF(0, top, w, bot - top)), ("drow", i)))
        # game cover on the left
        cvh = rh - 2 * pad
        cvr = QRectF(cx + pad, y + pad, cvh * 0.68, cvh)
        if it.get("hdr"):
            cpm = self._ws_pix(it["hdr"])
        elif it.get("cover"):
            cpm = self._dl_cover(it["cover"])
        else:
            cpm = it.get("cover_pm")
        _bpe_draw_cover(p, cvr, cpm, rh * 0.09)
        lx = cvr.right() + pad
        bw, bh, gap = h * 0.125, rh * 0.38, h * 0.01
        btns = it["btns"]
        bx = rect.right() - pad - len(btns) * (bw + gap) + gap
        for j, (label, _cb) in enumerate(btns):
            br = QRectF(bx + j * (bw + gap), y + (rh - bh) / 2, bw, bh)
            self._x_pill(p, br, label, acc, sel=(sel and dl["btn"] == j), size=0.019)
            self._xhits.append((br.intersected(QRectF(0, top, w, bot - top)), ("dbtn", i, j)))
        tw = (bx if btns else rect.right() - pad) - lx - pad
        col = QColor(GREEN) if it["state"] == "done" else QColor(RED) if it["state"] == "failed" else QColor(200, 200, 220)
        sw = min(tw * 0.4, h * 0.3)
        self._x_text(p, QRectF(lx, y + rh * 0.08, tw - sw - pad, rh * 0.3), it["title"], 0.025, QColor(245, 245, 252), True)
        self._x_text(p, QRectF(lx + tw - sw, y + rh * 0.08, sw, rh * 0.3), it["status"], 0.02, col, False,
                     int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter))
        track = QRectF(lx, y + rh * 0.47, tw, rh * 0.11)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 36))
        p.drawRoundedRect(track, track.height() / 2, track.height() / 2)
        if it["pct"] is None:
            p.setBrush(QColor(acc.red(), acc.green(), acc.blue(), 90))
            p.drawRoundedRect(track, track.height() / 2, track.height() / 2)
        elif it["pct"] > 0:
            fw = max(track.height(), track.width() * min(100, it["pct"]) / 100.0)
            p.setBrush(QColor(GREEN) if it["state"] == "done" else acc)
            p.drawRoundedRect(QRectF(track.left(), track.top(), fw, track.height()), track.height() / 2, track.height() / 2)
        self._x_text(p, QRectF(lx, y + rh * 0.64, tw, rh * 0.27), it["info"], 0.0185, QColor(150, 150, 175))
    p.restore()


# ── Workshop tab ──
_BPX_HDR = "https://cdn.cloudflare.steamstatic.com/steam/apps/%d/header.jpg"


@_bpm("_x_grid")
def _bpx_grid(self, aspect, th_frac=0.2):
    w, h = self.width(), self.height()
    m, gap = w * 0.05, h * 0.022
    th = h * th_frac
    tw = th * aspect
    cols = max(1, int((w - 2 * m + gap) // (tw + gap)))
    x0 = (w - (cols * tw + (cols - 1) * gap)) / 2
    return gap, tw, th, cols, x0, h * 0.2, h * 0.86


@_bpm("_x_grid_paint")
def _bpx_grid_paint(self, p, w, h, acc, n, sel, aspect, draw, th_frac=0.2):
    gap, tw, th, cols, x0, top, bot = self._x_grid(aspect, th_frac)
    pitch, pad = th + gap, h * 0.012
    clip = QRectF(0, top, w, bot - top)
    p.save()
    p.setClipRect(clip)
    first = max(0, int(self._xscroll // pitch) - 1) * cols
    last = min(n, (int((self._xscroll + bot - top) // pitch) + 2) * cols)
    focus = self._zone == "content"
    for i in range(first, last):
        row, col = divmod(i, cols)
        r = QRectF(x0 + col * (tw + gap), top + pad + row * pitch - self._xscroll, tw, th)
        if r.bottom() < top or r.top() > bot:
            continue
        vis = r.intersected(clip)
        if not vis.isEmpty():
            self._xhits.append((vis, ("tile", i)))
        s = focus and i == sel
        if s:
            self._x_ring(p, r, tw * 0.05)
        draw(r, i, s)
    p.restore()


@_bpm("_x_tile")
def _bpx_tile(self, p, r, pm, title, sub, acc, badge=None):
    h = self.height()
    rad = r.width() * 0.05
    path = QPainterPath()
    path.addRoundedRect(r, rad, rad)
    p.save()
    p.setClipPath(path, Qt.ClipOperation.IntersectClip)
    if pm is not None and not pm.isNull():
        sr = pm.rect()
        sc = max(r.width() / sr.width(), r.height() / sr.height())
        vw, vh = r.width() / sc, r.height() / sc
        p.drawPixmap(r, pm, QRectF((sr.width() - vw) / 2, (sr.height() - vh) / 2, vw, vh))
    else:
        p.fillRect(r, QColor(255, 255, 255, 20))
    g = QLinearGradient(0, r.top() + r.height() * 0.45, 0, r.bottom())
    g.setColorAt(0, QColor(0, 0, 0, 0))
    g.setColorAt(1, QColor(0, 0, 0, 225))
    p.fillRect(r, QBrush(g))
    p.restore()
    pad = h * 0.012
    self._x_text(p, QRectF(r.left() + pad, r.bottom() - h * 0.072, r.width() - 2 * pad, h * 0.036), title, 0.0215, QColor(245, 245, 252), True)
    if sub:
        self._x_text(p, QRectF(r.left() + pad, r.bottom() - h * 0.038, r.width() - 2 * pad, h * 0.03), sub, 0.0165, QColor(185, 185, 205))
    if badge:
        bf = self._font(h * 0.0155, True)
        p.setFont(bf)
        b = QRectF(r.left() + h * 0.008, r.top() + h * 0.008, QFontMetrics(bf).horizontalAdvance(badge) + h * 0.026, h * 0.028)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(acc)
        p.drawRoundedRect(b, h * 0.014, h * 0.014)
        p.setPen(QColor(_on_accent()))
        p.drawText(b, int(Qt.AlignmentFlag.AlignCenter), badge)


@_bpm("_ws_pix")
def _bpx_ws_pix(self, url):
    wk = self._wk
    pm = wk["pix"].get(url)
    if pm is None and url and url not in wk["asked"]:
        wk["asked"].add(url)
        wp = getattr(self._app, "workshop_page", None)
        if wp is not None:
            wp.img.request(url, lambda pm_, u=url: self._ws_img_ready(u, pm_))
    return pm


@_bpm("_ws_img_ready")
def _bpx_ws_img_ready(self, url, pm):
    self._wk["pix"][url] = pm
    QTimer.singleShot(0, self.update)


@_bpm("_ws_enter")
def _bpx_ws_enter(self):
    wk = self._wk
    if wk["mode"] == "games":
        try:
            wk["all"] = list(_ws_installed_games())
            wk["err"] = ""
        except Exception as ex:
            wk["all"], wk["err"] = [], str(ex)
        self._ws_count_games()
        self._ws_filter_games()
    self._ws_ensure()
    if wk["mode"] == "items" and not wk["items"] and not wk["loading"]:
        self._ws_fetch(1)


@_bpm("_ws_count_games")
def _bpx_ws_count_games(self):
    """Look up how many Workshop items each installed game has (shared cache with the main Workshop tab)."""
    wk = self._wk
    wk.setdefault("failed", set())
    wk.setdefault("counting", set())
    for g in wk.get("all", []):
        aid = g["appid"]
        if aid in _WS_MOD_COUNTS or aid in wk["counting"] or aid in wk["failed"]:
            continue
        wk["counting"].add(aid)
        w_ = WorkshopCountWorker(aid, self)
        w_.done.connect(self._ws_counted)
        wk["workers"].append(w_)
        w_.finished.connect(lambda x=w_: wk["workers"].remove(x) if x in wk["workers"] else None)
        w_.start()


@_bpm("_ws_counted")
def _bpx_ws_counted(self, appid, count):
    wk = self._wk
    wk["counting"].discard(appid)
    if count >= 0:
        _WS_MOD_COUNTS[appid] = count
    else:
        wk["failed"].add(appid)           # lookup failed: keep the game listed rather than hide it
    if wk["mode"] == "games":
        self._ws_filter_games()
    self.update()


@_bpm("_ws_filter_games")
def _bpx_ws_filter_games(self):
    wk = self._wk
    allg = wk.get("all", [])
    cur = wk["games"][wk["gsel"]]["appid"] if wk["games"] and 0 <= wk["gsel"] < len(wk["games"]) else None
    keep = []
    for g in allg:
        cnt = _WS_MOD_COUNTS.get(g["appid"])
        if (cnt is not None and cnt > 0) or (cnt is None and g["appid"] in wk.get("failed", ())):
            keep.append(g)
    wk["games"] = keep
    wk["gsel"] = next((i for i, g in enumerate(keep) if g["appid"] == cur), 0)
    if keep or not allg:
        wk["err"] = ""
    elif any(g["appid"] in wk.get("counting", ()) for g in allg):
        wk["err"] = "Checking which games have Workshop mods..."
    else:
        wk["err"] = "None of your installed games have Workshop mods."


@_bpm("_ws_ensure")
def _bpx_ws_ensure(self):
    wk = self._wk
    games = wk["mode"] == "games"
    gap, tw, th, cols, x0, top, bot = self._x_grid(2.14 if games else 1.6, 0.2)
    row = (wk["gsel"] if games else wk["sel"]) // cols
    pitch = th + gap
    self._x_ensure(row * pitch, row * pitch + pitch + self.height() * 0.024, bot - top)


@_bpm("_ws_open_game")
def _bpx_ws_open_game(self, g):
    wk = self._wk
    wk.update(mode="items", appid=int(g["appid"]), title=g["title"], query="", sort=0)
    self._ws_reset_items()
    self._ws_fetch(1)


def _bpx_ws_reset_items(self):
    wk = self._wk
    wk.update(items=[], seen=set(), sel=0, more=False, err="")
    wk["token"] += 1
    self._x_reset_scroll()


_BigPicture._ws_reset_items = _bpx_ws_reset_items


@_bpm("_ws_fetch")
def _bpx_ws_fetch(self, page):
    wk = self._wk
    wk["token"] += 1
    wk["page"], wk["loading"], wk["err"] = page, True, ""
    wkr = WorkshopFetchWorker(wk["token"], wk["appid"], wk["query"], WS_SORTS[wk["sort"]][1], page, self)
    wkr.done.connect(self._ws_fetched)
    wk["workers"].append(wkr)
    wkr.finished.connect(lambda w_=wkr: wk["workers"].remove(w_) if w_ in wk["workers"] else None)
    wkr.start()
    self.update()


@_bpm("_ws_fetched")
def _bpx_ws_fetched(self, token, items, err):
    wk = self._wk
    if token != wk["token"]:
        return
    wk["loading"] = False
    if err:
        wk["err"] = err
    else:
        new = [it for it in items if it["id"] not in wk["seen"]]
        for it in new:
            wk["seen"].add(it["id"])
            wk["items"].append(it)
        wk["more"] = len(items) >= 9 and bool(new)
    self.update()


@_bpm("_ws_search")
def _bpx_ws_search(self, text):
    self._wk["query"] = (text or "").strip()
    self._ws_reset_items()
    self._ws_fetch(1)


@_bpm("_ws_install")
def _bpx_ws_install(self, it):
    wk = self._wk
    wp = getattr(self._app, "workshop_page", None)
    if wp is None:
        return
    try:
        if wp._ws_have(wk["appid"], it["id"]):
            self._say("Already installed", 2000)
        elif wp.enqueue(it, wk["appid"], wk["title"]):
            self._say("Queued: %s  (see the Downloads tab)" % it["title"], 3000)
        else:
            self._say("Already in the queue", 2000)
    except Exception as ex:
        self._say("Couldn't queue it: %s" % ex, 4000)


def _bpx_grid_nav(sel, n, cols, name):
    """New selection index for a grid move, -1 when 'up' leaves the top row."""
    if name == "left":
        return max(0, sel - 1)
    if name == "right":
        return min(n - 1, sel + 1)
    if name == "down":
        if sel + cols < n:
            return sel + cols
        return n - 1 if sel // cols < (n - 1) // cols else sel
    if name == "up":
        return sel - cols if sel >= cols else -1
    return sel


@_bpm("_ws_act")
def _bpx_ws_act(self, name):
    wk = self._wk
    games = wk["mode"] == "games"
    lst, key = (wk["games"], "gsel") if games else (wk["items"], "sel")
    n = len(lst)
    cols = self._x_grid(2.14 if games else 1.6)[3]
    if name == "back":
        if games:
            self._switch_tab(0)
        else:
            wk["mode"] = "games"
            self._x_reset_scroll()
            self._ws_ensure()
        return
    if name in ("left", "right", "up", "down"):
        if not n:
            if name == "up":
                _bpx_top(self)
            return
        new = _bpx_grid_nav(wk[key], n, cols, name)
        if new < 0:
            _bpx_top(self)
            return
        wk[key] = new
        self._ws_ensure()
        if not games and wk["more"] and not wk["loading"] and new // cols >= (n - 1) // cols - 1:
            self._ws_fetch(wk["page"] + 1)
    elif name == "accept":
        if games and n:
            self._ws_open_game(lst[wk[key]])
        elif not games and n:
            self._ws_install(lst[wk[key]])
        elif not games and wk["err"]:
            self._ws_fetch(1)
    elif not games and name == "alt":
        self._kb_open("Search the Workshop - %s" % wk["title"], wk["query"], None, self._ws_search, 80)
    elif not games and name == "x":
        wk["sort"] = (wk["sort"] + 1) % len(WS_SORTS)
        self._ws_reset_items()
        self._ws_fetch(1)
        self._say("Sorted by: %s" % WS_SORTS[wk["sort"]][0], 2000)


@_bpm("_paint_workshop")
def _bpx_paint_ws(self, p, w, h, m, acc):
    wk = self._wk
    wp = getattr(self._app, "workshop_page", None)
    top, bot = h * 0.2, h * 0.86
    area = QRectF(0, top, w, bot - top)
    if wp is None:
        self._x_msg(p, area, "Workshop isn't available")
        return
    if wk["mode"] == "games":
        self._x_text(p, QRectF(m, h * 0.125, w - 2 * m, h * 0.05), "Steam Workshop   -   choose a game", 0.028,
                     QColor(235, 235, 245), True)
        games = wk["games"]
        if not games:
            self._x_msg(p, area, wk["err"] or "No installed Steam games found. Add a game to your library first.")
            return

        def draw_game(r, i, s):
            g = games[i]
            try:
                url = _BPX_HDR % int(g["appid"])
            except (TypeError, ValueError):
                url = ""
            cnt = _WS_MOD_COUNTS.get(g["appid"])
            self._x_tile(p, r, self._ws_pix(url), g["title"], ("%s%s items" % (format(cnt, ","), "+" if g["appid"] in _WS_COUNT_APPROX else "")) if cnt else "", acc)
        self._x_grid_paint(p, w, h, acc, len(games), wk["gsel"], 2.14, draw_game)
        return
    # items of one game: small toolbar (mouse friendly) + grid of previews
    y, bh, gap = h * 0.128, h * 0.046, h * 0.012
    focus = self._zone == "content"
    sort_lbl = "Sort: %s" % WS_SORTS[wk["sort"]][0]
    q_lbl = "Search: %s" % wk["query"] if wk["query"] else "Search"
    bws = (h * 0.16, h * 0.3, h * 0.3)
    x = m
    for t, bw, tag in (("< Games", bws[0], "wback"), (sort_lbl, bws[1], "wsort"), (q_lbl, bws[2], "wsearch")):
        r = QRectF(x, y, bw, bh)
        self._x_pill(p, r, QFontMetrics(self._font(h * 0.019, True)).elidedText(t, Qt.TextElideMode.ElideRight, int(bw - h * 0.03)),
                     acc, size=0.019)
        self._xhits.append((r, (tag,)))
        x += bw + gap
    self._x_text(p, QRectF(x + gap, y, w - x - m, bh), wk["title"], 0.026, QColor(235, 235, 245), True)
    items = wk["items"]
    if not items:
        if wk["loading"]:
            self._paint_loading(p, w, h, area, "Loading Workshop...")
        else:
            self._x_msg(p, area, ("Couldn't load the Workshop: %s" % wk["err"]) if wk["err"] else "No Workshop items found")
        return

    def draw_item(r, i, s):
        it = items[i]
        badge = None
        try:
            if wp._ws_have(wk["appid"], it["id"]):
                badge = "INSTALLED"
            else:
                q = next((e for e in wp.queue if e["id"] == it["id"] and e["appid"] == wk["appid"]
                          and e["status"] in ("queued", "downloading")), None)
                if q is not None:
                    badge = "QUEUED" if q["status"] == "queued" else "DOWNLOADING"
        except Exception:    # expected: offline or the server did not answer
            pass
        by = ("by " + it["author"]) if it.get("author") else ""
        self._x_tile(p, r, self._ws_pix(it.get("preview", "")), it.get("title", "?"), by, acc, badge)
    self._x_grid_paint(p, w, h, acc, len(items), wk["sel"], 1.6, draw_item, 0.2)
    if wk["loading"]:
        p.setFont(self._font(h * 0.018))
        p.setPen(QColor(170, 170, 195))
        p.drawText(QRectF(0, bot - h * 0.035, w, h * 0.03), int(Qt.AlignmentFlag.AlignCenter), "Loading more...")
    elif wk["err"]:
        p.setFont(self._font(h * 0.018))
        p.setPen(QColor(230, 170, 170))
        p.drawText(QRectF(0, bot - h * 0.035, w, h * 0.03), int(Qt.AlignmentFlag.AlignCenter), wk["err"])


# ── Big Picture: X options sidebar, in-BP download server picker,
# Fan Games tab and Garry's Mod Addons tab. Tabs: Library, Store, Friends, Downloads, Workshop, Fan Games, (GMod Addons).
_bpy_o = {n: getattr(_BigPicture, n) for n in (
    "__init__", "enter", "leave", "_act", "keyPressEvent", "mousePressEvent", "wheelEvent", "_launch", "_switch_tab",
    "_tab_labels", "_x_enter", "_x_act", "_x_tag", "_x_hint", "_paint_extra", "paintEvent")}


def _bpy_active_bp():
    try:
        for w in QApplication.topLevelWidgets():
            bp = getattr(w, "_big_picture", None)
            if bp is not None and bp._active and not bp._asleep and bp.isVisible():
                return bp
    except Exception:
        _log_exc("_bpy_active_bp")
    return None


@_bpm("__init__")
def _bpy_init(self, app):
    _bpy_o["__init__"](self, app)
    self._ov = None                       # open overlay: X sidebar ("side") or download-server picker ("pick")
    self._pick_q = []
    self._gm_root = None
    self._ovtimer = QTimer(self)
    self._ovtimer.setInterval(250)
    self._ovtimer.timeout.connect(self.update)
    self._fg = {"list": [], "sel": 0, "tag": "", "query": "", "pix": {}, "asked": set(), "tags": [""]}
    self._gm = {"sel": 0, "btn": 0, "query": "", "confirm": None}
    self._fgl = FanCoverLoader()
    self._fgl.loaded.connect(self._fg_cover)
    QApplication.instance().aboutToQuit.connect(self._fgl.shutdown)


@_bpm("enter")
def _bpy_enter(self):
    try:
        self._gm_root = find_gmod_root()
    except Exception:
        self._gm_root = None
    _bpy_o["enter"](self)


@_bpm("leave")
def _bpy_leave(self, show_main=True):
    pend = [self._ov] if self._ov is not None and self._ov["kind"] == "pick" else []
    pend += [{"box": b, "ev": e} for _t, b, e in self._pick_q]
    self._pick_q = []
    self._ov = None
    self._ovtimer.stop()
    for o in pend:                        # a download waiting for a server pick is cancelled
        o["ev"].set()
    self._fg["pix"].clear()
    self._fg["asked"].clear()
    try:
        self._fgl.cancel_pending()
    except Exception:
        _log_exc("_bpy_leave")
    _bpy_o["leave"](self, show_main)


@_bpm("_switch_tab")
def _bpy_switch_tab(self, t):
    global _BP_NTABS
    _BP_NTABS = len(self._tab_labels())
    _bpy_o["_switch_tab"](self, t)


@_bpm("_tab_labels")
def _bpy_tab_labels(self):
    return tuple(_bpy_o["_tab_labels"](self)) + ("Fan Games",) + (("GMod Addons",) if self._gm_root else ())


# ── downloads stay inside Big Picture ──
@_bpm("_launch")
def _bpy_launch(self):
    if not self._items:
        return
    it = self._items[self._sel]
    btn = it["btn"]
    try:
        label = btn.text().strip().lower() if btn is not None else ""
        usable = btn is not None and btn.isEnabled()
    except RuntimeError:
        label, usable = "", False
    if not usable or label in ("play", "launch", "open"):
        _bpy_o["_launch"](self)
        return
    before = len(self._dl_infos())
    self._lib_dirty = True
    btn.click()                           # same button the launcher uses; Big Picture stays open
    if self._active and len(self._dl_infos()) > before:
        self._switch_tab(3)
        self._say("Downloading %s" % it["title"], 3500)
    self.update()


def _bpy_asker_show(title, box, ev):
    bp = _bpy_active_bp()
    if bp is None:
        _ServerAsker._show(_PW_ASKER, title, box, ev)       # normal popup when Big Picture isn't open
    else:
        bp._pick_open(title, box, ev)


try:
    _PW_ASKER.request.disconnect()
except Exception:    # expected: cleanup that may already be done
    pass
_PW_ASKER.request.connect(_bpy_asker_show)


def _bpy_probe(states, title, sid):
    try:
        states[sid] = _pw_probe_server(title, sid)
    except Exception:
        states[sid] = "error"


@_bpm("_pick_open")
def _bpy_pick_open(self, title, box, ev):
    if self._ov is not None and self._ov["kind"] == "pick":
        self._pick_q.append((title, box, ev))
        return
    sids = list(PW_SERVER_NAMES.keys())
    states = {s: "checking" for s in sids}
    self._ov = {"kind": "pick", "title": title, "box": box, "ev": ev, "sids": sids, "states": states, "sel": 0, "rects": []}
    for s in sids:
        threading.Thread(target=_bpy_probe, args=(states, title, s), daemon=True).start()
    self._ovtimer.start()
    self.setCursor(Qt.CursorShape.BlankCursor)
    self.update()


@_bpm("_pick_done")
def _bpy_pick_done(self, sid):
    ov = self._ov
    self._ov = None
    if ov is not None and ov["kind"] == "pick":
        ov["box"]["v"] = sid
        ov["ev"].set()
    if self._pick_q:
        self._pick_open(*self._pick_q.pop(0))
    else:
        self._ovtimer.stop()
    self.update()


# ── X sidebar (the launcher's 3-dot menu) ──
def _bpy_menu_entries(menu):
    try:
        menu.aboutToShow.emit()           # some menus fill themselves in lazily
    except Exception:
        _log_exc("_bpy_menu_entries")
    out = []
    for a in menu.actions():
        try:
            if a.isSeparator() or not a.isVisible():
                continue
            txt = a.text().replace("&", "").strip()
            if not txt:
                continue
            try:
                sub = a.menu()
            except Exception:
                sub = None
            out.append({"text": txt, "enabled": a.isEnabled(), "act": a, "sub": sub,
                        "checked": a.isChecked() if a.isCheckable() else None})
        except RuntimeError:
            continue
    return out


@_bpm("_side_open")
def _bpy_side_open(self):
    if not self._items or not (0 <= self._sel < len(self._items)):
        return
    it = self._items[self._sel]
    try:
        more = it["card"].findChild(QPushButton, "MoreButton")
        menu = more.menu() if more is not None else None
    except RuntimeError:
        menu = None
    ents = _bpy_menu_entries(menu) if menu is not None else []
    if not ents:
        self._say("No options for this game", 2000)
        self.update()
        return
    sel = next((i for i, e in enumerate(ents) if e["enabled"]), 0)
    self._ov = {"kind": "side", "title": it["title"], "stack": [("Options", ents)], "sel": sel, "scroll": 0, "rects": []}
    self.setCursor(Qt.CursorShape.BlankCursor)
    self.update()


@_bpm("_side_run")
def _bpy_side_run(self, a):
    try:
        a.trigger()
    except Exception as ex:
        self._say("Couldn't run that: %s" % ex, 3000)
    self._lib_dirty = True
    QTimer.singleShot(700, self._side_after)


@_bpm("_side_after")
def _bpy_side_after(self):
    if self._active and not self._asleep and self._tab == 0 and self._ov is None and self._detail is None and self._kb is None:
        self._refresh()
    self.update()


@_bpm("_ov_act")
def _bpy_ov_act(self, name):
    ov = self._ov
    if ov is None:
        return
    if name == "start":
        name = "accept"
    if ov["kind"] == "side":
        title, ents = ov["stack"][-1]
        n = len(ents)
        if name in ("up", "down"):
            d = -1 if name == "up" else 1
            j = ov["sel"] + d
            while 0 <= j < n and not ents[j]["enabled"]:
                j += d
            if 0 <= j < n:
                ov["sel"] = j
        elif name == "accept" and n:
            e = ents[ov["sel"]]
            if not e["enabled"]:
                return
            if e["sub"] is not None:
                sub = _bpy_menu_entries(e["sub"])
                if sub:
                    ov["stack"].append((e["text"], sub))
                    ov["sel"], ov["scroll"] = next((i for i, x in enumerate(sub) if x["enabled"]), 0), 0
                return
            a = e["act"]
            self._ov = None
            QTimer.singleShot(60, lambda a=a: self._side_run(a))
        elif name in ("back", "x"):
            if len(ov["stack"]) > 1:
                ov["stack"].pop()
                ov["sel"], ov["scroll"] = 0, 0
            else:
                self._ov = None
    else:
        n = len(ov["sids"]) + 1                       # servers + Cancel
        if name in ("up", "down"):
            ov["sel"] = max(0, min(n - 1, ov["sel"] + (-1 if name == "up" else 1)))
        elif name == "accept":
            if ov["sel"] >= len(ov["sids"]):
                self._pick_done("")
            else:
                sid = ov["sids"][ov["sel"]]
                if ov["states"].get(sid) != "404":
                    self._pick_done(sid)
        elif name == "back":
            self._pick_done("")
    self.update()


@_bpm("_ov_click")
def _bpy_ov_click(self, tag):
    ov = self._ov
    ov["sel"] = tag[1]
    self._ov_act("accept")


@_bpm("_act")
def _bpy_act(self, name):
    if not self._from_key:
        self._pad_last = True
    if self._ov is not None:
        self.setCursor(Qt.CursorShape.BlankCursor)
        self._ov_act(name)
        return
    if name == "x" and self._tab == 0 and self._detail is None and self._kb is None:
        self._side_open()
        return
    _bpy_o["_act"](self, name)


@_bpm("keyPressEvent")
def _bpy_key(self, e):
    k, K = e.key(), Qt.Key
    if self._ov is not None:
        self._pad_last = False
        name = {K.Key_Up: "up", K.Key_Down: "down", K.Key_Left: "up", K.Key_Right: "down", K.Key_Return: "accept",
                K.Key_Enter: "accept", K.Key_Space: "accept", K.Key_Escape: "back", K.Key_Backspace: "back",
                K.Key_F11: "back", K.Key_X: "x"}.get(k)
        if self._ov["kind"] in ("view", "files") and k in (K.Key_Left, K.Key_Right):
            name = "left" if k == K.Key_Left else "right"
        if name:
            self._ov_act(name)
        return
    if (k == K.Key_X and self._tab == 0 and self._detail is None and self._kb is None
            and not (e.modifiers() & (Qt.KeyboardModifier.ControlModifier | Qt.KeyboardModifier.AltModifier))):
        self._pad_last = False
        self._side_open()
        return
    _bpy_o["keyPressEvent"](self, e)


@_bpm("mousePressEvent")
def _bpy_mouse(self, e):
    if self._ov is not None:
        pt = e.position()
        for r, tag in self._ov["rects"]:
            if r.contains(pt):
                self._ov_click(tag)
                return
        if self._ov["kind"] in ("side", "view"):
            self._ov_act("back")
        return
    _bpy_o["mousePressEvent"](self, e)


@_bpm("wheelEvent")
def _bpy_wheel(self, e):
    if self._ov is not None:
        self._ov_act("up" if e.angleDelta().y() > 0 else "down")
        return
    _bpy_o["wheelEvent"](self, e)


@_bpm("paintEvent")
def _bpy_paint(self, e):
    _bpy_o["paintEvent"](self, e)
    if self._ov is None:
        return
    p = QPainter(self)
    p.setRenderHints(QPainter.RenderHint.Antialiasing | QPainter.RenderHint.TextAntialiasing)
    try:
        self._paint_ov(p, self.width(), self.height(), QApplication.palette().color(QPalette.ColorRole.Highlight))
    finally:
        p.end()


@_bpm("_paint_ov")
def _bpy_paint_ov(self, p, w, h, acc):
    ov = self._ov
    ov["rects"] = []
    al_r = int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
    if ov["kind"] == "side":
        px, pad = w * 0.64, h * 0.03
        p.fillRect(QRectF(0, 0, px, h), QColor(0, 0, 0, 150))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(14, 14, 26, 250))
        p.drawRect(QRectF(px, 0, w - px, h))
        p.setBrush(acc)
        p.drawRect(QRectF(px, 0, max(2.0, h * 0.003), h))
        title, ents = ov["stack"][-1]
        self._x_text(p, QRectF(px + pad, h * 0.04, w - px - 2 * pad, h * 0.05), ov["title"], 0.032, QColor(245, 245, 252), True)
        self._x_text(p, QRectF(px + pad, h * 0.095, w - px - 2 * pad, h * 0.04), title, 0.021, QColor(170, 170, 200))
        top, bot, rh, pitch = h * 0.16, h * 0.9, h * 0.068, h * 0.076
        vis = max(1, int((bot - top) // pitch))
        sel = ov["sel"]
        if sel < ov["scroll"]:
            ov["scroll"] = sel
        if sel >= ov["scroll"] + vis:
            ov["scroll"] = sel - vis + 1
        clip = QRectF(px, top - h * 0.01, w - px, bot - top + h * 0.02)
        p.save()
        p.setClipRect(clip)
        for n in range(ov["scroll"], min(len(ents), ov["scroll"] + vis + 1)):
            e = ents[n]
            r = QRectF(px + pad, top + (n - ov["scroll"]) * pitch, w - px - 2 * pad, rh)
            s = n == sel
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(acc if s else QColor(255, 255, 255, 22))
            p.drawRoundedRect(r, rh * 0.25, rh * 0.25)
            label = ("[x] " if e["checked"] else "[ ] " if e["checked"] is not None else "") + e["text"]
            col = QColor(_on_accent()) if s else (QColor(235, 235, 245) if e["enabled"] else QColor(110, 110, 130))
            self._x_text(p, QRectF(r.left() + pad * 0.7, r.top(), r.width() - pad * 1.9, rh), label, 0.024, col, s)
            if e["sub"] is not None:
                self._x_text(p, QRectF(r.left(), r.top(), r.width() - pad * 0.7, rh), ">", 0.026, col, True, al_r)
            ov["rects"].append((r.intersected(clip), ("row", n)))
        p.restore()
        p.setFont(self._font(h * 0.0185))
        p.setPen(QColor(150, 150, 175))
        p.drawText(QRectF(px + pad, h * 0.935, w - px - 2 * pad, h * 0.035),
                   int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter), "Up / Down  Move      A  Select      B / X  Close")
        return
    # download server picker
    bw, bh = w * 0.46, h * 0.62
    bx, by, pad = (w - bw) / 2, (h - bh) / 2, h * 0.03
    p.fillRect(QRectF(0, 0, w, h), QColor(0, 0, 0, 175))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(14, 14, 26, 250))
    p.drawRoundedRect(QRectF(bx, by, bw, bh), h * 0.025, h * 0.025)
    self._x_text(p, QRectF(bx + pad, by + h * 0.025, bw - 2 * pad, h * 0.05), "Choose download server", 0.032, QColor(245, 245, 252), True)
    self._x_text(p, QRectF(bx + pad, by + h * 0.078, bw - 2 * pad, h * 0.04), "Where do you want to download %s from?" % ov["title"],
                 0.021, QColor(170, 170, 200))
    y, rh = by + h * 0.14, h * 0.1
    names = {"ok": "available", "404": "Not found (404)", "checking": "checking..."}
    for i, sid in enumerate(ov["sids"]):
        name, desc = PW_SERVER_NAMES[sid]
        st = ov["states"].get(sid, "checking")
        r = QRectF(bx + pad, y + i * (rh + h * 0.012), bw - 2 * pad, rh)
        s = i == ov["sel"]
        dead = st == "404"
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(acc if s and not dead else QColor(255, 255, 255, 22))
        p.drawRoundedRect(r, rh * 0.2, rh * 0.2)
        col = QColor(110, 110, 130) if dead else (QColor(_on_accent()) if s else QColor(240, 240, 250))
        self._x_text(p, QRectF(r.left() + pad * 0.7, r.top() + rh * 0.08, r.width() - pad * 1.4, rh * 0.46), name, 0.026, col, True)
        self._x_text(p, QRectF(r.left() + pad * 0.7, r.top() + rh * 0.52, r.width() - pad * 1.4, rh * 0.38),
                     "%s  -  %s" % (desc, names.get(st, "couldn't check")), 0.0185, col)
        ov["rects"].append((r, ("srv", i)))
    r = QRectF(bx + pad, y + len(ov["sids"]) * (rh + h * 0.012), bw - 2 * pad, h * 0.065)
    self._x_pill(p, r, "Cancel", acc, sel=(ov["sel"] == len(ov["sids"])))
    ov["rects"].append((r, ("cancel", len(ov["sids"]))))


# ── Fan Games tab ──
@_bpm("_x_enter")
def _bpy_x_enter(self, t):
    _bpy_o["_x_enter"](self, t)
    if t == 5:
        self._fg_enter()
    elif t == 6:
        self._gm_enter()


@_bpm("_x_act")
def _bpy_x_act(self, name):
    if self._tab == 5:
        self._fg_act(name)
    elif self._tab == 6:
        self._gm_act(name)
    else:
        _bpy_o["_x_act"](self, name)
        return
    self.update()


@_bpm("_x_hint")
def _bpy_hint(self):
    if self._tab == 5:
        return "Arrows  Browse      A  Add to library      Y  Search      X  Category      LB / RB  Switch tab      B  Library"
    if self._tab == 6:
        return "Up / Down  Select      Left / Right  Button      A  Press      Y  Search      X  Enable / disable all      LB / RB  Switch tab      B  Library"
    return _bpy_o["_x_hint"](self)


@_bpm("_paint_extra")
def _bpy_paint_extra(self, p, w, h, m, acc, k):
    if self._tab < 5:
        _bpy_o["_paint_extra"](self, p, w, h, m, acc, k)
        return
    self._xhits = []
    p.setOpacity(k)
    if self._tab == 5:
        self._paint_fan(p, w, h, m, acc)
    else:
        self._paint_gm(p, w, h, m, acc)
    p.setOpacity(1.0)


@_bpm("_x_tag")
def _bpy_x_tag(self, tag):
    k = tag[0]
    if self._tab == 5:
        fg = self._fg
        if k == "tile":
            if fg["sel"] == tag[1]:
                self._fg_act("accept")
            else:
                fg["sel"] = tag[1]
                self._fg_ensure()
        elif k == "fgtag":
            self._fg_act("x")
        elif k == "fgsearch":
            self._fg_act("alt")
        self.update()
        return
    if self._tab == 6:
        gm = self._gm
        if k == "grow":
            gm["sel"], gm["btn"] = tag[1], 0
        elif k == "gbtn":
            gm["sel"], gm["btn"] = tag[1], tag[2]
            self._gm_act("accept")
        elif k == "gall":
            self._gm_all(tag[1])
        elif k == "gsearch":
            self._gm_act("alt")
        self.update()
        return
    _bpy_o["_x_tag"](self, tag)


@_bpm("_fg_cover")
def _bpy_fg_cover(self, gid, path):
    pm = QPixmap()
    if path:
        q = QPixmap(path)
        if not q.isNull():
            pm = q.scaledToWidth(480, Qt.TransformationMode.SmoothTransformation) if q.width() > 480 else q
    self._fg["pix"][gid] = pm
    QTimer.singleShot(0, self.update)


@_bpm("_fg_rebuild")
def _bpy_fg_rebuild(self):
    fg = self._fg
    games = load_fan_games()
    q = fg["query"].lower()
    cur = fg["list"][fg["sel"]][0] if fg["list"] and 0 <= fg["sel"] < len(fg["list"]) else None
    fg["list"] = [g for g in games if q in g[1].lower() and (not fg["tag"] or fg["tag"] in g[3])]
    fg["sel"] = next((i for i, g in enumerate(fg["list"]) if g[0] == cur), 0)
    tags = set()
    for g in games:
        tags |= set(g[3])
    fg["tags"] = [""] + [t for t in _FAN_TAG_NAMES if t in tags] + sorted(t for t in tags if t not in _FAN_TAG_NAMES)


@_bpm("_fg_enter")
def _bpy_fg_enter(self):
    self._fg_rebuild()
    self._fg_ensure()


@_bpm("_fg_ensure")
def _bpy_fg_ensure(self):
    gap, tw, th, cols, x0, top, bot = self._x_grid(1.6)
    pitch = th + gap
    row = self._fg["sel"] // cols
    self._x_ensure(row * pitch, row * pitch + pitch + self.height() * 0.024, bot - top)


@_bpm("_fg_search")
def _bpy_fg_search(self, text):
    self._fg["query"] = (text or "").strip()
    self._fg_rebuild()
    self._x_reset_scroll()


@_bpm("_fg_act")
def _bpy_fg_act(self, name):
    fg = self._fg
    lst = fg["list"]
    n = len(lst)
    fg["sel"] = max(0, min(max(0, n - 1), fg["sel"]))
    if name == "back":
        self._switch_tab(0)
    elif name in ("left", "right", "up", "down"):
        if not n:
            if name == "up":
                _bpx_top(self)
            return
        new = _bpx_grid_nav(fg["sel"], n, self._x_grid(1.6)[3], name)
        if new < 0:
            _bpx_top(self)
            return
        fg["sel"] = new
        self._fg_ensure()
    elif name == "accept" and n:
        gid, title, link, _tags = lst[fg["sel"]]
        lib = getattr(self._app, "fan_lib_cards", None) or {}
        if gid in lib:                                   # already added: jump to it in the Library
            card = lib[gid]
            self._switch_tab(0)
            if self._lib_dirty:
                self._refresh()
            for i, li in enumerate(self._items):
                if li["card"] is card:
                    self._sel, self._pos = i, float(i)
                    self._cache.clear()
                    self._sync_bg(animate=False)
                    break
            return
        cover = os.path.join(get_fan_cover_dir(), "%s.img" % gid)
        try:
            self._app._fan_add(gid, title, cover if os.path.exists(cover) else "")
            self._lib_dirty = True
            self._say("Added %s to your library" % title, 3000)
        except Exception as ex:
            self._say("Couldn't add game: %s" % ex, 4000)
    elif name == "alt":
        self._kb_open("Search Fan Games", fg["query"], None, self._fg_search, 80)
    elif name == "x":
        tags = fg["tags"]
        fg["tag"] = tags[(tags.index(fg["tag"]) + 1) % len(tags)] if fg["tag"] in tags else ""
        self._fg_rebuild()
        self._x_reset_scroll()
        self._say("Category: %s" % (_FAN_TAG_NAMES.get(fg["tag"], fg["tag"].title()) if fg["tag"] else "All"), 2000)


@_bpm("_paint_fan")
def _bpy_paint_fan(self, p, w, h, m, acc):
    fg = self._fg
    top, bot = h * 0.2, h * 0.86
    area = QRectF(0, top, w, bot - top)
    y, bh, gap = h * 0.128, h * 0.046, h * 0.012
    fm = QFontMetrics(self._font(h * 0.019, True))
    tag_lbl = "Category: %s" % (_FAN_TAG_NAMES.get(fg["tag"], fg["tag"].title()) if fg["tag"] else "All")
    q_lbl = ("Search: " + fg["query"]) if fg["query"] else "Search"
    x = m
    for t, bw, tag in ((tag_lbl, h * 0.34, "fgtag"), (q_lbl, h * 0.34, "fgsearch")):
        r = QRectF(x, y, bw, bh)
        self._x_pill(p, r, fm.elidedText(t, Qt.TextElideMode.ElideRight, int(bw - h * 0.03)), acc, size=0.019)
        self._xhits.append((r, (tag,)))
        x += bw + gap
    lst = fg["list"]
    self._x_text(p, QRectF(x + gap, y, w - x - m, bh), "Fan Games   %d" % len(lst), 0.026, QColor(235, 235, 245), True)
    if not lst:
        self._x_msg(p, area, "No fan games match" if load_fan_games() else "No fan_games.csv found next to main.py")
        return
    lib = getattr(self._app, "fan_lib_cards", None) or {}

    def draw(r, i, s):
        gid, title, link, tags = lst[i]
        pm = fg["pix"].get(gid)
        if pm is None and gid not in fg["asked"]:
            fg["asked"].add(gid)
            self._fgl.request(gid, link, title)
        sub = ", ".join(_FAN_TAG_NAMES.get(t, t.title()) for t in sorted(tags))
        self._x_tile(p, r, pm, title, sub, acc, "IN LIBRARY" if gid in lib else None)
    self._x_grid_paint(p, w, h, acc, len(lst), fg["sel"], 1.6, draw)


# ── Garry's Mod Addons tab ──
def _bpy_gm_page(self):
    return getattr(self._app, "gmod_page", None) if self._gm_root else None


@_bpm("_gm_rows")
def _bpy_gm_rows(self):
    gp = _bpy_gm_page(self)
    if gp is None:
        return []
    q = self._gm["query"].lower()
    return [r for r in gp.rows if q in r["name"].lower()]


@_bpm("_gm_enter")
def _bpy_gm_enter(self):
    gp = _bpy_gm_page(self)
    if gp is not None:
        try:
            gp.set_root(self._gm_root)
            gp.refresh_addons()
        except Exception as ex:
            self._say("Couldn't read addons: %s" % ex, 3000)
    self._gm.update(sel=0, btn=0, confirm=None)


@_bpm("_gm_ensure")
def _bpy_gm_ensure(self):
    h = self.height()
    pitch = h * 0.097
    i = self._gm["sel"]
    self._x_ensure(i * pitch, (i + 1) * pitch, h * 0.86 - h * 0.2)


@_bpm("_gm_set")
def _bpy_gm_set(self, r, enable):
    gp = _bpy_gm_page(self)
    if gp is None or r["btn"].isChecked() == enable:
        return True
    try:
        gp._move(r, enable)
    except Exception as ex:
        self._say("Couldn't move addon: %s" % ex, 4000)
        return False
    b = r["btn"]
    b.blockSignals(True)
    b.setChecked(enable)
    b.setText("Enabled" if enable else "Disabled")
    b.blockSignals(False)
    return True


@_bpm("_gm_all")
def _bpy_gm_all(self, enable):
    rows = self._gm_rows()
    done = sum(1 for r in rows if r["btn"].isChecked() != enable and self._gm_set(r, enable))
    self._say("%s %d addon%s" % ("Enabled" if enable else "Disabled", done, "" if done == 1 else "s"), 2500)


@_bpm("_gm_delete")
def _bpy_gm_delete(self, r):
    gp = _bpy_gm_page(self)
    if gp is None:
        return
    base = gp.addons_dir()
    path = os.path.join(base if r["btn"].isChecked() else os.path.join(base, "disabled"), r["real"])
    try:
        if os.path.isdir(path) and not os.path.islink(path):
            shutil.rmtree(path)
        elif os.path.exists(path):
            os.remove(path)
    except Exception as ex:
        self._say("Couldn't delete addon: %s" % ex, 4000)
        return
    name = r["name"]
    gp.refresh_addons()
    self._say("Deleted %s" % name, 2500)


@_bpm("_gm_search")
def _bpy_gm_search(self, text):
    self._gm.update(query=(text or "").strip(), sel=0, confirm=None)
    self._x_reset_scroll()


@_bpm("_gm_act")
def _bpy_gm_act(self, name):
    gm = self._gm
    rows = self._gm_rows()
    n = len(rows)
    gm["sel"] = max(0, min(max(0, n - 1), gm["sel"]))
    if name == "back":
        self._switch_tab(0)
    elif name == "up":
        gm["confirm"] = None
        if gm["sel"] <= 0:
            _bpx_top(self)
        else:
            gm["sel"] -= 1
            gm["btn"] = 0
            self._gm_ensure()
    elif name == "down":
        gm["confirm"] = None
        if gm["sel"] < n - 1:
            gm["sel"] += 1
            gm["btn"] = 0
            self._gm_ensure()
    elif name in ("left", "right"):
        gm["confirm"] = None
        gm["btn"] = 1 if name == "right" else 0
    elif name == "accept" and n:
        r = rows[gm["sel"]]
        if gm["btn"] == 0:
            self._gm_set(r, not r["btn"].isChecked())
        elif gm["confirm"] == r["name"]:
            gm["confirm"] = None
            self._gm_delete(r)
        else:
            gm["confirm"] = r["name"]
            self._say("Press A again to delete \"%s\"" % r["name"], 3000)
    elif name == "alt":
        self._kb_open("Search addons", gm["query"], None, self._gm_search, 80)
    elif name == "x" and n:
        self._gm_all(any(not r["btn"].isChecked() for r in rows))


@_bpm("_paint_gm")
def _bpy_paint_gm(self, p, w, h, m, acc):
    gm = self._gm
    top, bot = h * 0.2, h * 0.86
    area = QRectF(0, top, w, bot - top)
    gp = _bpy_gm_page(self)
    if gp is None:
        self._x_msg(p, area, "Garry's Mod isn't installed")
        return
    rows = self._gm_rows()
    y, bh, gap = h * 0.128, h * 0.046, h * 0.012
    fm = QFontMetrics(self._font(h * 0.019, True))
    q_lbl = ("Search: " + gm["query"]) if gm["query"] else "Search"
    x = m
    for t, bw, tag in (("Enable all", h * 0.2, ("gall", True)), ("Disable all", h * 0.2, ("gall", False)),
                       (q_lbl, h * 0.34, ("gsearch",))):
        r = QRectF(x, y, bw, bh)
        self._x_pill(p, r, fm.elidedText(t, Qt.TextElideMode.ElideRight, int(bw - h * 0.03)), acc, size=0.019)
        self._xhits.append((r, tag))
        x += bw + gap
    en = sum(1 for r in gp.rows if r["btn"].isChecked())
    self._x_text(p, QRectF(x + gap, y, w - x - m, bh), "Addons   %d installed, %d enabled" % (len(gp.rows), en), 0.026,
                 QColor(235, 235, 245), True)
    if not rows:
        self._x_msg(p, area, "No addons found" if not gp.rows else "No addons match your search")
        return
    cx, cw, rh, pitch = w * 0.14, w * 0.72, h * 0.085, h * 0.097
    focus = self._zone == "content"
    p.save()
    p.setClipRect(QRectF(0, top - h * 0.01, w, bot - top + h * 0.02))
    for i, r in enumerate(rows):
        yy = top + i * pitch - self._xscroll
        if yy + rh < top - h * 0.01 or yy > bot:
            continue
        rect = QRectF(cx, yy, cw, rh)
        sel = focus and i == gm["sel"]
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 48 if sel else 22))
        p.drawRoundedRect(rect, rh * 0.2, rh * 0.2)
        if sel:
            self._x_ring(p, rect, rh * 0.2)
        vis = QRectF(0, top, w, bot - top)
        self._xhits.append((rect.intersected(vis), ("grow", i)))
        pad, bw2, bh2 = rh * 0.2, h * 0.15, rh * 0.55
        delr = QRectF(rect.right() - pad - bw2, yy + (rh - bh2) / 2, bw2, bh2)
        togr = QRectF(delr.left() - h * 0.012 - bw2, delr.top(), bw2, bh2)
        on = r["btn"].isChecked()
        self._x_pill(p, togr, "Enabled" if on else "Disabled", acc, sel=(sel and gm["btn"] == 0), primary=on, size=0.02)
        self._x_pill(p, delr, "Confirm?" if gm["confirm"] == r["name"] else "Delete", acc, sel=(sel and gm["btn"] == 1), size=0.02)
        self._xhits.append((togr.intersected(vis), ("gbtn", i, 0)))
        self._xhits.append((delr.intersected(vis), ("gbtn", i, 1)))
        self._x_text(p, QRectF(cx + pad, yy, togr.left() - cx - 2 * pad, rh), r["name"], 0.026,
                     QColor(245, 245, 252) if on else QColor(160, 160, 180), True)
    p.restore()


# ── Big Picture chat: game invites + attachments ──
class _BPMediaBus(QObject):
    ready = pyqtSignal(str, str, str)       # attachment id (or "inv:<link>"), file path, error


_bpz_o = {n: getattr(_BigPicture, n) for n in (
    "__init__", "leave", "_fr_act", "_x_tag", "_x_hint", "_x_tick", "_ov_act", "_paint_ov")}


@_bpm("__init__")
def _bpz_init(self, app):
    _bpz_o["__init__"](self, app)
    self._fr.update(cfocus="btns", media={}, mreq=set(), cov={}, want=None, seen=None)
    self._mb = _BPMediaBus()
    self._mb.ready.connect(self._fr_media_ready)


@_bpm("leave")
def _bpz_leave(self, show_main=True):
    fr = self._fr
    fr["media"].clear()
    fr["cov"].clear()
    fr["want"] = None
    fr["cfocus"] = "btns"
    _bpz_o["leave"](self, show_main)


# ── media (thumbnails, invite covers) ──
@_bpm("_fr_media_req")
def _bpz_media_req(self, att, force=False):
    fr = self._fr
    aid, other = str(att.get("id", "")), fr["chat"]
    if not aid or not other or aid in fr["mreq"] or (aid in fr["media"] and not force):
        return
    fr["mreq"].add(aid)
    bus = self._mb

    def work():
        try:
            path, err = cloud_fetch_media(other, att), ""
        except Exception as e:
            path, err = "", (str(e) or "Couldn't load this attachment.")
        try:
            bus.ready.emit(aid, path, err)
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    threading.Thread(target=work, daemon=True).start()


@_bpm("_fr_media_ready")
def _bpz_media_ready(self, aid, path, err):
    fr = self._fr
    fr["mreq"].discard(aid)
    if aid.startswith("inv:"):
        pm = QPixmap(path) if path else QPixmap()
        fr["cov"][aid[4:]] = pm.scaledToHeight(240, Qt.TransformationMode.SmoothTransformation) if not pm.isNull() else QPixmap()
    else:
        pm = QPixmap()
        if path:
            q = QPixmap(path)
            if not q.isNull():
                pm = q.scaledToHeight(540, Qt.TransformationMode.SmoothTransformation) if q.height() > 540 else q
        fr["media"][aid] = pm
        want = fr["want"]
        if want and want[0] == aid:
            fr["want"] = None
            if err or not path:
                self._say("Couldn't open it: %s" % (err or "not available"), 4000)
            else:
                self._att_show(want[1], want[2], path)
    self.update()


@_bpm("_att_open")
def _bpz_att_open(self, atts, i):
    att = atts[i]
    path = _att_cache_path(att)
    if path and os.path.exists(path) and os.path.getsize(path) > 0:
        self._att_show(atts, i, path)
        return
    self._fr["want"] = (str(att.get("id", "")), atts, i)
    self._fr_media_req(att, force=True)
    self._say("Downloading...", 3000)


@_bpm("_att_show")
def _bpz_att_show(self, atts, i, path):
    att = atts[i]
    if att.get("k") in ("img", "gif"):
        imgs = [a for a in atts if a.get("k") in ("img", "gif")]
        j = next((n for n, a in enumerate(imgs) if a is att), 0)
        self._ov = {"kind": "view", "atts": imgs, "i": j, "pm": QPixmap(path), "rects": []}
        self.setCursor(Qt.CursorShape.BlankCursor)
    else:
        QDesktopServices.openUrl(QUrl.fromLocalFile(path))
        self._say("Opened in your default app", 2500)
    self.update()


@_bpm("_att_step")
def _bpz_att_step(self, ov, d):
    imgs = ov["atts"]
    if len(imgs) < 2:
        return
    j = (ov["i"] + d) % len(imgs)
    path = _att_cache_path(imgs[j])
    if path and os.path.exists(path) and os.path.getsize(path) > 0:
        ov["i"], ov["pm"] = j, QPixmap(path)
    else:
        self._fr["want"] = (str(imgs[j].get("id", "")), imgs, j)
        self._fr_media_req(imgs[j], force=True)
        self._say("Downloading...", 3000)


def _bpz_cover(self, inv, sender):
    fr = self._fr
    link = inv["link"]
    pm = fr["cov"].get(link)
    if pm is not None:
        return pm
    path = ""
    try:
        path = invite_cover_path(inv, sender)
    except Exception:
        _log_exc("_bpz_cover")
    if path:
        q = QPixmap(path)
        pm = q.scaledToHeight(240, Qt.TransformationMode.SmoothTransformation) if not q.isNull() else QPixmap()
        fr["cov"][link] = pm
        return pm
    key = "inv:" + link
    if not (inv.get("appid") or (sender and inv.get("key"))):
        fr["cov"][link] = QPixmap()
        return fr["cov"][link]
    if key not in fr["mreq"]:
        fr["mreq"].add(key)
        bus = self._mb

        def work():
            try:
                pth = _fetch_invite_cover(inv, sender) or ""
            except Exception:
                pth = ""
            try:
                bus.ready.emit(key, pth, "")
            except RuntimeError:    # expected: the widget or object may already be deleted
                pass
        threading.Thread(target=work, daemon=True).start()
    return None


# ── chat drawing ──
@_bpm("_chat_parts")
def _bpz_parts(self, mg, iw, fm):
    fr, h, parts = self._fr, self.height(), []
    text = str(mg.get("text") or "")
    inv = parse_invite(text)
    if inv:
        parts.append({"t": "inv", "inv": inv, "w": min(iw, h * 0.5), "h": h * 0.11, "from": mg.get("from")})
        return parts
    if text.strip():
        br = fm.boundingRect(QRect(0, 0, int(iw), 10000), int(Qt.TextFlag.TextWordWrap), text)
        parts.append({"t": "txt", "text": text, "w": br.width(), "h": br.height()})
    atts = [a for a in (mg.get("att") if isinstance(mg.get("att"), list) else []) if isinstance(a, dict)]
    for a in atts[:CHAT_MAX_ATTACH]:
        k, aid = a.get("k"), str(a.get("id", ""))
        if k in ("img", "gif"):
            pm = fr["media"].get(aid)
            if pm is None:
                self._fr_media_req(a)
            if pm is not None and not pm.isNull():
                s = min(iw / pm.width(), h * 0.22 / pm.height(), 1.0)
                parts.append({"t": "img", "pm": pm, "w": pm.width() * s, "h": pm.height() * s})
            else:
                parts.append({"t": "ph", "label": "Loading image..." if pm is None else "Image unavailable",
                              "w": min(iw, h * 0.3), "h": h * 0.06})
        else:
            parts.append({"t": "file", "label": "[%s] %s" % ("Video" if k == "vid" else "File", str(a.get("n") or "attachment")),
                          "w": min(iw, h * 0.45), "h": h * 0.05})
    return parts


@_bpm("_paint_chat")
def _bpz_paint_chat(self, p, w, h, acc):
    fr = self._fr
    row = next((r for r in fr["rows"] if r["uid"] == fr["chat"]), None)
    cx, cw = w * 0.2, w * 0.6
    if row is not None:
        ad = h * 0.075
        self._x_avatar(p, QRectF(cx, h * 0.14, ad, ad), row)
        st, col = _friend_status(row["d"])
        self._x_text(p, QRectF(cx + ad * 1.25, h * 0.138, cw - ad * 1.25, h * 0.045), row["name"], 0.03, QColor(245, 245, 252), True)
        self._x_text(p, QRectF(cx + ad * 1.25, h * 0.18, cw - ad * 1.25, h * 0.035), st, 0.021, QColor(col))
    top = h * 0.24
    bot = h * 0.42 if self._kb is not None else h * 0.78
    clip = QRectF(cx - h * 0.01, top, cw + h * 0.02, bot - top)
    p.save()
    p.setClipRect(clip)
    msgs = fr["msgs"]
    if not msgs:
        self._x_msg(p, QRectF(cx, top, cw, bot - top), "Loading messages..." if fr["loading"] else "No messages yet. Press A to say hi!")
    f = self._font(h * 0.024)
    p.setFont(f)
    fm = QFontMetrics(f)
    maxw, padx, pady, gap = cw * 0.72, h * 0.018, h * 0.012, h * 0.01
    inner = cw * 0.72 - 2 * padx
    y, idx, first = bot, len(msgs) - 1 - fr["moff"], True
    focus = self._zone == "content" and fr["cfocus"] == "msgs"
    al_c = int(Qt.AlignmentFlag.AlignCenter)
    while idx >= 0 and y > top:
        mg, i = msgs[idx], idx
        idx -= 1
        parts = self._chat_parts(mg, inner, fm)
        if not parts:
            continue
        bh = sum(pt["h"] for pt in parts) + gap * 0.6 * (len(parts) - 1) + 2 * pady
        bw = min(maxw, max(pt["w"] for pt in parts) + 2 * padx)
        y -= bh
        mine = mg.get("from") == fr["me"]
        bx = cx + cw - bw if mine else cx
        rect = QRectF(bx, y, bw, bh)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(acc if mine else QColor(255, 255, 255, 36))
        p.drawRoundedRect(rect, h * 0.02, h * 0.02)
        if first and focus:
            self._x_ring(p, rect, h * 0.02)
        self._xhits.append((rect.intersected(clip), ("cmsg", i)))
        ink = QColor(_on_accent()) if mine else QColor(235, 235, 245)
        yy = y + pady
        for pt in parts:
            r = QRectF(bx + padx, yy, pt["w"], pt["h"])
            t = pt["t"]
            if t == "txt":
                p.setFont(f)
                p.setPen(ink)
                p.drawText(QRectF(r.left(), r.top(), bw - 2 * padx, r.height()),
                           int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop) | int(Qt.TextFlag.TextWordWrap), pt["text"])
            elif t == "img":
                path = QPainterPath()
                path.addRoundedRect(r, h * 0.01, h * 0.01)
                p.save()
                p.setClipPath(path, Qt.ClipOperation.IntersectClip)
                p.drawPixmap(r, pt["pm"], QRectF(pt["pm"].rect()))
                p.restore()
            elif t in ("ph", "file"):
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(0, 0, 0, 70))
                p.drawRoundedRect(r, r.height() / 2 if t == "file" else h * 0.01, r.height() / 2 if t == "file" else h * 0.01)
                self._x_text(p, r.adjusted(h * 0.014, 0, -h * 0.014, 0), pt["label"], 0.02, ink, False,
                             al_c if t == "ph" else None)
            else:                                                   # game invite card
                inv = pt["inv"]
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(0, 0, 0, 80))
                p.drawRoundedRect(r, h * 0.014, h * 0.014)
                ch = r.height() * 0.84
                cr = QRectF(r.left() + r.height() * 0.08, r.top() + (r.height() - ch) / 2, ch * 0.75, ch)
                cov = _bpz_cover(self, inv, pt["from"])
                if cov is not None and not cov.isNull():
                    cp = QPainterPath()
                    cp.addRoundedRect(cr, h * 0.008, h * 0.008)
                    p.save()
                    p.setClipPath(cp, Qt.ClipOperation.IntersectClip)
                    sc = max(cr.width() / cov.width(), cr.height() / cov.height())
                    vw, vh = cr.width() / sc, cr.height() / sc
                    p.drawPixmap(cr, cov, QRectF((cov.width() - vw) / 2, (cov.height() - vh) / 2, vw, vh))
                    p.restore()
                else:
                    p.setBrush(QColor(255, 255, 255, 30))
                    p.drawRoundedRect(cr, h * 0.008, h * 0.008)
                tx = cr.right() + h * 0.014
                tw = r.right() - tx - h * 0.012
                self._x_text(p, QRectF(tx, r.top() + r.height() * 0.08, tw, r.height() * 0.26),
                             "Game invite" + (" (sent)" if mine else ""), 0.0165, ink)
                self._x_text(p, QRectF(tx, r.top() + r.height() * 0.32, tw, r.height() * 0.3), inv["game"] or "Steam game", 0.024, ink, True)
                self._x_text(p, QRectF(tx, r.top() + r.height() * 0.66, tw, r.height() * 0.26),
                             "A  Join" if (first and focus and not mine) else ("Press A to join" if not mine else ""), 0.0175, ink)
            yy += pt["h"] + gap * 0.6
        y -= gap
        first = False
    p.restore()
    labels = ("Sending..." if fr["sending"] else "Message", "Invite to game", "Send file", "Back")
    gb = h * 0.014
    bw = min(h * 0.22, (cw - 3 * gb) / 4)
    for j, t in enumerate(labels):
        r = QRectF(cx + j * (bw + gb), h * 0.81, bw, h * 0.065)
        self._x_pill(p, r, t, acc, sel=(self._zone == "content" and fr["cfocus"] == "btns" and fr["cbtn"] == j),
                     primary=(j == 0), size=0.019)
        self._xhits.append((r, ("cbtn", j)))


# ── chat input ──
@_bpm("_fr_act")
def _bpz_fr_act(self, name):
    fr = self._fr
    if not fr["chat"]:
        _bpz_o["_fr_act"](self, name)
        if fr["chat"]:                                   # a chat was just opened
            fr["cfocus"], fr["seen"] = "btns", None
        return
    uid, msgs = fr["chat"], fr["msgs"]
    if name == "back":
        if fr["cfocus"] == "msgs":
            fr["cfocus"] = "btns"
        else:
            fr["chat"] = None
    elif name == "alt":
        self._fr_compose(uid)
    elif name == "x":
        self._files_open(uid)
    elif fr["cfocus"] == "msgs":
        if name == "up":
            fr["moff"] = min(max(0, len(msgs) - 1), fr["moff"] + 1)
        elif name == "down":
            if fr["moff"] > 0:
                fr["moff"] -= 1
            else:
                fr["cfocus"] = "btns"
        elif name == "accept" and msgs:
            self._fr_msg_open(max(0, min(len(msgs) - 1, len(msgs) - 1 - fr["moff"])))
    else:
        if name in ("left", "right"):
            fr["cbtn"] = max(0, min(3, fr["cbtn"] + (1 if name == "right" else -1)))
        elif name == "up" and msgs:
            fr["cfocus"] = "msgs"
        elif name == "accept":
            b = fr["cbtn"]
            if b == 0:
                self._fr_compose(uid)
            elif b == 1:
                self._fr_invite(uid)
            elif b == 2:
                self._files_open(uid)
            else:
                fr["chat"] = None


@_bpm("_fr_msg_open")
def _bpz_msg_open(self, i):
    fr = self._fr
    mg = fr["msgs"][i]
    inv = parse_invite(str(mg.get("text") or ""))
    if inv:
        if mg.get("from") == fr["me"]:
            self._say("That's the invite you sent", 2500)
        else:
            self._say("Joining %s..." % (inv["game"] or "game"), 6000)
            try:
                accept_invite(inv["link"], inv["game"])
            except Exception as ex:
                self._say("Couldn't join: %s" % ex, 4000)
        return
    atts = [a for a in (mg.get("att") if isinstance(mg.get("att"), list) else []) if isinstance(a, dict)]
    if atts:
        self._att_open(atts, 0)
    else:
        self._say("Nothing to open on this message", 2000)


@_bpm("_x_tag")
def _bpz_x_tag(self, tag):
    fr = self._fr
    if self._tab == 2 and fr["chat"]:
        if tag[0] == "cmsg":
            fr["cfocus"], fr["moff"] = "msgs", len(fr["msgs"]) - 1 - tag[1]
            self._fr_act("accept")
            self.update()
            return
        if tag[0] == "cbtn":
            fr["cfocus"] = "btns"
    _bpz_o["_x_tag"](self, tag)


@_bpm("_x_hint")
def _bpz_hint(self):
    fr = self._fr
    if self._tab == 2 and fr["chat"]:
        if fr["cfocus"] == "msgs":
            return "Up / Down  Messages      A  Open / Join      Y  Message      X  Send file      B  Buttons"
        return "Up  Messages      Left / Right  Choose      A  Select      Y  Message      X  Send file      B  Back"
    return _bpz_o["_x_hint"](self)


@_bpm("_x_tick")
def _bpz_tick(self):
    _bpz_o["_x_tick"](self)
    fr = self._fr
    if self._tab == 2 and fr["chat"] and not fr["loading"]:
        msgs = fr["msgs"]
        last = msgs[-1] if msgs else None
        key = (fr["chat"], len(msgs), last.get("_key") if last else None)
        if fr["seen"] != key:
            if (fr["seen"] and fr["seen"][0] == fr["chat"] and last and last.get("from") != fr["me"]
                    and parse_invite(str(last.get("text") or ""))):
                self._say("New game invite!", 4000)
            fr["seen"] = key


# ── sending: messages, files, invites ──
@_bpm("_fr_send_raw")
def _bpz_send_raw(self, uid, fn, ok):
    fp = getattr(self._app, "friends_page", None)
    fr = self._fr
    if fp is None or fr["sending"]:
        return
    fr["sending"] = True
    self.update()

    def done(res, err):
        try:
            fr["sending"] = False
            if err:
                self._say("Couldn't send: %s" % err, 4000)
            else:
                self._say(ok, 2200)
                fr["moff"] = 0
                if fr["chat"] == uid:
                    self._fr_load_chat(uid, quiet=True)
            self.update()
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    fp._run(fn, done)


@_bpm("_fr_send_file")
def _bpz_send_file(self, uid, path):
    self._say("Sending %s..." % os.path.basename(path), 20000)
    self._fr_send_raw(uid, lambda: cloud_send_message(uid, "", [prepare_attachment(path)]), "File sent")


@_bpm("_fr_send_invite")
def _bpz_send_invite(self, uid, game, link, appid):
    text = make_invite_text(game, link, appid)
    self._fr_send_raw(uid, lambda: cloud_send_message(uid, text), "Invite sent")


@_bpm("_fr_invite")
def _bpz_invite(self, uid):
    fp = getattr(self._app, "friends_page", None)
    fr = self._fr
    if fp is None or fr["sending"]:
        return
    clip = normalize_steam_join(QApplication.clipboard().text())     # a link you just copied from the game
    fr["sending"] = True
    self._say("Finding your game and join link...", 20000)
    self.update()

    def done(info, err):
        try:
            fr["sending"] = False
            info = info or {}
            game, appid, link = info.get("game", ""), info.get("appid", 0), info.get("link", "") or clip
            self._say("")
            if game and link:
                self._fr_send_invite(uid, game, link, appid)
            else:
                self._fr_invite_ask(uid, game, appid, link)
            self.update()
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    fp._run(detect_invite_info, done, key="bp-invite")


@_bpm("_fr_invite_ask")
def _bpz_invite_ask(self, uid, game, appid, link):
    if not link:
        self._say("No join link found. Type one (steam://... or ip:port)", 5000)
        self._kb_open("Join link or ip:port", "", None, lambda t: self._fr_invite_link(uid, game, appid, t), 120)
    elif not game:
        self._kb_open("Game name", "", None, lambda t: self._fr_invite_name(uid, link, appid, t), 60)
    else:
        self._fr_send_invite(uid, game, link, appid)


@_bpm("_fr_invite_link")
def _bpz_invite_link(self, uid, game, appid, text):
    link = normalize_steam_join(text)
    if not link:
        self._say("That isn't a valid join link", 3000)
        return
    self._fr_invite_ask(uid, game, appid, link)


@_bpm("_fr_invite_name")
def _bpz_invite_name(self, uid, link, appid, text):
    game = (text or "").strip()[:60]
    if not game:
        return
    try:
        appid = appid or _steam_appid_for_title(game)
    except Exception:
        _log_exc("_bpz_invite_name")
    self._fr_send_invite(uid, game, link, appid)


# ── in-Big-Picture file browser (images / videos) ──
def _bpz_ls(path):
    if path is None:                                  # Windows drive list
        return [{"label": d + ":\\", "path": d + ":\\", "dir": True} for d in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                if os.path.exists(d + ":\\")]
    parent = os.path.dirname(path.rstrip("\\/")) or path
    if parent == path or parent.rstrip("\\/") == path.rstrip("\\/"):
        parent = None if sys.platform.startswith("win") else path
    ents = [{"label": ".. (up)", "path": parent, "dir": True}]
    dirs, files = [], []
    try:
        for e in os.scandir(path):
            if e.name.startswith("."):
                continue
            try:
                if e.is_dir():
                    dirs.append(e)
                elif os.path.splitext(e.name)[1].lower() in CHAT_IMAGE_EXTS + CHAT_VIDEO_EXTS:
                    files.append(e)
            except OSError:
                continue
    except OSError:
        _log_exc("_bpz_ls")
    dirs.sort(key=lambda e: e.name.lower())
    files.sort(key=lambda e: -e.stat().st_mtime if os.path.exists(e.path) else 0)
    ents += [{"label": e.name, "path": e.path, "dir": True} for e in dirs[:300]]
    for e in files[:300]:
        try:
            sz = e.stat().st_size
        except OSError:
            sz = 0
        ents.append({"label": e.name, "path": e.path, "dir": False, "size": sz})
    return ents


@_bpm("_files_open")
def _bpz_files_open(self, uid):
    home = os.path.expanduser("~")
    start = next((d for d in (os.path.join(home, "Pictures", "Screenshots"), os.path.join(home, "Pictures"),
                              os.path.join(home, "Videos"), os.path.join(home, "Downloads"), home) if os.path.isdir(d)), home)
    name = next((r["name"] for r in self._fr["rows"] if r["uid"] == uid), "friend")
    ents = _bpz_ls(start)
    self._ov = {"kind": "files", "uid": uid, "name": name, "dir": start, "ents": ents,
                "sel": 1 if len(ents) > 1 else 0, "scroll": 0, "rects": []}
    self.setCursor(Qt.CursorShape.BlankCursor)
    self.update()


def _bpz_files_cd(ov, path):
    ov["dir"] = path
    ov["ents"] = _bpz_ls(path)
    ov["sel"], ov["scroll"] = (1 if len(ov["ents"]) > 1 else 0), 0


@_bpm("_ov_act")
def _bpz_ov_act(self, name):
    ov = self._ov
    if ov is None or ov["kind"] not in ("view", "files"):
        _bpz_o["_ov_act"](self, name)
        return
    if name == "start":
        name = "accept"
    if ov["kind"] == "view":
        if name in ("back", "accept", "x", "alt"):
            self._ov = None
        elif name in ("left", "right"):
            self._att_step(ov, -1 if name == "left" else 1)
    else:
        ents, n = ov["ents"], len(ov["ents"])
        if name == "back":
            self._ov = None
        elif name in ("up", "down") and n:
            ov["sel"] = max(0, min(n - 1, ov["sel"] + (-1 if name == "up" else 1)))
        elif name == "left" and n:
            _bpz_files_cd(ov, ents[0]["path"])
        elif name in ("accept", "right") and n:
            e = ents[ov["sel"]]
            if e["dir"]:
                _bpz_files_cd(ov, e["path"])
            elif name == "accept":
                uid, path = ov["uid"], e["path"]
                self._ov = None
                self._fr_send_file(uid, path)
    self.update()


@_bpm("_paint_ov")
def _bpz_paint_ov(self, p, w, h, acc):
    ov = self._ov
    if ov["kind"] not in ("view", "files"):
        _bpz_o["_paint_ov"](self, p, w, h, acc)
        return
    ov["rects"] = []
    al_r = int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
    p.setPen(Qt.PenStyle.NoPen)
    if ov["kind"] == "view":
        p.fillRect(QRectF(0, 0, w, h), QColor(0, 0, 0, 238))
        pm = ov["pm"]
        area = QRectF(w * 0.05, h * 0.09, w * 0.9, h * 0.8)
        if not pm.isNull():
            s = min(area.width() / pm.width(), area.height() / pm.height())
            rw, rh = pm.width() * s, pm.height() * s
            p.drawPixmap(QRectF(area.center().x() - rw / 2, area.center().y() - rh / 2, rw, rh), pm, QRectF(pm.rect()))
        else:
            self._x_msg(p, area, "Couldn't show this image")
        att = ov["atts"][ov["i"]]
        self._x_text(p, QRectF(w * 0.05, h * 0.03, w * 0.7, h * 0.05), str(att.get("n") or "Image"), 0.026, QColor(235, 235, 245), True)
        self._x_text(p, QRectF(w * 0.75, h * 0.03, w * 0.2, h * 0.05), "%d / %d" % (ov["i"] + 1, len(ov["atts"])), 0.022,
                     QColor(170, 170, 200), False, al_r)
        p.setFont(self._font(h * 0.0185))
        p.setPen(QColor(150, 150, 175))
        p.drawText(QRectF(w * 0.05, h * 0.93, w * 0.9, h * 0.035), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                   "Left / Right  Previous / Next      A / B  Close")
        return
    bw, bh = w * 0.6, h * 0.84
    bx, by, pad = (w - bw) / 2, (h - bh) / 2, h * 0.03
    p.fillRect(QRectF(0, 0, w, h), QColor(0, 0, 0, 175))
    p.setBrush(QColor(14, 14, 26, 250))
    p.drawRoundedRect(QRectF(bx, by, bw, bh), h * 0.025, h * 0.025)
    self._x_text(p, QRectF(bx + pad, by + h * 0.02, bw - 2 * pad, h * 0.05), "Send a file to %s" % ov["name"], 0.03, QColor(245, 245, 252), True)
    self._x_text(p, QRectF(bx + pad, by + h * 0.07, bw - 2 * pad, h * 0.035), ov["dir"] or "This PC", 0.0185, QColor(170, 170, 200))
    top, bot, rh, pitch = by + h * 0.12, by + bh - h * 0.06, h * 0.058, h * 0.065
    ents = ov["ents"]
    vis = max(1, int((bot - top) // pitch))
    if ov["sel"] < ov["scroll"]:
        ov["scroll"] = ov["sel"]
    if ov["sel"] >= ov["scroll"] + vis:
        ov["scroll"] = ov["sel"] - vis + 1
    clip = QRectF(bx, top - h * 0.005, bw, bot - top + h * 0.01)
    p.save()
    p.setClipRect(clip)
    for n in range(ov["scroll"], min(len(ents), ov["scroll"] + vis + 1)):
        e = ents[n]
        r = QRectF(bx + pad, top + (n - ov["scroll"]) * pitch, bw - 2 * pad, rh)
        s = n == ov["sel"]
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(acc if s else QColor(255, 255, 255, 22))
        p.drawRoundedRect(r, rh * 0.25, rh * 0.25)
        col = QColor(_on_accent()) if s else QColor(235, 235, 245)
        self._x_text(p, QRectF(r.left() + pad * 0.6, r.top(), r.width() * 0.75, rh), ("[DIR] " if e["dir"] and n else "") + e["label"], 0.022, col, s)
        if not e["dir"]:
            self._x_text(p, QRectF(r.left(), r.top(), r.width() - pad * 0.6, rh), _fmt_size(e.get("size", 0)), 0.0185, col, False, al_r)
        ov["rects"].append((r.intersected(clip), ("row", n)))
    p.restore()
    if len(ents) <= 1:
        self._x_msg(p, QRectF(bx, top, bw, bh * 0.5), "No images or videos in this folder")
    p.setFont(self._font(h * 0.0185))
    p.setPen(QColor(150, 150, 175))
    p.drawText(QRectF(bx + pad, by + bh - h * 0.05, bw - 2 * pad, h * 0.035), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
               "Up / Down  Move      A  Open / Send      Left  Parent folder      B  Close")










# ── Big Picture: embedded windows, settings cog, download covers ──
# Every dialog the launcher opens with exec() / QMessageBox.xxx() / QInputDialog.getXxx() while Big Picture is on screen is
# shown INSIDE Big Picture (dimmed backdrop + panel) instead of as a separate window, so the X sidebar options (Launch Options,
# Switch Compatibility Tool, Uninstall confirmations, ...) and the new Settings cog stay in Big Picture. The controller moves
# focus around the panel (D-pad), A presses / opens, B closes. Text fields open Big Picture's on-screen keyboard with A.
# Native OS file/folder pickers (QFileDialog.getXxx) and external programs (Winetricks, browsers) can't be embedded.
from PyQt6.QtCore import QEventLoop
from PyQt6.QtGui import QTransform, QKeyEvent
from PyQt6.QtWidgets import QAbstractButton, QAbstractSpinBox, QAbstractSlider, QTextEdit, QPlainTextEdit, QColorDialog, QTabBar, QFrame, QLabel


def _bpe_draw_cog(p, r, col):
    c, R = r.center(), min(r.width(), r.height()) / 2.0
    path = QPainterPath()
    path.addEllipse(c, R * 0.64, R * 0.64)
    for i in range(8):
        tooth = QPainterPath()
        tooth.addRoundedRect(QRectF(-R * 0.18, -R, R * 0.36, R * 0.45), R * 0.07, R * 0.07)
        t = QTransform()
        t.translate(c.x(), c.y())
        t.rotate(i * 45)
        path = path.united(t.map(tooth))
    hole = QPainterPath()
    hole.addEllipse(c, R * 0.28, R * 0.28)
    path = path.subtracted(hole)
    p.save()
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(col)
    p.drawPath(path)
    p.restore()


def _bpe_draw_cover(p, r, pm, radius):
    p.save()
    clip = QPainterPath()
    clip.addRoundedRect(r, radius, radius)
    p.setClipPath(clip)
    if pm is None or pm.isNull():
        p.fillRect(r, QColor(255, 255, 255, 30))
    else:
        s = pm.size().scaled(r.size().toSize(), Qt.AspectRatioMode.KeepAspectRatioByExpanding)
        tgt = QRectF(r.center().x() - s.width() / 2.0, r.center().y() - s.height() / 2.0, s.width(), s.height())
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        p.drawPixmap(tgt, pm, QRectF(pm.rect()))
    p.restore()


# remember each download card's cover file (the Downloads tab in Big Picture shows it)
_bpe_dc_init = DownloadCard.__init__


def _bpe_dc_init2(self, title, download_url, expected_size=0, cover_path="", *a, **k):
    self.cover_path = cover_path or ""
    _bpe_dc_init(self, title, download_url, expected_size, cover_path, *a, **k)


DownloadCard.__init__ = _bpe_dc_init2

class _BPEmbHost(QWidget):
    """Full-size dimmed layer that holds one embedded window."""
    def __init__(self, bp):
        super().__init__(bp)
        self.setObjectName("BPEmbHost")
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setStyleSheet("#BPEmbHost { background: rgba(0, 0, 0, 190); }")
        self.setCursor(Qt.CursorShape.ArrowCursor)

    def mousePressEvent(self, e):
        e.accept()

    def mouseReleaseEvent(self, e):
        e.accept()

    def wheelEvent(self, e):
        e.accept()


_bpe_o = {n: getattr(_BigPicture, n) for n in (
    "__init__", "leave", "_act", "keyPressEvent", "mousePressEvent", "wheelEvent", "resizeEvent", "_kb_close", "_kb_submit",
    "_paint_extra", "_x_hint", "paintEvent")}


@_bpm("__init__")
def _bpe_init(self, app):
    self._embs = []                       # open embedded windows (last = on top)
    self._st = None                       # native Settings menu state
    self._hsel = None                     # header item picked by the controller: None | "cog" | "exit"
    self._barsel = 0                      # toolbar pill picked by the controller (zone "bar")
    self._cog_rect = QRectF()
    self._dl_pm = {}
    _bpe_o["__init__"](self, app)


@_bpm("_dl_cover")
def _bpe_dl_cover(self, path):
    pm = self._dl_pm.get(path)
    if pm is None:
        pm = QPixmap(path)
        self._dl_pm[path] = pm
    return pm


def _bpe_scale_font(widget, h):
    f = widget.font()
    sc = max(1.0, min(1.5, h / 900.0))
    if f.pointSizeF() > 0:
        f.setPointSizeF(f.pointSizeF() * sc)
        widget.setFont(f)


@_bpm("_emb_open")
def _bpe_emb_open(self, widget, title, kind, frac=None, on_close=None):
    """Put `widget` into a panel on top of Big Picture. Returns the entry dict."""
    W, H = max(400, self.width()), max(300, self.height())
    host = _BPEmbHost(self)
    host.setGeometry(0, 0, self.width(), self.height())
    acc = QApplication.palette().color(QPalette.ColorRole.Highlight)
    panel = QFrame(host)
    panel.setObjectName("BPEmbPanel")
    panel.setStyleSheet("#BPEmbPanel { background: rgb(14, 14, 26); border: 2px solid %s; border-radius: 18px; }" % acc.name())
    lay = QVBoxLayout(panel)
    lay.setContentsMargins(14, 12, 14, 10)
    lay.setSpacing(8)
    ent = {"kind": kind, "host": host, "panel": panel, "w": widget, "close": None, "on_close": on_close}
    head = QHBoxLayout()
    tl = QLabel(title or "")
    tl.setStyleSheet("font-weight: bold; color: rgb(245,245,252); background: transparent;")
    _bpe_scale_font(tl, H * 1.15)
    head.addWidget(tl, 1)
    if kind == "settings":
        cb = QPushButton("Close")
        cb.setCursor(Qt.CursorShape.PointingHandCursor)
        cb.clicked.connect(lambda _c=False, e=ent: e["close"]())
        head.addWidget(cb)
    lay.addLayout(head)
    scroll = QScrollArea()
    scroll.setWidgetResizable(True)
    scroll.setFrameShape(QFrame.Shape.NoFrame)
    scroll.setAlignment(Qt.AlignmentFlag.AlignCenter)
    scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
    lay.addWidget(scroll, 1)
    hint = QLabel("D-pad / arrows  Move      A / Enter  Select      B / Esc  Back")
    hint.setStyleSheet("color: rgb(150,150,175); background: transparent;")
    lay.addWidget(hint)
    ent["scroll"] = scroll
    ent["title"] = tl
    widget.setParent(None)
    widget.move(0, 0)
    scroll.setWidget(widget)
    _bpe_scale_font(panel, H)
    widget.adjustSize()
    want = widget.sizeHint().expandedTo(widget.minimumSizeHint())
    if frac:
        pw, ph = int(W * frac[0]), int(H * frac[1])
    else:
        pw = min(int(W * 0.92), max(380, want.width() + 60))
        ph = min(int(H * 0.92), want.height() + 130)
    panel.setFixedSize(pw, ph)
    g = QGridLayout(host)
    g.setContentsMargins(0, 0, 0, 0)
    g.addWidget(panel, 0, 0, Qt.AlignmentFlag.AlignCenter)
    self._embs.append(ent)
    host.show()
    host.raise_()
    widget.show()
    self.setCursor(Qt.CursorShape.ArrowCursor)
    QTimer.singleShot(0, lambda e=ent: self._emb_focus_first(e))
    self.update()
    return ent


@_bpm("_emb_focus_first")
def _bpe_focus_first(self, ent):
    try:
        w = ent["w"]
        fw = w.focusWidget()
        if fw is not None and fw.isVisible() and fw.isEnabled():
            fw.setFocus()
            return
        for b in w.findChildren(QPushButton):
            if b.isDefault() and b.isEnabled() and b.isVisible():
                b.setFocus()
                return
        for c in w.findChildren(QWidget):
            if c.isVisible() and c.isEnabled() and _bpe_focusable(c):
                c.setFocus()
                return
        w.setFocus()
    except RuntimeError:    # expected: the widget or object may already be deleted
        pass


def _bpe_focusable(c):
    try:
        if c.focusPolicy().value not in (1, 11, 15):
            return False
        par = c.parentWidget()
        if isinstance(par, (QAbstractSpinBox, QComboBox)):
            return False
        return True
    except RuntimeError:
        return False


@_bpm("_emb_close_ent")
def _bpe_close_ent(self, ent):
    if ent not in self._embs:
        return
    self._embs.remove(ent)
    w = ent["w"]
    try:
        ent["scroll"].takeWidget()
    except RuntimeError:    # expected: the widget or object may already be deleted
        pass
    try:
        w.hide()
        if ent.get("on_close"):
            ent["on_close"]()
    except RuntimeError:    # expected: the widget or object may already be deleted
        pass
    try:
        ent["host"].hide()
        ent["host"].setParent(None)
        ent["host"].deleteLater()
    except RuntimeError:    # expected: the widget or object may already be deleted
        pass
    if self._embs:
        self._emb_focus_first(self._embs[-1])
    else:
        self.setFocus()
    self.update()


@_bpm("_emb_run")
def _bpe_run(self, dlg):
    """Blocking replacement for QDialog.exec(): the dialog lives inside Big Picture until it is closed."""
    orig_parent, orig_flags = dlg.parentWidget(), dlg.windowFlags()
    loop = QEventLoop()
    ent = self._emb_open(dlg, dlg.windowTitle(), "dialog",
                         on_close=lambda: dlg.setParent(orig_parent, orig_flags))
    ent["loop"] = loop
    ent["close"] = dlg.reject
    dlg.finished.connect(loop.quit)
    loop.exec()
    try:
        dlg.finished.disconnect(loop.quit)
    except Exception:    # expected: cleanup that may already be done
        pass
    self._emb_close_ent(ent)
    return dlg.result()


_bpe_qdialog_exec = QDialog.exec


def _bpe_exec(self, *a):
    bp = _bpy_active_bp()
    if bp is None or self.isVisible() or self is None or isinstance(self, QFileDialog):
        return _bpe_qdialog_exec(self, *a)
    try:
        return bp._emb_run(self)
    except RuntimeError:
        return _bpe_qdialog_exec(self, *a)


QDialog.exec = _bpe_exec


def _bpe_mb_static(icon, default_buttons, orig):
    def f(parent, title, text, buttons=default_buttons, defaultButton=QMessageBox.StandardButton.NoButton, *a, **k):
        if _bpy_active_bp() is None:
            return orig(parent, title, text, buttons, defaultButton)
        box = QMessageBox(icon, title, text, buttons, parent)
        if defaultButton != QMessageBox.StandardButton.NoButton:
            box.setDefaultButton(defaultButton)
        return QMessageBox.StandardButton(box.exec())
    return staticmethod(f)


_SB = QMessageBox.StandardButton
QMessageBox.information = _bpe_mb_static(QMessageBox.Icon.Information, _SB.Ok, QMessageBox.information)
QMessageBox.warning = _bpe_mb_static(QMessageBox.Icon.Warning, _SB.Ok, QMessageBox.warning)
QMessageBox.critical = _bpe_mb_static(QMessageBox.Icon.Critical, _SB.Ok, QMessageBox.critical)
QMessageBox.question = _bpe_mb_static(QMessageBox.Icon.Question, _SB.Yes | _SB.No, QMessageBox.question)

_bpe_qi = {n: getattr(QInputDialog, n) for n in ("getText", "getInt", "getItem", "getMultiLineText")}


def _bpe_input(kind):
    orig = _bpe_qi[kind]

    def f(parent, title, label, *a, **k):
        if _bpy_active_bp() is None:
            return orig(parent, title, label, *a, **k)
        try:
            d = QInputDialog(parent)
            d.setWindowTitle(title)
            d.setLabelText(label)
            if kind == "getText":
                echo = a[0] if len(a) > 0 else k.get("echo", QLineEdit.EchoMode.Normal)
                d.setTextEchoMode(echo)
                d.setTextValue(a[1] if len(a) > 1 else k.get("text", ""))
            elif kind == "getMultiLineText":
                d.setOption(QInputDialog.InputDialogOption.UsePlainTextEditForTextInput, True)
                d.setTextValue(a[0] if len(a) > 0 else k.get("text", ""))
            elif kind == "getInt":
                d.setInputMode(QInputDialog.InputMode.IntInput)
                d.setIntRange(a[1] if len(a) > 1 else k.get("minValue", -2147483647), a[2] if len(a) > 2 else k.get("maxValue", 2147483647))
                d.setIntStep(a[3] if len(a) > 3 else k.get("step", 1))
                d.setIntValue(a[0] if len(a) > 0 else k.get("value", 0))
            else:
                items = list(a[0] if len(a) > 0 else k.get("items", []))
                d.setComboBoxItems(items)
                cur = a[1] if len(a) > 1 else k.get("current", 0)
                if isinstance(cur, int) and 0 <= cur < len(items):
                    d.setTextValue(items[cur])
                d.setComboBoxEditable(a[2] if len(a) > 2 else k.get("editable", True))
        except Exception:
            return orig(parent, title, label, *a, **k)
        ok = bool(d.exec())
        if kind == "getInt":
            return d.intValue(), ok
        return d.textValue(), ok
    return staticmethod(f)


for _n in _bpe_qi:
    setattr(QInputDialog, _n, _bpe_input(_n))

_bpe_getcolor = QColorDialog.getColor


def _bpe_get_color(initial=None, parent=None, title="", options=None):
    if _bpy_active_bp() is None:
        args = [x for x in (initial, parent, title, options) if x is not None]
        return _bpe_getcolor(*args)
    d = QColorDialog(initial if initial is not None else QColor(Qt.GlobalColor.white), parent)
    if title:
        d.setWindowTitle(title)
    if options is not None:
        d.setOptions(options)
    return d.currentColor() if d.exec() else QColor()


QColorDialog.getColor = staticmethod(_bpe_get_color)


# ── controller / keyboard navigation inside an embedded window ──
def _bpe_key(widget, key):
    for t in (QEvent.Type.KeyPress, QEvent.Type.KeyRelease):
        QApplication.sendEvent(widget, QKeyEvent(t, key, Qt.KeyboardModifier.NoModifier))


def _bpe_scroll_to(w):
    par = w.parentWidget()
    while par is not None:
        if isinstance(par, QScrollArea):
            try:
                par.ensureWidgetVisible(w, 40, 90)
            except Exception:
                _log_exc("_bpe_scroll_to")
            break
        par = par.parentWidget()


@_bpm("_emb_move")
def _bpe_move(self, name):
    ent = self._embs[-1]
    root = ent["panel"]
    cands = [c for c in root.findChildren(QWidget) if c.isVisible() and c.isEnabled() and _bpe_focusable(c)]
    if not cands:
        return
    cur = QApplication.focusWidget()

    def ctr(c):
        r = c.rect()
        pt = c.mapTo(root, QPoint(r.width() // 2, r.height() // 2))
        return pt.x(), pt.y()
    if cur not in cands:
        cands.sort(key=lambda c: (ctr(c)[1], ctr(c)[0]))
        tgt = cands[0]
    else:
        cx, cy = ctr(cur)
        best, bs = None, None
        for c in cands:
            if c is cur:
                continue
            x, y = ctr(c)
            dx, dy = x - cx, y - cy
            if name == "down" and dy > 2:
                sc = dy + 3 * abs(dx)
            elif name == "up" and dy < -2:
                sc = -dy + 3 * abs(dx)
            elif name == "right" and dx > 2:
                sc = dx + 3 * abs(dy)
            elif name == "left" and dx < -2:
                sc = -dx + 3 * abs(dy)
            else:
                continue
            if bs is None or sc < bs:
                best, bs = c, sc
        if best is None:
            if name in ("up", "down"):                      # nothing further: scroll the area instead
                par = cur.parentWidget()
                while par is not None and not isinstance(par, QScrollArea):
                    par = par.parentWidget()
                if par is not None:
                    sb = par.verticalScrollBar()
                    sb.setValue(sb.value() + (120 if name == "down" else -120))
            return
        tgt = best
    tgt.setFocus()
    _bpe_scroll_to(tgt)


@_bpm("_emb_text")
def _bpe_text(self, w):
    if isinstance(w, QLineEdit):
        if w.isReadOnly():
            return
        text, setter = w.text(), w.setText
    else:
        text, setter = w.toPlainText(), w.setPlainText
    title = (w.placeholderText() if isinstance(w, QLineEdit) else "") or "Type text"
    for e in self._embs:
        e["host"].hide()

    def done(t, w=w, setter=setter):
        setter(t)
        QTimer.singleShot(0, lambda: w.setFocus())
    self._kb_open(title, text, None, done, 500)


@_bpm("_emb_show_hosts")
def _bpe_show_hosts(self):
    if self._kb is None:
        for e in self._embs:
            e["host"].show()
            e["host"].raise_()


@_bpm("_emb_act")
def _bpe_emb_act(self, name):
    pop = QApplication.activePopupWidget()
    if pop is not None:                                      # an open drop-down list
        k = {"up": Qt.Key.Key_Up, "down": Qt.Key.Key_Down, "left": Qt.Key.Key_Up, "right": Qt.Key.Key_Down,
             "accept": Qt.Key.Key_Return, "start": Qt.Key.Key_Return, "back": Qt.Key.Key_Escape}.get(name)
        if k is not None:
            _bpe_key(pop, k)
        return
    ent = self._embs[-1]
    if name == "back":
        ent["close"]()
        return
    cur = QApplication.focusWidget()
    inside = cur is not None and ent["panel"].isAncestorOf(cur)
    if name in ("accept", "start"):
        if not inside:
            self._emb_focus_first(ent)
            return
        if isinstance(cur, QAbstractButton):
            cur.click()
        elif isinstance(cur, QComboBox):
            cur.showPopup()
        elif isinstance(cur, (QLineEdit, QTextEdit, QPlainTextEdit)):
            self._emb_text(cur)
        elif isinstance(cur, QAbstractSpinBox):
            pass
        else:
            _bpe_key(cur, Qt.Key.Key_Return)
        return
    if name in ("up", "down", "left", "right"):
        if inside and name in ("left", "right") and isinstance(cur, (QAbstractSlider, QAbstractSpinBox, QTabBar)):
            _bpe_key(cur, Qt.Key.Key_Left if name == "left" else Qt.Key.Key_Right)
            return
        if inside and name in ("up", "down") and isinstance(cur, QAbstractItemView):
            before = cur.currentIndex()
            _bpe_key(cur, Qt.Key.Key_Up if name == "up" else Qt.Key.Key_Down)
            if cur.currentIndex() != before:
                return
        if inside and name in ("up", "down") and isinstance(cur, QAbstractSpinBox):
            _bpe_key(cur, Qt.Key.Key_Up if name == "up" else Qt.Key.Key_Down)
            return
        self._emb_move(name)


@_bpm("_act")
def _bpe_act(self, name):
    if self._embs and self._kb is None:
        if not self._from_key:
            self._pad_last = True
        self.setCursor(Qt.CursorShape.ArrowCursor)
        self._emb_act(name)
        return
    if self._st is not None and self._kb is None:
        if not self._from_key:
            self._pad_last = True
        self._st_act(name)
        return
    if self._zone != "tabs":
        self._hsel = None
    plain = (self._kb is None and not self._embs and self._st is None and self._ov is None and self._detail is None)
    if not plain:
        _bpe_o["_act"](self, name)
        return
    if not self._from_key:
        self._pad_last = True
    if name == "start":                                     # Start button = Settings
        self._settings_open()
        return
    if self._zone == "tabs":                                # header: tabs ... cog wheel, Exit
        hs = self._hsel
        if hs:
            self.setCursor(Qt.CursorShape.BlankCursor)
            if name == "left":
                self._hsel = "cog" if hs == "exit" else None
            elif name == "right":
                self._hsel = "exit" if hs == "cog" else hs
            elif name in ("accept", "start"):
                if hs == "cog":
                    self._settings_open()
                else:
                    self.leave(True)
                    return
            elif name in ("down", "back", "prev", "next", "alt", "x"):
                self._hsel = None
                _bpe_o["_act"](self, name)
                return
            self.update()
            return
        if name == "right" and self._tab == len(self._tab_labels()) - 1:
            self.setCursor(Qt.CursorShape.BlankCursor)
            self._hsel = "cog"
            self.update()
            return
    if self._tab >= 2:
        if self._zone == "bar":                             # toolbar pills (Category / Search / Sort / ...) of the tab
            self.setCursor(Qt.CursorShape.BlankCursor)
            items = self._bar_items()
            if not items:
                self._zone = "content"
            else:
                self._barsel = max(0, min(len(items) - 1, self._barsel))
                if name == "left":
                    self._barsel = max(0, self._barsel - 1)
                elif name == "right":
                    self._barsel = min(len(items) - 1, self._barsel + 1)
                elif name == "up":
                    self._zone = "tabs"
                elif name == "down":
                    self._zone = "content"
                elif name in ("accept", "start"):
                    tag = items[self._barsel][1]
                    if tag[0] == "wback":
                        self._zone = "content"
                    try:
                        self._x_tag(tag)
                    except (IndexError, KeyError):    # expected: missing or odd value: the default is fine
                        pass
                elif name in ("prev", "next"):
                    self._switch_tab(self._tab + (1 if name == "next" else -1))
                    self._zone = "content"
                elif name == "back":
                    self._zone = "content"
            self.update()
            return
        was = self._zone
        _bpe_o["_act"](self, name)
        if name == "up" and was == "content" and self._zone == "tabs" and self._bar_items():
            self._zone, self._barsel = "bar", 0             # from the top of the grid go to the toolbar first
            self.update()
        return
    _bpe_o["_act"](self, name)


_BPE_BAR_TAGS = ("fgtag", "fgsearch", "wback", "wsort", "wsearch", "gall", "gsearch")


@_bpm("_bar_items")
def _bpe_bar_items(self):
    items = [(r, t) for r, t in getattr(self, "_xhits", []) if t and t[0] in _BPE_BAR_TAGS]
    items.sort(key=lambda it: it[0].left())
    return items


@_bpm("_paint_extra")
def _bpe_paint_extra(self, p, w, h, m, acc, k):
    _bpe_o["_paint_extra"](self, p, w, h, m, acc, k)
    if self._tab >= 2 and self._zone == "bar":
        items = self._bar_items()
        if items:
            r = items[max(0, min(len(items) - 1, self._barsel))][0]
            self._x_ring(p, r, r.height() / 2)


@_bpm("_x_hint")
def _bpe_hint(self):
    if self._zone == "bar":
        return "Left / Right  Choose      A  Press      Up  Tabs      Down  Back to the list      LB / RB  Switch tab"
    if self._zone == "tabs" and self._hsel:
        return "Left / Right  Choose      A  Open      Down  Content"
    return _bpe_o["_x_hint"](self)


@_bpm("keyPressEvent")
def _bpe_keypress(self, e):
    k, K = e.key(), Qt.Key
    if self._embs and self._kb is None:
        name = {K.Key_Escape: "back", K.Key_Up: "up", K.Key_Down: "down", K.Key_Left: "left", K.Key_Right: "right"}.get(k)
        if name:
            self._emb_act(name)
        e.accept()
        return
    if self._st is not None and self._kb is None:
        self._pad_last = False
        name = {K.Key_Up: "up", K.Key_Down: "down", K.Key_Left: "left", K.Key_Right: "right", K.Key_Return: "accept",
                K.Key_Enter: "accept", K.Key_Space: "accept", K.Key_Escape: "back", K.Key_Backspace: "back",
                K.Key_F11: "back"}.get(k)
        if name:
            self._st_act(name)
        e.accept()
        return
    if (k == K.Key_Comma and (e.modifiers() & Qt.KeyboardModifier.ControlModifier) and self._kb is None
            and self._ov is None and self._detail is None):
        self._settings_open()
        return
    _bpe_o["keyPressEvent"](self, e)


@_bpm("mousePressEvent")
def _bpe_mouse(self, e):
    if self._embs and self._kb is None:
        return
    if self._st is not None and self._kb is None:
        pt = e.position()
        for r, tag in reversed(self._st["rects"]):
            if r.contains(pt):
                self._st_click(tag)
                return
        self._st_close()
        return
    if (self._kb is None and self._ov is None and self._detail is None and self._cog_rect.contains(e.position())):
        self._settings_open()
        return
    _bpe_o["mousePressEvent"](self, e)


@_bpm("wheelEvent")
def _bpe_wheel(self, e):
    if self._embs:
        return
    if self._st is not None and self._kb is None:
        self._st_act("up" if e.angleDelta().y() > 0 else "down")
        return
    _bpe_o["wheelEvent"](self, e)


@_bpm("resizeEvent")
def _bpe_resize(self, e):
    _bpe_o["resizeEvent"](self, e)
    for ent in getattr(self, "_embs", ()):
        try:
            ent["host"].setGeometry(0, 0, self.width(), self.height())
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass


@_bpm("_kb_close")
def _bpe_kb_close(self):
    _bpe_o["_kb_close"](self)
    self._emb_show_hosts()


@_bpm("_kb_submit")
def _bpe_kb_submit(self):
    _bpe_o["_kb_submit"](self)
    self._emb_show_hosts()


@_bpm("leave")
def _bpe_leave(self, show_main=True):
    self._st = None
    for ent in list(reversed(self._embs)):                  # close everything that is embedded before leaving
        try:
            ent["close"]()
        except Exception:
            _log_exc("_bpe_leave")
    for ent in list(self._embs):
        self._emb_close_ent(ent)
    _bpe_o["leave"](self, show_main)


# ── Settings: a native Big Picture menu (cog wheel in the header,
# Start button, Ctrl+,). The rows are read from the launcher's Settings page, so every setting that page has is here and
# changing one here changes the real setting (the controls of the real page are driven, nothing is duplicated).
def _bpe_hidden(w, stop):
    while w is not None and w is not stop:
        if w.isHidden():
            return True
        w = w.parentWidget()
    return False


def _bpe_st_scan(sp):
    """[{'title', 'desc', 'ctrls': [widgets]}] in page order."""
    rows, cur, cur_panel = [], None, None

    def panel_of(w):
        par = w.parentWidget()
        while par is not None:
            if par.objectName() == "Panel":
                return par
            par = par.parentWidget()
        return None
    try:
        kids = sp._content.findChildren(QWidget)
    except Exception:
        kids = sp.findChildren(QWidget)
    for c in kids:
        try:
            if isinstance(c, QLabel):
                if c.objectName() == "RowTitle" and c.text().strip():
                    cur = {"title": c.text().strip(), "desc": "", "ctrls": []}
                    cur_panel = panel_of(c)
                    rows.append(cur)
                elif c.objectName() == "RowDesc" and cur is not None and not cur["desc"] and not cur["ctrls"] \
                        and panel_of(c) is cur_panel:
                    cur["desc"] = c.text().strip()
                continue
            if cur is None or _bpe_hidden(c, sp._content):
                continue
            if isinstance(c.parentWidget(), (QAbstractSpinBox, QComboBox)):
                continue
            if isinstance(c, (QComboBox, QAbstractButton, QLineEdit)) and panel_of(c) is cur_panel:
                cur["ctrls"].append(c)
        except RuntimeError:
            continue
    return [r for r in rows if r["ctrls"]]


def _bpe_ctl_text(c):
    try:
        if isinstance(c, QComboBox):
            return c.currentText() or "-"
        if isinstance(c, QLineEdit):
            t = c.text()
            if c.echoMode() != QLineEdit.EchoMode.Normal and t:
                return "*" * min(12, len(t))
            return t or c.placeholderText() or "Edit"
        t = c.text().replace("&", "").strip()
        if not t:
            t = ("On" if c.isChecked() else "Off") if c.isCheckable() else "..."
        return t
    except RuntimeError:
        return "?"


@_bpm("_settings_open")
def _bpe_settings_open(self):
    if self._embs or self._st is not None or self._kb is not None or self._detail is not None or self._ov is not None:
        return
    sp = getattr(self._app, "settings_page", None)
    rows = _bpe_st_scan(sp) if sp is not None else []
    if not rows:
        self._say("Settings aren't available", 2500)
        self.update()
        return
    self._st = {"rows": rows, "sel": 0, "btn": 0, "scroll": 0, "rects": []}
    self.update()


@_bpm("_st_close")
def _bpe_st_close(self):
    self._st = None
    self.update()


@_bpm("_st_press")
def _bpe_st_press(self, c):
    try:
        if not c.isEnabled():
            return
        if isinstance(c, QComboBox):
            n = c.count()
            if n:
                c.setCurrentIndex((c.currentIndex() + 1) % n)
        elif isinstance(c, QAbstractButton):
            c.click()
        elif isinstance(c, QLineEdit):
            if c.isReadOnly():
                return
            title = c.placeholderText() or "Type text"

            def done(t, c=c):
                c.setText(t)
                try:
                    c.editingFinished.emit()
                except Exception:
                    _log_exc("done")
                try:
                    c.returnPressed.emit()
                except Exception:
                    _log_exc("done")
            self._kb_open(title, c.text(), None, done, 500)
    except RuntimeError:    # expected: the widget or object may already be deleted
        pass
    self.update()


@_bpm("_st_click")
def _bpe_st_click(self, tag):
    st = self._st
    if tag[0] == "close":
        self._st_close()
    elif tag[0] == "row":
        st["sel"], st["btn"] = tag[1], 0
    elif tag[0] == "pill":
        st["sel"], st["btn"] = tag[1], tag[2]
        self._st_press(st["rows"][tag[1]]["ctrls"][tag[2]])
    self.update()


@_bpm("_st_act")
def _bpe_st_act(self, name):
    st = self._st
    if st is None:
        return
    if name == "start":
        name = "accept"
    rows = st["rows"]
    row = rows[st["sel"]]
    ctrls = row["ctrls"]
    if name in ("back", "x"):
        self._st_close()
        return
    if name in ("up", "down"):
        st["sel"] = max(0, min(len(rows) - 1, st["sel"] + (-1 if name == "up" else 1)))
        st["btn"] = 0
    elif name in ("left", "right"):
        d = -1 if name == "left" else 1
        if len(ctrls) == 1 and isinstance(ctrls[0], QComboBox):      # a single drop-down: Left / Right change its value
            c = ctrls[0]
            if c.count() and c.isEnabled():
                c.setCurrentIndex(max(0, min(c.count() - 1, c.currentIndex() + d)))
        else:
            st["btn"] = max(0, min(len(ctrls) - 1, st["btn"] + d))
    elif name == "accept":
        self._st_press(ctrls[max(0, min(len(ctrls) - 1, st["btn"]))])
    self.update()


@_bpm("paintEvent")
def _bpe_paint(self, e):
    _bpe_o["paintEvent"](self, e)
    if self._st is None or self._kb is not None:
        return
    p = QPainter(self)
    p.setRenderHints(QPainter.RenderHint.Antialiasing | QPainter.RenderHint.TextAntialiasing)
    try:
        self._paint_st(p, self.width(), self.height(), QApplication.palette().color(QPalette.ColorRole.Highlight))
    finally:
        p.end()


@_bpm("_paint_st")
def _bpe_paint_st(self, p, w, h, acc):
    st = self._st
    st["rects"] = []
    rows = st["rows"]
    p.fillRect(QRectF(0, 0, w, h), QColor(0, 0, 0, 205))
    cx, cw = w * 0.14, w * 0.72
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(14, 14, 26, 252))
    p.drawRoundedRect(QRectF(cx - h * 0.035, h * 0.04, cw + h * 0.07, h * 0.92), h * 0.025, h * 0.025)
    self._x_text(p, QRectF(cx, h * 0.06, cw * 0.6, h * 0.07), "Settings", 0.038, QColor(245, 245, 252), True)
    cr = QRectF(cx + cw - h * 0.16, h * 0.072, h * 0.16, h * 0.05)
    self._x_pill(p, cr, "Close", acc, size=0.02)
    st["rects"].append((cr, ("close",)))
    top, bot, pitch, rh = h * 0.16, h * 0.9, h * 0.1, h * 0.088
    vis = max(1, int((bot - top) // pitch))
    sel = max(0, min(len(rows) - 1, st["sel"]))
    if sel < st["scroll"]:
        st["scroll"] = sel
    if sel >= st["scroll"] + vis:
        st["scroll"] = sel - vis + 1
    clip = QRectF(cx - h * 0.02, top - h * 0.01, cw + h * 0.04, bot - top + h * 0.02)
    p.save()
    p.setClipRect(clip)
    for n in range(st["scroll"], min(len(rows), st["scroll"] + vis + 1)):
        row = rows[n]
        r = QRectF(cx, top + (n - st["scroll"]) * pitch, cw, rh)
        s = n == sel
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 48 if s else 22))
        p.drawRoundedRect(r, rh * 0.18, rh * 0.18)
        if s:
            self._x_ring(p, r, rh * 0.18)
        st["rects"].append((r.intersected(clip), ("row", n)))
        # controls on the right
        ctrls = row["ctrls"][:4]
        pf = QFontMetrics(self._font(h * 0.02, True))
        pb, gap = rh * 0.62, h * 0.01
        widths = []
        for c in ctrls:
            t = _bpe_ctl_text(c)
            widths.append(max(h * 0.15, min(h * 0.34, pf.horizontalAdvance(t) + h * 0.07)))
        x = r.right() - rh * 0.2 - (sum(widths) + gap * (len(widths) - 1))
        single_combo = len(ctrls) == 1 and isinstance(ctrls[0], QComboBox)
        for j, c in enumerate(ctrls):
            pr = QRectF(x, r.top() + (rh - pb) / 2, widths[j], pb)
            x += widths[j] + gap
            txt = _bpe_ctl_text(c)
            if single_combo and s:
                txt = "<  %s  >" % txt
            txt = pf.elidedText(txt, Qt.TextElideMode.ElideRight, int(widths[j] - h * 0.03))
            try:
                on = isinstance(c, QAbstractButton) and c.isCheckable() and c.isChecked()
            except RuntimeError:
                on = False
            self._x_pill(p, pr, txt, acc, sel=(s and (j == st["btn"] or single_combo)), primary=on, size=0.02)
            st["rects"].append((pr.intersected(clip), ("pill", n, j)))
        tw = x - gap - (r.left() + rh * 0.3)
        left_w = r.right() - rh * 0.2 - (sum(widths) + gap * (len(widths) - 1)) - (r.left() + rh * 0.3) - rh * 0.2
        self._x_text(p, QRectF(r.left() + rh * 0.3, r.top() + rh * 0.08, left_w, rh * 0.46), row["title"], 0.0245, QColor(245, 245, 252), True)
        if row["desc"]:
            self._x_text(p, QRectF(r.left() + rh * 0.3, r.top() + rh * 0.52, left_w, rh * 0.38), row["desc"], 0.0165, QColor(150, 150, 175))
    p.restore()
    p.setFont(self._font(h * 0.0185))
    p.setPen(QColor(150, 150, 175))
    p.drawText(QRectF(cx, h * 0.915, cw, h * 0.035), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
               "Up / Down  Move      Left / Right  Change      A  Select      B  Close")


# ── Admin panel + bans ──
# The admin panel is for ADMIN_UID only: the button is hidden for everyone else AND every call refuses to run for other
# accounts. The real gate is the Firebase database rules (see firebase_rules_admin.txt): the client check is only UI.
# Bans: bans/<uid> in the database. A banned launcher crashes on startup, and a local ban.lock keeps it crashing after
# logging out (any account) until the ban is removed. Running launchers also check every ~45 s and crash when banned.
ADMIN_UID = "XcqSn5Zvhsf1npoNl3FNG1bKpU63"
_ADMIN_UIDS = {ADMIN_UID, "LtVp5drXTcfedfGmWGMhHSVzGiU2", "uL9mPMvEjzLwxyeROUSylV6ra123"}   # all can open the admin panel

def _adm_is_admin():
    try:
        return (load_account() or {}).get("uid", "") in _ADMIN_UIDS
    except Exception:
        return False

def _adm_require():
    if not _adm_is_admin():
        raise CloudError("Admin only.", "NOT_ADMIN")

# ── ban lock (survives log out, lives next to launcher.json) ──
def _ban_lock_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "ban.lock")

def _ban_lock_read():
    try:
        with open(_ban_lock_path(), encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict) and d.get("uid"):
            return d
    except Exception:    # expected: file may not exist yet or be unreadable
        pass
    return None

def _ban_lock_write(uid):
    try:
        os.makedirs(os.path.dirname(_ban_lock_path()), exist_ok=True)
        with open(_ban_lock_path(), "w", encoding="utf-8") as f:
            json.dump({"uid": uid}, f)
    except OSError:    # expected: file may not exist yet or be unreadable
        pass

def _ban_lock_clear():
    try:
        os.remove(_ban_lock_path())
    except OSError:    # expected: cleanup that may already be done
        pass

def _ban_fetch(uid):
    """bans/<uid> without logging in (the rules let anyone read bans). None = not banned. Raises CloudError."""
    base = FIREBASE_DB_URL.strip().rstrip("/")
    return _http_json(f"{base}/bans/{urllib.parse.quote(uid, safe='')}.json", timeout=8)

def _ban_crash():
    try:
        sys.stderr.write("NCZ Games Launcher: this account is banned.\n")
        sys.stderr.flush()
    except Exception:
        _log_exc("_ban_crash")
    os._exit(1)

def _ban_check_startup():
    """Runs first thing in main(). Crashes if the locked-out uid or the logged-in account is banned."""
    if not cloud_configured():
        return
    lock = _ban_lock_read()
    acct = load_account()
    uids = []
    if lock:
        uids.append(lock["uid"])
    if acct and acct.get("uid") and acct["uid"] not in uids:
        uids.append(acct["uid"])
    lock_unknown = False
    for uid in uids:
        try:
            banned = _ban_fetch(uid)
        except CloudError:
            if lock and uid == lock["uid"]:
                lock_unknown = True          # can't tell (offline): stay locked
            continue
        if banned:
            _ban_lock_write(uid)
            _ban_crash()
        elif lock and uid == lock["uid"]:
            _ban_lock_clear()                # unbanned
            lock = None
    if lock and lock_unknown:
        _ban_crash()

class _AcctBus(QObject):
    changed = pyqtSignal()

def _acct_watch_start(window):
    """Background: crash when the account gets banned while running; pick up admin edits to the profile / library."""
    bus = _AcctBus(window)
    bus.changed.connect(lambda: window.account_page.account_changed.emit())
    window._acct_bus = bus

    def loop():
        last_prof = None
        while True:
            time.sleep(45)
            try:
                acct = load_account()
                if not acct:
                    continue
                uid = acct["uid"]
                try:
                    if _ban_fetch(uid):
                        _ban_lock_write(uid)
                        _ban_crash()
                except CloudError:    # expected: offline or timed out
                    pass
                token, _u = get_id_token()
                upd = _http_json(_fdb(f"users/{uid}/profile/updated", token))
                lib = _http_json(_fdb(f"users/{uid}/library/updated", token))
                changed = False
                if last_prof is not None and upd != last_prof:
                    cloud_pull_profile()
                    changed = True
                last_prof = upd
                if lib is not None and lib != _lib_load_state().get("rev"):
                    changed = True
                if changed:
                    bus.changed.emit()
            except Exception:    # expected: offline or the server did not answer
                pass
    threading.Thread(target=loop, daemon=True).start()

# ── admin cloud operations (all need the admin's token + the admin database rules) ──
def _adm_sv():
    return {".sv": "timestamp"}

def _adm_fetch_users():
    _adm_require()
    token, _me = get_id_token()
    shallow = _http_json(_fdb("users", token, "shallow=true"), timeout=40)
    uids = sorted(shallow) if isinstance(shallow, dict) else []
    bans = _http_json(_fdb("bans", token))
    bans = bans if isinstance(bans, dict) else {}

    def one(u):
        try:
            name = _http_json(_fdb(f"users/{u}/profile/username", token))
        except CloudError:
            name = None
        return {"uid": u, "username": name if isinstance(name, str) else "", "banned": u in bans, "ban": bans.get(u)}
    with ThreadPoolExecutor(max_workers=8) as ex:
        return list(ex.map(one, uids))

def _adm_fetch_profile(uid):
    _adm_require()
    token, _me = get_id_token()
    d = _http_json(_fdb(f"users/{uid}/profile", token))
    d = d if isinstance(d, dict) else {}
    return {"username": d.get("username") if isinstance(d.get("username"), str) else "",
            "png": _decode_photo(d.get("photo")),
            "country": str(d.get("country") or "").upper()}

def _adm_patch_both(uid, fields):
    """Writes to the account's profile and to the public copy friends read."""
    _adm_require()
    token, _me = get_id_token()
    _http_json(_fdb(f"users/{uid}/profile", token), "PATCH", dict(fields, updated=_adm_sv()))
    try:
        _http_json(_fdb(f"public/{uid}", token), "PATCH", fields)
    except CloudError:    # expected: offline or timed out
        pass

def _adm_set_username(uid, name):
    err = validate_username(name)
    if err:
        raise CloudError(err, "BAD_NAME")
    _adm_patch_both(uid, {"username": name})

def _adm_set_picture(uid, png):
    _adm_patch_both(uid, {"photo": base64.b64encode(png).decode("ascii") if png else None})

def _adm_set_country(uid, code):
    code = str(code or "").upper()
    _adm_patch_both(uid, {"country": code if code in COUNTRIES else None})

def _adm_get_library(uid):
    _adm_require()
    token, _me = get_id_token()
    d = _http_json(_fdb(f"users/{uid}/library", token))
    d = d if isinstance(d, dict) else {}
    return _lib_as_dict(d.get("games")), _lib_as_dict(d.get("fan"))

def _adm_save_library(uid, games, fan):
    _adm_require()
    token, _me = get_id_token()
    _http_json(_fdb(f"users/{uid}/library", token), "PATCH",
               {"updated": _adm_sv(), "device": "Admin", "games": games or None, "fan": fan or None})

def _adm_get_friends(uid):
    _adm_require()
    token, _me = get_id_token()
    ids = _http_json(_fdb(f"friends/{uid}", token))
    ids = sorted(ids) if isinstance(ids, dict) else []

    def one(f):
        try:
            n = _http_json(_fdb(f"users/{f}/profile/username", token))
        except CloudError:
            n = None
        return {"uid": f, "username": n if isinstance(n, str) else ""}
    with ThreadPoolExecutor(max_workers=6) as ex:
        return list(ex.map(one, ids))

def _adm_remove_friend(uid, other):
    _adm_require()
    token, _me = get_id_token()
    _http_json(_fdb(f"friends/{uid}/{other}", token), "DELETE")
    _http_json(_fdb(f"friends/{other}/{uid}", token), "DELETE")

def _adm_add_friend(uid, other):
    _adm_require()
    if uid == other:
        raise CloudError("An account can't be its own friend.", "SELF")
    token, _me = get_id_token()
    _http_json(_fdb(f"friends/{uid}/{other}", token), "PUT", True)
    _http_json(_fdb(f"friends/{other}/{uid}", token), "PUT", True)
    for a, b in ((uid, other), (other, uid)):
        try:
            _http_json(_fdb(f"requests/{a}/{b}", token), "DELETE")
        except CloudError:    # expected: offline or timed out
            pass

def _adm_ban(uid, reason):
    _adm_require()
    if uid in _ADMIN_UIDS:
        raise CloudError("You can't ban an admin account.", "SELF")
    token, _me = get_id_token()
    _http_json(_fdb(f"bans/{uid}", token), "PUT",
               {"reason": (reason or "")[:200], "by": (load_account() or {}).get("uid", ADMIN_UID), "time": _adm_sv()})
    try:
        _http_json(_fdb(f"public/{uid}", token), "PATCH", {"seen": 0, "playing": "", "idle": False})
    except CloudError:    # expected: offline or timed out
        pass

def _adm_unban(uid):
    _adm_require()
    token, _me = get_id_token()
    _http_json(_fdb(f"bans/{uid}", token), "DELETE")

def _adm_get_theme_override(uid):
    _adm_require()
    token, _me = get_id_token()
    v = _http_json(_fdb(f"themeunlock/{uid}", token))
    return v if isinstance(v, bool) else None

def _adm_set_theme_override(uid, value):
    """True = unlock custom themes, False = lock them, None = back to the 8 hour rule."""
    _adm_require()
    token, _me = get_id_token()
    if value is None:
        _http_json(_fdb(f"themeunlock/{uid}", token), "DELETE")
    else:
        _http_json(_fdb(f"themeunlock/{uid}", token), "PUT", bool(value))


# ── admin UI ──
def _adm_run(owner, func, done=None, busy="Working..."):
    """Runs func on a worker thread with a wait dialog; shows errors; calls done(result) on success."""
    dlg = BusyDialog(busy, func, owner)
    ok, value, error = dlg.run()
    if not ok:
        QMessageBox.warning(owner, "Admin", error or "Something went wrong.")
        return False
    if done:
        done(value)
    return True

def _adm_label(u):
    name = u.get("username") or "(no username)"
    return f"{name}  -  {u['uid']}" + ("   [BANNED]" if u.get("banned") else "")

class _AdminLibraryDialog(QDialog):
    def __init__(self, uid, name, parent=None):
        super().__init__(parent)
        self.uid = uid
        self.setWindowTitle(f"Library - {name}")
        self.resize(460, 520)
        self.games, self.fan = {}, {}
        lay = QVBoxLayout(self)
        lay.addWidget(QLabel("Games in this account's library (applies the next time their launcher syncs)."))
        self.list = QListWidget()
        self.list.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        lay.addWidget(self.list, 1)
        row = QHBoxLayout()
        add = QPushButton("Add store game")
        add.clicked.connect(self._add)
        rem = QPushButton("Remove selected")
        rem.clicked.connect(self._remove)
        row.addWidget(add)
        row.addWidget(rem)
        row.addStretch()
        lay.addLayout(row)
        row2 = QHBoxLayout()
        row2.addStretch()
        cancel = QPushButton("Cancel")
        cancel.clicked.connect(self.reject)
        save = QPushButton("Save")
        save.setObjectName("Primary")
        save.clicked.connect(self._save)
        row2.addWidget(cancel)
        row2.addWidget(save)
        lay.addLayout(row2)
        self.ok_loaded = _adm_run(self, lambda: _adm_get_library(uid), self._loaded, "Loading library...")

    def _loaded(self, res):
        self.games, self.fan = dict(res[0]), dict(res[1])
        self._fill()

    def _fill(self):
        self.list.clear()
        for aid, info in sorted(self.games.items(), key=lambda kv: str((kv[1] or {}).get("title", "")).lower()):
            it = QListWidgetItem(f"{(info or {}).get('title', '?')}   (store {aid})")
            it.setData(Qt.ItemDataRole.UserRole, ("games", aid))
            self.list.addItem(it)
        for gid, info in sorted(self.fan.items(), key=lambda kv: str((kv[1] or {}).get("title", "")).lower()):
            it = QListWidgetItem(f"{(info or {}).get('title', '?')}   (fan game {gid})")
            it.setData(Qt.ItemDataRole.UserRole, ("fan", gid))
            self.list.addItem(it)

    def _add(self):
        aid, ok = QInputDialog.getText(self, "Add store game", "Steam appid (numbers):")
        aid = (aid or "").strip()
        if not ok or not aid.isdigit():
            return
        title, ok = QInputDialog.getText(self, "Add store game", "Game title:")
        title = (title or "").strip()
        if not ok or not title:
            return
        self.games[aid] = {"title": title}
        self._fill()

    def _remove(self):
        for it in self.list.selectedItems():
            kind, key = it.data(Qt.ItemDataRole.UserRole)
            (self.games if kind == "games" else self.fan).pop(key, None)
        self._fill()

    def _save(self):
        if _adm_run(self, lambda: _adm_save_library(self.uid, self.games, self.fan), None, "Saving..."):
            self.accept()

class _AdminFriendsDialog(QDialog):
    def __init__(self, uid, name, users, parent=None):
        super().__init__(parent)
        self.uid, self.users = uid, users
        self.setWindowTitle(f"Friends - {name}")
        self.resize(440, 480)
        lay = QVBoxLayout(self)
        self.list = QListWidget()
        self.list.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        lay.addWidget(self.list, 1)
        row = QHBoxLayout()
        add = QPushButton("Add friend")
        add.clicked.connect(self._add)
        rem = QPushButton("Remove selected")
        rem.clicked.connect(self._remove)
        close = QPushButton("Close")
        close.clicked.connect(self.accept)
        row.addWidget(add)
        row.addWidget(rem)
        row.addStretch()
        row.addWidget(close)
        lay.addLayout(row)
        self.friends = []
        self._reload()

    def _reload(self):
        def got(res):
            self.friends = res
            self.list.clear()
            for f in res:
                it = QListWidgetItem(f"{f['username'] or '(no username)'}  -  {f['uid']}")
                it.setData(Qt.ItemDataRole.UserRole, f["uid"])
                self.list.addItem(it)
        _adm_run(self, lambda: _adm_get_friends(self.uid), got, "Loading friends...")

    def _add(self):
        have = {f["uid"] for f in self.friends} | {self.uid}
        pool = [u for u in self.users if u["uid"] not in have]
        if not pool:
            QMessageBox.information(self, "Admin", "No other accounts to add.")
            return
        labels = [_adm_label(u) for u in pool]
        pick, ok = QInputDialog.getItem(self, "Add friend", "Account:", labels, 0, False)
        if not ok:
            return
        other = pool[labels.index(pick)]["uid"]
        if _adm_run(self, lambda: _adm_add_friend(self.uid, other), None, "Adding..."):
            self._reload()

    def _remove(self):
        ids = [it.data(Qt.ItemDataRole.UserRole) for it in self.list.selectedItems()]
        if not ids:
            return

        def work():
            for o in ids:
                _adm_remove_friend(self.uid, o)
        if _adm_run(self, work, None, "Removing..."):
            self._reload()

class AdminPanel(QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Admin panel")
        self.resize(860, 560)
        self.users = []
        self.sel = None                       # the selected user dict
        root = QHBoxLayout(self)
        left = QVBoxLayout()
        self.search = QLineEdit()
        self.search.setPlaceholderText("Search username or uid")
        self.search.textChanged.connect(self._filter)
        left.addWidget(self.search)
        self.list = QListWidget()
        self.list.currentItemChanged.connect(self._picked)
        left.addWidget(self.list, 1)
        refresh = QPushButton("Refresh accounts")
        refresh.clicked.connect(self.reload)
        left.addWidget(refresh)
        root.addLayout(left, 1)

        right = QVBoxLayout()
        head = QHBoxLayout()
        self.avatar = QLabel()
        self.avatar.setFixedSize(96, 96)
        head.addWidget(self.avatar)
        info = QVBoxLayout()
        self.name_lbl = QLabel("Select an account")
        f = self.name_lbl.font()
        f.setPointSize(f.pointSize() + 4)
        f.setBold(True)
        self.name_lbl.setFont(f)
        self.uid_lbl = QLabel("")
        self.uid_lbl.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
        self.status_lbl = QLabel("")
        info.addWidget(self.name_lbl)
        info.addWidget(self.uid_lbl)
        info.addWidget(self.status_lbl)
        info.addStretch()
        head.addLayout(info, 1)
        right.addLayout(head)
        self.buttons = []
        for text, fn in (("Change picture", self._picture), ("Change username", self._username),
                         ("Change profile country", self._country), ("Manage library", self._library),
                         ("Manage friends", self._friends), ("Custom themes access", self._themes)):
            b = QPushButton(text)
            b.setMinimumHeight(36)
            b.clicked.connect(fn)
            right.addWidget(b)
            self.buttons.append(b)
        self.ban_btn = QPushButton("Ban")
        self.ban_btn.setMinimumHeight(36)
        self.ban_btn.clicked.connect(self._ban)
        right.addWidget(self.ban_btn)
        self.buttons.append(self.ban_btn)
        right.addStretch()
        root.addLayout(right, 1)
        self._set_enabled(False)
        QTimer.singleShot(0, self.reload)

    def _set_enabled(self, on):
        for b in self.buttons:
            b.setEnabled(on)

    def reload(self):
        keep = self.sel["uid"] if self.sel else None
        def got(res):
            self.users = sorted(res, key=lambda u: (u.get("username") or "~").lower())
            self._filter(self.search.text())
            if keep:
                for i in range(self.list.count()):
                    if self.list.item(i).data(Qt.ItemDataRole.UserRole)["uid"] == keep:
                        self.list.setCurrentRow(i)
                        break
        _adm_run(self, _adm_fetch_users, got, "Loading accounts...")

    def _filter(self, text=""):
        text = (text or "").strip().lower()
        self.list.blockSignals(True)
        self.list.clear()
        for u in self.users:
            if text and text not in u["uid"].lower() and text not in (u.get("username") or "").lower():
                continue
            it = QListWidgetItem(_adm_label(u))
            it.setData(Qt.ItemDataRole.UserRole, u)
            self.list.addItem(it)
        self.list.blockSignals(False)
        self._picked(None, None)

    def _picked(self, cur, _prev):
        it = self.list.currentItem()
        if it is None:
            self.sel = None
            self.name_lbl.setText("Select an account")
            self.uid_lbl.setText("")
            self.status_lbl.setText("")
            self.avatar.clear()
            self._set_enabled(False)
            return
        self.sel = it.data(Qt.ItemDataRole.UserRole)
        u = self.sel
        self.name_lbl.setText(u.get("username") or "(no username)")
        self.uid_lbl.setText(u["uid"])
        ban = u.get("ban")
        reason = (ban.get("reason") if isinstance(ban, dict) else "") or ""
        self.status_lbl.setText(("BANNED" + (f": {reason}" if reason else "")) if u["banned"] else "Active")
        self.ban_btn.setText("Unban" if u["banned"] else "Ban")
        self._set_enabled(True)
        self.avatar.clear()
        uid = u["uid"]

        def got(p):
            if self.sel and self.sel["uid"] == uid and p.get("png"):
                pm = QPixmap()
                pm.loadFromData(p["png"])
                self.avatar.setPixmap(pm.scaled(96, 96, Qt.AspectRatioMode.KeepAspectRatio,
                                                Qt.TransformationMode.SmoothTransformation))
            if self.sel and self.sel["uid"] == uid:
                self.sel["country"] = p.get("country", "")
        w = TaskWorker(lambda: _adm_fetch_profile(uid))
        w.done.connect(got)
        self._pw = w                           # keep a reference while it runs
        w.start()

    def _picture(self):
        u = self.sel
        box = QMessageBox(self)
        box.setWindowTitle("Change picture")
        box.setText(f"New profile picture for {u.get('username') or u['uid']}")
        choose = box.addButton("Choose image...", QMessageBox.ButtonRole.AcceptRole)
        remove = box.addButton("Remove picture", QMessageBox.ButtonRole.DestructiveRole)
        box.addButton(QMessageBox.StandardButton.Cancel)
        box.exec()
        clicked = box.clickedButton()
        png = None
        if clicked is choose:
            path, _f = QFileDialog.getOpenFileName(self, "Choose a picture", "", "Images (*.png *.jpg *.jpeg *.bmp *.gif *.webp)")
            if not path:
                return
            try:
                png = prepare_avatar_png(path)
            except CloudError as e:
                QMessageBox.warning(self, "Admin", str(e))
                return
        elif clicked is not remove:
            return
        if _adm_run(self, lambda: _adm_set_picture(u["uid"], png), None, "Saving..."):
            self._picked(None, None)

    def _username(self):
        u = self.sel
        name, ok = QInputDialog.getText(self, "Change username", "New username:", text=u.get("username") or "")
        name = (name or "").strip()
        if not ok or not name:
            return
        err = validate_username(name)
        if err:
            QMessageBox.warning(self, "Admin", err)
            return
        def done(_r):
            u["username"] = name
            self.reload()
        _adm_run(self, lambda: _adm_set_username(u["uid"], name), done, "Saving...")

    def _country(self):
        u = self.sel
        dlg = CountryDialog(self, u.get("country", ""))
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        code = dlg.code()
        def done(_r):
            u["country"] = code
        _adm_run(self, lambda: _adm_set_country(u["uid"], code), done, "Saving...")

    def _library(self):
        u = self.sel
        _AdminLibraryDialog(u["uid"], u.get("username") or u["uid"], self).exec()

    def _friends(self):
        u = self.sel
        _AdminFriendsDialog(u["uid"], u.get("username") or u["uid"], self.users, self).exec()

    def _themes(self):
        u = self.sel
        uid = u["uid"]
        who = u.get("username") or uid

        def got(cur):
            state = ("Unlocked by an admin" if cur is True else "Locked by an admin" if cur is False
                     else "Default (unlocks after 8 hours on the launcher)")
            box = QMessageBox(self)
            box.setWindowTitle("Custom themes access")
            box.setText(f"{who}\nCurrent: {state}")
            unlock = box.addButton("Unlock", QMessageBox.ButtonRole.AcceptRole)
            lock = box.addButton("Lock", QMessageBox.ButtonRole.DestructiveRole)
            default = box.addButton("Use 8 hour rule", QMessageBox.ButtonRole.ActionRole)
            box.addButton(QMessageBox.StandardButton.Cancel)
            box.exec()
            c = box.clickedButton()
            val = {unlock: True, lock: False, default: None}.get(c, "skip")
            if val == "skip":
                return
            _adm_run(self, lambda: _adm_set_theme_override(uid, val), None, "Saving...")
        _adm_run(self, lambda: _adm_get_theme_override(uid), got, "Loading...")

    def _ban(self):
        u = self.sel
        uid = u["uid"]
        if u["banned"]:
            if QMessageBox.question(self, "Unban", f"Unban {u.get('username') or uid}?") != QMessageBox.StandardButton.Yes:
                return
            if _adm_run(self, lambda: _adm_unban(uid), None, "Unbanning..."):
                self.reload()
            return
        if uid in _ADMIN_UIDS:
            QMessageBox.warning(self, "Admin", "You can't ban an admin account.")
            return
        reason, ok = QInputDialog.getText(self, "Ban", f"Reason for banning {u.get('username') or uid} (optional):")
        if not ok:
            return
        if _adm_run(self, lambda: _adm_ban(uid, reason), None, "Banning..."):
            self.reload()

def _adm_open(window):
    if not _adm_is_admin():
        return
    AdminPanel(window).exec()





# ── Settings: grouped sections + Big Picture auto-launch ──
# 1) The Settings page (regular AND Big Picture) is sorted into sections: Appearance, Big Picture & Controller, Startup & Updates,
#    Library & Downloads, Compatibility, Online & Integrations. Big Picture reads the real page, so it gets the same sections.
# 2) New settings: "Launch Big Picture on startup" and "Big Picture when a controller connects".
_NCZ_SET_CATS = [
    ("Shortcuts", ("game shortcuts",)),
    ("NCZ Command Line Tool", ("command line tool",)),
    ("Appearance", ("dark mode", "accent color", "interface style")),
    ("Big Picture & Controller", ("big picture", "controller", "input bridge")),
    ("Startup & Updates", ("start with", "automatic update", "launcher update", "desktop shortcut")),
    ("Library & Downloads", ("game library", "download server", "7-zip", "winrar", "steamgriddb", "currency", "nsfw")),
    ("Compatibility", ("direct3d", "xwayland", "renderer")),
    ("Online & Integrations", ("discord", "ncz link", "overlay", "sync profile", "friend", "account")),
]


def _ncz_cat_index(title):
    t = (title or "").lower()
    for i, (_n, keys) in enumerate(_NCZ_SET_CATS):
        if any(k in t for k in keys):
            return i
    return len(_NCZ_SET_CATS)


def _ncz_cat_name(i):
    return _NCZ_SET_CATS[i][0] if i < len(_NCZ_SET_CATS) else "Other"


def _ncz_block_title(w):
    try:
        if isinstance(w, QLabel) and w.objectName() == "RowTitle":
            return w.text().strip()
        for c in w.findChildren(QLabel):
            if c.objectName() == "RowTitle" and c.text().strip():
                return c.text().strip()
    except RuntimeError:    # expected: the widget or object may already be deleted
        pass
    return None


def _ncz_section_header(sp, name):
    hdrs = sp.__dict__.setdefault("_ncz_hdrs", {})
    h = hdrs.get(name)
    if h is None:
        h = QLabel(name.upper(), sp._content)
        h.setObjectName("NczSectionTitle")
        h.setStyleSheet("QLabel#NczSectionTitle { color: palette(highlight); font-size: 12px; font-weight: 700;"
                        " padding: 4px 4px 0px 4px; background: transparent; }")
        hdrs[name] = h
    return h


def _ncz_organize(sp):
    """Sort the settings panels into sections (idempotent; cheap when nothing changed)."""
    lay = getattr(sp, "_content_layout", None)
    if lay is None:
        return
    hdrs = sp.__dict__.setdefault("_ncz_hdrs", {})
    hset = set(hdrs.values())
    widgets = [lay.itemAt(i).widget() for i in range(lay.count()) if lay.itemAt(i).widget() is not None]
    head, blocks, tail = [], [], []
    for w in widgets:
        if w in hset:
            continue
        if w.objectName() == "PageTitle":
            head.append(w)
            continue
        t = _ncz_block_title(w)
        if t is None:
            tail.append(w)
        else:
            blocks.append((_ncz_cat_index(t), w))
    blocks.sort(key=lambda b: b[0])                      # stable: keeps the original order inside a section
    desired, groups = list(head), {}
    last = None
    for ci, w in blocks:
        if ci != last:
            last = ci
            desired.append(_ncz_section_header(sp, _ncz_cat_name(ci)))
        groups.setdefault(ci, []).append(w)
        desired.append(w)
    desired += tail
    if desired != widgets:
        while lay.count():
            lay.takeAt(0)
        for w in desired:
            if w in head:
                lay.addWidget(w)
                lay.addSpacing(18)
            elif w in hset or w.objectName() == "NczSectionTitle":
                lay.addSpacing(10)
                lay.addWidget(w)
                lay.addSpacing(4)
            else:
                lay.addWidget(w)
                lay.addSpacing(12)
        lay.addStretch(1)
    for ci, ws in groups.items():                        # hide a section title when every panel under it is hidden
        _ncz_section_header(sp, _ncz_cat_name(ci)).setVisible(any(not w.isHidden() for w in ws))


# ── the two new settings ──
_NCZ_PAD = {"timer": None, "had": None, "app": None}


def _ncz_pad_present():
    try:
        if sys.platform.startswith("win"):
            import ctypes    # lazy: saves memory/startup until used
            try:
                dll = ctypes.windll.xinput1_4
            except Exception:
                dll = ctypes.windll.xinput1_3
            buf = ctypes.create_string_buffer(16)
            return any(dll.XInputGetState(i, buf) == 0 for i in range(4))
        if sys.platform.startswith("linux"):
            import glob    # lazy: saves memory/startup until used
            return bool(glob.glob("/dev/input/js*"))
    except Exception:    # expected: optional module may be missing
        pass
    return False


def _ncz_pad_tick():
    now = _ncz_pad_present()
    had, _NCZ_PAD["had"] = _NCZ_PAD["had"], now
    app = _NCZ_PAD["app"]
    if now and had is False and app is not None:         # a controller just showed up
        bp = getattr(app, "_big_picture", None)
        if bp is None or not getattr(bp, "_active", False):
            app.open_big_picture()


def _ncz_pad_apply():
    """Polls for controllers only while the setting is on (nothing runs when it's off)."""
    on = bool(load_launcher_settings().get("bp_on_controller", True))
    t = _NCZ_PAD["timer"]
    if t is None:
        t = _NCZ_PAD["timer"] = QTimer(QApplication.instance())
        t.timeout.connect(_ncz_pad_tick)
    if on and not t.isActive():
        _NCZ_PAD["had"] = _ncz_pad_present()
        t.start(2000)
    elif not on:
        t.stop()


_NCZ_BP_SPECS = (("Launch Big Picture on startup", "Open Big Picture mode automatically whenever the launcher starts",
                  "bp_on_startup", None),
                 ("Big Picture when a controller connects", "Switch to Big Picture as soon as a controller is plugged in or turned on",
                  "bp_on_controller", _ncz_pad_apply))
_NCZ_SND_SPECS = (("Overlay notification sound", "Play a short chime when a friend notification pops up",
                   "overlay_sound", None),)


def _ncz_add_bp_settings(sp):
    if getattr(sp, "_ncz_bp_panel", None) is not None:
        return
    _ncz_make_panel(sp, _NCZ_BP_SPECS, "_ncz_bp_panel")
    _ncz_make_panel(sp, _NCZ_SND_SPECS, "_ncz_snd_panel")


def _ncz_make_panel(sp, specs, attr):
    panel = QFrame()
    panel.setObjectName("Panel")
    pl = QVBoxLayout(panel)
    pl.setContentsMargins(22, 18, 22, 18)
    for n, (title, desc, key, cb) in enumerate(specs):
        if n:
            pl.addSpacing(10)
        row, col = QHBoxLayout(), QVBoxLayout()
        col.setSpacing(2)
        t = QLabel(title)
        t.setObjectName("RowTitle")
        d = QLabel(desc)
        d.setObjectName("RowDesc")
        d.setWordWrap(True)
        col.addWidget(t)
        col.addWidget(d)
        b = QPushButton()
        b.setCheckable(True)
        b.setFixedWidth(160)
        b.setCursor(Qt.CursorShape.PointingHandCursor)
        on = bool(load_launcher_settings().get(key, key in ("bp_on_controller", "overlay_sound")))
        b.setChecked(on)
        b.setText("On" if on else "Off")

        def toggled(_c=False, b=b, key=key, cb=cb):
            v = b.isChecked()
            b.setText("On" if v else "Off")
            s = load_launcher_settings()
            s[key] = v
            save_launcher_settings(s)
            if cb:
                cb()
        b.clicked.connect(toggled)
        row.addLayout(col, 1)
        row.addWidget(b)
        pl.addLayout(row)
    sp._content_layout.addWidget(panel)
    setattr(sp, attr, panel)


_ncz_show_o = SettingsPage.showEvent


def _ncz_settings_show(self, e):
    _ncz_show_o(self, e)
    try:
        _ncz_organize(self)                              # picks up panels other features added after startup
    except Exception:
        import traceback    # lazy: saves memory/startup until used
        traceback.print_exc()


SettingsPage.showEvent = _ncz_settings_show


# ── Settings: "NCZ Command Line Tool" (its own section, first on the page) ──
# Install runs `py "%LOCALAPPDATA%/NCZ_Games_Launcher/ncz_gm.py" install` (Windows) / `python3 "$HOME/.local/share/
# NCZ_Games_Launcher/ncz_gm.py" install` (Linux) and then opens a terminal that runs `ncz-gm`; Uninstall runs the same with `uninstall`.
class _CliToolSignal(QObject):
    done = pyqtSignal(str, int, str)        # action, exit code (-1 = couldn't run), output

def _cli_tool_script():
    if sys.platform.startswith("win"):
        p = os.path.join(os.environ.get("LOCALAPPDATA", os.path.expanduser("~/AppData/Local")),
                         "NCZ_Games_Launcher", "ncz_gm.py")
    else:
        p = os.path.expanduser("~/.local/share/NCZ_Games_Launcher/ncz_gm.py")
    if not os.path.isfile(p):                       # not copied there yet: the copy next to main.py does the same job
        alt = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ncz_gm.py")
        if os.path.isfile(alt):
            return alt
    return p

def _cli_tool_command(action):
    if getattr(sys, "frozen", False):               # packaged build: the exe runs the CLI itself
        return [sys.executable, "--cli", action]
    if sys.platform.startswith("win"):
        py = shutil.which("py") or shutil.which("python")
    else:
        py = shutil.which("python3") or shutil.which("python")
    if not py:
        return None
    return [py, _cli_tool_script(), action]

def _cli_tool_open_terminal(cmd):
    """Opens the user's own terminal app (Windows Terminal / the default console, or their Linux terminal) as a normal
    interactive session and runs the install command in it, then `ncz-gm`."""
    import tempfile    # lazy: saves memory/startup until used
    if sys.platform.startswith("win"):
        root = os.environ.get("SystemDrive", "C:") + "\\"
        bat = os.path.join(tempfile.gettempdir(), "ncz_gm_terminal.bat")
        with open(bat, "w", encoding="utf-8") as f:
            f.write('@echo off\r\n'
                    + subprocess.list2cmdline(cmd) + '\r\n'
                    'for /f "usebackq skip=2 tokens=2,*" %%A in (`reg query "HKCU\\Environment" /v Path 2^>nul`) do '
                    'call set "PATH=%%B;%%PATH%%"\r\n'          # picks up the PATH entry the install just added
                    'call ncz-gm\r\n')
        wt = shutil.which("wt")                                  # Windows Terminal, when it's installed
        if wt:
            subprocess.Popen([wt, "-d", root, "cmd.exe", "/k", bat])
        else:                                                    # `start` opens the default console app for the system
            subprocess.Popen(f'start "NCZ Command Line Tool" /d "{root}" cmd.exe /k "{bat}"', shell=True, cwd=root)
        return True
    import shlex    # lazy: saves memory/startup until used
    rc = os.path.join(tempfile.gettempdir(), "ncz_gm_terminal.sh")
    with open(rc, "w", encoding="utf-8") as f:                    # runs inside a normal interactive bash, after the user's own bashrc
        f.write('[ -f "$HOME/.bashrc" ] && . "$HOME/.bashrc"\n'
                'export PATH="$HOME/.local/bin:$PATH"\n'
                'cd "$HOME"\n'
                + shlex.join(cmd) + '\n'
                'ncz-gm\n')
    for term, pre in (("x-terminal-emulator", ["-e"]), ("gnome-terminal", ["--"]), ("konsole", ["-e"]),
                      ("xfce4-terminal", ["-x"]), ("kitty", []), ("alacritty", ["-e"]), ("xterm", ["-e"])):
        exe = shutil.which(term)
        if exe:
            subprocess.Popen([exe] + pre + ["bash", "--rcfile", rc, "-i"], start_new_session=True,
                             cwd=os.path.expanduser("~"))
            return True
    return False

def _cli_tool_run(sp, action):
    cmd = _cli_tool_command(action)
    if cmd is None or (not getattr(sys, "frozen", False) and not os.path.isfile(cmd[1])):
        QMessageBox.warning(sp.window(), "NCZ Command Line Tool",
                            "Couldn't find ncz_gm.py" + ("" if cmd else " or Python") + ".\n\nExpected it at:\n" + _cli_tool_script())
        return
    if action == "install":                         # visible: a terminal runs the install, then ncz-gm
        try:
            if not _cli_tool_open_terminal(cmd):
                QMessageBox.information(sp.window(), "NCZ Command Line Tool",
                                        "No terminal app was found. Open one and run:\n\n" + " ".join(cmd) + "\nncz-gm")
        except Exception as e:
            QMessageBox.warning(sp.window(), "NCZ Command Line Tool", f"Couldn't open a terminal: {e}")
        return
    sig = sp.__dict__.get("_cli_sig")
    if sig is None:
        sig = sp._cli_sig = _CliToolSignal(sp)
        def finished(act, code, out):
            win = sp.window()
            if code != 0:
                QMessageBox.warning(win, "NCZ Command Line Tool",
                                    f"{act.capitalize()} failed" + (f" (exit code {code})" if code > 0 else "") +
                                    (":\n\n" + out[-600:] if out.strip() else "."))
                return
            if act == "install":
                try:
                    if not _cli_tool_open_terminal():
                        QMessageBox.information(win, "NCZ Command Line Tool",
                                                "Installed. No terminal app was found: open one and run  ncz-gm")
                except Exception as e:
                    QMessageBox.warning(win, "NCZ Command Line Tool", f"Installed, but the terminal didn't open: {e}")
            else:
                QMessageBox.information(win, "NCZ Command Line Tool", "NCZ Command Line Tool uninstalled.")
        sig.done.connect(finished)
    def work():
        try:
            kw = {"creationflags": 0x08000000} if sys.platform.startswith("win") else {}    # CREATE_NO_WINDOW
            r = subprocess.run(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                               timeout=180, **kw)
            sig.done.emit(action, r.returncode, r.stdout.decode("utf-8", errors="replace"))
        except Exception as e:
            sig.done.emit(action, -1, str(e))
    threading.Thread(target=work, daemon=True).start()

def _cli_tool_manage(sp):
    box = QMessageBox(sp.window())
    box.setWindowTitle("NCZ Command Line Tool")
    box.setText("What do you want to do with the NCZ Command Line Tool?")
    box.setInformativeText("Install adds the  ncz-gm  command and opens a terminal running it. "
                           "Uninstall removes the command.")
    install = box.addButton("Install", QMessageBox.ButtonRole.AcceptRole)
    uninstall = box.addButton("Uninstall", QMessageBox.ButtonRole.DestructiveRole)
    box.addButton(QMessageBox.StandardButton.Cancel)
    box.exec()
    c = box.clickedButton()
    if c is install:
        _cli_tool_run(sp, "install")
    elif c is uninstall:
        _cli_tool_run(sp, "uninstall")

def _cli_tool_panel(sp):
    panel = QFrame()
    panel.setObjectName("Panel")
    pl = QVBoxLayout(panel)
    pl.setContentsMargins(22, 18, 22, 18)
    row, col = QHBoxLayout(), QVBoxLayout()
    col.setSpacing(2)
    t = QLabel("Manage NCZ Command Line Tool")
    t.setObjectName("RowTitle")
    d = QLabel("Install or uninstall the ncz-gm command (installing also opens a terminal running it)")
    d.setObjectName("RowDesc")
    d.setWordWrap(True)
    col.addWidget(t)
    col.addWidget(d)
    b = QPushButton("Manage...")
    b.setFixedWidth(160)
    b.setCursor(Qt.CursorShape.PointingHandCursor)
    b.clicked.connect(lambda _c=False: _cli_tool_manage(sp))
    row.addLayout(col, 1)
    row.addWidget(b)
    pl.addLayout(row)
    sp._content_layout.addWidget(panel)         # the section sorter puts it under its own header, first on the page
    sp._cli_tool_panel = panel

