def _ncz_scan(sp):
    rows = _ncz_scan_o(sp)
    try:
        rows = [r for r in rows if r.get("ctrls")]       # drop hidden / non-interactive rows
        for r in rows:
            r["_cat"] = _ncz_cat_index(r["title"])
        rows.sort(key=lambda r: r["_cat"])
        out, last = [], None
        for r in rows:
            if r["_cat"] != last:
                last = r["_cat"]
                out.append({"title": _ncz_cat_name(last), "desc": "", "ctrls": [], "header": True})
            out.append(r)
        return out
    except Exception:
        return rows


