# ── Store: "Recommended for you" shelf (horizontal covers, no popup) ──
_REC_W, _REC_H = 280, 131                      # Steam's landscape header art is 460x215

def landscape_art_path(appid):
    """Landscape art for a Steam game, cached on disk: SteamGridDB first (with an API key), then Steam's own header,
    then whatever the store page lists. "" when there is none."""
    appid = int(appid)
    path = ""
    try:
        folder = get_store_cache_dir()
        os.makedirs(folder, exist_ok=True)
        dest = os.path.join(folder, f"{appid}-hdr.img")
        sgdb_dest = os.path.join(folder, f"{appid}-hdr-sgdb.img")
        sgdb_marker = os.path.join(folder, f"{appid}-nohdrsgdb")
        key = get_steamgriddb_key()
        if os.path.exists(sgdb_dest):
            dest = sgdb_dest
        elif key and not (os.path.exists(sgdb_marker)
                          and time.time() - os.path.getmtime(sgdb_marker) < NO_ART_RETRY_SECONDS):
            try:
                sg = _first_grid_image(_sgdb_get_json(
                    f"/grids/steam/{appid}?dimensions=920x430,460x215&types=static", key))
                if sg:
                    with open(sgdb_dest, "wb") as f:
                        f.write(sg)
                    dest = sgdb_dest
                else:
                    open(sgdb_marker, "w").close()
            except Exception:
                pass    # bad key / rate limit / network: use Steam's art this time
        if not os.path.exists(dest):
            data = b""
            for url in (_BPX_HDR % appid, f"https://cdn.cloudflare.steamstatic.com/steam/apps/{appid}/capsule_616x353.jpg"):
                try:
                    data = _http_get(url, timeout=12)
                except Exception:
                    data = b""
                if data:
                    break
            if not data:
                for url in steam_details_art_urls(appid, portrait=False):
                    try:
                        data = _http_get(url, timeout=12)
                    except Exception:
                        data = b""
                    if data:
                        break
            if data:
                with open(dest, "wb") as f:
                    f.write(data)
        if os.path.exists(dest):
            path = dest
    except Exception:
        path = ""
    return path

def cached_landscape_art(appid):
    """The landscape art already on disk for this game (no network), or ""."""
    folder = get_store_cache_dir()
    for name in (f"{int(appid)}-hdr-sgdb.img", f"{int(appid)}-hdr.img"):
        full = os.path.join(folder, name)
        if os.path.exists(full):
            return full
    return ""

class _RecArt(QObject):
    """Downloads Steam's landscape header art for recommended games and caches it on disk."""
    loaded = pyqtSignal(int, str)              # appid, cached image path ("" if there is none)

    def __init__(self):
        super().__init__()
        self._pool = ThreadPoolExecutor(max_workers=3)
        QApplication.instance().aboutToQuit.connect(lambda: self._pool.shutdown(wait=False, cancel_futures=True))

    def request(self, appid):
        self._pool.submit(self._work, int(appid))

    def _work(self, appid):
        path = landscape_art_path(appid)
        try:
            self.loaded.emit(appid, path)
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass


class _RecCard(QFrame):
    clicked = pyqtSignal(object)

    def __init__(self, rec, parent=None):
        super().__init__(parent)
        self.rec = rec
        self.art = ""                          # landscape header
        self.portrait = ""                     # the Store's normal cover, handed to the detail page
        self.nsfw = False
        self.have_art = self.known = False     # header downloaded / NSFW check finished
        nsfw_bus.revealed.connect(self._refresh)
        self.setObjectName("GameCard")
        self.setFixedWidth(_REC_W + 18)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip("%s\nBecause you played %s\nClick for details" % (rec["title"], rec["because"]))
        lay = QVBoxLayout(self)
        lay.setContentsMargins(8, 8, 8, 10)
        lay.setSpacing(0)
        self.cover = QLabel("...")
        self.cover.setObjectName("CoverPlaceholder")
        self.cover.setFixedSize(_REC_W, _REC_H)
        self.cover.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lay.addWidget(self.cover)
        lay.addSpacing(8)
        fm = QFontMetrics(self.font())
        self.title_label = QLabel(fm.elidedText(rec["title"], Qt.TextElideMode.ElideRight, _REC_W - 6))
        self.title_label.setObjectName("CardTitle")
        lay.addWidget(self.title_label)
        why = QLabel(fm.elidedText("Because you played " + rec["because"], Qt.TextElideMode.ElideRight, _REC_W - 6))
        why.setObjectName("RowDesc")
        lay.addWidget(why)

    def _refresh(self):
        if not (self.have_art and self.known):
            return
        hidden = self.nsfw and not nsfw_revealed()
        pix = rounded_cover_pixmap(self.art, _REC_W, _REC_H, 8, blur=hidden) if self.art else None
        if pix:
            self.cover.setText("")
            self.cover.setPixmap(pix)
            self.cover.setStyleSheet("background: transparent; border: none;")
        else:
            self.cover.setText("No\ncover")

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit(self.rec)
        super().mousePressEvent(event)


class _HScroll(QScrollArea):
    """Horizontal strip: only sideways wheel / trackpad movement scrolls it, so the page itself still scrolls normally."""
    def wheelEvent(self, e):
        dx = e.angleDelta().x()
        if dx:
            bar = self.horizontalScrollBar()
            bar.setValue(bar.value() - dx)
            e.accept()
        else:
            e.ignore()


class _RecShelf(QWidget):
    open_game = pyqtSignal(object)

    def __init__(self):
        super().__init__()
        self.cards = {}
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 14)
        lay.setSpacing(6)
        head = QHBoxLayout()
        title = QLabel("Recommended for you")
        title.setStyleSheet("font-size: 16px; font-weight: bold;")
        self.sub = QLabel("Based on the games you play")
        self.sub.setObjectName("RowDesc")
        self.prev_btn, self.next_btn = QPushButton("<"), QPushButton(">")
        for b, d in ((self.prev_btn, -1), (self.next_btn, 1)):
            b.setFixedSize(32, 28)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _c=False, d=d: self._nudge(d))
        head.addWidget(title)
        head.addSpacing(10)
        head.addWidget(self.sub, 1)
        head.addWidget(self.prev_btn)
        head.addWidget(self.next_btn)
        lay.addLayout(head)
        self.msg = QLabel("")
        self.msg.setObjectName("RowDesc")
        self.msg.setWordWrap(True)
        self.msg.hide()
        lay.addWidget(self.msg)
        self.scroll = _HScroll()
        self.scroll.setWidgetResizable(True)
        self.scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setFixedHeight(_REC_H + 82)
        inner = QWidget()
        inner.setObjectName("GridContainer")
        self.row = QHBoxLayout(inner)
        self.row.setContentsMargins(0, 0, 0, 0)
        self.row.setSpacing(14)
        self.row.addStretch()
        self.scroll.setWidget(inner)
        lay.addWidget(self.scroll)
        self.scroll.hide()
        self.prev_btn.hide()
        self.next_btn.hide()

    def _nudge(self, d):
        bar = self.scroll.horizontalScrollBar()
        bar.setValue(bar.value() + d * 2 * (_REC_W + 32))

    def clear(self):
        for c in self.cards.values():
            self.row.removeWidget(c)
            c.setParent(None)
            c.deleteLater()
        self.cards = {}

    def show_message(self, text):
        self.clear()
        self.scroll.hide()
        self.prev_btn.hide()
        self.next_btn.hide()
        self.msg.setText(text)
        self.msg.setVisible(bool(text))

    def fill(self, recs):
        self.clear()
        self.msg.hide()
        for r in recs:
            card = _RecCard(r)
            card.clicked.connect(self.open_game.emit)
            self.row.insertWidget(self.row.count() - 1, card)
            self.cards[r["appid"]] = card
        self.scroll.setVisible(bool(recs))
        self.prev_btn.setVisible(bool(recs))
        self.next_btn.setVisible(bool(recs))


_rs_prev_init = StorePage.__init__

def _rs_init(self, *a, **k):
    _rs_prev_init(self, *a, **k)
    if type(self) is not StorePage:
        return
    try:
        self._rec_art = _RecArt()
        self._rec_shelf = _RecShelf()
        self._rec_workers, self._rec_t, self._rec_busy = [], 0.0, False
        old = self.scroll.takeWidget()                      # the shelf scrolls together with the grid
        outer = QWidget()
        outer.setObjectName("GridContainer")
        ol = QVBoxLayout(outer)
        ol.setContentsMargins(0, 0, 0, 0)
        ol.setSpacing(0)
        ol.addWidget(self._rec_shelf)
        ol.addWidget(old, 1)
        self.scroll.setWidget(outer)
        self._rec_shelf.open_game.connect(self._rec_open)
        self._rec_art.loaded.connect(self._rec_art_loaded)
        self.loader.loaded.connect(self._rec_cover_loaded)
        self.loader.nsfw_known.connect(self._rec_nsfw_known)
    except Exception:
        _log_exc("_rs_init")

def _rec_open(self, rec):
    card = self._rec_shelf.cards.get(rec["appid"])
    self.window().open_store_game(rec["appid"], rec["title"], card.portrait if card is not None else "")

def _rec_art_loaded(self, appid, path):
    card = self._rec_shelf.cards.get(appid)
    if card is not None:
        card.art, card.have_art = path, True
        card._refresh()

def _rec_cover_loaded(self, appid, path):                   # the Store loader finishes after its NSFW check
    card = self._rec_shelf.cards.get(appid)
    if card is not None:
        card.portrait, card.known = path or "", True
        card._refresh()

def _rec_nsfw_known(self, appid, flag):
    card = self._rec_shelf.cards.get(appid)
    if card is not None:
        card.nsfw = bool(flag)

def _rec_visible(self):
    return not (self._term or self._tag_filter)

def _rec_apply(self, recs):
    self._rec_busy = False
    self._rec_t = time.time()
    shelf = self._rec_shelf
    if not recs:
        shelf.show_message("Add some Store games to your library and play them, and games like them show up here.")
        return
    shelf.fill(recs)
    for r in recs:
        self._rec_art.request(r["appid"])
        self.loader.request(r["appid"], r["base"], r["title"])      # portrait cover + NSFW check (the header stays blurred until it's done)

def _rec_load(self, force=False):
    if self._rec_busy or not self._rec_visible():
        return
    if not force and self._rec_shelf.cards and time.time() - self._rec_t < 600:
        return
    self._rec_busy = True
    if not self._rec_shelf.cards:
        self._rec_shelf.show_message("Finding games like the ones you play...")
    w = TaskWorker(lambda: _fy_recs(force))
    w.done.connect(self._rec_apply)
    w.failed.connect(lambda _e: (setattr(self, "_rec_busy", False),
                                 self._rec_shelf.show_message("Couldn't load recommendations. Check your connection.")))
    self._rec_workers = [x for x in self._rec_workers if x.isRunning()] + [w]
    w.start()

StorePage.__init__ = _rs_init
StorePage._rec_open = _rec_open
StorePage._rec_art_loaded = _rec_art_loaded
StorePage._rec_cover_loaded = _rec_cover_loaded
StorePage._rec_nsfw_known = _rec_nsfw_known
StorePage._rec_visible = _rec_visible
StorePage._rec_apply = _rec_apply
StorePage._rec_load = _rec_load

_rs_prev_start = StorePage._start_search

def _rs_start_search(self):
    _rs_prev_start(self)
    if hasattr(self, "_rec_shelf"):
        self._rec_shelf.setVisible(self._rec_visible())      # hidden while you search or filter by tags
        self._rec_load()

StorePage._start_search = _rs_start_search

_rs_prev_show = StorePage.showEvent

def _rs_show(self, event):
    _rs_prev_show(self, event)
    if hasattr(self, "_rec_shelf"):
        self._rec_load()

StorePage.showEvent = _rs_show


# ── Big Picture: For You tab, Screenshots tab, library toolbar, download limits ──
_BPG_SPEEDS = (0, 1, 2, 5, 10, 20, 50, 100, 250, 500)           # MB/s, 0 = unlimited
_BPE_BAR_TAGS = _BPE_BAR_TAGS + ("rrefresh", "sgame", "sfolder", "dlimit", "dpause")     # toolbar pills the controller can reach

_bpg_o = {n: getattr(_BigPicture, n) for n in (
    "__init__", "leave", "_tab_labels", "_x_enter", "_x_act", "_x_hint", "_x_tag", "_paint_extra", "_paint_library",
    "_paint_downloads", "_act", "mousePressEvent", "keyPressEvent", "_ov_act", "_paint_ov", "_ov_click")}


def _bpg_base(self):
    return 6 + (1 if self._gm_root else 0)          # Library, Store, Friends, Downloads, Workshop, Fan Games, (GMod Addons)


def _bpg_kind(self):
    n0 = _bpg_base(self)
    return "rec" if self._tab == n0 else ("shot" if self._tab == n0 + 1 else None)


@_bpm("__init__")
def _bpg_init(self, app):
    _bpg_o["__init__"](self, app)
    self._rc = {"list": [], "sel": 0, "loading": False, "err": "", "items": {}, "blur": {}, "t": 0.0, "req_t": 0.0}
    self._sg = {"list": [], "sel": 0, "game": "", "games": [], "pix": {}, "confirm": False, "w": []}
    self._lbs = 0                                   # Library toolbar focus (zone "lbar")
    self._lb_rects = []
    self._loader.loaded.connect(self._rc_cover)
    self._loader.nsfw_known.connect(self._rc_nsfw)


@_bpm("leave")
def _bpg_leave(self, show_main=True):
    self._rc["blur"].clear()
    self._sg["pix"].clear()
    self._sg["game"] = ""
    _bpg_o["leave"](self, show_main)


@_bpm("_tab_labels")
def _bpg_tab_labels(self):
    return tuple(_bpg_o["_tab_labels"](self)) + ("For You", "Screenshots")


# ── Library toolbar: view filters + favorite / hide ──
def _bpg_lb_tags(self):
    tags = [("view", k) for _l, k in _LB_VIEWS]
    if self._items:
        tags += [("fav",), ("hide",)]
    return tags


@_bpm("_lb_apply")
def _bpg_lb_apply(self, tag):
    kind = tag[0]
    if kind == "view":
        _bpf_set_view(self._app, tag[1])
        self._refresh()
        label = next(l for l, k in _LB_VIEWS if k == tag[1])
        self._say("Library: %s (%d)" % (label, len(self._items)), 2200)
    elif self._items and 0 <= self._sel < len(self._items):
        old = self._sel
        title = self._items[old]["title"]
        key = "fav" if kind == "fav" else "hidden"
        lb_toggle(key, title)
        on = title in lbmeta()[key]
        self._app.apply_filter(self._app.search_edit.text())
        self._refresh()
        if self._items:
            self._sel = min(old, len(self._items) - 1)
            self._pos = float(self._sel)
        self._cache.clear()
        self._sync_bg(animate=False)
        self._say(("Added to favorites: " if (key == "fav" and on) else "Removed from favorites: " if key == "fav"
                   else "Hidden from your library: " if on else "Back in your library: ") + title, 2600)
    self.update()


def _bpg_plain(self):
    return (self._kb is None and not self._embs and self._st is None and self._ov is None and self._detail is None)


@_bpm("_act")
def _bpg_act(self, name):
    if _bpg_plain(self) and self._tab == 0:
        z = self._zone
        if z == "lbar":
            tags = _bpg_lb_tags(self)
            self._lbs = max(0, min(len(tags) - 1, self._lbs))
            if name in ("left", "right", "up", "down", "back", "accept"):
                self.setCursor(Qt.CursorShape.BlankCursor)
                if name == "left":
                    self._lbs = max(0, self._lbs - 1)
                elif name == "right":
                    self._lbs = min(len(tags) - 1, self._lbs + 1)
                elif name == "up":
                    self._zone = "tabs"
                elif name in ("down", "back"):
                    self._zone = "content"
                else:
                    self._lb_apply(tags[self._lbs])
                self.update()
                return
        elif (z == "content" and name == "up") or (z == "tabs" and name == "down"):
            self.setCursor(Qt.CursorShape.BlankCursor)
            self._hsel = None
            modes = [k for _l, k in _LB_VIEWS]
            self._zone, self._lbs = "lbar", (modes.index(_lb_view["mode"]) if _lb_view["mode"] in modes else 0)
            self.update()
            return
    _bpg_o["_act"](self, name)


@_bpm("mousePressEvent")
def _bpg_mouse(self, e):
    if self._tab == 0 and _bpg_plain(self):
        pt = e.position()
        for n, (r, tag) in enumerate(self._lb_rects):
            if r.contains(pt):
                self._zone, self._lbs = "lbar", n
                self._lb_apply(tag)
                return
    _bpg_o["mousePressEvent"](self, e)


@_bpm("_paint_library")
def _bpg_paint_library(self, p, w, h, m, acc, k):
    self._lb_rects = []
    mode, zone = _lb_view["mode"], self._zone
    if zone == "lbar":
        self._zone = "tabs"                          # no focus ring on the tile while the toolbar has focus
    try:
        if not self._items and mode != "all":
            p.setOpacity(k)
            p.setFont(self._font(h * 0.035))
            p.setPen(QColor(200, 200, 220))
            msg = {"fav": "No favorites yet\nOpen a game's options (X) and pick Add to favorites",
                   "recent": "Nothing played yet\nGames you launch show up here",
                   "hidden": "No hidden games"}.get(mode, "Nothing here")
            p.drawText(self.rect(), int(Qt.AlignmentFlag.AlignCenter), msg)
        else:
            _bpg_o["_paint_library"](self, p, w, h, m, acc, k)
    finally:
        self._zone = zone
    n = len(self._items)
    if n:                                            # gold star on favorites
        fav = lbmeta()["fav"]
        for i in range(max(0, int(self._pos) - 4), min(n, int(self._pos) + 6)):
            if self._items[i]["title"] not in fav:
                continue
            r = self._tile_rect(i)
            if r.right() < 0 or r.left() > w:
                continue
            near = max(0.0, 1 - abs(i - self._pos))
            p.setOpacity(k * (0.5 + 0.5 * near))
            d = h * 0.042
            b = QRectF(r.left() + h * 0.012, r.top() + h * 0.012, d, d)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(0, 0, 0, 170))
            p.drawEllipse(b)
            p.setFont(self._font(d * 0.62, True))
            p.setPen(QColor(255, 200, 61))
            p.drawText(b, int(Qt.AlignmentFlag.AlignCenter), "★")
    p.setOpacity(k)
    # toolbar: view pills on the left, favorite / hide for the selected game on the right
    y, bh, gap = h * 0.127, h * 0.046, h * 0.012
    fm = QFontMetrics(self._font(h * 0.0185, True))
    focus = self._zone == "lbar"
    tags = _bpg_lb_tags(self)
    x = m
    for idx, tag in enumerate(tags):
        if tag[0] == "view":
            text = next(l for l, kk in _LB_VIEWS if kk == tag[1])
            active = tag[1] == mode
            if active:
                text += "  (%d)" % n
        else:
            title = self._items[self._sel]["title"] if 0 <= self._sel < n else ""
            if tag[0] == "fav":
                text, active = ("Remove favorite" if title in lbmeta()["fav"] else "Add favorite"), False
            else:
                text, active = ("Unhide game" if title in lbmeta()["hidden"] else "Hide game"), False
        bw = fm.horizontalAdvance(text) + h * 0.05
        if tag[0] == "fav":
            x = w - m - bw - gap - (fm.horizontalAdvance("Unhide game") + h * 0.05)
        elif tag[0] == "hide":
            x = w - m - bw
        r = QRectF(x, y, bw, bh)
        self._x_pill(p, r, text, acc, sel=(focus and idx == self._lbs), primary=active, size=0.0185)
        self._lb_rects.append((r, tag))
        if tag[0] == "view":
            x += bw + gap


# ── Downloads: speed limit and schedule ──
@_bpm("_paint_downloads")
def _bpg_paint_dl(self, p, w, h, m, acc):
    _bpg_o["_paint_downloads"](self, p, w, h, m, acc)
    cx, cw = w * 0.14, w * 0.72
    bw, bh, gap = h * 0.17, h * 0.05, h * 0.012
    d = dl_limits()
    text = "Limit: " + ("Unlimited" if not d.get("mb_s") else "%g MB/s" % float(d["mb_s"])) + ("  +  schedule" if d.get("sched") else "")
    lw = h * 0.34
    r = QRectF(cx + cw - 2 * bw - gap - gap - lw, h * 0.125, lw, bh)
    self._x_pill(p, r, text, acc, sel=False, primary=bool(d.get("mb_s") or d.get("sched")), size=0.019)
    self._xhits.append((r, ("dlimit",)))


@_bpm("_dlim_open")
def _bpg_dlim_open(self):
    d = dl_limits()
    self._ov = {"kind": "dlim", "sel": 0, "d": {"mb_s": float(d.get("mb_s") or 0), "sched": bool(d.get("sched")),
                                                 "from": int(d.get("from", 1)), "to": int(d.get("to", 8))}, "rects": []}
    self.setCursor(Qt.CursorShape.BlankCursor)
    self.update()


def _bpg_dlim_text(ov, row):
    d = ov["d"]
    if row == 0:
        return "Unlimited" if not d["mb_s"] else "%g MB/s" % d["mb_s"]
    if row == 1:
        return "On" if d["sched"] else "Off"
    if row == 2:
        return "%02d:00" % d["from"]
    return "%02d:00" % d["to"]


def _bpg_dlim_adjust(ov, row, step, wrap=False):
    d = ov["d"]
    if row == 0:
        cur = min(range(len(_BPG_SPEEDS)), key=lambda i: abs(_BPG_SPEEDS[i] - d["mb_s"]))
        j = cur + step
        j = j % len(_BPG_SPEEDS) if wrap else max(0, min(len(_BPG_SPEEDS) - 1, j))
        d["mb_s"] = float(_BPG_SPEEDS[j])
    elif row == 1:
        d["sched"] = not d["sched"]
    elif row == 2:
        d["from"] = (d["from"] + step) % 24
    elif row == 3:
        d["to"] = (d["to"] + step) % 24
    dl_limits_save({"mb_s": d["mb_s"], "sched": d["sched"], "from": d["from"], "to": d["to"]})


# ── For You tab (horizontal covers) ──
@_bpm("_rc_load")
def _bpg_rc_load(self, force=False):
    rc = self._rc
    if rc["loading"]:
        return
    rc["loading"], rc["err"] = True, ""
    w = TaskWorker(lambda: _fy_recs(force))
    w.done.connect(self._rc_done)
    w.failed.connect(self._rc_fail)
    self._workers = [x for x in self._workers if x.isRunning()] + [w]
    w.start()
    self.update()


@_bpm("_rc_done")
def _bpg_rc_done(self, recs):
    rc = self._rc
    rc["loading"], rc["t"] = False, time.time()
    rc["list"], rc["sel"], rc["items"] = list(recs), 0, {}
    for r in recs:
        rc["items"][r["appid"]] = {"appid": r["appid"], "title": r["title"], "path": "", "nsfw": False, "done": False}
        self._loader.request(r["appid"], r["base"], r["title"])      # portrait cover (for the detail page) + NSFW check
    if not recs:
        rc["err"] = "Nothing to recommend yet. Add Store games to your library and play them first."
    self._x_reset_scroll()
    self.update()


@_bpm("_rc_fail")
def _bpg_rc_fail(self, msg):
    self._rc["loading"] = False
    self._rc["err"] = "Couldn't load recommendations. Press A to try again."
    self.update()


@_bpm("_rc_cover")
def _bpg_rc_cover(self, appid, path):
    it = self._rc["items"].get(appid)
    if it is None:
        return
    it["path"], it["done"] = path or "", True
    self._spix.pop(appid, None)
    if self._active:
        self.update()


@_bpm("_rc_nsfw")
def _bpg_rc_nsfw(self, appid, flag):
    it = self._rc["items"].get(appid)
    if it is not None:
        it["nsfw"] = bool(flag)


@_bpm("_rc_enter")
def _bpg_rc_enter(self):
    rc = self._rc
    if not rc["loading"] and (not rc["list"] or time.time() - rc["t"] > 600):
        self._rc_load(False)
    self._rc_ensure()


@_bpm("_rc_ensure")
def _bpg_rc_ensure(self):
    gap, tw, th, cols, x0, top, bot = self._x_grid(2.14)
    row = self._rc["sel"] // cols
    pitch = th + gap
    self._x_ensure(row * pitch, row * pitch + pitch + self.height() * 0.024, bot - top)


@_bpm("_rc_open")
def _bpg_rc_open(self, rec):
    it = self._rc["items"].get(rec["appid"])
    if it is None:
        return
    self._detail, self._detail_btn = {"item": it}, 0
    self._load_details(rec["appid"])
    self.update()


@_bpm("_rc_act")
def _bpg_rc_act(self, name):
    rc = self._rc
    lst = rc["list"]
    n = len(lst)
    rc["sel"] = max(0, min(max(0, n - 1), rc["sel"]))
    if name == "back":
        self._switch_tab(0)
    elif name in ("left", "right", "up", "down"):
        if not n:
            if name == "up":
                _bpx_top(self)
            return
        new = _bpx_grid_nav(rc["sel"], n, self._x_grid(2.14)[3], name)
        if new < 0:
            _bpx_top(self)
            return
        rc["sel"] = new
        self._rc_ensure()
    elif name == "accept":
        if n:
            self._rc_open(lst[rc["sel"]])
        elif not rc["loading"]:
            self._rc_load(False)
    elif name == "x":
        self._say("Refreshing recommendations...", 2000)
        self._rc_load(True)


@_bpm("_paint_rec")
def _bpg_paint_rec(self, p, w, h, m, acc):
    rc = self._rc
    lst = rc["list"]
    top, bot = h * 0.2, h * 0.86
    area = QRectF(0, top, w, bot - top)
    y, bh = h * 0.128, h * 0.046
    self._x_text(p, QRectF(m, y, w * 0.6, bh), "Recommended for you   -   based on the games you play", 0.028, QColor(235, 235, 245), True)
    r = QRectF(w - m - h * 0.2, y, h * 0.2, bh)
    self._x_pill(p, r, "Refresh", acc, size=0.019)
    self._xhits.append((r, ("rrefresh",)))
    if not lst:
        if rc["loading"]:
            self._paint_loading(p, w, h, area, "Finding games you'll like...")
        else:
            self._x_msg(p, area, rc["err"] or "Nothing to recommend yet.")
        return
    now = time.time()
    if now - rc["req_t"] > 5:                       # covers whose request was cancelled by another tab are asked for again
        rc["req_t"] = now
        for rec in lst:
            if not rc["items"][rec["appid"]]["done"]:
                self._loader.request(rec["appid"], rec["base"], rec["title"])

    def draw(r, i, s):
        rec = lst[i]
        it = rc["items"][rec["appid"]]
        url = _BPX_HDR % rec["appid"]
        pm = self._ws_pix(url) if it["done"] else None      # the header waits for the NSFW check
        if pm is not None and not pm.isNull() and it["nsfw"] and not nsfw_revealed():
            b = rc["blur"].get(url)
            if b is None:
                small = pm.scaled(max(8, pm.width() // 24), max(4, pm.height() // 24),
                                  Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
                b = rc["blur"][url] = small.scaled(pm.size(), Qt.AspectRatioMode.IgnoreAspectRatio,
                                                   Qt.TransformationMode.SmoothTransformation)
            pm = b
        badge = "IN LIBRARY" if self._in_library(rec["appid"]) else None
        self._x_tile(p, r, pm, rec["title"], "Because you played " + rec["because"], acc, badge)
    self._x_grid_paint(p, w, h, acc, len(lst), rc["sel"], 2.14, draw)


# ── Screenshots tab ──
def _bpg_shots_all():
    try:
        d = _screenshots_dir()
        paths = [os.path.join(d, n) for n in os.listdir(d) if n.lower().endswith(".png")]
    except Exception:
        return []
    return sorted(paths, key=lambda q: os.path.getmtime(q), reverse=True)


def _bpg_shot_game(path):
    base = os.path.splitext(os.path.basename(path))[0]
    return base.rsplit(" - ", 1)[0] if " - " in base else base


@_bpm("_shots_open")
def _bpg_shots_open(self, title):
    """From a game's options: jump to the Screenshots tab filtered to that game."""
    self._sg["game"] = title
    idx = _bpg_base(self) + 1
    if self._tab == idx:
        self._sg_enter()
    else:
        self._switch_tab(idx)
    self._say("Screenshots: %s (%d)" % (title, len(self._sg["list"])), 2600)


@_bpm("_sg_rebuild")
def _bpg_sg_rebuild(self):
    sg = self._sg
    allp = _bpg_shots_all()
    sg["games"] = sorted({_bpg_shot_game(q) for q in allp}, key=str.casefold)
    lst = _shots_for(sg["game"]) if sg["game"] else allp
    cur = sg["list"][sg["sel"]] if sg["list"] and 0 <= sg["sel"] < len(sg["list"]) else None
    sg["list"] = lst
    sg["sel"] = lst.index(cur) if cur in lst else 0
    if len(sg["pix"]) > 150:
        sg["pix"].clear()


@_bpm("_sg_enter")
def _bpg_sg_enter(self):
    self._sg_rebuild()
    self._sg_ensure()


@_bpm("_sg_ensure")
def _bpg_sg_ensure(self):
    gap, tw, th, cols, x0, top, bot = self._x_grid(1.78)
    row = self._sg["sel"] // cols
    pitch = th + gap
    self._x_ensure(row * pitch, row * pitch + pitch + self.height() * 0.024, bot - top)


def _bpg_sg_pix(sg, path):
    pm = sg["pix"].get(path)
    if pm is None:
        q = QPixmap(path)
        pm = QPixmap() if q.isNull() else q.scaledToWidth(480, Qt.TransformationMode.SmoothTransformation)
        sg["pix"][path] = pm
    return pm


@_bpm("_sg_cycle_game")
def _bpg_sg_cycle_game(self):
    sg = self._sg
    opts = [""] + sg["games"]
    sg["game"] = opts[(opts.index(sg["game"]) + 1) % len(opts)] if sg["game"] in opts else ""
    self._sg_rebuild()
    sg["sel"] = 0
    self._x_reset_scroll()
    self._say("Screenshots: %s" % (sg["game"] or "all games"), 2000)


@_bpm("_sg_act")
def _bpg_sg_act(self, name):
    sg = self._sg
    lst = sg["list"]
    n = len(lst)
    sg["sel"] = max(0, min(max(0, n - 1), sg["sel"]))
    if name == "back":
        self._switch_tab(0)
    elif name in ("left", "right", "up", "down"):
        if not n:
            if name == "up":
                _bpx_top(self)
            return
        new = _bpx_grid_nav(sg["sel"], n, self._x_grid(1.78)[3], name)
        if new < 0:
            _bpx_top(self)
            return
        sg["sel"] = new
        self._sg_ensure()
    elif name == "accept" and n:
        self._shot_view(sg["sel"])
    elif name == "x":
        self._sg_cycle_game()
    elif name == "alt":
        os.makedirs(_screenshots_dir(), exist_ok=True)
        QDesktopServices.openUrl(QUrl.fromLocalFile(_screenshots_dir()))


@_bpm("_paint_shots")
def _bpg_paint_shots(self, p, w, h, m, acc):
    sg = self._sg
    lst = sg["list"]
    top, bot = h * 0.2, h * 0.86
    area = QRectF(0, top, w, bot - top)
    y, bh, gap = h * 0.128, h * 0.046, h * 0.012
    fm = QFontMetrics(self._font(h * 0.019, True))
    self._x_text(p, QRectF(m, y, w * 0.3, bh), "Screenshots", 0.028, QColor(235, 235, 245), True)
    x = w - m
    for text, tag in (("Open folder", "sfolder"), ("Game: " + (sg["game"] or "All"), "sgame")):
        bw = min(h * 0.5, fm.horizontalAdvance(text) + h * 0.06)
        x -= bw
        r = QRectF(x, y, bw, bh)
        self._x_pill(p, r, fm.elidedText(text, Qt.TextElideMode.ElideRight, int(bw - h * 0.03)), acc, size=0.019)
        self._xhits.append((r, (tag,)))
        x -= gap
    if not lst:
        self._x_msg(p, area, ("No screenshots for %s yet" % sg["game"]) if sg["game"]
                    else "No screenshots yet. Press F9 while a game is running to take one.")
        return
    budget = [3]                                     # decode a few thumbnails per frame so scrolling stays smooth

    def draw(r, i, s):
        path = lst[i]
        pm = sg["pix"].get(path)
        if pm is None:
            if budget[0] > 0:
                budget[0] -= 1
                pm = _bpg_sg_pix(sg, path)
            else:
                QTimer.singleShot(30, self.update)
        try:
            when = time.strftime("%d %b %Y  %H:%M", time.localtime(os.path.getmtime(path)))
        except OSError:
            when = ""
        self._x_tile(p, r, pm, _bpg_shot_game(path), when, acc)
    self._x_grid_paint(p, w, h, acc, len(lst), sg["sel"], 1.78, draw)


@_bpm("_shot_view")
def _bpg_shot_view(self, i):
    lst = list(self._sg["list"])
    if not lst:
        return
    i = max(0, min(len(lst) - 1, i))
    self._ov = {"kind": "shot", "list": lst, "i": i, "pm": QPixmap(lst[i]), "confirm": False, "rects": []}
    self.setCursor(Qt.CursorShape.BlankCursor)
    self.update()


def _bpg_shot_step(ov, d):
    n = len(ov["list"])
    if n:
        ov["i"] = (ov["i"] + d) % n
        ov["pm"] = QPixmap(ov["list"][ov["i"]])
        ov["confirm"] = False


def _bpg_shot_share(bp, path):
    fp = getattr(bp._app, "friends_page", None)
    try:
        friends = {(d.get("username") or "Friend"): uid for uid, d in (fp.friends.items() if fp else [])}
    except Exception:
        friends = {}
    if not friends:
        bp._say("Add a friend first to share screenshots", 2800)
        return
    name, ok = QInputDialog.getItem(bp, "Share", "Send to:", sorted(friends), 0, False)
    if not ok:
        return
    game = _bpg_shot_game(path)

    def send():
        cloud_send_message(friends[name], "Screenshot from %s" % game, [prepare_attachment(path)])
        return name
    w = TaskWorker(send)
    w.done.connect(lambda n: bp._say("Sent to %s" % n, 2600))
    w.failed.connect(lambda e: bp._say(e, 3500))
    bp._sg["w"] = [x for x in bp._sg["w"] if x.isRunning()] + [w]
    w.start()
    bp._say("Sending...", 0)


def _bpg_shot_delete(bp, ov):
    path = ov["list"][ov["i"]]
    try:
        os.remove(path)
    except OSError:    # expected: cleanup that may already be done
        pass
    bp._sg["pix"].pop(path, None)
    ov["list"].pop(ov["i"])
    bp._sg_rebuild()
    if not ov["list"]:
        bp._ov = None
        bp._say("Screenshot deleted", 2000)
        return
    ov["i"] = min(ov["i"], len(ov["list"]) - 1)
    ov["pm"] = QPixmap(ov["list"][ov["i"]])
    ov["confirm"] = False
    bp._say("Screenshot deleted", 2000)


# ── tab plumbing ──
@_bpm("_x_enter")
def _bpg_x_enter(self, t):
    n0 = _bpg_base(self)
    kind = "rec" if t == n0 else ("shot" if t == n0 + 1 else None)
    if kind is None:
        _bpg_o["_x_enter"](self, t)
        return
    self._xtimer.stop()
    self._xticks = 0
    self._x_reset_scroll()
    if kind == "rec":
        self._rc_enter()
    else:
        self._sg_enter()
    if self._active and not self._asleep:
        self._xtimer.start()


@_bpm("_x_act")
def _bpg_x_act(self, name):
    kind = _bpg_kind(self)
    if kind == "rec":
        self._rc_act(name)
    elif kind == "shot":
        self._sg_act(name)
    else:
        _bpg_o["_x_act"](self, name)
        return
    self.update()


@_bpm("_x_hint")
def _bpg_x_hint(self):
    kind = _bpg_kind(self)
    if kind == "rec" and self._zone != "bar":
        return "Arrows  Browse      A  Details      X  Refresh      LB / RB  Switch tab      B  Library"
    if kind == "shot" and self._zone != "bar":
        return "Arrows  Browse      A  View      X  Filter by game      Y  Open folder      LB / RB  Switch tab      B  Library"
    return _bpg_o["_x_hint"](self)


@_bpm("_x_tag")
def _bpg_x_tag(self, tag):
    k = tag[0]
    if k == "dlimit":
        self._dlim_open()
    elif k == "rrefresh":
        self._rc_act("x")
    elif k == "sgame":
        self._sg_cycle_game()
    elif k == "sfolder":
        self._sg_act("alt")
    elif _bpg_kind(self) == "rec" and k == "tile":
        rc = self._rc
        if rc["sel"] == tag[1]:
            self._rc_act("accept")
        else:
            rc["sel"] = tag[1]
            self._rc_ensure()
    elif _bpg_kind(self) == "shot" and k == "tile":
        sg = self._sg
        if sg["sel"] == tag[1]:
            self._sg_act("accept")
        else:
            sg["sel"] = tag[1]
            self._sg_ensure()
    else:
        _bpg_o["_x_tag"](self, tag)
        return
    self.update()


@_bpm("_paint_extra")
def _bpg_paint_extra(self, p, w, h, m, acc, k):
    kind = _bpg_kind(self)
    if kind is None:
        _bpg_o["_paint_extra"](self, p, w, h, m, acc, k)
        return
    self._xhits = []
    p.setOpacity(k)
    if kind == "rec":
        self._paint_rec(p, w, h, m, acc)
    else:
        self._paint_shots(p, w, h, m, acc)
    p.setOpacity(1.0)
    if self._zone == "bar":
        items = self._bar_items()
        if items:
            r = items[max(0, min(len(items) - 1, self._barsel))][0]
            self._x_ring(p, r, r.height() / 2)


# ── overlays: download limits + screenshot viewer ──
@_bpm("_ov_act")
def _bpg_ov_act(self, name):
    ov = self._ov
    if ov is None or ov["kind"] not in ("dlim", "shot"):
        _bpg_o["_ov_act"](self, name)
        return
    if name == "start":
        name = "accept"
    if ov["kind"] == "dlim":
        sel = ov["sel"]
        if name == "up":
            ov["sel"] = max(0, sel - 1)
        elif name == "down":
            ov["sel"] = min(4, sel + 1)
        elif name in ("left", "right") and sel < 4:
            _bpg_dlim_adjust(ov, sel, -1 if name == "left" else 1)
        elif name == "accept":
            if sel == 4:
                self._ov = None
            else:
                _bpg_dlim_adjust(ov, sel, 1, wrap=True)
        elif name in ("back", "x"):
            self._ov = None
    else:
        if name in ("left", "right"):
            _bpg_shot_step(ov, -1 if name == "left" else 1)
        elif name in ("back", "accept"):
            self._ov = None
        elif name == "x":
            if ov["confirm"]:
                _bpg_shot_delete(self, ov)
            else:
                ov["confirm"] = True
        elif name == "alt":
            path = ov["list"][ov["i"]]
            QTimer.singleShot(0, lambda: _bpg_shot_share(self, path))
    self.update()


@_bpm("_ov_click")
def _bpg_ov_click(self, tag):
    ov = self._ov
    if ov is None or ov["kind"] not in ("dlim", "shot"):
        _bpg_o["_ov_click"](self, tag)
        return
    k = tag[0]
    if k == "dclose" or k == "sclose":
        self._ov = None
    elif k == "dlm":
        ov["sel"] = tag[1]
        _bpg_dlim_adjust(ov, tag[1], tag[2])
    elif k == "row":
        ov["sel"] = tag[1]
        self._ov_act("accept")
    elif k == "sprev":
        _bpg_shot_step(ov, -1)
    elif k == "snext":
        _bpg_shot_step(ov, 1)
    elif k == "sact":
        self._ov_act(("alt", "x", "back")[tag[1]])
    self.update()


@_bpm("keyPressEvent")
def _bpg_key(self, e):
    ov = self._ov
    if ov is not None and ov["kind"] in ("dlim", "shot"):
        K = Qt.Key
        self._pad_last = False
        name = {K.Key_Up: "up", K.Key_Down: "down", K.Key_Left: "left", K.Key_Right: "right", K.Key_Return: "accept",
                K.Key_Enter: "accept", K.Key_Space: "accept", K.Key_Escape: "back", K.Key_Backspace: "back",
                K.Key_F11: "back", K.Key_X: "x", K.Key_Delete: "x", K.Key_Y: "alt", K.Key_S: "alt"}.get(e.key())
        if name:
            self._ov_act(name)
        return
    _bpg_o["keyPressEvent"](self, e)


@_bpm("_paint_ov")
def _bpg_paint_ov(self, p, w, h, acc):
    ov = self._ov
    if ov["kind"] not in ("dlim", "shot"):
        _bpg_o["_paint_ov"](self, p, w, h, acc)
        return
    ov["rects"] = []
    al_r = int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
    p.setPen(Qt.PenStyle.NoPen)
    if ov["kind"] == "shot":
        p.fillRect(QRectF(0, 0, w, h), QColor(0, 0, 0, 238))
        pm, path = ov["pm"], ov["list"][ov["i"]]
        area = QRectF(w * 0.05, h * 0.1, w * 0.9, h * 0.74)
        if not pm.isNull():
            s = min(area.width() / pm.width(), area.height() / pm.height())
            rw, rh = pm.width() * s, pm.height() * s
            p.drawPixmap(QRectF(area.center().x() - rw / 2, area.center().y() - rh / 2, rw, rh), pm, QRectF(pm.rect()))
        else:
            self._x_msg(p, area, "Couldn't open this screenshot")
        try:
            when = time.strftime("%d %b %Y  %H:%M", time.localtime(os.path.getmtime(path)))
        except OSError:
            when = ""
        self._x_text(p, QRectF(w * 0.05, h * 0.03, w * 0.7, h * 0.05), "%s   -   %s" % (_bpg_shot_game(path), when), 0.026,
                     QColor(235, 235, 245), True)
        self._x_text(p, QRectF(w * 0.75, h * 0.03, w * 0.2, h * 0.05), "%d / %d" % (ov["i"] + 1, len(ov["list"])), 0.022,
                     QColor(170, 170, 200), False, al_r)
        bw, bh, gap = h * 0.24, h * 0.055, h * 0.015
        labels = ("Share (Y)", "Press X again to delete" if ov["confirm"] else "Delete (X)", "Close (B)")
        widths = (bw, h * 0.4 if ov["confirm"] else bw, bw)
        x = w / 2 - (sum(widths) + 2 * gap) / 2
        for j, t in enumerate(labels):
            r = QRectF(x, h * 0.87, widths[j], bh)
            self._x_pill(p, r, t, acc, primary=(j == 1 and ov["confirm"]), size=0.02)
            ov["rects"].append((r, ("sact", j)))
            x += widths[j] + gap
        ov["rects"].append((QRectF(0, h * 0.1, w * 0.15, h * 0.74), ("sprev",)))
        ov["rects"].append((QRectF(w * 0.85, h * 0.1, w * 0.15, h * 0.74), ("snext",)))
        ov["rects"].append((QRectF(0, 0, w, h), ("sclose",)))
        p.setFont(self._font(h * 0.0185))
        p.setPen(QColor(150, 150, 175))
        p.drawText(QRectF(w * 0.05, h * 0.945, w * 0.9, h * 0.035), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                   "Left / Right  Previous / Next      Y  Share with a friend      X  Delete      A / B  Close")
        return
    # download limits panel
    bw, bh, pad = w * 0.5, h * 0.7, h * 0.03
    bx, by = (w - bw) / 2, (h - bh) / 2
    p.fillRect(QRectF(0, 0, w, h), QColor(0, 0, 0, 175))
    p.setBrush(QColor(14, 14, 26, 250))
    p.drawRoundedRect(QRectF(bx, by, bw, bh), h * 0.025, h * 0.025)
    self._x_text(p, QRectF(bx + pad, by + h * 0.025, bw - 2 * pad, h * 0.05), "Download limits", 0.032, QColor(245, 245, 252), True)
    self._x_text(p, QRectF(bx + pad, by + h * 0.08, bw - 2 * pad, h * 0.04),
                 "Applies to every launcher download. Changes are saved straight away.", 0.0185, QColor(170, 170, 200))
    d = ov["d"]
    rows = ("Speed limit", "Only download between set hours", "Start hour", "End hour")
    y, rh, pitch = by + h * 0.15, h * 0.075, h * 0.087
    ar = h * 0.055
    for i in range(5):
        r = QRectF(bx + pad, y + i * pitch, bw - 2 * pad, rh)
        s = i == ov["sel"]
        dim = i in (2, 3) and not d["sched"]
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(acc if s else QColor(255, 255, 255, 22))
        p.drawRoundedRect(r, rh * 0.25, rh * 0.25)
        col = QColor(_on_accent()) if s else (QColor(120, 120, 140) if dim else QColor(235, 235, 245))
        if i == 4:
            self._x_text(p, r, "Done", 0.026, col, True, int(Qt.AlignmentFlag.AlignCenter))
            ov["rects"].append((r, ("row", 4)))
            continue
        self._x_text(p, QRectF(r.left() + pad * 0.7, r.top(), r.width() * 0.55, rh), rows[i], 0.0235, col, s)
        right = QRectF(r.right() - pad * 0.5 - ar, r.top(), ar, rh)
        left = QRectF(right.left() - h * 0.24 - ar, r.top(), ar, rh)
        self._x_text(p, QRectF(left.right(), r.top(), h * 0.24, rh), _bpg_dlim_text(ov, i), 0.0235, col, True, int(Qt.AlignmentFlag.AlignCenter))
        self._x_text(p, left, "<", 0.028, col, True, int(Qt.AlignmentFlag.AlignCenter))
        self._x_text(p, right, ">", 0.028, col, True, int(Qt.AlignmentFlag.AlignCenter))
        ov["rects"].append((left, ("dlm", i, -1)))
        ov["rects"].append((right, ("dlm", i, 1)))
        ov["rects"].append((r, ("row", i)))
    ov["rects"].append((QRectF(0, 0, w, h), ("dclose",)))
    p.setFont(self._font(h * 0.0185))
    p.setPen(QColor(150, 150, 175))
    p.drawText(QRectF(bx + pad, by + bh - h * 0.055, bw - 2 * pad, h * 0.035), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
               "Up / Down  Select      Left / Right  Change      A  Toggle / Done      B  Close")


# ── games started outside the launcher ──
# A game that was already running when the launcher opened, or that was started some other way (desktop shortcut,
# Steam, Explorer, a terminal...), is noticed by a background scan and then counted exactly like a game started with
# the Launch button: Stop button, "Playing" status, playtime, Discord presence, friends. A game is recognised when one
# of its processes is a library game's exe (or runs from that game's folder). Turn it off with
# "detect_running_games": false in the launcher settings file.
_EXT_SCAN_SECS = 4.0
_EXT_EXE_SUFFIX = (".exe", ".x86_64", ".x86", ".appimage", ".sh", ".bat", ".cmd", ".bin")
_EXT_SKIP_WORDS = tuple(globals().get("_BAD_EXE_WORDS", ())) + ("crashpad", "bugreport", "installer")


class _AdoptedProc:
    """Popen look-alike for a game process the launcher did not start itself (so Stop and the watchers work on it)."""
    def __init__(self, ps):
        self._ps = ps
        self.pid = ps.pid
        self.args = []
        self.returncode = None

    def _alive(self):
        import psutil    # lazy: saves memory/startup until used
        try:
            return self._ps.is_running() and self._ps.status() != psutil.STATUS_ZOMBIE
        except psutil.Error:
            return False

    def poll(self):
        if self._alive():
            return None
        if self.returncode is None:
            self.returncode = 0
        return self.returncode

    def wait(self, timeout=None):
        end = None if timeout is None else time.time() + timeout
        while self._alive():
            if end is not None and time.time() >= end:
                raise subprocess.TimeoutExpired(self.args, timeout)
            time.sleep(0.25)
        return self.poll()

    def terminate(self):
        try:
            self._ps.terminate()
        except Exception:    # expected: cleanup that may already be done
            pass

    def kill(self):
        try:
            self._ps.kill()
        except Exception:    # expected: cleanup that may already be done
            pass

    def send_signal(self, sig):
        try:
            self._ps.send_signal(sig)
        except Exception:
            _log_exc("send_signal")


def _ext_fix_path(p):
    """An absolute, comparable path from a process path (Wine's Z:\\ drive is mapped back to /), or ''."""
    if not isinstance(p, str) or not p:
        return ""
    if not sys.platform.startswith("win") and re.match(r"^[A-Za-z]:[\\/]", p):
        if p[0] not in "zZ":
            return ""                       # another Wine drive: can't tell where it lives
        p = p[2:].replace("\\", "/")
    if not os.path.isabs(p):
        return ""
    return os.path.abspath(p)


def _ext_build_index():
    """What the library knows: {'exes': {norm exe: title}, 'folders': {norm folder + sep: title}, 'roots': [norm root + sep]}."""
    exes, folders = {}, {}
    try:
        fan = load_fan_library()
    except Exception:
        fan = []
    for g in load_steam_library() + load_custom_games() + fan:
        exe, title = g.get("exe_path"), g.get("title")
        if not (exe and title):
            continue
        full = _ext_fix_path(exe) or os.path.abspath(exe)
        title = pretty_game_name(_canonical_title(title))
        exes[os.path.normcase(full)] = title
        fol = _game_folder_for([full], os.path.dirname(full))     # None for the shared library folder, a drive root, home
        if fol:
            folders[fol + os.sep] = title
    # Store games don't save an exe_path: the launcher finds the exe inside the game's install folder when you click
    # Launch (find_best_game_exe), or from the exe recorded after a setup.exe install. Index both the same way.
    try:
        recorded = _load_installed_exes()
    except Exception:
        recorded = {}
    for g in load_steam_library() + fan:
        raw_title = g.get("title")
        if not raw_title:
            continue
        title = pretty_game_name(_canonical_title(raw_title))
        try:
            d = os.path.abspath(_safe_installed_game_dir(raw_title))
            if os.path.isdir(d):
                folders[os.path.normcase(d) + os.sep] = title
        except Exception:
            _log_exc("_ext_build_index")
        rec = recorded.get(raw_title) or recorded.get(sanitize_folder_name(raw_title))
        if rec and os.path.isfile(rec):
            full = os.path.abspath(rec)
            exes[os.path.normcase(full)] = title
            fol = _game_folder_for([full], os.path.dirname(full))
            if fol:
                folders[fol + os.sep] = title
    try:
        roots = [os.path.normcase(os.path.abspath(r)) + os.sep for r in library_roots()]
    except Exception:
        roots = []
    return {"exes": exes, "folders": folders, "roots": roots}


def _ext_title_for_path(path, idx):
    norm = os.path.normcase(path)
    if norm in idx["exes"]:
        return idx["exes"][norm]
    best = ""
    for fol in idx["folders"]:
        if norm.startswith(fol) and len(fol) > len(best):
            best = fol
    if best:
        return idx["folders"][best]
    for root in idx["roots"]:
        if norm.startswith(root):
            rel = os.path.relpath(path, root[:-1]).split(os.sep)
            if len(rel) < 2 or rel[0] == "..":
                return None                  # a loose file in the library folder, not a game's folder
            first = rel[0]
            for info in GAME_INFO.values():
                if first.lower().startswith(info["name"].lower()):
                    return pretty_game_name(_canonical_title(info["name"]))
            return pretty_game_name(_canonical_title(first))
    return None


def _ext_match_process(info, idx):
    """(title, exe path) if this process is a library game, else None."""
    name = (info.get("name") or "").lower()
    if name in _TRACK_IGNORE:
        return None
    paths = [info.get("exe")]
    paths += [a for a in (info.get("cmdline") or [])[:8] if isinstance(a, str) and a.lower().endswith(_EXT_EXE_SUFFIX)]
    for raw in paths:
        path = _ext_fix_path(raw)
        if not path:
            continue
        base = os.path.basename(path).lower()
        if any(w in base for w in _EXT_SKIP_WORDS):
            continue
        title = _ext_title_for_path(path, idx)
        if title:
            return title, path
    return None


def _ext_is_running(title):
    low = pretty_game_name(title).casefold()
    return any(pretty_game_name(n).casefold() == low for n in list(_running))


def _ext_scan(cache):
    """-> {title: [(create_time, psutil.Process, exe path)]} for every library game that has a live process."""
    import psutil    # lazy: saves memory/startup until used
    idx = _ext_build_index()
    sig = (tuple(sorted(idx["exes"].items())), tuple(sorted(idx["folders"].items())), tuple(idx["roots"]))
    if cache.get("sig") != sig:                 # the library changed: forget what was decided before
        cache.clear()
        cache["sig"] = sig
    seen_keys = cache.setdefault("procs", {})
    me = os.getpid()
    mine = {me}
    try:
        mine.update(c.pid for c in psutil.Process(me).children(recursive=True))   # the launcher's own helpers/installers
    except psutil.Error:    # expected: the process may already have exited
        pass
    for gpid in list(_ncz_game_pids):             # ... except games a shortcut started through this launcher process
        try:
            gp = psutil.Process(gpid)
            mine.discard(gpid)
            mine.difference_update(c.pid for c in gp.children(recursive=True))
        except psutil.Error:
            _ncz_game_pids.discard(gpid)
    live, found = set(), {}
    for p in psutil.process_iter(["pid", "name", "exe", "cmdline", "create_time"]):
        info = p.info
        pid, ct = info.get("pid"), info.get("create_time") or 0
        if pid is None or pid in mine:
            continue
        key = (pid, ct)
        live.add(key)
        if key not in seen_keys:
            try:
                seen_keys[key] = _ext_match_process(info, idx)
            except Exception:
                seen_keys[key] = None
        hit = seen_keys[key]
        if hit:
            found.setdefault(hit[0], []).append((ct, p, hit[1]))
    for key in [k for k in seen_keys if k not in live]:
        del seen_keys[key]
    return found


class _ExtGameBus(QObject):
    adopt = pyqtSignal(str, object, str)       # title, _AdoptedProc, game folder ('' if unknown)


def _ext_on_adopt(title, proc, folder):
    """GUI thread: from here on it is the same as a game started with Launch."""
    try:
        if _ext_is_running(title) or proc.poll() is not None:
            return
        _track_playing(title, proc, folder or None)
    except Exception:
        _log_exc("_ext_on_adopt")


def _ext_loop(bus, stop=None):
    try:
        import psutil  # noqa: F401
    except ImportError:
        return                                  # without psutil there is nothing to scan with
    cache, streak = {}, {}
    time.sleep(3.0)                             # let the window finish building
    while not (stop is not None and stop()):
        try:
            if load_launcher_settings().get("detect_running_games", True):
                found = _ext_scan(cache)
                for title in list(streak):
                    if title not in found:
                        del streak[title]
                for title, procs in found.items():
                    if _ext_is_running(title):
                        streak.pop(title, None)
                        continue
                    streak[title] = streak.get(title, 0) + 1
                    if streak[title] < (1 if any(pr.pid in _ncz_game_pids for _c, pr, _p in procs) else 2):       # seen on two scans in a row, so a game the launcher is just starting isn't doubled
                        continue
                    ct, ps, path = min(procs, key=lambda x: x[0])      # the oldest process is the game's root
                    streak.pop(title, None)
                    bus.adopt.emit(title, _AdoptedProc(ps), _game_folder_for([path], None) or "")
        except Exception:
            _log_exc("_ext_loop")
        time.sleep(_EXT_SCAN_SECS)






# ── desktop shortcuts ──
# 1. A game's desktop shortcut runs `main.py --launch-game <title>`: if the launcher is open it is told to start the
#    game, otherwise the launcher starts and then starts the game.
# 2. Desktop shortcuts whose name is a game in the store are added to the library automatically (with their path).
# 3. Switching theme / changing the Classic accent colour deletes the launcher's desktop shortcut and makes a new one
#    with the new icon.
_ncz_workers = set()

def _ncz_game_launch_argv(title):
    """([launcher, args..., '--launch-game', <title>], working dir). The title is percent-encoded so any name is safe."""
    target, args, workdir = get_launch_command()
    return [target] + list(args) + ["--launch-game", urllib.parse.quote(str(title), safe="")], workdir

def _ncz_desktop_exec(argv):
    """argv -> the value of a .desktop file's Exec= line (quoting and escaping as the Desktop Entry spec wants)."""
    def q(a):
        a = str(a).replace("\\", "\\\\\\\\")
        for ch in ('"', "`", "$"):
            a = a.replace(ch, "\\\\" + ch)
        return '"' + a.replace("%", "%%") + '"'
    return " ".join(q(a) for a in argv)

def _ncz_launch_arg():
    """The game name from `--launch-game <title>` ('' if the launcher wasn't started from a game's shortcut)."""
    try:
        i = sys.argv.index("--launch-game")
    except ValueError:
        return ""
    return urllib.parse.unquote(sys.argv[i + 1]).strip() if i + 1 < len(sys.argv) else ""

def _ncz_send_launch(title, wait=0):
    """Asks the running launcher to start `title`. True if one answered (retries for `wait` seconds)."""
    try:
        from PyQt6.QtNetwork import QLocalSocket    # lazy: optional module: the except below handles it missing
    except ImportError:
        return False
    deadline = time.time() + wait
    while True:
        try:
            sock = QLocalSocket()
            sock.connectToServer(_instance_name())
            if sock.waitForConnected(800):
                sock.write(b"launch:" + str(title).encode("utf-8"))
                sock.flush()
                sock.waitForBytesWritten(800)
                sock.disconnectFromServer()
                return True
        except Exception:
            _log_exc("_ncz_send_launch")
        if time.time() >= deadline:
            return False
        time.sleep(0.3)

def _ncz_launch_requested(app, title, tries=0):
    """Presses the Play / Launch button of the library game called `title`. The library is built in the background
    while the launcher starts, so keep trying for about 30 seconds."""
    window = getattr(app, "_ncz_main_window", None)
    try:
        if window is not None:
            want = _norm_title(title)
            for card, name in _remote_cards(window):
                if name == title or _norm_title(name) == want:
                    btn = _remote_play_button(card)
                    if btn is not None:
                        if name not in _running:          # already running: nothing to do
                            btn.click()
                        return
    except Exception:
        import traceback    # lazy: saves memory/startup until used
        traceback.print_exc()
    if tries < 60:
        QTimer.singleShot(500, lambda: _ncz_launch_requested(app, title, tries + 1))
    elif window is not None:
        QMessageBox.information(window, "Launch Game",
                                f"Couldn't start {title}. Is it installed and in your library?")

def _ncz_after_window_created(app, window, title):
    """Called once when the window is built: starts the game a (Wine/Proton) shortcut asked for. No desktop auto-add."""
    pending = list(getattr(app, "_ncz_pending_launches", []))
    app._ncz_pending_launches = []
    if title:
        pending.insert(0, title)
    for t in dict.fromkeys(pending):
        QTimer.singleShot(1500, lambda t=t: _ncz_launch_requested(app, t))
    QTimer.singleShot(8000, lambda: _ncz_convert_shortcuts_once(window))     # once: old launcher-routed shortcuts -> direct
    if get_shortcuts_via_launcher():                                         # "Game shortcuts open the launcher" is on
        QTimer.singleShot(15000, lambda: _slr_startup_sync(window))

# ── auto-add desktop shortcuts that are store games ──
def _ncz_autoadd_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "desktop_autoadd.json")

def _ncz_autoadd_load():
    try:
        with open(_ncz_autoadd_path(), encoding="utf-8") as f:
            st = json.load(f)
        if isinstance(st, dict):
            st.setdefault("added", {})
            st.setdefault("cache", {})
            return st
    except Exception:    # expected: file may not exist yet or be unreadable
        pass
    return {"added": {}, "cache": {}}

def _ncz_autoadd_save(st):
    try:
        os.makedirs(os.path.dirname(_ncz_autoadd_path()), exist_ok=True)
        with open(_ncz_autoadd_path(), "w", encoding="utf-8") as f:
            json.dump(st, f)
    except Exception:    # expected: file may not exist yet or be unreadable
        pass

def _ncz_store_lookup(title, cache):
    """(appid, store title, image base) when `title` is exactly a game's name in the Steam store, else None.
    Answers are cached on disk (misses for a week) so the same shortcut isn't looked up on every start."""
    key = _norm_title(title)
    hit = cache.get(key)
    now = time.time()
    if isinstance(hit, list) and len(hit) == 3:
        ts, appid, base = hit
        if appid:
            return appid, title, base
        if now - ts < 7 * 86400:
            return None
    res = _desk_steam_lookup(title)
    if res and _norm_title(res[1]) != key:
        res = None                       # only an exact name counts here, so apps like "Discord" are never taken for games
    cache[key] = [now, res[0] if res else 0, res[2] if res else ""]
    return res

def _ncz_is_own_shortcut(c):
    """The launcher's own shortcuts (and game shortcuts that already open the launcher) are not games to add."""
    blob = " ".join([str(c.get("title", "")), str(c.get("args", "")), " ".join(map(str, c.get("launch_cmd") or [])),
                     str(c.get("launch_file", "")), str(c.get("source", ""))]).lower()
    if "--launch-game" in blob or "ncz games launcher" in blob:
        return True
    here = os.path.dirname(os.path.abspath(__file__)).lower()
    return bool(here) and here in blob

def _ncz_autoadd_scan(dirs, titles, exes, urls, appids, state, key, loader):
    """Worker thread: desktop entries that are exactly a store game and aren't in the library, with a cover each."""
    cache = state.setdefault("cache", {})
    cands = scan_desktop_games(dirs, titles, exes, urls, appids, steam_lookup=lambda t: _ncz_store_lookup(t, cache))
    done = state.get("added", {})
    out = []
    for c in cands:
        if not c.get("appid") or _norm_title(c["title"]) in done or _ncz_is_own_shortcut(c):
            continue
        if c.get("launch_url") and not _norm_title(c["title"]):
            continue
        out.append(c)
    for c in out:
        try:
            c["cover_path"] = _desk_find_cover(c, key, loader) or ""
        except Exception:
            c["cover_path"] = ""
    return out

# kept: used at import time before the later definition at line 51026
def _ncz_reroute_shortcut(c, gid):
    """Makes the desktop shortcut open the launcher, which then starts the game. The original is kept in the settings
    folder. Only .desktop (Linux) and .lnk (Windows) files can be changed; .url / .exe / folders are left alone."""
    src = c.get("source") or ""
    low = src.lower()
    if not src or not os.path.isfile(src) or os.path.islink(src):
        return False
    argv, workdir = _ncz_game_launch_argv(c["title"])
    keep_dir = os.path.join(os.path.dirname(get_launcher_settings_path()), "desktop_shortcuts")
    os.makedirs(keep_dir, exist_ok=True)
    if low.endswith(".desktop") and not sys.platform.startswith("win"):
        shutil.copyfile(src, os.path.join(keep_dir, f"{gid}.orig.desktop"))
        with open(src, encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
        out, in_entry, done = [], False, False
        for ln in lines:
            st = ln.strip()
            if st.startswith("["):
                in_entry = st == "[Desktop Entry]"
            if in_entry and ln.startswith("Exec=") and not done:
                out += ["Exec=" + _ncz_desktop_exec(argv), "X-NCZ-Launcher-Game=true"]
                done = True
                continue
            if in_entry and ln.startswith("Terminal="):
                out.append("Terminal=false")
                continue
            out.append(ln)
        if not done:
            return False
        with open(src, "w", encoding="utf-8") as f:           # same file, so its permissions / trusted flag stay
            f.write("\n".join(out) + "\n")
        return True
    if low.endswith(".lnk") and sys.platform.startswith("win"):
        if os.path.normcase(c.get("launch_file", "")) == os.path.normcase(src):
            return False                                         # the library would launch this very file again
        shutil.copyfile(src, os.path.join(keep_dir, f"{gid}.orig.lnk"))
        q = _ps_quote
        ps = (f"$s=(New-Object -ComObject WScript.Shell).CreateShortcut({q(src)});"
              "if(-not $s.TargetPath){exit 3};"
              "$i=$s.IconLocation;if(-not $i -or $i.StartsWith(',')){$i=$s.TargetPath+',0'};"
              f"$s.TargetPath={q(argv[0])};$s.Arguments={q(subprocess.list2cmdline(argv[1:]))};"
              f"$s.WorkingDirectory={q(workdir)};$s.IconLocation=$i;$s.Save()")
        r = subprocess.run(["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", ps],
                           capture_output=True, timeout=30, creationflags=0x08000000)
        return r.returncode == 0
    return False

def _ncz_autoadd_apply(window, cands, state):
    """GUI thread: adds the found games to the library and points their desktop shortcuts at the launcher."""
    if cands:
        games = load_custom_games()
        stamp = int(time.time() * 1000)
        for n, c in enumerate(cands):
            gid = f"custom_{stamp}_{n}"
            cover = c.get("cover_path") or ""
            if not cover or not os.path.exists(cover):
                source = c["exe_path"] if os.path.exists(c["exe_path"]) else c["source"]
                cover = _desk_icon_cover(source, c["title"],
                                         os.path.join(get_library_cover_dir(), f"desk-{_cover_key(c['title'])}.png"))
            if cover and os.path.exists(cover):
                try:
                    os.makedirs(get_library_cover_dir(), exist_ok=True)
                    dest = os.path.join(get_library_cover_dir(), f"{gid}.img")
                    shutil.copyfile(cover, dest)
                    cover = dest
                except Exception:
                    _log_exc("_ncz_autoadd_apply")
            entry = {"id": gid, "title": c["title"], "exe_path": c["exe_path"], "cover_path": cover, "compat_tool": ""}
            if c.get("launch_file"):
                try:
                    folder = os.path.join(os.path.dirname(get_launcher_settings_path()), "desktop_shortcuts")
                    os.makedirs(folder, exist_ok=True)
                    keep = os.path.join(folder, f"{gid}.lnk")
                    shutil.copyfile(c["launch_file"], keep)
                    c["launch_file"] = keep
                except Exception:
                    _log_exc("_ncz_autoadd_apply")
            for k in ("launch_url", "launch_file", "launch_args", "launch_cmd", "workdir"):
                if c.get(k):
                    entry[k] = c[k]
            games.append(entry)
            save_custom_games(games)         # saved per game so a crash half way doesn't lose the earlier ones
            window.create_custom_card(gid, entry["title"], entry["exe_path"], cover, "")
            state.setdefault("added", {})[_norm_title(c["title"])] = gid
            try:
                _ncz_reroute_shortcut(c, gid)
            except Exception:
                import traceback    # lazy: saves memory/startup until used
                traceback.print_exc()
        window.apply_filter()
    _ncz_autoadd_save(state)

def _ncz_autoadd_desktop(window):
    """Looks through the Desktop for shortcuts named like a store game and adds the new ones to the library."""
    try:
        if getattr(window, "_ncz_autoadd_busy", False) or _ncz_profile:
            return
        dirs = _desktop_dirs()
        if not dirs:
            return
        titles, exes, urls, appids = _desk_known(window)
        state = _ncz_autoadd_load()
        key = get_steamgriddb_key()
        loader = CoverLoader()
        loader.set_key(key)
        window._ncz_autoadd_busy = True
        worker = TaskWorker(lambda: _ncz_autoadd_scan(dirs, titles, exes, urls, appids, state, key, loader))
        _ncz_workers.add(worker)

        def done(cands):
            window._ncz_autoadd_busy = False
            try:
                _ncz_autoadd_apply(window, cands, state)
            except Exception:
                import traceback    # lazy: saves memory/startup until used
                traceback.print_exc()

        def failed(_msg):
            window._ncz_autoadd_busy = False
        worker.done.connect(done)
        worker.failed.connect(failed)
        worker.finished.connect(lambda: _ncz_workers.discard(worker))
        worker.start()
    except Exception:
        window._ncz_autoadd_busy = False
        import traceback    # lazy: saves memory/startup until used
        traceback.print_exc()

# ── update game shortcuts made by older launchers (once) ──
def _ncz_migration_path():
    return os.path.join(os.path.dirname(get_launcher_settings_path()), "shortcut_migration.json")

def _ncz_old_shortcut_title(path):
    """Game name for a desktop shortcut an older launcher made for a game (it started the game directly), else ''."""
    low = path.lower()
    try:
        if low.endswith(".desktop") and not sys.platform.startswith("win"):
            info = _desk_read_ini(path)
            ex = info.get("Exec", "").replace("\\", "/")
            if "game-launcher/shortcuts/" in ex and "--launch-game" not in ex:
                return info.get("Name", "").strip()
        elif low.endswith(".lnk") and sys.platform.startswith("win"):
            r = _desk_parse_lnk(path)
            if r and r[0].lower().endswith(".exe") and "--launch-game" not in r[1]:
                return os.path.splitext(os.path.basename(path))[0]    # old ones are named after the game
    except Exception:    # expected: cleanup that may already be done
        pass
    return ""

# kept: used at import time before the later definition at line 51033
def _ncz_migrate_old_shortcuts(window):
    """First launch since this update: every desktop shortcut an older launcher made for a library game is rewritten
    to open the launcher and then the game. Retries a couple of times in case the library is still loading."""
    try:
        try:
            with open(_ncz_migration_path(), encoding="utf-8") as f:
                st = json.load(f)
        except Exception:
            st = {}
        if st.get("done") or _ncz_profile:
            return
        cards = list(getattr(window, "cards", []))
        if not cards:
            return                                   # library not built yet: try again on the next tick
        lookup = {}
        for _c, t in cards:
            for k in (_norm_title(t), _norm_title(sanitize_folder_name(t))):
                lookup.setdefault(k, t)
        stamp, changed, left = int(time.time() * 1000), 0, 0
        for d in _desktop_dirs():
            try:
                names = sorted(os.listdir(d))
            except OSError:
                continue
            for n in names:
                p = os.path.join(d, n)
                if not os.path.isfile(p) or os.path.islink(p):
                    continue
                t = _ncz_old_shortcut_title(p)
                if not t:
                    continue
                card_title = lookup.get(_norm_title(t))
                if not card_title:
                    left += 1                        # not in the library (any more): leave that shortcut alone
                    continue
                try:
                    if _ncz_reroute_shortcut({"source": p, "title": card_title}, f"old_{stamp}_{changed}"):
                        changed += 1
                    else:
                        left += 1
                except Exception:
                    left += 1
        st["tries"] = int(st.get("tries", 0)) + 1
        st["updated"] = int(st.get("updated", 0)) + changed
        if left == 0 or st["tries"] >= 3:
            st["done"] = True
        os.makedirs(os.path.dirname(_ncz_migration_path()), exist_ok=True)
        with open(_ncz_migration_path(), "w", encoding="utf-8") as f:
            json.dump(st, f)
    except Exception:
        import traceback    # lazy: saves memory/startup until used
        traceback.print_exc()

# ── launcher shortcut: delete + recreate with the new icon ──
def _ncz_theme_icon_src(kind):
    """The icon file a theme uses ('' -> the normal one). Mirrors asset_path('icon.png') for another theme."""
    if kind == "classic":
        if os.path.exists(accent_icon_path()):
            return accent_icon_path()                       # Classic with its own accent colour
        return _theme_icon_file("classic") or os.path.join(ASSETS_DIR, "icon_default.png")
    if kind in ("sunset", "legacy"):
        return _theme_icon_file(kind) or os.path.join(ASSETS_DIR, "icon.png")
    if kind in _ACCOUNT_THEMES:
        return _ensure_theme_icon(_ACCOUNT_THEMES[kind]) or os.path.join(ASSETS_DIR, "icon.png")
    return os.path.join(ASSETS_DIR, "icon.png")

def _ncz_launcher_shortcut_files():
    """The 'NCZ Games Launcher' shortcuts on the Desktop right now. Call from the GUI thread."""
    out = []
    for d in _desktop_dirs():
        for n in ("NCZ Games Launcher.lnk", "NCZ Games Launcher.desktop"):
            p = os.path.join(d, n)
            if os.path.isfile(p):
                out.append(p)
    return out

def _ncz_recreate_launcher_shortcut(existing, theme_key, only_if_changed):
    backups = {}
    try:
        src = _ncz_theme_icon_src(theme_key) if theme_key else None
        icon = prepare_shortcut_icon(src)
        if only_if_changed:
            try:
                with open(_shortcut_marker(), encoding="utf-8") as f:
                    old = f.read().strip()
            except Exception:
                return                                   # this launcher never made the shortcut
            if not icon or os.path.basename(icon) == old:
                return                                   # same icon as before
        for p in existing:
            try:
                with open(p, "rb") as f:
                    backups[p] = f.read()
                os.remove(p)                             # delete the old shortcut ...
            except OSError:    # expected: cleanup that may already be done
                pass
        create_desktop_shortcut(src)                     # ... and make a new one with the new icon
    except Exception:
        for p, data in backups.items():                  # couldn't make the new one: put the old one back
            try:
                if not os.path.exists(p):
                    with open(p, "wb") as f:
                        f.write(data)
                    os.chmod(p, 0o755)
            except Exception:    # expected: cleanup that may already be done
                pass

def _ncz_refresh_launcher_shortcut(theme_key=None, only_if_changed=False):
    """Replaces the launcher's desktop shortcut (if there is one) with a fresh one using the current / chosen
    theme's icon. Runs in the background. Never creates a shortcut the user doesn't have."""
    if _ncz_profile:
        return
    try:
        existing = _ncz_launcher_shortcut_files()
    except Exception:
        return
    if not existing:
        return
    threading.Thread(target=_ncz_recreate_launcher_shortcut, args=(existing, theme_key, only_if_changed),
                     daemon=True).start()


# ── Settings: install missing dependencies ──
# Same package list as bootstrap_win.py. One button checks what's missing and pip-installs it into the Python
# that's running the launcher (the private embeddable Python on Windows), plus Chromium for Playwright.
# Packages installed while the launcher is open are picked up after a restart.
import importlib as _dep_importlib
import importlib.util as _dep_iu
import glob as _dep_glob
from PyQt6.QtWidgets import QPlainTextEdit as _DepLogBox

_DEP_CORE = [("PyQt6", "PyQt6"), ("psutil", "psutil"), ("rarfile", "rarfile"),
             ("playwright", "playwright"), ("pywin32", "win32api")]
_DEP_OPTIONAL = [("pypresence", "pypresence"), ("libtorrent", "libtorrent"), ("pynput", "pynput"),
                 ("nudenet", "nudenet"), ("vgamepad", "vgamepad"),
                 ("PyQt6-WebEngine", "PyQt6.QtWebEngineWidgets"), ("librsync", "librsync")]
_DEP_WIN_ONLY = {"pywin32", "vgamepad"}

def _dep_have(module):
    try:
        return _dep_iu.find_spec(module) is not None
    except Exception:
        return False

def _dep_applicable(pairs):
    win = sys.platform.startswith("win")
    return [(p, m) for p, m in pairs if win or p not in _DEP_WIN_ONLY]

def _dep_python():
    exe = sys.executable
    d, n = os.path.split(exe)
    if n.lower() == "pythonw.exe" and os.path.exists(os.path.join(d, "python.exe")):
        return os.path.join(d, "python.exe")      # pythonw has no stdout to read pip's output from
    return exe

def _dep_env():
    env = {k: v for k, v in os.environ.items() if k not in ("PYTHONHOME", "PYTHONPATH")}
    env["PYTHONIOENCODING"] = "utf-8"
    return env

def _dep_chromium_present():
    base = os.environ.get("PLAYWRIGHT_BROWSERS_PATH")
    if not base:
        if sys.platform.startswith("win"):
            base = os.path.join(os.environ.get("LOCALAPPDATA") or os.path.expanduser("~"), "ms-playwright")
        elif sys.platform == "darwin":
            base = os.path.expanduser("~/Library/Caches/ms-playwright")
        else:
            base = os.path.expanduser("~/.cache/ms-playwright")
    return bool(_dep_glob.glob(os.path.join(base, "chromium-*")))

def _dep_missing():
    """(missing core pip names, missing optional pip names, chromium missing?)"""
    core = [p for p, m in _dep_applicable(_DEP_CORE) if not _dep_have(m)]
    opt = [p for p, m in _dep_applicable(_DEP_OPTIONAL) if not _dep_have(m)]
    chromium = _dep_have("playwright") and not _dep_chromium_present()
    return core, opt, chromium

_FFMPEG_URLS = ["https://www.gyan.dev/ffmpeg/builds/ffmpeg-release-essentials.zip",
                "https://github.com/BtbN/FFmpeg-Builds/releases/download/latest/ffmpeg-master-latest-win64-gpl.zip"]

def _dep_ffmpeg_dir():
    return os.path.join(os.environ.get("LOCALAPPDATA") or os.path.expanduser("~"), "NCZ_Games_Launcher", "ffmpeg")

def _dep_add_to_path(folder):
    """Adds folder to this process's PATH and permanently to the user's PATH (no admin needed)."""
    cur = os.environ.get("PATH", "")
    if folder.lower() not in [x.strip().lower() for x in cur.split(os.pathsep)]:
        os.environ["PATH"] = folder + os.pathsep + cur
    if not sys.platform.startswith("win"):
        return
    import winreg, ctypes    # lazy: saves memory/startup until used
    with winreg.OpenKey(winreg.HKEY_CURRENT_USER, "Environment", 0,
                        winreg.KEY_READ | winreg.KEY_SET_VALUE) as key:
        try:
            old, kind = winreg.QueryValueEx(key, "Path")
        except FileNotFoundError:
            old, kind = "", winreg.REG_EXPAND_SZ
        parts = [x for x in old.split(";") if x.strip()]
        if folder.lower() not in [x.strip().lower().rstrip("\\") for x in parts]:
            parts.append(folder)
            winreg.SetValueEx(key, "Path", 0, kind if kind in (winreg.REG_SZ, winreg.REG_EXPAND_SZ)
                              else winreg.REG_EXPAND_SZ, ";".join(parts))
    try:      # tell Explorer / new terminals the environment changed
        ctypes.windll.user32.SendMessageTimeoutW(0xFFFF, 0x1A, 0, "Environment", 2, 5000, None)
    except Exception:
        _log_exc("_dep_add_to_path")

def _dep_ffmpeg_missing():
    return sys.platform.startswith("win") and shutil.which("ffmpeg") is None

# if ffmpeg was installed by the launcher earlier, make sure this run can see it
try:
    if sys.platform.startswith("win") and os.path.exists(os.path.join(_dep_ffmpeg_dir(), "ffmpeg.exe")):
        _dep_add_to_path(_dep_ffmpeg_dir())
except Exception:
    _log_exc("<module>")

class _DepPanel(QFrame):
    _line = pyqtSignal(str)
    _finished = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName("Panel")
        self._busy = False
        pl = QVBoxLayout(self)
        pl.setContentsMargins(22, 18, 22, 18)
        row = QHBoxLayout()
        text = QVBoxLayout()
        text.setSpacing(2)
        name = QLabel("Dependencies")
        name.setObjectName("RowTitle")
        desc = QLabel("Installs any Python packages the launcher needs that are missing (PyQt6, psutil, rarfile, "
                      "playwright + Chromium, pypresence, libtorrent...). Needs internet. "
                      "Restart the launcher afterwards so new packages get picked up.")
        desc.setObjectName("RowDesc")
        desc.setWordWrap(True)
        self.status = QLabel()
        self.status.setObjectName("RowDesc")
        self.status.setWordWrap(True)
        text.addWidget(name)
        text.addWidget(desc)
        text.addWidget(self.status)
        self.btn = QPushButton("Install missing dependencies")
        self.btn.clicked.connect(self.start_install)
        row.addLayout(text, 1)
        row.addWidget(self.btn)
        pl.addLayout(row)
        self.log = _DepLogBox()
        self.log.setReadOnly(True)
        self.log.setMaximumHeight(150)
        self.log.hide()
        pl.addWidget(self.log)
        self._line.connect(self._on_line)
        self._finished.connect(self._on_finished)
        self.refresh()

    def refresh(self):
        core, opt, chromium = _dep_missing()
        miss = core + opt + (["Chromium"] if chromium else []) + (["ffmpeg"] if _dep_ffmpeg_missing() else [])
        if miss:
            self.status.setText("Missing: " + ", ".join(miss))
        else:
            self.status.setText("Everything is installed.")
        self.btn.setEnabled(bool(miss) and not self._busy)

    def _on_line(self, s):
        self.log.appendPlainText(s)

    def _on_finished(self, summary):
        self._busy = False
        self.log.appendPlainText(summary)
        _dep_importlib.invalidate_caches()
        self.refresh()
        self.btn.setText("Install missing dependencies")

    def start_install(self):
        if self._busy:
            return
        self._busy = True
        self.btn.setEnabled(False)
        self.btn.setText("Installing...")
        self.log.clear()
        self.log.show()
        threading.Thread(target=self._work, daemon=True).start()

    def _run(self, cmd):
        self._line.emit("> " + " ".join(os.path.basename(c) if i == 0 else c for i, c in enumerate(cmd)))
        flags = 0x08000000 if sys.platform.startswith("win") else 0
        p = subprocess.Popen(cmd, env=_dep_env(), stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                             stderr=subprocess.STDOUT, text=True, errors="replace", creationflags=flags)
        for line in p.stdout:
            line = line.rstrip()
            if line:
                self._line.emit(line)
        return p.wait() == 0

    def _install_ffmpeg(self):
        dest = _dep_ffmpeg_dir()
        os.makedirs(dest, exist_ok=True)
        zp = os.path.join(dest, "ffmpeg.zip")
        last_err = None
        for url in _FFMPEG_URLS:
            try:
                self._line.emit("Downloading ffmpeg (~80 MB)...")
                req = urllib.request.Request(url, headers={"User-Agent": "NCZ-Games-Launcher"})
                with urllib.request.urlopen(req, timeout=30, context=_NCZ_SSL_CTX) as r, open(zp, "wb") as f:
                    shutil.copyfileobj(r, f)
                last_err = None
                break
            except Exception as e:
                last_err = e
        if last_err:
            raise last_err
        with zipfile.ZipFile(zp) as z:
            for n in z.namelist():
                base = os.path.basename(n).lower()
                if base in ("ffmpeg.exe", "ffprobe.exe") and "/bin/" in n.replace("\\", "/"):
                    with z.open(n) as src, open(os.path.join(dest, base), "wb") as out:
                        shutil.copyfileobj(src, out)
        os.remove(zp)
        if not os.path.exists(os.path.join(dest, "ffmpeg.exe")):
            raise RuntimeError("ffmpeg.exe not found in the download")
        _dep_add_to_path(dest)
        self._line.emit("ffmpeg installed and added to PATH: " + dest)

    def _work(self):
        failed = []
        try:
            core, opt, chromium = _dep_missing()
            py = _dep_python()
            pip = [py, "-m", "pip", "install", "--disable-pip-version-check", "--no-warn-script-location"]
            if (core or opt) and not (_dep_have("setuptools") and _dep_have("wheel")):
                self._run(pip + ["--upgrade", "setuptools", "wheel"])
            if core:
                if not self._run(pip + ["--only-binary=:all:", *core]):
                    for p in core:                    # one bad package shouldn't block the rest
                        if not self._run(pip + ["--only-binary=:all:", p]):
                            failed.append(p)
            for p in opt:
                if not (self._run(pip + ["--only-binary=:all:", p]) or
                        self._run(pip + ["--no-build-isolation", p])):
                    failed.append(p)
            _dep_importlib.invalidate_caches()
            if _dep_have("playwright") and not _dep_chromium_present():
                self._line.emit("Downloading Chromium (~150 MB)...")
                if not self._run([py, "-m", "playwright", "install", "chromium"]):
                    failed.append("Chromium")
            if _dep_ffmpeg_missing():
                try:
                    self._install_ffmpeg()
                except Exception as e:
                    self._line.emit(f"ffmpeg failed: {e}")
                    failed.append("ffmpeg")
            summary = "Done. Restart the launcher to use the new packages."
            if failed:
                summary = "Done, but couldn't install: " + ", ".join(failed) + "."
        except Exception as e:
            summary = f"Install failed: {e}"
        self._finished.emit(summary)

_dep_prev_settings_init = SettingsPage.__init__

def _dep_settings_init(self, *a, **k):
    _dep_prev_settings_init(self, *a, **k)
    try:
        layout = self.layout()
        panel = _DepPanel()
        idx = max(layout.count() - 1, 0)
        layout.insertSpacing(idx, 12)
        layout.insertWidget(idx + 1, panel)
    except Exception:
        _log_exc("_dep_settings_init")

SettingsPage.__init__ = _dep_settings_init


# ── Game shortcuts launch the exe directly ──
# Shortcuts you create from a game's menu in the launcher start the game's exe on their own. The launcher no longer
# adds / rewrites desktop shortcuts by itself; launcher-routed shortcuts of games downloaded through the launcher are made direct once (_ncz_convert_shortcuts_once).
def get_shortcuts_via_launcher():
    """Settings > "Game shortcuts open the launcher". On: library games' desktop shortcuts open the launcher in the tray,
    which then starts the game (`--launch-game`). Off (default): shortcuts start the game's exe directly.
    A Windows game on Linux, which needs Wine/Proton, always opens through the launcher."""
    try:
        return bool(load_launcher_settings().get("shortcuts_open_launcher", False))
    except Exception:
        return False

def _sc_args_text(a):
    if not a:
        return ""
    return subprocess.list2cmdline([str(x) for x in a]) if isinstance(a, (list, tuple)) else str(a)

def _sc_can_direct(exe, compat_tool=""):
    """Windows: any exe. Linux: only native games (a Windows exe needs Wine/Proton, which the launcher sets up)."""
    if not exe or not os.path.exists(exe):
        return False
    if sys.platform.startswith("win"):
        return True
    return not compat_tool and not exe.lower().endswith(".exe")

def _sc_game_exe_argv(exe, args=""):
    """[launcher, ..., '--game-exe', <exe>, ('--game-args', <args>)]: starts the exe itself, then keeps the launcher in the tray."""
    target, largs, workdir = get_launch_command()
    argv = [target] + list(largs) + ["--game-exe", urllib.parse.quote(str(exe), safe="")]
    if args:
        argv += ["--game-args", urllib.parse.quote(str(args), safe="")]
    return argv, workdir

def _sc_write_direct(path, title, exe, args="", workdir=""):
    """Writes a shortcut at `path` that starts the game's exe itself (the launcher only comes along quietly in the tray,
    unless it is already open). Raises on failure."""
    argv, lworkdir = _sc_game_exe_argv(exe, args)
    if sys.platform.startswith("win"):
        q = _ps_quote
        ps = (f"$s=(New-Object -ComObject WScript.Shell).CreateShortcut({q(path)});"
              f"$s.TargetPath={q(argv[0])};$s.Arguments={q(subprocess.list2cmdline(argv[1:]))};"
              f"$s.WorkingDirectory={q(lworkdir)};"
              f"$s.IconLocation={q(exe + ',0')};$s.Description={q(title)};$s.Save()")
        subprocess.run(["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", ps],
                       check=True, capture_output=True, timeout=30, creationflags=0x08000000)
        return
    icon = ""
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            for ln in f:
                if ln.startswith("Icon="):
                    icon = ln.strip()
    except OSError:    # expected: file may not exist yet or be unreadable
        pass
    if not icon:
        p = _exe_icon_png(exe, sanitize_folder_name(title) or "Game")
        icon = f"Icon={p}" if p else ""
    with open(path, "w", encoding="utf-8") as f:
        f.write("[Desktop Entry]\nType=Application\n"
                f"Name={title}\nExec={_ncz_desktop_exec(argv)}\nPath={lworkdir}\n"
                + (icon + "\n" if icon else "") + "Terminal=false\nCategories=Game;\n")
    os.chmod(path, 0o755)

def _ncz_game_exe_arg():
    """(exe, args) from `--game-exe <exe> [--game-args <args>]`, else ('', '')."""
    def val(flag):
        try:
            i = sys.argv.index(flag)
        except ValueError:
            return ""
        return urllib.parse.unquote(sys.argv[i + 1]) if i + 1 < len(sys.argv) else ""
    return val("--game-exe").strip(), val("--game-args")

_ncz_game_pids = set()      # games this process started for a shortcut (--game-exe): they count as games, not launcher helpers

def _ncz_spawn_game_exe(exe, args=""):
    """Starts the game's exe on its own, detached from the launcher."""
    if not exe or not os.path.isfile(exe):
        return False
    popen = globals().get("_RealPopen", subprocess.Popen)
    kw = dict(cwd=os.path.dirname(exe), stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
              stderr=subprocess.DEVNULL, close_fds=True)
    try:
        if sys.platform.startswith("win"):
            cmd = subprocess.list2cmdline([exe]) + (" " + args if args else "")
            proc = popen(cmd, creationflags=0x00000008 | 0x00000200, **kw)      # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
        else:
            proc = popen([exe] + (shlex.split(args) if args else []), start_new_session=True, **kw)
        _ncz_game_pids.add(proc.pid)
        return True
    except Exception:
        import traceback    # lazy: saves memory/startup until used
        traceback.print_exc()
        return False

def _sc_launcher_title(path):
    """Game title if this desktop file opens the launcher for a game (`--launch-game <title>`), else ''."""
    low = path.lower()
    try:
        if low.endswith(".lnk") and sys.platform.startswith("win"):
            r = _desk_parse_lnk(path)
            if r and "--launch-game" in (r[1] or ""):
                t = r[1].split()
                return urllib.parse.unquote(t[t.index("--launch-game") + 1].strip('"'))
        elif low.endswith(".desktop") and not sys.platform.startswith("win"):
            with open(path, encoding="utf-8", errors="replace") as f:
                txt = f.read()
            m = re.search(r'--launch-game"?\s+"?([^"\s]+)', txt)
            if m:
                return urllib.parse.unquote(m.group(1).replace("%%", "%"))
    except Exception:    # expected: cleanup that may already be done
        pass
    return ""

def _sc_restore_all():
    """Desktop shortcuts that open the launcher -> back to what they were. Returns (restored, left)."""
    keep_dir = os.path.join(os.path.dirname(get_launcher_settings_path()), "desktop_shortcuts")
    added = _ncz_autoadd_load().get("added", {})
    custom = {_norm_title(g.get("title", "")): g for g in load_custom_games()}
    done = left = 0
    for d in _desktop_dirs():
        try:
            names = sorted(os.listdir(d))
        except OSError:
            continue
        for n in names:
            p = os.path.join(d, n)
            if not os.path.isfile(p) or os.path.islink(p):
                continue
            title = _sc_launcher_title(p)
            if not title:
                continue
            ext = ".lnk" if p.lower().endswith(".lnk") else ".desktop"
            gid = added.get(_norm_title(title))
            orig = os.path.join(keep_dir, f"{gid}.orig{ext}") if gid else ""
            try:
                if orig and os.path.isfile(orig):
                    shutil.copyfile(orig, p)                  # the shortcut exactly as it was
                    done += 1
                    continue
                g = custom.get(_norm_title(title))
                if g and _sc_can_direct(g.get("exe_path", ""), g.get("compat_tool", "")):
                    _sc_write_direct(p, title, g["exe_path"], _sc_args_text(g.get("launch_args")),
                                     g.get("workdir", ""))
                    done += 1
                    continue
            except Exception:
                _log_exc("_sc_restore_all")
            left += 1
    return done, left

# --- keep the launcher from rewriting shortcuts while the option is off
_sc_prev_reroute = _ncz_reroute_shortcut

def _ncz_reroute_shortcut(c, gid):
    if not get_shortcuts_via_launcher():
        return False
    return _sc_prev_reroute(c, gid)

_sc_prev_migrate = _ncz_migrate_old_shortcuts

def _ncz_migrate_old_shortcuts(window):
    if not get_shortcuts_via_launcher():
        return                                    # not marked done, so it still runs if the option is turned back on
    return _sc_prev_migrate(window)

# --- new game shortcuts
_sc_prev_create = create_game_shortcut

def create_game_shortcut(app, title, exe, compat_tool="", fallback_icon="", launch_args=None):
    if get_shortcuts_via_launcher() or not _sc_can_direct(exe, compat_tool):
        return _sc_prev_create(app, title, exe, compat_tool, fallback_icon, launch_args)
    from PyQt6.QtCore import QStandardPaths    # lazy: saves memory/startup until used
    desktop = QStandardPaths.writableLocation(QStandardPaths.StandardLocation.DesktopLocation) or os.path.expanduser("~/Desktop")
    try:
        os.makedirs(desktop, exist_ok=True)
        target = os.path.join(desktop, (sanitize_folder_name(title) or "Game") +
                              (".lnk" if sys.platform.startswith("win") else ".desktop"))
        _sc_write_direct(target, title, exe, _sc_args_text(launch_args))
        if not sys.platform.startswith("win"):
            try:
                subprocess.run(["gio", "set", target, "metadata::trusted", "true"], capture_output=True, timeout=5)
            except Exception:
                _log_exc("create_game_shortcut")
        QMessageBox.information(app, "Desktop Shortcut", f"Shortcut created (launches the game directly):\n{target}")
    except Exception as e:
        QMessageBox.warning(app, "Desktop Shortcut", f"Couldn't create the shortcut: {e}")

def _sc_downloaded_exe(title):
    """The exe of a game that was downloaded through the launcher (it has an installed-version record), else ''."""
    want = _norm_title(title)
    names = [n for n in _load_installed_versions() if _norm_title(n) == want]
    for n in names:
        try:
            exe = _find_game_exe(_safe_installed_game_dir(n)) or _fan_installed_exe(n)
        except Exception:
            exe = ""
        if exe and os.path.exists(exe):
            return n, exe
    return "", ""

def _ncz_convert_shortcuts_once(window):
    """Once: a desktop shortcut that opens the launcher for a game (`--launch-game`) is rewritten to start the exe directly,
    but only for games downloaded through the launcher. Every other shortcut is left exactly as it is."""
    try:
        if _ncz_profile or load_launcher_settings().get("shortcuts_made_direct_v2") or get_shortcuts_via_launcher():
            return
        def work():
            try:
                for d in _desktop_dirs():
                    try:
                        names = sorted(os.listdir(d))
                    except OSError:
                        continue
                    for n in names:
                        path = os.path.join(d, n)
                        if not os.path.isfile(path) or os.path.islink(path):
                            continue
                        title = _sc_launcher_title(path)
                        if not title:
                            continue
                        game, exe = _sc_downloaded_exe(title)
                        if not exe or not _sc_can_direct(exe, ""):
                            continue                       # not a launcher download (or needs Wine/Proton): untouched
                        try:
                            _sc_write_direct(path, game, exe)
                        except Exception:
                            _log_exc("work")
                st = load_launcher_settings()
                st["shortcuts_made_direct_v2"] = True
                save_launcher_settings(st)
            except Exception:
                import traceback    # lazy: saves memory/startup until used
                traceback.print_exc()
        threading.Thread(target=work, daemon=True).start()
    except Exception:
        _log_exc("_sc_settings_init")


# ── pages built the first time they're opened ──
# Store, Store detail, GE-Proton, Wine, GMod addons, Fan Games and Fan detail used to be built at startup although a normal
# start never opens them. A placeholder keeps each one's slot (so hard-coded indexes like pages.setCurrentIndex(4) and the
# nav buttons keep working); the real page is built when the placeholder is shown or when code reads win.<name>
# (AdaptiveApp.__getattr__). Startup wiring goes into on-built hooks. Code that only wants the page if it exists uses
# self.__dict__.get(name) (hasattr / getattr would build it).
class _LazyPagePlaceholder(QWidget):
    def __init__(self, app, name):
        super().__init__()
        self.setObjectName("Content")
        self._app, self._name = app, name

    def showEvent(self, e):
        super().showEvent(e)
        QTimer.singleShot(0, self._build_if_shown)

    def _build_if_shown(self):
        try:
            if self.isVisible():        # still the page on screen (not just passed through while the stack changed)
                _lazy_build(self._app, self._name)
        except RuntimeError:
            pass                        # already replaced

def _lazy_page(app, name, factory, *hooks):
    """Adds a placeholder for page `name` to app.pages and returns it."""
    if "_lazy_pages" not in app.__dict__:
        app._lazy_pages = {}
    ph = _LazyPagePlaceholder(app, name)
    app._lazy_pages[name] = {"ph": ph, "factory": factory, "hooks": list(hooks)}
    app.pages.addWidget(ph)
    return ph

def _lazy_on_built(app, name, hook):
    """hook(page) now if the page exists, otherwise right after it's built."""
    page = app.__dict__.get(name)
    if page is not None:
        hook(page)
    elif name in app.__dict__.get("_lazy_pages", {}):
        app._lazy_pages[name]["hooks"].append(hook)

def _lazy_slot(app, name):
    """The page if built, else its placeholder (None if neither): for indexOf / 'is this the current page' checks."""
    page = app.__dict__.get(name)
    if page is not None:
        return page
    ent = app.__dict__.get("_lazy_pages", {}).get(name)
    return ent["ph"] if ent else None

def _lazy_build(app, name):
    page = app.__dict__.get(name)
    if page is not None:
        return page
    ent = app.__dict__.get("_lazy_pages", {}).get(name)
    if ent is None:
        raise AttributeError(name)
    page = ent["factory"]()
    app.__dict__[name] = page               # set first: hooks and signal handlers below may read it
    ph, stack = ent["ph"], app.pages
    idx, was_current = stack.indexOf(ph), stack.currentWidget() is ph
    stack.blockSignals(True)
    try:
        stack.insertWidget(idx, page)
        if was_current:
            stack.setCurrentWidget(page)    # before removing the placeholder, or the stack shows the next page meanwhile
        stack.removeWidget(ph)
    finally:
        stack.blockSignals(False)
    ph.deleteLater()
    for hook in ent["hooks"]:
        try:
            hook(page)
        except Exception:
            import traceback    # lazy: saves memory/startup until used
            traceback.print_exc()
    ent["hooks"] = []
    if was_current:
        stack.currentChanged.emit(stack.currentIndex())     # listeners see the real page open (blocked above)
    _memlog(f"page built: {name}")
    return page

def _lazy_getattr(self, name):
    lazy = self.__dict__.get("_lazy_pages") if not name.startswith("__") else None
    if lazy and name in lazy:
        return _lazy_build(self, name)
    raise AttributeError(f"'{type(self).__name__}' object has no attribute '{name}'")
AdaptiveApp.__getattr__ = _lazy_getattr    # kept as patch: _lazy_getattr belongs to the lazy-page memory work, which stays exactly as it is


# ── chess page: timers only while they have something to do ──
# The page is kept after you leave it, and its 100 ms clock, 1.5 s game poll and 10 s inbox poll kept firing for good.
#   clock_timer: only while a board is on screen (_tick did nothing otherwise; a clock that ran out is flagged on return)
#   inbox_timer: only while the lobby is on screen (_poll_inbox already returned early otherwise)
#   game_timer:  only while an online game is going (it already slows to 5 s while the page isn't shown)
def _ch_sync_timers(self):
    try:
        shown = self.isVisible()
        idx = self.stack.currentIndex()
        for t, on in ((self.clock_timer, shown and idx == 1), (self.inbox_timer, shown and idx == 0),
                      (self.game_timer, bool(self.net_gid) and self.net_state not in ("over", "cancelled"))):
            if on and not t.isActive():
                t.start()
            elif not on and t.isActive():
                t.stop()
    except (AttributeError, RuntimeError):    # expected: cleanup that may already be done
        pass

_ch_prev_init = NczChessPage.__init__
def _ch_timers_init(self, *a, **k):
    _ch_prev_init(self, *a, **k)
    self.stack.currentChanged.connect(lambda _i: _ch_sync_timers(self))
    _ch_sync_timers(self)
NczChessPage.__init__ = _ch_timers_init

_ch_prev_show = NczChessPage.showEvent
def _ch_timers_show(self, e):
    _ch_prev_show(self, e)
    _ch_sync_timers(self)
NczChessPage.showEvent = _ch_timers_show

def _ch_timers_hide(self, e):
    QWidget.hideEvent(self, e)
    _ch_sync_timers(self)
NczChessPage.hideEvent = _ch_timers_hide

_ch_prev_poll_game = NczChessPage._poll_game
def _ch_timers_poll_game(self):
    _ch_sync_timers(self)       # starts it for a new online game (open_online calls this), stops it once the game is over
    _ch_prev_poll_game(self)
NczChessPage._poll_game = _ch_timers_poll_game


# ── memory: NCZ_MEMLOG=1 logging, free memory while hidden in the tray ──
_MEMLOG = os.environ.get("NCZ_MEMLOG", "").strip() not in ("", "0")

def _mem_usage():
    """(working set MiB, private MiB) on Windows, (RSS MiB, anonymous RSS MiB) on Linux, None if unknown."""
    try:
        if sys.platform.startswith("win"):
            import ctypes    # lazy: saves memory/startup until used
            from ctypes import wintypes    # lazy: saves memory/startup until used
            class _PMC(ctypes.Structure):       # PROCESS_MEMORY_COUNTERS_EX
                _fields_ = [("cb", wintypes.DWORD), ("PageFaultCount", wintypes.DWORD)] + [
                    (n, ctypes.c_size_t) for n in ("PeakWorkingSetSize", "WorkingSetSize", "QuotaPeakPagedPoolUsage",
                                                   "QuotaPagedPoolUsage", "QuotaPeakNonPagedPoolUsage", "QuotaNonPagedPoolUsage",
                                                   "PagefileUsage", "PeakPagefileUsage", "PrivateUsage")]
            pmc = _PMC()
            pmc.cb = ctypes.sizeof(pmc)
            psapi, k32 = ctypes.WinDLL("psapi"), ctypes.WinDLL("kernel32")     # own handles: don't touch windll's shared argtypes
            k32.GetCurrentProcess.restype = wintypes.HANDLE
            psapi.GetProcessMemoryInfo.argtypes = [wintypes.HANDLE, ctypes.c_void_p, wintypes.DWORD]
            if psapi.GetProcessMemoryInfo(k32.GetCurrentProcess(), ctypes.byref(pmc), pmc.cb):
                return pmc.WorkingSetSize / 1048576.0, pmc.PrivateUsage / 1048576.0
        elif os.path.exists("/proc/self/status"):
            vals = {}
            with open("/proc/self/status") as f:
                for line in f:
                    k, _, v = line.partition(":")
                    if k in ("VmRSS", "RssAnon"):
                        vals[k] = int(v.split()[0]) / 1024.0
            if "VmRSS" in vals:
                return vals["VmRSS"], vals.get("RssAnon", 0.0)
    except Exception:    # expected: optional module may be missing
        pass
    return None

def _memlog(what):
    if not _MEMLOG:
        return
    m = _mem_usage()
    names = ("working set", "private") if sys.platform.startswith("win") else ("RSS", "anon")
    text = time.strftime("%H:%M:%S ") + f"[memlog] {what}: " + (
        f"{names[0]} {m[0]:.1f} MiB, {names[1]} {m[1]:.1f} MiB" if m else "unknown")
    if sys.stdout is not None:
        print(text, flush=True)
    else:       # pythonw / shortcut: no console, so keep it next to launcher.json
        try:
            with open(os.path.join(os.path.dirname(get_launcher_settings_path()), "memlog.txt"), "a", encoding="utf-8") as f:
                f.write(text + "\n")
        except Exception:
            _log_exc("_memlog")

def _memlog_start(window):
    """Called once from main(): startup figure now, then every 60 s."""
    if not _MEMLOG:
        return
    _memlog("startup")
    t = QTimer(window)
    t.setInterval(60 * 1000)
    t.timeout.connect(lambda: _memlog("every 60 s (window " + ("shown" if window.isVisible() else "hidden") + ")"))
    t.start()
    window._memlog_timer = t

# Timers that only redraw the window: paused while it's hidden (tray / Big Picture), restarted when it's shown again.
# Not paused: _lib_timer ("playing" listeners), _state_timer (presence), friends / chat / group polls, overlay, remote.
def _ui_pause_targets(self):
    out = [getattr(self, n, None) for n in ("_stop_timer", "_pt_ui_timer", "_gmod_timer", "_unread_timer")]
    gp = getattr(getattr(self, "friends_page", None), "group_page", None)
    out.append(getattr(gp, "tick_timer", None))         # group composer's 1 s "timed out" countdown
    return [t for t in out if t is not None]

def _ui_timers_pause(self):
    paused = getattr(self, "_ui_paused_timers", [])
    for t in _ui_pause_targets(self):
        try:
            if t.isActive():
                t.stop()
                paused.append(t)
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    self._ui_paused_timers = paused
    movies = getattr(self, "_ui_paused_movies", [])          # chat GIFs kept animating (decoding frames) while hidden
    for mv in self.findChildren(QMovie):
        try:
            if mv.state() == QMovie.MovieState.Running:
                mv.setPaused(True)
                movies.append(mv)
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    self._ui_paused_movies = movies
    _web_tabs_sleep(self, True)

def _web_tabs_sleep(self, sleep):
    """NCZFront tabs are frozen (no JS, no timers) while the window is hidden, unless NCZFront is what's playing."""
    page = self.__dict__.get("web_page")
    if page is None or (sleep and _now_playing.get("name") == "NCZFront"):
        return
    try:
        from PyQt6.QtWebEngineCore import QWebEnginePage    # lazy: saves memory/startup until used
        want = QWebEnginePage.LifecycleState.Frozen if sleep else QWebEnginePage.LifecycleState.Active
        for i in range(page.tabs.count()):
            pg = page.tabs.widget(i).page()
            if pg.lifecycleState() != want and (not sleep or pg.lifecycleState() == QWebEnginePage.LifecycleState.Active):
                pg.setLifecycleState(want)
    except Exception as e:
        _ncz_log(f"NCZFront: couldn't change the tabs' sleep state ({e!r})")

def _ui_timers_resume(self):
    paused, self._ui_paused_timers = getattr(self, "_ui_paused_timers", []), []
    _web_tabs_sleep(self, False)
    for mv in getattr(self, "_ui_paused_movies", []):
        try:
            mv.setPaused(False)
        except RuntimeError:
            pass                        # that chat message was removed meanwhile
    self._ui_paused_movies = []
    gp = getattr(getattr(self, "friends_page", None), "group_page", None)
    for t in paused:
        try:
            if t is getattr(gp, "tick_timer", None) and not gp.chat_timer.isActive():
                continue            # the group chat was closed meanwhile
            t.start()
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
    if paused:
        try:
            _pt_refresh_cards(self)     # playtime labels right away instead of after 3 s
        except Exception:
            _log_exc("_ui_timers_resume")

_mem_prev_show = AdaptiveApp.showEvent
def _mem_show_event(self, ev):
    _mem_prev_show(self, ev)
    if not self.isMinimized():
        _ui_timers_resume(self)
        _memlog("window shown")
AdaptiveApp.showEvent = _mem_show_event    # kept as patch chain: the base is inherited from Qt, so there is no method to merge into

def _mem_drop_store_cards(page):
    """Drops a Store / Fan Games page's loaded cards (and their covers). Its showEvent loads them again from the top, with
    the same search and tags, the next time the page is opened."""
    if page is None or not getattr(page, "_cards", None):
        return
    page._request_id += 1               # a page still on its way is ignored
    page.loader.cancel_pending()
    page._clear_cards()
    page._next_start, page._total = 0, 0
    page._exhausted = page._loading = False
    page._loaded_once = False

def _mem_trim():
    """Hands unused memory back to the OS, so Task Manager's figure really drops (pages come back on demand)."""
    try:
        if sys.platform.startswith("win"):
            import ctypes    # lazy: saves memory/startup until used
            from ctypes import wintypes    # lazy: saves memory/startup until used
            psapi, k32 = ctypes.WinDLL("psapi"), ctypes.WinDLL("kernel32")
            k32.GetCurrentProcess.restype = wintypes.HANDLE
            psapi.EmptyWorkingSet.argtypes = [wintypes.HANDLE]
            psapi.EmptyWorkingSet(k32.GetCurrentProcess())
        elif sys.platform.startswith("linux"):
            import ctypes    # lazy: saves memory/startup until used
            ctypes.CDLL("libc.so.6").malloc_trim(0)
    except Exception:    # expected: optional module may be missing
        pass

def _mem_free_hidden(self, step=0):
    """Hidden to the tray: drop the Store / Fan Games cards, then (once Qt has deleted them) clear the pixmap cache,
    collect garbage and trim. Skipped while Big Picture is what hid the window, or if it was shown again meanwhile."""
    bp = getattr(self, "_big_picture", None)
    if not self.isHidden() or (bp is not None and getattr(bp, "_active", False)):
        return
    try:
        if step == 0:
            for name in ("store_page", "fan_page"):
                _mem_drop_store_cards(self.__dict__.get(name))
            _free_idle_chess(self)
            _free_big_picture(self)
            QTimer.singleShot(500, lambda: _mem_free_hidden(self, 1))     # deleteLater runs in the event loop first
            return
        from PyQt6.QtGui import QPixmapCache    # lazy: saves memory/startup until used
        import gc    # lazy: saves memory/startup until used
        QPixmapCache.clear()
        gc.collect()
        _mem_trim()
        _memlog("after freeing memory (hidden)")
    except Exception:
        import traceback    # lazy: saves memory/startup until used
        traceback.print_exc()

def _free_idle_chess(self):
    """The chess page is kept for good once opened; free it while hidden unless a game is going (open_chess builds it
    again)."""
    cp = self.__dict__.get("chess_page")
    if cp is None:
        return
    try:
        g = cp.game
        busy = ((g is not None and not getattr(g, "result", None)) or
                (cp.net_gid and cp.net_state not in ("over", "cancelled")) or cp.bg._cbs or self.pages.currentWidget() is cp)
        if busy:
            return
        for t in (cp.clock_timer, cp.game_timer, cp.inbox_timer):
            t.stop()
        try:
            _theme_listeners.remove(cp.restyle)
        except ValueError:    # expected: missing or odd value: the default is fine
            pass
        self.pages.removeWidget(cp)
        del self.__dict__["chess_page"]
        cp.deleteLater()
        _memlog("freed the chess page (hidden)")
    except Exception:
        import traceback    # lazy: saves memory/startup until used
        traceback.print_exc()

# Big Picture: kept for good once opened. It's freed while hidden in the tray when it isn't open and nothing is embedded in
# it; open_big_picture builds a new one. Its callbacks in the module-level listener lists are removed first (game
# tracking calls _playing_listeners without error handling, so a deleted Big Picture there would break it).
_BP_LISTENER_LISTS = ("_playing_listeners", "_bp_friend_listeners", "_theme_listeners")

_bpf_prev_open = AdaptiveApp.open_big_picture
def _bpf_open(self):
    if getattr(self, "_big_picture", None) is not None:
        return _bpf_prev_open(self)
    before = {n: len(globals()[n]) for n in _BP_LISTENER_LISTS if isinstance(globals().get(n), list)}
    _bpf_prev_open(self)
    bp = getattr(self, "_big_picture", None)
    if bp is not None:      # exactly what it added (a bound signal's emit can't be matched back to its object later)
        bp._ncz_added = [(n, globals()[n][i]) for n, k in before.items() for i in range(k, len(globals()[n]))]
AdaptiveApp.open_big_picture = _bpf_open    # kept as patch chain: the wrapper uses the original twice

def _free_big_picture(self):
    bp = self.__dict__.get("_big_picture")
    if bp is None or getattr(bp, "_active", False) or getattr(bp, "_embs", None):
        return
    try:
        from PyQt6 import sip    # lazy: saves memory/startup until used
        for n, cb in getattr(bp, "_ncz_added", []):
            try:
                globals()[n].remove(cb)
            except ValueError:    # expected: missing or odd value: the default is fine
                pass
        kids = set(id(o) for o in bp.findChildren(QObject)) | {id(bp)}
        for n in _BP_LISTENER_LISTS:                 # added later (e.g. its friends tab): bound methods of it or its parts
            lst = globals().get(n)
            if isinstance(lst, list):
                lst[:] = [cb for cb in lst if id(getattr(cb, "__self__", None)) not in kids]
        loader = getattr(bp, "_loader", None)
        for name in ("cancel_pending", "shutdown"):
            try:
                getattr(loader, name)()
            except Exception:
                _log_exc("_free_big_picture")
        del self.__dict__["_big_picture"]
        bp.deleteLater()
        _memlog("freed Big Picture (hidden)")
    except Exception:
        import traceback    # lazy: saves memory/startup until used
        traceback.print_exc()

_ch_prev_sync_look = _ch_sync_launcher_look
def _ch_sync_launcher_look(page):
    """Ignores a chess page that was freed (its pages.currentChanged hook stays connected)."""
    try:
        from PyQt6 import sip    # lazy: optional module: the except below handles it missing
        if sip.isdeleted(page):
            return
    except ImportError:    # expected: optional module may be missing
        pass
    return _ch_prev_sync_look(page)

_mem_prev_hide = getattr(AdaptiveApp, "hideEvent", QMainWindow.hideEvent)
def _mem_hide_event(self, ev):
    _mem_prev_hide(self, ev)
    if self.isHidden():                 # hidden for real (tray, Big Picture), not just minimized
        _ui_timers_pause(self)
        _memlog("window hidden")
        QTimer.singleShot(1500, lambda: _mem_free_hidden(self))      # not on a quick hide / show
AdaptiveApp.hideEvent = _mem_hide_event    # kept as patch chain: the base is inherited from Qt, so there is no method to merge into


# ── Big Picture: startup animation ──
# Plays a full-screen animation (with sound) every time Big Picture opens. Press ANY key / mouse button / controller button to skip.
# Settings -> "Big Picture startup animation": pick the NCZ default, turn it off, or use your own. A custom animation is an image
# file (GIF / WebP / APNG, or a PNG / JPG still) dropped in the "startup_animations" folder inside the launcher's settings folder
# (Settings has an "Add custom animation" button and an "Open folder" button). An audio file with the SAME NAME (WAV / MP3 / OGG /
# FLAC / M4A) next to it plays together with it. The default is assets/ncz_bigpicture_startup.gif + .wav.
_NCZ_SU_IMG = (".gif", ".webp", ".apng", ".png", ".jpg", ".jpeg")
_NCZ_SU_SND = (".wav", ".mp3", ".ogg", ".flac", ".m4a", ".aac")
_NCZ_SU_DEFAULT = "ncz_bigpicture_startup"
_NCZ_SU_STILL_MS = 3500          # a still image (PNG / JPG) is shown this long
_NCZ_SU_MAX_MS = 15000           # safety cap: never block Big Picture longer than this
_NCZ_SU_GRACE_MS = 450           # ignore input this long (the key / button that opened Big Picture may still be held)
_NCZ_SU = {"snd": None}


def _ncz_su_dir():
    d = os.path.join(os.path.dirname(get_launcher_settings_path()), "startup_animations")
    try:
        os.makedirs(d, exist_ok=True)
    except OSError:
        _log_exc("_ncz_su_dir")
    return d


def _ncz_su_find_sound(base):
    for ext in _NCZ_SU_SND:
        for e in (ext, ext.upper()):
            if os.path.isfile(base + e):
                return base + e
    return ""


def _ncz_su_customs():
    """[(name, image path, sound path or "")] for every custom animation in the folder."""
    out, d = [], _ncz_su_dir()
    try:
        for fn in sorted(os.listdir(d), key=str.lower):
            base, ext = os.path.splitext(fn)
            if ext.lower() in _NCZ_SU_IMG:
                out.append((base, os.path.join(d, fn), _ncz_su_find_sound(os.path.join(d, base))))
    except OSError:    # expected: file may not exist yet or be unreadable
        pass
    return out


def _ncz_su_choice():
    """(image, sound) to play, or None when the startup animation is off / missing."""
    sel = str(load_launcher_settings().get("bp_startup_anim", "default") or "default")
    if sel == "off":
        return None
    if sel.startswith("custom:"):
        for name, img, snd in _ncz_su_customs():
            if name == sel[7:]:
                return img, snd
    img = os.path.join(ASSETS_DIR, _NCZ_SU_DEFAULT + ".gif")        # default (also the fallback if a custom one was deleted)
    if not os.path.isfile(img):
        return None
    return img, _ncz_su_find_sound(os.path.join(ASSETS_DIR, _NCZ_SU_DEFAULT))


class _NczSuSound:
    """WAV through QSoundEffect, anything else through QMediaPlayer. It is LOADED first and played on play(), so the picture and
    the sound can start on the same instant (on_ready is called once the audio is loaded, or at once if there is no audio)."""

    def __init__(self, path, on_ready):
        self._fx = self._pl = self._ao = None
        self._cli = None
        self._path = path
        self._vol = 0.7
        self._cb = on_ready
        if _lx_cli_available():
            self._ready()                                 # Linux: played through paplay/ffplay/... in play()
            return
        try:
            if path.lower().endswith(".wav"):
                from PyQt6.QtMultimedia import QSoundEffect    # lazy: saves memory/startup until used
                self._fx = QSoundEffect()
                self._fx.setVolume(self._vol)
                self._fx.statusChanged.connect(self._fx_status)
                self._fx.setSource(QUrl.fromLocalFile(path))
                self._fx_status()
            else:
                from PyQt6.QtMultimedia import QMediaPlayer, QAudioOutput    # lazy: saves memory/startup until used
                self._ao = QAudioOutput()
                self._ao.setVolume(self._vol)
                self._pl = QMediaPlayer()
                self._pl.setAudioOutput(self._ao)
                self._pl.mediaStatusChanged.connect(self._pl_status)
                self._pl.setSource(QUrl.fromLocalFile(path))
        except Exception:
            self._fx = self._pl = self._ao = None
            self._ready()

    def _ready(self):
        cb, self._cb = self._cb, None
        if cb is not None:
            try:
                cb()
            except RuntimeError:                      # the overlay was already closed
                pass

    def _fx_status(self, *_a):
        if self._fx is not None and self._fx.status().name in ("Ready", "Error"):
            self._ready()

    def _pl_status(self, st):
        if getattr(st, "name", "") in ("LoadedMedia", "BufferedMedia", "InvalidMedia"):
            self._ready()

    def play(self):
        try:
            bad = (self._fx is None and self._pl is None) \
                or (self._fx is not None and self._fx.status().name == "Error") \
                or (self._pl is not None and (self._pl.mediaStatus().name == "InvalidMedia" or self._pl.error().name != "NoError"))
        except Exception:
            bad = True
        if bad:                                           # Linux: QtMultimedia failed, use a command-line player
            self._cli = _lx_cli_play(self._path, self._vol)
            return
        try:
            if self._fx is not None:
                self._fx.play()
            if self._pl is not None:
                self._pl.play()
        except Exception:
            _log_exc("play")

    def _set(self, v):
        try:
            if self._fx is not None:
                self._fx.setVolume(v)
            if self._ao is not None:
                self._ao.setVolume(v)
        except Exception:
            _log_exc("_set")

    def stop(self):
        try:
            if self._fx is not None:
                self._fx.stop()
            if self._pl is not None:
                self._pl.stop()
            if self._cli is not None and self._cli.poll() is None:
                self._cli.terminate()
        except Exception:    # expected: cleanup that may already be done
            pass

    def fade_stop(self, ms=180):
        steps = 8
        for i in range(1, steps + 1):
            QTimer.singleShot(int(ms * i / steps), lambda v=self._vol * (1 - i / steps): self._set(v))
        QTimer.singleShot(ms + 30, self.stop)


class _NczStartup(QWidget):
    """Covers Big Picture while the startup animation plays."""
    done = pyqtSignal()

    def __init__(self, host, img, snd):
        from PyQt6.QtCore import QVariantAnimation, QEasingCurve    # lazy: saves memory/startup until used
        super().__init__(host)
        self._host, self._ending, self._skipped = host, False, False
        self._op, self._last, self._sched = 1.0, -1, False
        self._t0 = time.time()
        self._movie, self._still = QMovie(img), None
        if not self._movie.isValid() or self._movie.frameCount() == 1:
            self._movie = None
            self._still = QPixmap(img)
        self.setGeometry(host.rect())
        host.installEventFilter(self)
        self._fade = QVariantAnimation(self)
        self._fade.setEasingCurve(QEasingCurve.Type.InOutQuad)
        self._fade.valueChanged.connect(self._on_fade)
        self._fade.finished.connect(self._finish_now)
        self._cap = QTimer(self)
        self._cap.setSingleShot(True)
        self._cap.timeout.connect(lambda: self.end(False))
        _ncz_su_stop_sound()
        self._started = self._sndok = self._snd_made = False
        self._cap_ms = _NCZ_SU_MAX_MS if self._movie is not None else _NCZ_SU_STILL_MS
        if self._movie is not None:
            self._movie.frameChanged.connect(self._on_frame)
        self._wait = QTimer(self)                        # never wait long for the audio device
        self._wait.setSingleShot(True)
        self._wait.timeout.connect(self._go)
        if snd:
            self._wait.start(700)
            _NCZ_SU["snd"] = _NczSuSound(snd, self._snd_ready)
        else:
            self._sndok = True
        self._snd_made = True
        self._try_go()

    def _snd_ready(self):
        self._sndok = True
        self._try_go()

    def _try_go(self):
        if self._sndok and self._snd_made:
            self._go()

    def _go(self):
        """Picture and sound start on the same instant, so they stay in sync."""
        if self._started or self._ending:
            return
        self._started = True
        self._wait.stop()
        snd = _NCZ_SU.get("snd")
        if snd is not None:
            snd.play()
        if self._movie is not None:
            self._movie.start()
        self._cap.start(self._cap_ms)

    def eventFilter(self, obj, ev):
        from PyQt6.QtCore import QEvent    # lazy: saves memory/startup until used
        try:
            if obj is self._host and ev.type() == QEvent.Type.Resize:
                self.setGeometry(self._host.rect())
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
        return False

    def _on_frame(self, n):
        if self._ending:
            return
        cnt = self._movie.frameCount()
        if n < self._last:                               # wrapped around: one full play-through is done
            self.end(False)
            return
        self._last = n
        if cnt > 1 and n >= cnt - 1 and not self._sched:
            self._sched = True
            QTimer.singleShot(max(0, self._movie.nextFrameDelay()), lambda: self.end(False))
        self.update()

    def can_skip(self):
        return (time.time() - self._t0) * 1000.0 >= _NCZ_SU_GRACE_MS

    def end(self, skipped):
        """Fade out. Skipped -> quick fade and the sound fades too; played to the end -> the sound's tail rings on over Big Picture."""
        if self._ending:
            return
        self._ending, self._skipped = True, skipped
        self._cap.stop()
        if skipped:
            snd = _NCZ_SU.get("snd")
            if snd is not None:
                snd.fade_stop(180)
        self._fade.setDuration(180 if skipped else 380)
        self._fade.setStartValue(1.0)
        self._fade.setEndValue(0.0)
        self._fade.start()

    def _on_fade(self, v):
        self._op = float(v)
        self.update()

    def _finish_now(self):
        if self._movie is not None:
            self._movie.stop()
        try:
            self._host.removeEventFilter(self)
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
        self.hide()
        self.done.emit()
        self.deleteLater()
        try:
            self._host.setFocus()
            self._host.update()
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass

    def kill(self):
        """Close at once (Big Picture left / went to sleep)."""
        if self._movie is not None:
            self._movie.stop()
        self._cap.stop()
        self._fade.stop()
        _ncz_su_stop_sound()
        try:
            self._host.removeEventFilter(self)
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass
        self.hide()
        self.deleteLater()

    def mousePressEvent(self, e):
        if self.can_skip():
            self.end(True)
        e.accept()

    def keyPressEvent(self, e):
        if self.can_skip() and not e.isAutoRepeat():
            self.end(True)
        e.accept()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        p.setOpacity(self._op)
        p.fillRect(self.rect(), QColor(0, 0, 0))
        pm = self._movie.currentPixmap() if self._movie is not None else self._still
        w, h = self.width(), self.height()
        if pm is not None and not pm.isNull():
            s = pm.size().scaled(w, h, Qt.AspectRatioMode.KeepAspectRatioByExpanding)       # cover the screen, like Steam
            p.drawPixmap(QRectF((w - s.width()) / 2.0, (h - s.height()) / 2.0, s.width(), s.height()), pm, QRectF(pm.rect()))
        age = (time.time() - self._t0) * 1000.0
        if age > 700 and not self._ending:                  # small hint at the top (the bottom of the default animation is white)
            p.setOpacity(self._op * min(1.0, (age - 700) / 500.0) * 0.55)
            f = p.font()
            f.setPixelSize(max(12, int(h * 0.019)))
            p.setFont(f)
            p.setPen(QColor(255, 255, 255))
            p.drawText(QRectF(0, h * 0.03, w - w * 0.025, h * 0.04),
                       int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter), "Press any key to skip")
        p.end()


def _ncz_su_stop_sound():
    snd = _NCZ_SU.get("snd")
    if snd is not None:
        snd.stop()
    _NCZ_SU["snd"] = None


def _ncz_su_live(bp):
    ov = getattr(bp, "_ncz_su", None)
    try:
        if ov is not None and ov.isVisible() and not ov._ending:
            return ov
    except RuntimeError:    # expected: the widget or object may already be deleted
        pass
    return None


def _ncz_su_kill(bp):
    ov = getattr(bp, "_ncz_su", None)
    bp._ncz_su = None
    if ov is not None:
        try:
            ov.kill()
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass


def _ncz_su_start(bp):
    _ncz_su_kill(bp)
    ch = _ncz_su_choice()
    if ch is None:
        return
    img, snd = ch
    if not load_launcher_settings().get("bp_startup_sound", True):
        snd = ""
    ov = _NczStartup(bp, img, snd)
    bp._ncz_su = ov
    ov.show()
    ov.raise_()


_ncz_su_enter_o = _BigPicture.enter


def _ncz_su_enter(self):
    was_active = bool(self._active)
    _ncz_su_enter_o(self)
    if not was_active:                                    # only when Big Picture really opens (not when it wakes after a game)
        try:
            _ncz_su_start(self)
        except Exception:
            import traceback    # lazy: saves memory/startup until used
            traceback.print_exc()


_BigPicture.enter = _ncz_su_enter

_ncz_su_leave_o = _BigPicture.leave
_ncz_su_stopawake_o = _BigPicture._stop_awake


def _ncz_su_leave(self, *a, **k):
    _ncz_su_kill(self)
    return _ncz_su_leave_o(self, *a, **k)


def _ncz_su_stopawake(self):
    _ncz_su_kill(self)
    return _ncz_su_stopawake_o(self)


_BigPicture.leave = _ncz_su_leave
_BigPicture._stop_awake = _ncz_su_stopawake

_ncz_su_key_o = _BigPicture.keyPressEvent
_ncz_su_act_o = _BigPicture._act


def _ncz_su_key(self, e):
    ov = _ncz_su_live(self)
    if ov is not None:                                    # any key skips (key repeat of the opening shortcut is ignored)
        if ov.can_skip() and not e.isAutoRepeat():
            ov.end(True)
        e.accept()
        return
    _ncz_su_key_o(self, e)


def _ncz_su_act(self, name, *a, **k):
    ov = _ncz_su_live(self)
    if ov is not None:                                    # any controller button / stick direction skips
        if ov.can_skip():
            ov.end(True)
        return
    return _ncz_su_act_o(self, name, *a, **k)


_BigPicture.keyPressEvent = _ncz_su_key
_BigPicture._act = _ncz_su_act


# ── Settings: choose / add / remove startup animations ──
def _ncz_su_fill(combo):
    sel = str(load_launcher_settings().get("bp_startup_anim", "default") or "default")
    combo.blockSignals(True)
    combo.clear()
    combo.addItem("NCZ default", "default")
    combo.addItem("Off", "off")
    for name, _img, _snd in _ncz_su_customs():
        combo.addItem(name, "custom:" + name)
    i = combo.findData(sel)
    combo.setCurrentIndex(i if i >= 0 else 0)
    combo.blockSignals(False)


def _ncz_su_set(key, value):
    s = load_launcher_settings()
    s[key] = value
    save_launcher_settings(s)


def _ncz_su_add_custom(sp):
    imgs = " ".join("*" + e for e in _NCZ_SU_IMG)
    path, _f = QFileDialog.getOpenFileName(sp, "Choose a startup animation", "",
                                           "Animations / images (%s);;All files (*)" % imgs)
    if not path:
        return
    base, ext = os.path.splitext(os.path.basename(path))
    if ext.lower() not in _NCZ_SU_IMG or not QMovie(path).isValid():
        QMessageBox.warning(sp, "Startup animation", "Pick a GIF, WebP, APNG, PNG or JPG file.")
        return
    d = _ncz_su_dir()
    safe = re.sub(r"[^\w\-. ()]", "_", base).strip() or "custom"
    name, n = safe, 2
    while any(os.path.exists(os.path.join(d, name + e)) for e in _NCZ_SU_IMG):
        name, n = "%s %d" % (safe, n), n + 1
    try:
        shutil.copy2(path, os.path.join(d, name + ext.lower()))
        ask = QMessageBox.question(sp, "Startup animation",
                                   "Add a sound to play with it? (WAV, MP3, OGG, FLAC or M4A)")
        if ask == QMessageBox.StandardButton.Yes:
            snds = " ".join("*" + e for e in _NCZ_SU_SND)
            sp2, _f = QFileDialog.getOpenFileName(sp, "Choose a startup sound", "", "Audio (%s);;All files (*)" % snds)
            if sp2:
                e2 = os.path.splitext(sp2)[1].lower()
                if e2 in _NCZ_SU_SND:
                    shutil.copy2(sp2, os.path.join(d, name + e2))
                else:
                    QMessageBox.warning(sp, "Startup animation", "That isn't a supported audio file, so no sound was added.")
    except OSError as err:
        QMessageBox.warning(sp, "Startup animation", "Couldn't add it: %s" % err)
        return
    _ncz_su_set("bp_startup_anim", "custom:" + name)
    _ncz_su_fill(sp._ncz_su_combo)


def _ncz_su_remove_custom(sp):
    sel = str(load_launcher_settings().get("bp_startup_anim", "default") or "default")
    if not sel.startswith("custom:"):
        QMessageBox.information(sp, "Startup animation", "Select one of your custom animations first.")
        return
    name = sel[7:]
    if QMessageBox.question(sp, "Startup animation", "Remove \"%s\"?" % name) != QMessageBox.StandardButton.Yes:
        return
    for n, img, snd in _ncz_su_customs():
        if n == name:
            for f in (img, snd):
                try:
                    if f:
                        os.remove(f)
                except OSError:    # expected: cleanup that may already be done
                    pass
    _ncz_su_set("bp_startup_anim", "default")
    _ncz_su_fill(sp._ncz_su_combo)


def _ncz_su_add_settings(sp):
    if getattr(sp, "_ncz_su_panel", None) is not None:
        return
    panel = QFrame()
    panel.setObjectName("Panel")
    pl = QVBoxLayout(panel)
    pl.setContentsMargins(22, 18, 22, 18)

    def row(title, desc, ctrl, first=False):
        if not first:
            pl.addSpacing(10)
        r, col = QHBoxLayout(), QVBoxLayout()
        col.setSpacing(2)
        t = QLabel(title)
        t.setObjectName("RowTitle")
        d = QLabel(desc)
        d.setObjectName("RowDesc")
        d.setWordWrap(True)
        col.addWidget(t)
        col.addWidget(d)
        ctrl.setFixedWidth(220)
        r.addLayout(col, 1)
        r.addWidget(ctrl)
        pl.addLayout(r)

    combo = QComboBox()
    combo.setCursor(Qt.CursorShape.PointingHandCursor)
    _ncz_su_fill(combo)
    combo.currentIndexChanged.connect(lambda _i, c=combo: _ncz_su_set("bp_startup_anim", c.currentData() or "default"))
    row("Big Picture startup animation", "Played full-screen when Big Picture opens. Press any key to skip it", combo, True)

    snd = QPushButton()
    snd.setCheckable(True)
    snd.setCursor(Qt.CursorShape.PointingHandCursor)
    on = bool(load_launcher_settings().get("bp_startup_sound", True))
    snd.setChecked(on)
    snd.setText("On" if on else "Off")

    def snd_toggled(_c=False, b=snd):
        b.setText("On" if b.isChecked() else "Off")
        _ncz_su_set("bp_startup_sound", b.isChecked())
    snd.clicked.connect(snd_toggled)
    row("Startup animation sound", "Play the sound that goes with the startup animation", snd)

    add = QPushButton("Add custom animation...")
    add.setCursor(Qt.CursorShape.PointingHandCursor)
    add.clicked.connect(lambda _c=False: _ncz_su_add_custom(sp))
    row("Add custom startup animation", "A GIF, WebP, APNG, PNG or JPG, optionally with a sound", add)

    rem = QPushButton("Remove selected")
    rem.setCursor(Qt.CursorShape.PointingHandCursor)
    rem.clicked.connect(lambda _c=False: _ncz_su_remove_custom(sp))
    row("Remove custom startup animation", "Deletes the custom animation that is currently selected", rem)

    opn = QPushButton("Open folder")
    opn.setCursor(Qt.CursorShape.PointingHandCursor)
    opn.clicked.connect(lambda _c=False: QDesktopServices.openUrl(QUrl.fromLocalFile(_ncz_su_dir())))
    row("Startup animations folder", "Drop files here yourself. A sound with the same file name plays with the animation", opn)

    sp._content_layout.addWidget(panel)
    sp._ncz_su_panel, sp._ncz_su_combo = panel, combo



_ncz_su_show_o = SettingsPage.showEvent


def _ncz_su_settings_show(self, e):
    _ncz_su_show_o(self, e)
    try:
        if getattr(self, "_ncz_su_combo", None) is not None:
            _ncz_su_fill(self._ncz_su_combo)              # picks up files dropped into the folder
    except Exception:
        _log_exc("_ncz_su_settings_show")


SettingsPage.showEvent = _ncz_su_settings_show


# ══ Store redesign ══
# A final layer over the Store and its details page. It rearranges and restyles widgets that already exist (search, Tags,
# Trending / Most Popular / Works on your PC, tag chips, the recommendations loader, the grid, reviews), so every feature
# keeps working. If anything in here fails, the page stays as it was.
from PyQt6.QtWidgets import QGraphicsDropShadowEffect

_STH_MIN_W = 320                          # smallest card width; cards then stretch to fill the row
_STH_MAX_W = 460                          # ...but never grow wider than this
_ST_SIDE_W = 320                          # width of the recommendations sidebar
_ST_CHIP_CSS = (
    'QPushButton[chip="true"] { border-radius: 16px; padding: 0px 18px; font-size: 12px; }'
    'QPushButton[chip="true"][active="false"]:!hover:!pressed { background: rgba(128,128,128,0.16); }'
)

def _st_search_icon():
    pm = QPixmap(36, 36)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    pen = QPen(QColor(150, 150, 160))
    pen.setWidthF(3.2)
    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
    p.setPen(pen)
    p.drawEllipse(7, 7, 16, 16)
    p.drawLine(21, 21, 29, 29)
    p.end()
    return QIcon(pm)

def _st_repolish(w):
    w.style().unpolish(w)
    w.style().polish(w)

class StoreCardH(StoreCard):
    """Store card with Steam's landscape header art instead of the tall cover. The tall cover is still loaded
    (NSFW check, and it is what 'Add to Library' keeps), the picture shown is the header."""
    def __init__(self, appid, title, parent=None):
        super().__init__(appid, title, parent)
        self.art = ""
        self.have_art = False                 # header download finished
        self.known = False                    # tall cover + NSFW check finished (the header stays hidden until then)
        self.title_label.setFixedHeight(40)
        self.title_label.setStyleSheet("font-size: 15px; font-weight: 700;")
        self._tags = []
        self.tags_label = QLabel("")
        self.tags_label.setObjectName("RowDesc")
        self.tags_label.setStyleSheet("font-size: 11px;")
        self.tags_label.setFixedHeight(16)
        self.flag_label = QLabel()
        self.flag_label.setFixedHeight(22)
        self.flag_label.hide()
        self.price_label = QLabel("")
        self.price_label.setTextFormat(Qt.TextFormat.RichText)
        self.price_label.setStyleSheet("font-size: 13px;")
        self.price_label.setFixedHeight(22)
        price_row = QHBoxLayout()
        price_row.setSpacing(7)
        price_row.addWidget(self.flag_label)
        price_row.addWidget(self.price_label)
        price_row.addStretch()
        lay = self.layout()
        lay.addSpacing(2)
        lay.addWidget(self.tags_label)
        lay.addSpacing(4)
        lay.addLayout(price_row)
        self.set_width(_STH_MIN_W)

    def set_tags(self, tags):
        self._tags = [t for t in (tags or []) if t][:3]
        self._apply_tags_text()

    def _apply_tags_text(self):
        text = "  \u00b7  ".join(self._tags)
        fm = QFontMetrics(self.tags_label.font())
        self.tags_label.setText(fm.elidedText(text, Qt.TextElideMode.ElideRight, max(40, self.width() - 26)))
        self.tags_label.setToolTip("  \u00b7  ".join(self._tags))

    def set_price(self, text, discount=0, original="", flag=""):
        # the currency's country flag sits before a real price (not for free / coming soon)
        pix = round_flag_pixmap(flag, 14) if (flag and text and text not in ("Free to Play", "Coming soon")) else None
        if pix:
            self.flag_label.setPixmap(pix)
            self.flag_label.show()
        else:
            self.flag_label.hide()
        if not text:
            self.price_label.setText("")
            return
        esc = html_lib.escape(text)
        if text == "Free to Play":
            body = f'<b style="color:{GREEN}">{esc}</b>'
        elif discount:
            body = (f'<span style="background:#4c6b22; color:#a4d007; font-weight:800;">&nbsp;-{int(discount)}%&nbsp;</span>'
                    f'&nbsp;&nbsp;<s style="color:#8a8a92;">{html_lib.escape(original)}</s>&nbsp;&nbsp;<b>{esc}</b>')
        else:
            body = f"<b>{esc}</b>"
        self.price_label.setText(body)

    def set_width(self, w):
        """Card width w; the cover keeps Steam's 460x215 header ratio."""
        cw = w - 16
        ch = round(cw * 215 / 460)
        if self.width() == w and self.cover.width() == cw and self.cover.height() == ch:
            return
        self.setFixedWidth(w)
        self.cover.setFixedSize(cw, ch)
        self._refresh_cover()
        self._apply_tags_text()

    def set_cover(self, path):
        self.cover_path = path or ""
        self.known = True
        self._refresh_cover()

    def set_art(self, path):
        self.art = path or ""
        self.have_art = True
        self._refresh_cover()

    def _refresh_cover(self):
        if not (self.known and self.have_art):
            return
        hidden = self.nsfw and not nsfw_revealed()
        src = self.art or self.cover_path
        pix = rounded_cover_pixmap(src, self.cover.width(), self.cover.height(), 10, blur=hidden) if src else None
        if pix:
            self.cover.setText("")
            self.cover.setPixmap(pix)
            self.cover.setStyleSheet("background: transparent; border: none;")
        else:
            self.cover.setText("No\ncover")
        update_reveal_button(self.cover, self, hidden and bool(pix))

class _RecRow(QFrame):
    """One recommendation in the sidebar: landscape thumbnail, title, and why it was picked."""
    clicked = pyqtSignal(object)

    def __init__(self, rec, parent=None):
        super().__init__(parent)
        self.rec = rec
        self.art = ""
        self.portrait = ""                    # the Store's normal cover, handed to the detail page
        self.nsfw = False
        self.have_art = self.known = False
        nsfw_bus.revealed.connect(self._refresh)
        self.setObjectName("GameCard")
        self.setFixedHeight(78)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip("%s\nBecause you played %s\nClick for details" % (rec["title"], rec["because"]))
        lay = QHBoxLayout(self)
        lay.setContentsMargins(6, 6, 6, 6)
        lay.setSpacing(10)
        self.thumb = QLabel("...")
        self.thumb.setObjectName("CoverPlaceholder")
        self.thumb.setFixedSize(120, 56)
        self.thumb.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lay.addWidget(self.thumb)
        col = QVBoxLayout()
        col.setSpacing(2)
        col.addStretch()
        self.title_label = QLabel(rec["title"])
        self.title_label.setObjectName("RowTitle")
        self.title_label.setWordWrap(True)
        self.title_label.setStyleSheet("font-size: 13px; font-weight: 700;")
        col.addWidget(self.title_label)
        fm = QFontMetrics(self.font())
        why = QLabel(fm.elidedText("Because you played " + rec["because"], Qt.TextElideMode.ElideRight, 150))
        why.setObjectName("RowDesc")
        why.setStyleSheet("font-size: 11px;")
        col.addWidget(why)
        col.addStretch()
        lay.addLayout(col, 1)

    def _refresh(self):
        if not (self.have_art and self.known):
            return
        hidden = self.nsfw and not nsfw_revealed()
        pix = rounded_cover_pixmap(self.art, 120, 56, 6, blur=hidden) if self.art else None
        if pix:
            self.thumb.setText("")
            self.thumb.setPixmap(pix)
            self.thumb.setStyleSheet("background: transparent; border: none;")
        else:
            self.thumb.setText("")

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit(self.rec)
        super().mousePressEvent(event)

class _RecSide(QWidget):
    """Sidebar list of recommendations. Same interface as the old horizontal shelf (cards, fill, show_message,
    open_game), so the existing loading code drives it unchanged."""
    open_game = pyqtSignal(object)

    def __init__(self):
        super().__init__()
        self.cards = {}
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(8)
        self.msg = QLabel("")
        self.msg.setObjectName("RowDesc")
        self.msg.setWordWrap(True)
        self.msg.hide()
        lay.addWidget(self.msg)
        self.rows = QVBoxLayout()
        self.rows.setSpacing(8)
        lay.addLayout(self.rows)
        lay.addStretch()

    def clear(self):
        for c in self.cards.values():
            self.rows.removeWidget(c)
            c.setParent(None)
            c.deleteLater()
        self.cards = {}

    def show_message(self, text):
        self.clear()
        self.msg.setText(text)
        self.msg.setVisible(bool(text))

    def fill(self, recs):
        self.clear()
        self.msg.hide()
        for r in recs:
            row = _RecRow(r)
            row.clicked.connect(self.open_game.emit)
            self.rows.addWidget(row)
            self.cards[r["appid"]] = row

def _st_short_price(usd, currency):
    """Short card price in the chosen currency: $9.99, EUR 9.99 -> \u20ac9.99, EGP 450, SAR 37.5 ..."""
    try:
        if currency == "USD":
            return f"${usd:,.2f}"
        amount = usd * get_usd_rates().get(currency, FALLBACK_RATES[currency])
        text = f"{amount:,.0f}" if currency == "EGP" else f"{amount:,.2f}"
        if text.endswith(".00"):
            text = text[:-3]
        return f"\u20ac{text}" if currency == "EUR" else f"{currency} {text}"
    except Exception:
        return f"${usd:,.2f}"

_ST_HOVER_TAG_RE = re.compile(r'<div class="app_tag"[^>]*>\s*([^<]+?)\s*</div>')

class _StMeta(QObject):
    """Price and tags for the Store cards, fetched in the background: prices in one batched Steam call per page,
    tags from Steam's small hover-card page (cached on disk, so each game is only asked once)."""
    price = pyqtSignal(int, str, int, str, str)  # appid, price text, discount %, original price text, flag image path
    tags = pyqtSignal(int, object)               # appid, [tag names]

    def __init__(self):
        super().__init__()
        self._pool = ThreadPoolExecutor(max_workers=3)
        self._lock = threading.Lock()
        self._asked_price, self._asked_tags = set(), set()
        self.price_cache, self.tag_cache = {}, {}
        self._disk = None
        self._unsaved = 0
        QApplication.instance().aboutToQuit.connect(lambda: self._pool.shutdown(wait=False, cancel_futures=True))

    def request(self, ids, currency):
        with self._lock:
            new_p = [i for i in ids if i not in self._asked_price]
            new_t = [i for i in ids if i not in self._asked_tags]
            self._asked_price.update(new_p)
            self._asked_tags.update(new_t)
        if new_p:
            self._pool.submit(self._price_job, new_p, currency)
        for i in new_t:
            self._pool.submit(self._tags_job, i)

    def _unask(self, ids, price=False, tags=False):
        with self._lock:
            if price:
                self._asked_price.difference_update(ids)
            if tags:
                self._asked_tags.difference_update(ids)

    def _emit_price(self, appid, text, disc=0, orig="", flag=""):
        self.price_cache[appid] = (text, disc, orig, flag)
        try:
            self.price.emit(appid, text, int(disc), orig, flag)
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass

    def _price_job(self, ids, currency):
        try:
            flag = get_flag_file(currency)       # the currency country's flag (downloaded once, then cached)
        except Exception:
            flag = ""
        for k in range(0, len(ids), 40):
            chunk = ids[k:k + 40]
            if time.time() < _steam_busy["until"]:
                self._unask(ids[k:], price=True)
                return
            try:
                url = ("https://store.steampowered.com/api/appdetails?appids=" + ",".join(str(i) for i in chunk)
                       + "&filters=price_overview&cc=us")
                data = json.loads(_http_get(url, timeout=20).decode("utf-8", errors="replace"))
            except urllib.error.HTTPError as e:
                if e.code in (429, 403):
                    _steam_busy["until"] = time.time() + 120
                self._unask(ids[k:], price=True)
                return
            except Exception:
                self._unask(ids[k:], price=True)
                return
            unresolved = []
            for i in chunk:
                entry = data.get(str(i))
                info = entry.get("data") if isinstance(entry, dict) else None
                po = info.get("price_overview") if isinstance(info, dict) else None
                if po and po.get("final"):
                    disc = int(po.get("discount_percent") or 0)
                    orig = _st_short_price(po["initial"] / 100, currency) if disc and po.get("initial") else ""
                    self._emit_price(i, _st_short_price(po["final"] / 100, currency), disc, orig, flag)
                else:
                    unresolved.append(i)
            # no price: free, not out yet, or simply not sold: one small call each tells which
            for i in unresolved[:25]:
                if time.time() < _steam_busy["until"]:
                    break
                try:
                    time.sleep(0.15)
                    raw = json.loads(_http_get(
                        f"https://store.steampowered.com/api/appdetails?appids={i}&l=english&cc=us&filters=basic",
                        timeout=15).decode("utf-8", errors="replace"))
                    info = (raw.get(str(i)) or {}).get("data") or {}
                    if info.get("is_free"):
                        self._emit_price(i, "Free to Play")
                    elif (info.get("release_date") or {}).get("coming_soon"):
                        self._emit_price(i, "Coming soon")
                    else:
                        self._emit_price(i, "")
                except urllib.error.HTTPError as e:
                    if e.code in (429, 403):
                        _steam_busy["until"] = time.time() + 120
                    break
                except Exception:
                    continue

    def _tags_path(self):
        return os.path.join(get_store_cache_dir(), "card_tags.json")

    def _load_disk(self):
        if self._disk is None:
            try:
                with open(self._tags_path(), encoding="utf-8") as f:
                    self._disk = {int(k): list(v) for k, v in json.load(f).items()}
            except Exception:
                self._disk = {}
        return self._disk

    def _tags_job(self, appid):
        with self._lock:
            tags = self._load_disk().get(appid)
        if not tags:
            if time.time() < _steam_busy["until"]:
                self._unask([appid], tags=True)
                return
            try:
                raw = _http_get(f"https://store.steampowered.com/apphoverpublic/{appid}?l=english&cc=us",
                                headers={"Accept-Language": "en-US,en;q=0.9",
                                         "Cookie": "birthtime=568022401; lastagecheckage=1-0-1988; wants_mature_content=1"},
                                timeout=12).decode("utf-8", errors="replace")
            except urllib.error.HTTPError as e:
                if e.code in (429, 403):
                    _steam_busy["until"] = time.time() + 120
                self._unask([appid], tags=True)
                return
            except Exception:
                self._unask([appid], tags=True)
                return
            tags = [html_lib.unescape(t).strip() for t in _ST_HOVER_TAG_RE.findall(raw)][:6]
            if tags:
                with self._lock:
                    self._load_disk()[appid] = tags
                    self._unsaved += 1
                    if self._unsaved >= 10:
                        self._unsaved = 0
                        try:
                            os.makedirs(get_store_cache_dir(), exist_ok=True)
                            with open(self._tags_path(), "w", encoding="utf-8") as f:
                                json.dump({str(k): v for k, v in self._disk.items()}, f)
                        except OSError:    # expected: file may not exist yet or be unreadable
                            pass
        self.tag_cache[appid] = tags or []
        try:
            self.tags.emit(appid, tags or [])
        except RuntimeError:    # expected: the widget or object may already be deleted
            pass

def _st_sync_chips(self):
    for b in getattr(self, "_st_chips", []):
        if b is self.tags_btn:
            b.setObjectName("Primary" if self._tag_filter else "")
        on = b.objectName() == "Primary"
        b.setProperty("active", "true" if on else "false")
        _st_repolish(b)

def _st_section_text(self):
    term = (getattr(self, "_term", "") or "").strip()
    tags = [n for _t, n in getattr(self, "_tag_filter", [])]
    if term:
        text = f"Results for \u201c{term}\u201d"
    elif getattr(self, "_works", False):
        text = "Games that run on your PC"
    elif getattr(self, "_mode", "") == "trending":
        text = "Trending now"
    elif getattr(self, "_mode", "") == "popular":
        text = "Most popular"
    else:
        text = "Discover games"
    if tags:
        text += "  \u00b7  " + ", ".join(tags[:3]) + ("..." if len(tags) > 3 else "")
    return text

def _st_metrics(self):
    """(columns, card width): as many columns as fit at the minimum width, then the cards share the row."""
    available = self.width() - 40 - 32 - _ST_SIDE_W - 24 - 12
    cols = max(1, (available + STORE_GRID_GAP) // (_STH_MIN_W + STORE_GRID_GAP))
    w = (available - STORE_GRID_GAP * (cols - 1)) // cols
    return cols, max(_STH_MIN_W, min(_STH_MAX_W, w))

def _st_columns(self):
    return _st_metrics(self)[0]

def _st_apply_sizes(self):
    try:
        w = _st_metrics(self)[1]
        for card in self._cards:
            if isinstance(card, StoreCardH):
                card.set_width(w)
    except Exception:
        _log_exc("_st_apply_sizes")

def _st_restyle_store(self):
    need = ("count_label", "search_edit", "tags_btn", "tag_bar", "banner", "status_label", "retry_btn", "scroll",
            "_mode_buttons", "grid", "_tag_filter")
    if any(not hasattr(self, n) for n in need):
        return
    # everything that can fail is prepared first, so the old layout is only taken apart when the new one is certain
    lay = self.layout()
    old_title = None
    try:
        first = lay.itemAt(0).layout()
        w0 = first.itemAt(0).widget() if first is not None else None
        if isinstance(w0, QLabel) and w0.objectName() == "PageTitle":
            old_title = w0
    except Exception:
        old_title = None
    title = old_title or QLabel("Store")
    title.setObjectName("PageTitle")
    title.setStyleSheet("font-size: 30px; font-weight: 800;")
    sub = QLabel("Browse Steam games and add them to your library")
